window.LWA_DATA={"papers":[{"id":"t2023a","year":2023,"stage":"Written Examination Paper I","short":"AMVI 2023 Paper 1 (GS & GA)","title":"TSPSC Assistant Motor Vehicles Inspector 2023: Paper I (General Studies & General Abilities)","notif":"Notification 31/2022 · CBRT · preliminary key","held":"28 June 2023","fmt":"mcq","slug":"tgpsc-amvi-2023-paper-1-general-studies-question-paper-with-answers","blurb":"Paper I: General Studies & General Abilities, computer-based test, 150 questions, 150 marks, 150 minutes, in English and Telugu. Answers are from TSPSC's preliminary key; the final key may differ for a few questions.","count":150,"key":"TSPSC's preliminary key (the final key was released only on candidates' response sheets)","alt":"General Studies & General Abilities","te_paper":"పేపర్-1 జనరల్ స్టడీస్ & జనరల్ ఎబిలిటీస్","kwname":"TGPSC AMVI 2023 Paper 1 General Studies & General Abilities","alabel":"Answer (TSPSC's preliminary key)","pdf":"","kw":"TGPSC AMVI 2023 Paper 1 General Studies & General Abilities"},{"id":"t2023b","year":2023,"stage":"Written Examination Paper II","short":"AMVI 2023 Paper 2 (Automobile)","title":"TSPSC Assistant Motor Vehicles Inspector 2023: Paper II (Automobile Engineering)","notif":"Notification 31/2022 · CBRT · preliminary key","held":"28 June 2023","fmt":"mcq","slug":"tgpsc-amvi-2023-paper-2-automobile-engineering-question-paper-with-answers","blurb":"Paper II: Automobile Engineering, computer-based test, 150 questions, 300 marks, 150 minutes, in English. Answers are from TSPSC's preliminary key; the final key may differ for a few questions.","count":150,"key":"TSPSC's preliminary key (the final key was released only on candidates' response sheets)","alt":"Automobile Engineering","te_paper":"పేపర్-2 ఆటోమొబైల్ ఇంజనీరింగ్","en_only":true,"kwname":"TGPSC AMVI 2023 Paper 2 Automobile Engineering","alabel":"Answer (TSPSC's preliminary key)","pdf":"","kw":"TGPSC AMVI 2023 Paper 2 Automobile Engineering"}],"subjects":[{"id":"cur","name":"Current Affairs","slug":"current-affairs","topics":["National","International","Telangana","Sports & Awards"]},{"id":"sci","name":"General Science & Technology","slug":"general-science","topics":["Physics","Chemistry","Biology & Health","Science & Technology"]},{"id":"env","name":"Environment & Disaster Management","slug":"environment-disaster-management","topics":["Environment & Ecology","Disaster Management"]},{"id":"geo","name":"Geography","slug":"geography","topics":["World Geography","Indian Geography","Telangana Geography"]},{"id":"ih","name":"Indian History & Culture","slug":"indian-history","topics":["Ancient India","Medieval India","Modern India & Freedom Struggle","Art & Culture"]},{"id":"tg","name":"Telangana History & Movement","slug":"telangana-history-movement","topics":["Telangana History & Culture","Telangana Movement & State Formation","Telangana Schemes & Policies"]},{"id":"pol","name":"Indian Polity","slug":"indian-polity","topics":["Constitution & Rights","Union & State Government","Local Government","Governance, Schemes & Social Issues"]},{"id":"eco","name":"Economy","slug":"economy","topics":["Indian Economy","Telangana Economy"]},{"id":"rea","name":"Reasoning & Data Interpretation","slug":"reasoning-data-interpretation","topics":["Logical Reasoning","Arithmetic & Mental Ability","Data Interpretation"]},{"id":"eng","name":"English","slug":"english","topics":["Grammar","Vocabulary"]},{"id":"thm","name":"Thermodynamics & Heat Transfer","slug":"thermodynamics-heat-transfer","topics":["Thermodynamics","Heat Transfer","Refrigeration & Air Conditioning"]},{"id":"ice","name":"IC Engines, Fuels & Emissions","slug":"ic-engines","topics":["Engine Fundamentals & Cycles","Fuel Supply & Combustion","Cooling & Lubrication","Fuels, Lubricants & Emissions"]},{"id":"chs","name":"Automobile Chassis & Transmission","slug":"automobile-chassis-transmission","topics":["Chassis & Body","Clutch & Gearbox","Drive Line, Axles & Differential","Brakes","Steering & Suspension","Wheels & Tyres"]},{"id":"ael","name":"Automotive Electrical & Electronics","slug":"automotive-electrical-electronics","topics":["Batteries & Charging","Starting & Ignition","Lighting, Instruments & Wiring","Electronics, Sensors & ECU"]},{"id":"mec","name":"Engineering Mechanics & Machine Design","slug":"mechanics-machine-design","topics":["Engineering Mechanics","Strength of Materials","Theory of Machines","Machine Design"]},{"id":"mfg","name":"Materials, Manufacturing & Metrology","slug":"materials-manufacturing","topics":["Engineering Materials","Manufacturing & Workshop","Metrology & Measurement"]},{"id":"flu","name":"Fluid Mechanics & Hydraulics","slug":"fluid-mechanics","topics":["Fluid Mechanics","Hydraulic Machines & Pneumatics"]},{"id":"mva","name":"Motor Vehicles Act, Transport & Maintenance","slug":"motor-vehicles-act-transport","topics":["Motor Vehicles Act & Rules","Transport Management","Vehicle Maintenance & Testing","Road Safety"]},{"id":"emv","name":"Electric, Hybrid & Alternative-Fuel Vehicles","slug":"electric-alternative-vehicles","topics":["Electric & Hybrid Vehicles","Alternative Fuels"]}],"questions":[{"id":"t2023a-1","p":"t2023a","n":1,"s":"cur","t":"Sports & Awards","q":"Who won the Nobel Peace Prize for their work on literature in 2022?","w":"The French writer Annie Ernaux won the 2022 Nobel Prize in Literature, not the Peace Prize, for the courage and clinical acuity with which she uncovers the roots of personal memory; the question mixes up the two prizes. The 2022 Peace Prize went to Ales Bialiatski (Belarus), Memorial (Russia) and the Center for Civil Liberties (Ukraine). Malala Yousafzai (2014) and Al Gore (2007) are past Peace laureates; Greta Thunberg has never won.","o":["Greta Thunberg","Annie Ernaux","Malala Yousafzai","Al Gore"],"a":[1],"qt":"2022 లో సాహిత్యంపై చేసిన కృషికి నోబెల్ శాంతి బహుమతిని గెలుచుకున్నవారు ఎవరు?","ot":["గ్రేటా థన్‌బెర్గ్","అన్నీ ఎర్నాక్స్","మలాలా యూసఫ్‌జాయ్","అల్ గోరె"],"wt":"ఫ్రెంచ్ రచయిత్రి అన్నీ ఎర్నాక్స్ 2022లో సాహిత్య నోబెల్ బహుమతిని గెలుచుకున్నారు, శాంతి బహుమతిని కాదు; వ్యక్తిగత జ్ఞాపకాల మూలాలను ధైర్యంగా, నిశితంగా వెలికితీసినందుకు ఆమెకు ఈ బహుమతి లభించింది. ప్రశ్న ఈ రెండు బహుమతులను కలిపేసింది. 2022 శాంతి బహుమతి అలెస్ బియాలియాట్స్కీ (బెలారస్), మెమోరియల్ (రష్యా), సెంటర్ ఫర్ సివిల్ లిబర్టీస్ (ఉక్రెయిన్)లకు లభించింది. మలాలా యూసఫ్‌జాయ్ (2014), అల్ గోరె (2007) గతంలో శాంతి బహుమతి పొందారు; గ్రేటా థన్‌బెర్గ్ ఎప్పుడూ గెలవలేదు."},{"id":"t2023a-2","p":"t2023a","n":2,"s":"cur","t":"International","q":"Which international organization recently recommended that the world should cut methane emissions by 45% by 2030?","w":"The Global Methane Assessment released in May 2021 by the UN Environment Programme (UNEP) and the Climate and Clean Air Coalition found that human-caused methane emissions can be cut by up to 45% this decade, avoiding nearly 0.3°C of warming by 2045. Methane is short-lived but a powerful greenhouse gas. The Global Methane Pledge launched at COP26 (2021) aims at a 30% cut from 2020 levels by 2030.","o":["United Nations","World Health Organization","International Monetary Fund","World Meteorological Organization"],"a":[0],"qt":"2030 నాటికి ప్రపంచం మీథేన్ ఉద్గారాలను 45% తగ్గించాలని ఇటీవల సిఫార్సు చేసిన అంతర్జాతీయ సంస్థ ఏది?","ot":["ఐక్యరాజ్యసమితి","ప్రపంచ ఆరోగ్య సంస్థ","అంతర్జాతీయ ద్రవ్య నిధి","ప్రపంచ వాతావరణ సంస్థ"],"wt":"ఐక్యరాజ్యసమితి పర్యావరణ కార్యక్రమం (UNEP), క్లైమేట్ అండ్ క్లీన్ ఎయిర్ కోయలిషన్ మే 2021లో విడుదల చేసిన గ్లోబల్ మీథేన్ అసెస్‌మెంట్, మానవ కార్యకలాపాల వల్ల వెలువడే మీథేన్ ఉద్గారాలను ఈ దశాబ్దంలో 45% వరకు తగ్గించవచ్చని, దానివల్ల 2045 నాటికి దాదాపు 0.3°C ఉష్ణోగ్రత పెరుగుదలను నివారించవచ్చని తెలిపింది. మీథేన్ వాతావరణంలో తక్కువ కాలం నిలిచినా శక్తిమంతమైన హరితగృహ వాయువు. COP26 (2021)లో ప్రారంభమైన గ్లోబల్ మీథేన్ ప్రతిజ్ఞ 2030 నాటికి 2020 స్థాయి నుంచి 30% తగ్గింపును లక్ష్యంగా పెట్టుకుంది."},{"id":"t2023a-3","p":"t2023a","n":3,"s":"cur","t":"International","q":"In which year did the United Nations adopt the Global Compact for Safe, Orderly and Regular Migration, which aims to better manage international migration?","w":"The Global Compact for Safe, Orderly and Regular Migration was adopted at an intergovernmental conference in Marrakech, Morocco, on 10 December 2018 and endorsed by the UN General Assembly on 19 December 2018. It is the first intergovernmentally negotiated UN agreement covering all dimensions of international migration; it is not legally binding and rests on 23 objectives.","o":["2020","2023","2018","2014"],"a":[2],"qt":"అంతర్జాతీయ వలసలను మెరుగ్గా నిర్వహించేందుకు ఉద్దేశించిన గ్లోబల్ కాంపాక్ట్ ఫర్ సేఫ్, ఆర్డర్లీ మరియు రెగ్యులర్ మైగ్రేషన్‌ను ఐక్యరాజ్యసమితి ఆమోదించిన సంవత్సరం ఏది?","ot":["2020","2023","2018","2014"],"wt":"గ్లోబల్ కాంపాక్ట్ ఫర్ సేఫ్, ఆర్డర్లీ అండ్ రెగ్యులర్ మైగ్రేషన్‌ను 10 డిసెంబర్ 2018న మొరాకోలోని మరాకేష్‌లో జరిగిన అంతర్ ప్రభుత్వ సదస్సు ఆమోదించగా, 19 డిసెంబర్ 2018న ఐక్యరాజ్యసమితి సాధారణ సభ దానిని ధ్రువీకరించింది. అంతర్జాతీయ వలసల అన్ని కోణాలను కవర్ చేస్తూ ప్రభుత్వాల మధ్య చర్చల ద్వారా రూపొందిన మొదటి ఐరాస ఒప్పందం ఇది; ఇది చట్టపరంగా బాధ్యత విధించేది కాదు, 23 లక్ష్యాలపై ఆధారపడింది."},{"id":"t2023a-4","p":"t2023a","n":4,"s":"cur","t":"International","q":"In 2020, which country withdrew from the Open Skies Treaty, which allows unarmed surveillance flights over the territories of its signatories?","w":"The Open Skies Treaty, signed in 1992 and in force since 2002, lets member states fly unarmed observation flights over one another's territory to build mutual confidence. The United States announced its withdrawal in May 2020, citing Russian violations, and left on 22 November 2020. Russia followed, leaving in December 2021. China was never a party, and France remains a member.","o":["Russia","China","United States","France"],"a":[2],"qt":"2020లో, ఏ దేశం తాము సంతకం చేసిన, తమ భూభాగాలపై నిరాయుధ నిఘా విమానాలను అనుమతించే బహిరంగ ఆకాశ ఒప్పందం (ఓపెన్ స్కైస్ ట్రీటి) నుండి వైదొలిగింది?","ot":["రష్యా","చైనా","సంయుక్త రాష్ట్రాలు","ఫ్రాన్స్"],"wt":"1992లో సంతకమై 2002 నుంచి అమలులో ఉన్న ఓపెన్ స్కైస్ ఒప్పందం, పరస్పర విశ్వాసం పెంచేందుకు సభ్య దేశాలు ఒకదాని భూభాగంపై మరొకటి నిరాయుధ నిఘా విమానాలు నడపడానికి అనుమతిస్తుంది. రష్యా ఉల్లంఘనలను కారణంగా చూపుతూ అమెరికా మే 2020లో వైదొలగుతున్నట్లు ప్రకటించి, 22 నవంబర్ 2020న బయటకు వచ్చింది. ఆ తర్వాత రష్యా డిసెంబర్ 2021లో వైదొలగింది. చైనా ఈ ఒప్పందంలో ఎప్పుడూ సభ్యదేశం కాదు; ఫ్రాన్స్ ఇప్పటికీ సభ్యదేశమే."},{"id":"t2023a-5","p":"t2023a","n":5,"s":"cur","t":"International","q":"In which year did Kamala Harris become the first woman, first Black person, and first person of South Asian descent to become Vice President of the United States?","w":"Kamala Harris was elected with Joe Biden in the November 2020 US presidential election and was sworn in as the 49th Vice President on 20 January 2021, becoming the first woman, the first Black American and the first person of South Asian (Indian) descent in that office. Her term ended in January 2025; J.D. Vance is now Vice President.","o":["2020","2021","2022","2023"],"a":[1],"qt":"కమలా హారిస్ సంయుక్త రాష్ట్రాల ఉపాధ్యక్షురాలు అయిన మొట్ట మొదటి మహిళ, మొదటి నల్లజాతి వ్యక్తి మరియు దక్షిణాసియా సంతతికి చెందిన మొదటి వ్యక్తిగా ఏ సంవత్సరంలో అయ్యారు?","ot":["2020","2021","2022","2023"],"wt":"కమలా హారిస్ నవంబర్ 2020 అమెరికా అధ్యక్ష ఎన్నికల్లో జో బైడెన్‌తో కలిసి ఎన్నికై, 20 జనవరి 2021న 49వ ఉపాధ్యక్షురాలిగా ప్రమాణం చేశారు; ఆ పదవిని చేపట్టిన మొదటి మహిళ, మొదటి నల్లజాతి అమెరికన్, దక్షిణాసియా (భారత) సంతతికి చెందిన మొదటి వ్యక్తి ఆమె. ఆమె పదవీకాలం జనవరి 2025లో ముగిసింది; ప్రస్తుతం జె.డి. వాన్స్ ఉపాధ్యక్షుడు."},{"id":"t2023a-6","p":"t2023a","n":6,"s":"cur","t":"Sports & Awards","q":"Which Indian cricketer became the first Indian to score a century in all three formats of international cricket, in 2023?","w":"With his Test century against Australia at Nagpur in February 2023, Rohit Sharma became the first Indian to score centuries in all three international formats as captain, which is what the question intends. He was not the first Indian with centuries in all formats overall: Suresh Raina achieved that in 2010, followed by Rohit, K.L. Rahul, Virat Kohli and, on 1 February 2023, Shubman Gill. Dhoni and Dhawan have no T20I century.","o":["Virat Kohli","Rohit Sharma","Mahendra Singh Dhoni","Shikhar Dhawan"],"a":[1],"qt":"2023 లో అంతర్జాతీయ క్రికెట్‌లోని మూడు ఫార్మాట్లలో శతకాన్ని సాధించిన మొట్ట మొదటి భారతీయ క్రికెటర్ ఎవరు?","ot":["విరాట్ కోహ్లీ","రోహిత్ శర్మ","మహేంద్ర సింగ్ ధోని","శిఖర్ ధావన్"],"wt":"ఫిబ్రవరి 2023లో నాగ్‌పూర్‌లో ఆస్ట్రేలియాపై టెస్ట్ శతకం చేయడంతో, కెప్టెన్‌గా మూడు అంతర్జాతీయ ఫార్మాట్లలోనూ శతకాలు సాధించిన మొదటి భారతీయుడిగా రోహిత్ శర్మ నిలిచారు; ప్రశ్న ఉద్దేశం ఇదే. మొత్తంగా మూడు ఫార్మాట్లలో శతకాలు చేసిన మొదటి భారతీయుడు ఆయన కాదు: 2010లో సురేష్ రైనా ఆ ఘనత సాధించారు, ఆ తర్వాత రోహిత్, కె.ఎల్. రాహుల్, విరాట్ కోహ్లీ, 1 ఫిబ్రవరి 2023న శుభ్‌మన్ గిల్ సాధించారు. ధోని, ధావన్‌లకు T20I శతకం లేదు."},{"id":"t2023a-7","p":"t2023a","n":7,"s":"cur","t":"National","q":"In which year did the Indian Council of Agricultural Research (ICAR) develop a new high-yielding variety of soybean called MACS 1407?","w":"MACS 1407, a high-yielding (about 39 quintals per hectare), pest-resistant soybean variety, was developed by the MACS-Agharkar Research Institute, Pune, in collaboration with ICAR and announced in 2021. It resists girdle beetle, leaf miner, stem fly and aphids, suits cultivation in Assam, West Bengal, Jharkhand, Chhattisgarh and the North-Eastern states, and its seed was to reach farmers from the 2022 kharif season.","o":["2021","2023","2019","2015"],"a":[0],"qt":"ఇండియన్ కౌన్సిల్ ఆఫ్ అగ్రికల్చరల్ రీసెర్చ్ (ICAR), MACS 1407 అనే కొత్త అధిక దిగుబడినిచ్చే సోయాబీన్‌ను అభివృద్ధి చేసిన సంవత్సరం ఏది?","ot":["2021","2023","2019","2015"],"wt":"అధిక దిగుబడి (హెక్టారుకు సుమారు 39 క్వింటాళ్లు) ఇచ్చే, చీడపీడలను తట్టుకునే సోయాబీన్ రకం MACS 1407ను పుణెలోని MACS-అఘార్కర్ పరిశోధన సంస్థ ICAR సహకారంతో అభివృద్ధి చేయగా, 2021లో ప్రకటించారు. ఇది గర్డిల్ బీటిల్, లీఫ్ మైనర్, స్టెమ్ ఫ్లై, పేనుబంక (ఆఫిడ్స్)లను తట్టుకుంటుంది; అస్సాం, పశ్చిమ బెంగాల్, జార్ఖండ్, ఛత్తీస్‌గఢ్, ఈశాన్య రాష్ట్రాల్లో సాగుకు అనువైనది; దీని విత్తనాలు 2022 ఖరీఫ్ నుంచి రైతులకు అందుబాటులోకి రావాల్సి ఉంది."},{"id":"t2023a-8","p":"t2023a","n":8,"s":"cur","t":"National","q":"Which app did the Indian government launch to help track and contain the spread of COVID-19?","w":"Aarogya Setu was launched on 2 April 2020 by the Ministry of Electronics and IT through the National Informatics Centre; it used Bluetooth and GPS for contact tracing and told users their COVID-19 risk. Aaykar Setu is the Income Tax Department's taxpayer-service app, BHIM is NPCI's UPI payments app, and mAadhaar is UIDAI's app for carrying an Aadhaar profile.","o":["Aarogya Setu App","Aaykar Setu App","BHIM UPI App","mAadhaar App"],"a":[0],"qt":"కోవిడ్-19 వ్యాప్తిని ట్రాక్ చేయడంలో మరియు నియంత్రించడంలో సహాయం చేయడానికి భారత ప్రభుత్వం ప్రారంభించిన యాప్ ఏది?","ot":["ఆరోగ్య సేతు యాప్","ఆయకర్ సేతు యాప్","BHIM UPI యాప్","mAadhaar యాప్"],"wt":"ఆరోగ్య సేతును ఎలక్ట్రానిక్స్ మరియు ఐటీ మంత్రిత్వ శాఖ నేషనల్ ఇన్ఫర్మాటిక్స్ సెంటర్ ద్వారా 2 ఏప్రిల్ 2020న ప్రారంభించింది; ఇది బ్లూటూత్, GPS ద్వారా కాంటాక్ట్ ట్రేసింగ్ చేసి వినియోగదారులకు వారి కోవిడ్-19 ప్రమాద స్థాయిని తెలిపేది. ఆయకర్ సేతు ఆదాయపు పన్ను శాఖ పన్ను చెల్లింపుదారుల సేవల యాప్; BHIM, NPCI రూపొందించిన UPI చెల్లింపుల యాప్; mAadhaar, ఆధార్ వివరాలను వెంట ఉంచుకోవడానికి UIDAI రూపొందించిన యాప్."},{"id":"t2023a-9","p":"t2023a","n":9,"s":"pol","t":"Governance, Schemes & Social Issues","q":"In which year did the Indian government launch the Swachh Bharat Abhiyan (Clean India Mission)?","w":"Prime Minister Narendra Modi launched the Swachh Bharat Mission on 2 October 2014, Gandhi Jayanti, to make India open-defecation free and improve solid waste management by 2 October 2019, Gandhi's 150th birth anniversary. It has rural (Ministry of Jal Shakti) and urban (Ministry of Housing and Urban Affairs) arms; Phase II of the rural mission and SBM-Urban 2.0 now continue it.","o":["2015","2012","2016","2014"],"a":[3],"qt":"భారత ప్రభుత్వం స్వచ్ఛ భారత్ అభియాన్ (క్లీన్ ఇండియా మిషన్)ను ప్రారంభించిన సంవత్సరం ఏది?","ot":["2015","2012","2016","2014"],"wt":"ప్రధానమంత్రి నరేంద్ర మోదీ 2 అక్టోబర్ 2014న, గాంధీ జయంతి నాడు, స్వచ్ఛ భారత్ మిషన్‌ను ప్రారంభించారు; గాంధీ 150వ జయంతి అయిన 2 అక్టోబర్ 2019 నాటికి భారతదేశాన్ని బహిరంగ మలవిసర్జన రహితంగా మార్చడం, ఘన వ్యర్థాల నిర్వహణను మెరుగుపరచడం దీని లక్ష్యం. దీనికి గ్రామీణ (జల శక్తి మంత్రిత్వ శాఖ), పట్టణ (గృహ, పట్టణ వ్యవహారాల మంత్రిత్వ శాఖ) విభాగాలు ఉన్నాయి; గ్రామీణ మిషన్ రెండో దశ, SBM-అర్బన్ 2.0 ప్రస్తుతం దీనిని కొనసాగిస్తున్నాయి."},{"id":"t2023a-10","p":"t2023a","n":10,"s":"sci","t":"Science & Technology","q":"Name the low-cost COVID-19 testing kit launched by Indian Institute of Technology (IIT) Delhi in 2020.","w":"Corosure, developed by IIT Delhi, was launched in July 2020 as a low-cost, probe-free RT-PCR-based COVID-19 test kit, priced at about ₹399 for the basic kit, and was made under licence by a private firm. Covishield (Serum Institute's version of the Oxford-AstraZeneca vaccine) and Covaxin (Bharat Biotech) are vaccines, while Coronil is a Patanjali herbal product.","o":["Covishield","Coronil","Corosure","Covaxin"],"a":[2],"qt":"ఇండియన్ ఇన్‌స్టిట్యూట్ ఆఫ్ టెక్నాలజీ (IIT) ఢిల్లీ 2020 లో ప్రారంభించిన తక్కువ-ధర కోవిడ్-19 టెస్టింగ్ కిట్ పేరును తెలపండి.","ot":["కోవిషీల్డ్","కోరోనిల్","కోరోష్యూర్","కోవాగ్జీన్"],"wt":"IIT ఢిల్లీ అభివృద్ధి చేసిన కోరోష్యూర్‌ను జూలై 2020లో తక్కువ ధర, ప్రోబ్ అవసరం లేని RT-PCR ఆధారిత కోవిడ్-19 పరీక్ష కిట్‌గా ప్రారంభించారు; ప్రాథమిక కిట్ ధర సుమారు ₹399. దీనిని లైసెన్స్ కింద ఒక ప్రైవేట్ సంస్థ తయారు చేసింది. కోవిషీల్డ్ (ఆక్స్‌ఫర్డ్-ఆస్ట్రాజెనెకా టీకాకు సీరం ఇన్‌స్టిట్యూట్ రూపం), కోవాగ్జీన్ (భారత్ బయోటెక్) టీకాలు కాగా, కోరోనిల్ పతంజలి మూలికా ఉత్పత్తి."},{"id":"t2023a-11","p":"t2023a","n":11,"s":"pol","t":"Governance, Schemes & Social Issues","q":"Name the scheme launched by the Indian government launch to promote literacy and education in adults, in 2020?","w":"Padhna Likhna Abhiyan was the centrally sponsored adult literacy scheme launched by the Ministry of Education in 2020, after the Saakshar Bharat programme ended in 2018, to teach basic reading, writing and numeracy to non-literate adults aged 15 and above. It was followed by the New India Literacy Programme (ULLAS) for 2022–27. RMSA and SSA are school-education programmes, and the RTE Act covers children aged 6–14.","o":["Rashtriya Madhyamik Shiksha Abhiyan","Right to Education Act","Padhna Likhna Abhiyan","Sarva Shiksha Abhiyan"],"a":[2],"qt":"2020 లో వయోజనులలో అక్షరాస్యత మరియు విద్యను ప్రోత్సహించడానికి భారత ప్రభుత్వం ప్రారంభించిన పథకం పేరు?","ot":["రాష్ట్రీయ మాధ్యమిక శిక్షా అభియాన్","విద్యా హక్కు చట్టం","పఢ్నా లిఖ్నా అభియాన్","సర్వశిక్షా అభియాన్"],"wt":"పఢ్నా లిఖ్నా అభియాన్, సాక్షర్ భారత్ కార్యక్రమం 2018లో ముగిసిన తర్వాత, 15 ఏళ్లు పైబడిన నిరక్షరాస్య వయోజనులకు ప్రాథమికంగా చదవడం, రాయడం, లెక్కలు నేర్పడానికి విద్యా మంత్రిత్వ శాఖ 2020లో ప్రారంభించిన కేంద్ర ప్రాయోజిత వయోజన అక్షరాస్యత పథకం. దాని తర్వాత 2022–27 కాలానికి న్యూ ఇండియా లిటరసీ ప్రోగ్రామ్ (ULLAS) వచ్చింది. రాష్ట్రీయ మాధ్యమిక శిక్షా అభియాన్, సర్వశిక్షా అభియాన్ పాఠశాల విద్యా కార్యక్రమాలు; విద్యా హక్కు చట్టం 6–14 ఏళ్ల పిల్లలకు వర్తిస్తుంది."},{"id":"t2023a-12","p":"t2023a","n":12,"s":"pol","t":"Governance, Schemes & Social Issues","q":"The National Commission for Protection of Child Rights (NCPCR) was established as a statutory body under which Act?","w":"The NCPCR was set up in March 2007 as a statutory body under the Commissions for Protection of Child Rights Act, 2005, which also provides for State Commissions. It works under the Ministry of Women and Child Development and monitors child rights laws; the RTE, POCSO and Juvenile Justice Acts give it further monitoring roles, but none of them created it.","o":["The Juvenile Justice (Care and Protection) Act","Commissions for Protection of Child Rights (CPCR) Act","The Child Labour (Prohibition and Regulation) Act","The Protection of Children from Sexual Offences Act"],"a":[1],"qt":"నేషనల్ కమీషన్ ఫర్ ప్రొటెక్షన్ ఆఫ్ చైల్డ్ రైట్స్ (NCPCR) అనేది చట్టబద్ధమైన సంస్థగా ఏ చట్టం ప్రకారం స్థాపించబడింది?","ot":["జువెనైల్ జస్టిస్ (కేర్ అండ్ ప్రొటెక్షన్) చట్టం","బాల హక్కుల సంరక్షణ కమీషన్ (CPCR) చట్టం","బాల కార్మిక (నిషేధం మరియు నియంత్రణ) చట్టం","లైంగిక నేరాల నుండి బాలల రక్షణ చట్టం"],"wt":"NCPCR, బాలల హక్కుల సంరక్షణ కమీషన్ల చట్టం, 2005 కింద మార్చి 2007లో చట్టబద్ధమైన సంస్థగా ఏర్పాటైంది; ఇదే చట్టం రాష్ట్ర కమీషన్ల ఏర్పాటుకూ వీలు కల్పిస్తుంది. ఇది మహిళా, శిశు అభివృద్ధి మంత్రిత్వ శాఖ పరిధిలో పనిచేస్తూ బాలల హక్కుల చట్టాల అమలును పర్యవేక్షిస్తుంది; విద్యా హక్కు, పోక్సో, జువెనైల్ జస్టిస్ చట్టాలు దీనికి అదనపు పర్యవేక్షణ బాధ్యతలు ఇచ్చాయి, కానీ వాటిలో ఏదీ దీనిని ఏర్పాటు చేయలేదు."},{"id":"t2023a-13","p":"t2023a","n":13,"s":"pol","t":"Governance, Schemes & Social Issues","q":"Name the scheme launched in India to improve nutritional outcomes for children, pregnant women, and lactating mothers in the year 2018.","w":"POSHAN Abhiyaan (Prime Minister's Overarching Scheme for Holistic Nourishment), the National Nutrition Mission, was launched on 8 March 2018 at Jhunjhunu, Rajasthan, to reduce stunting, undernutrition, anaemia and low birth weight among children, pregnant women and lactating mothers. It is now part of Mission Saksham Anganwadi and Poshan 2.0. PMMVY (2017) is a maternity cash benefit, and the other two are state girl-child schemes.","o":["Aapki Beti Hamari Beti","Pradhan Mantri Matru Vandhana Yojna","Kanya Kosh","Poshan Abhiyaan"],"a":[3],"qt":"2018 సంవత్సరంలో పిల్లలు, గర్భిణీ స్త్రీలు మరియు పాలిచ్చే తల్లులకు పోషకాహారాన్ని మెరుగుపరచడానికి భారతదేశంలో ప్రారంభించిన పథకం పేరును తెలపండి.","ot":["ఆప్కీ బేటీ హమారీ బేటీ","ప్రధాన మంత్రి మాతృ వందన యోజన","కన్యా కోష్","పోషణ్ అభియాన్"],"wt":"పోషణ్ అభియాన్ (ప్రైమ్ మినిస్టర్స్ ఓవరార్చింగ్ స్కీమ్ ఫర్ హోలిస్టిక్ నరిష్‌మెంట్) అనే జాతీయ పోషకాహార మిషన్‌ను 8 మార్చి 2018న రాజస్థాన్‌లోని ఝుంఝునులో ప్రారంభించారు; పిల్లలు, గర్భిణీ స్త్రీలు, పాలిచ్చే తల్లులలో ఎదుగుదల లోపం, పోషకాహార లోపం, రక్తహీనత, తక్కువ జనన బరువును తగ్గించడం దీని లక్ష్యం. ఇది ఇప్పుడు మిషన్ సక్షమ్ అంగన్‌వాడీ మరియు పోషణ్ 2.0లో భాగం. ప్రధాన మంత్రి మాతృ వందన యోజన (2017) ప్రసూతి నగదు ప్రయోజన పథకం; మిగిలిన రెండు రాష్ట్ర స్థాయి బాలికా పథకాలు."},{"id":"t2023a-14","p":"t2023a","n":14,"s":"cur","t":"National","q":"Which state did the National Green Tribunal (NGT) impose a fine of Rs. 100 crore industrial pollution in April 2023?","w":"In April 2023 the National Green Tribunal, headed by Justice Adarsh Kumar Goel, directed the State of Rajasthan to deposit ₹100 crore as interim environmental compensation for pollution of the Dravyavati river in Jaipur by textile printing units. The State may recover the amount from the polluting units and erring officials. The NGT was set up under the National Green Tribunal Act, 2010.","o":["Rajasthan","Gujarat","Assam","Goa"],"a":[0],"qt":"నేషనల్ గ్రీన్ ట్రిబ్యునల్ (NGT) ఏప్రిల్ 2023లో పారిశ్రామిక కాలుష్యానికి గాను రూ. 100 కోట్ల జరిమానాను ఏ రాష్ట్రానికి విధించింది?","ot":["రాజస్థాన్","గుజరాత్","అస్సాం","గోవా"],"wt":"ఏప్రిల్ 2023లో జస్టిస్ ఆదర్శ్ కుమార్ గోయెల్ అధ్యక్షతన గల నేషనల్ గ్రీన్ ట్రిబ్యునల్, జైపూర్‌లోని ద్రవ్యవతి నదిని వస్త్ర ముద్రణ (టెక్స్‌టైల్ ప్రింటింగ్) యూనిట్లు కలుషితం చేసినందుకు మధ్యంతర పర్యావరణ పరిహారంగా ₹100 కోట్లు జమ చేయాలని రాజస్థాన్ రాష్ట్రాన్ని ఆదేశించింది. ఈ మొత్తాన్ని కాలుష్యానికి కారణమైన యూనిట్లు, బాధ్యులైన అధికారుల నుంచి రాష్ట్రం వసూలు చేసుకోవచ్చు. NGT, నేషనల్ గ్రీన్ ట్రిబ్యునల్ చట్టం, 2010 కింద ఏర్పాటైంది."},{"id":"t2023a-15","p":"t2023a","n":15,"s":"cur","t":"National","q":"Which of the following is a popular mobile payment application used widely in India as of 2023?","w":"Paytm, run by the Noida-based One97 Communications, is one of India's most widely used mobile wallet and UPI payment apps. Interac is Canada's interbank payment network, Venmo is a PayPal-owned app used in the United States, and Square Cash (now Cash App, from Block Inc.) is also an American service. In 2024 the RBI curbed Paytm Payments Bank, but the app still offers UPI through partner banks.","o":["Interac","Venmo","Paytm","Square Cash"],"a":[2],"qt":"క్రింది వాటిలో 2023 నాటికి భారతదేశంలో విస్తృతంగా ఉపయోగించబడుతున్న ప్రముఖ మొబైల్ చెల్లింపు అప్లికేషన్ ఏది?","ot":["ఇంటరాక్","వెన్మో","Paytm","స్క్వేర్ క్యాష్"],"wt":"నోయిడాకు చెందిన వన్97 కమ్యూనికేషన్స్ నిర్వహించే Paytm భారతదేశంలో అత్యంత విస్తృతంగా ఉపయోగించే మొబైల్ వాలెట్, UPI చెల్లింపు యాప్‌లలో ఒకటి. ఇంటరాక్ కెనడాకు చెందిన అంతర్ బ్యాంకు చెల్లింపు నెట్‌వర్క్; వెన్మో అమెరికాలో వాడే పేపాల్ యాజమాన్యంలోని యాప్; స్క్వేర్ క్యాష్ (ఇప్పుడు బ్లాక్ ఇంక్. సంస్థకు చెందిన క్యాష్ యాప్) కూడా అమెరికా సేవే. 2024లో RBI పేటీఎం పేమెంట్స్ బ్యాంక్‌పై ఆంక్షలు విధించినా, ఈ యాప్ భాగస్వామి బ్యాంకుల ద్వారా UPI సేవలను కొనసాగిస్తోంది."},{"id":"t2023a-16","p":"t2023a","n":16,"s":"cur","t":"National","q":"Which of the following cities in India has been rated as the cleanest city in the Swachh Sarvekshan 2022 survey conducted by the Ministry of Housing and Urban Affairs?","w":"In Swachh Survekshan 2022, the annual cleanliness survey of the Ministry of Housing and Urban Affairs, Indore was declared India's cleanest city for the sixth year in a row, with Surat second and Navi Mumbai third; the results were announced on 1 October 2022. In Swachh Survekshan 2023 Indore shared the top spot with Surat.","o":["Indore","Surat","Bhopal","Varanasi"],"a":[0],"qt":"గృహ మరియు పట్టణ వ్యవహారాల మంత్రిత్వ శాఖ నిర్వహించిన స్వచ్ఛ సర్వేక్షణ్ 2022 సర్వేలో భారతదేశంలోని ఈ క్రింది నగరాల్లో అత్యంత పరిశుభ్రమైన నగరంగా రేట్ చేయబడిన నగరం ఏది?","ot":["ఇండోర్","సూరత్","భోపాల్","వారణాసి"],"wt":"గృహ, పట్టణ వ్యవహారాల మంత్రిత్వ శాఖ వార్షిక పరిశుభ్రత సర్వే అయిన స్వచ్ఛ సర్వేక్షణ్ 2022లో ఇండోర్ వరుసగా ఆరో ఏడాది భారతదేశంలో అత్యంత పరిశుభ్రమైన నగరంగా నిలిచింది; సూరత్ రెండో స్థానంలో, నవీ ముంబై మూడో స్థానంలో నిలిచాయి; ఫలితాలను 1 అక్టోబర్ 2022న ప్రకటించారు. స్వచ్ఛ సర్వేక్షణ్ 2023లో ఇండోర్ సూరత్‌తో కలిసి మొదటి స్థానాన్ని పంచుకుంది."},{"id":"t2023a-17","p":"t2023a","n":17,"s":"sci","t":"Biology & Health","q":"Which of the following diseases is caused by a virus and can be prevented by vaccination?","w":"Hepatitis B is caused by the hepatitis B virus, which attacks the liver and spreads through blood, sexual contact and from mother to child; a safe vaccine prevents it and is given in India's Universal Immunisation Programme, starting with a birth dose. Malaria is caused by the Plasmodium protozoan and tuberculosis by a bacterium. Dengue is viral, but no dengue vaccine was in India's programme in 2023.","o":["Malaria","Tuberculosis","Hepatitis B","Dengue fever"],"a":[2],"qt":"క్రింది వాటిల్లో వైరస్ వల్ల సోకి, టీకా ద్వారా నివారించగలిగే వ్యాధి ఏది?","ot":["మలేరియా","క్షయవ్యాధి","హెపటైటిస్ B","డెంగ్యూ జ్వరం"],"wt":"హెపటైటిస్ B కాలేయంపై దాడి చేసే హెపటైటిస్ B వైరస్ వల్ల వస్తుంది; ఇది రక్తం, లైంగిక సంపర్కం ద్వారా, తల్లి నుంచి బిడ్డకు వ్యాపిస్తుంది. సురక్షితమైన టీకా దీనిని నివారిస్తుంది; భారతదేశ సార్వత్రిక టీకాల కార్యక్రమంలో పుట్టిన వెంటనే ఇచ్చే మోతాదుతో మొదలుపెట్టి దీనిని ఇస్తారు. మలేరియా ప్లాస్మోడియం అనే ప్రోటోజోవా వల్ల, క్షయ బ్యాక్టీరియా వల్ల వస్తాయి. డెంగ్యూ వైరస్ వ్యాధే అయినా, 2023లో భారత టీకాల కార్యక్రమంలో డెంగ్యూ టీకా లేదు."},{"id":"t2023a-18","p":"t2023a","n":18,"s":"env","t":"Environment & Ecology","q":"Which animal was declared as the National Aquatic Animal of India in 2022?","w":"The Gangetic river dolphin (Platanista gangetica) was declared India's National Aquatic Animal on 5 October 2009, not in 2022 as the question says; 2022 saw the first National Dolphin Day on 5 October. Found in the Ganga–Brahmaputra–Meghna river systems, it is an endangered species listed in Schedule I of the Wildlife (Protection) Act, and Project Dolphin was announced in 2020.","o":["Olive Ridley Turtle","Gangetic River Dolphin","Gharial","Blue Whale"],"a":[1],"qt":"2022 లో భారతదేశ జాతీయ జల జంతువుగా ప్రకటించబడిన జంతువు ఏది?","ot":["ఆలివ్ రిడ్లీ తాబేలు","గంగా నది డాల్ఫిన్","మొసలి (ఘరియాల్)","నీలి తిమింగలం"],"wt":"గంగా నది డాల్ఫిన్ (ప్లాటానిస్టా గాంజెటికా)ను 5 అక్టోబర్ 2009న భారతదేశ జాతీయ జల జంతువుగా ప్రకటించారు, ప్రశ్నలో ఉన్నట్లు 2022లో కాదు; 2022లో అక్టోబర్ 5న మొదటి జాతీయ డాల్ఫిన్ దినోత్సవం జరిగింది. గంగా–బ్రహ్మపుత్ర–మేఘన నదీ వ్యవస్థల్లో కనిపించే ఈ జీవి అంతరించిపోయే ప్రమాదంలో ఉన్న జాతి, వన్యప్రాణి (సంరక్షణ) చట్టం షెడ్యూల్ Iలో ఉంది; 2020లో ప్రాజెక్ట్ డాల్ఫిన్‌ను ప్రకటించారు."},{"id":"t2023a-19","p":"t2023a","n":19,"s":"sci","t":"Biology & Health","q":"Which of the following is NOT an organ of the human body?","w":"Photophores are light-producing organs found in many deep-sea fishes, squids and some crustaceans, which use bioluminescence for camouflage, signalling or attracting prey; humans have no such organ. The liver (the largest gland), the oesophagus (food pipe) and the small intestine (where most digestion and absorption take place) are all organs of the human digestive system.","o":["Photophores","Liver","Esophagus","Small intestine"],"a":[0],"qt":"క్రింది వాటిలో మానవ శరీరంలోని అవయవం కానిది ఏది?","ot":["ఫోటోఫోర్స్","కాలేయం","అన్నవాహిక","చిన్న ప్రేగు"],"wt":"ఫోటోఫోర్‌లు అనేక లోతైన సముద్ర చేపలు, స్క్విడ్‌లు, కొన్ని క్రస్టేషియన్‌లలో ఉండే కాంతిని ఉత్పత్తి చేసే అవయవాలు; ఆ జీవులు జీవదీప్తిని (బయోలుమినిసెన్స్) మారువేషానికి, సంకేతాలు ఇవ్వడానికి లేదా ఎరను ఆకర్షించడానికి ఉపయోగిస్తాయి; మానవులకు అలాంటి అవయవం లేదు. కాలేయం (అతిపెద్ద గ్రంథి), అన్నవాహిక (ఆహార నాళం), చిన్న ప్రేగు (ఎక్కువ భాగం జీర్ణక్రియ, శోషణ జరిగే చోటు) అన్నీ మానవ జీర్ణవ్యవస్థ అవయవాలే."},{"id":"t2023a-20","p":"t2023a","n":20,"s":"sci","t":"Biology & Health","q":"Which of the following is an example of a macromolecule?","w":"Macromolecules are very large molecules, usually polymers built from smaller units; DNA is a polymer of nucleotides whose molecular mass runs into millions of daltons. Proteins, polysaccharides such as starch, and nucleic acids are the main biological macromolecules. Water (18 u), glucose (180 u) and sodium chloride (about 58.4 u, an ionic compound) are small molecules or formula units.","o":["Water","Glucose","Sodium chloride","Deoxyribonucleic acid (DNA)"],"a":[3],"qt":"క్రింది వాటిలో బృహదనువుకు ఉదాహరణ ఏది?","ot":["నీరు","గ్లూకోజ్","సోడియం క్లోరైడ్","డియోక్సిరైబోన్యూక్లిక్ యాసిడ్ (DNA)"],"wt":"బృహదణువులు (స్థూల అణువులు) చాలా పెద్ద అణువులు, సాధారణంగా చిన్న యూనిట్లతో నిర్మితమైన పాలిమర్లు; DNA న్యూక్లియోటైడ్ల పాలిమర్, దాని అణు ద్రవ్యరాశి మిలియన్ల డాల్టన్ల వరకు ఉంటుంది. ప్రోటీన్లు, పిండిపదార్థం వంటి పాలిశాకరైడ్లు, న్యూక్లిక్ ఆమ్లాలు ప్రధాన జీవ బృహదణువులు. నీరు (18 u), గ్లూకోజ్ (180 u), సోడియం క్లోరైడ్ (సుమారు 58.4 u, ఒక అయానిక సమ్మేళనం) చిన్న అణువులు లేదా ఫార్ములా యూనిట్లు."},{"id":"t2023a-21","p":"t2023a","n":21,"s":"sci","t":"Biology & Health","q":"Which of the following is required to increase the absorption of iron in the human body?","w":"Vitamin C (ascorbic acid) increases the absorption of non-haem iron from plant foods by reducing ferric iron (Fe³⁺) to the more soluble ferrous form (Fe²⁺) and keeping it in solution in the intestine. Phytates in cereals and pulses, calcium, and polyphenols such as the tannins in tea and coffee all inhibit iron absorption, which is why tea with meals can worsen iron-deficiency anaemia.","o":["Phytate","Vitamin C","Calcium","Polyphenols"],"a":[1],"qt":"మానవ శరీరంలో ఇనుము శోషణను పెంచడానికి ఈ క్రింది వాటిలో అవసరమైనది ఏది?","ot":["ఫైటేట్","విటమిన్ C","కాల్షియం","పాలీఫెనాల్స్"],"wt":"విటమిన్ C (ఆస్కార్బిక్ ఆమ్లం) ఫెర్రిక్ ఇనుము (Fe³⁺)ను ఎక్కువగా కరిగే ఫెర్రస్ రూపం (Fe²⁺)గా క్షయకరణం చేసి, ప్రేగులో ద్రావణంలో ఉంచడం ద్వారా వృక్ష ఆహారాల నుంచి వచ్చే నాన్-హీమ్ ఇనుము శోషణను పెంచుతుంది. తృణధాన్యాలు, పప్పుధాన్యాల్లోని ఫైటేట్లు, కాల్షియం, టీ, కాఫీల్లోని టానిన్‌ల వంటి పాలీఫెనాల్స్ ఇనుము శోషణను అడ్డుకుంటాయి; అందుకే భోజనంతో పాటు టీ తాగడం ఇనుము లోప రక్తహీనతను పెంచవచ్చు."},{"id":"t2023a-22","p":"t2023a","n":22,"s":"env","t":"Environment & Ecology","q":"Which of the following is a type of ecological succession that occurs in an area that was previously devoid of life?","w":"Primary succession begins where no life or soil existed before, such as bare rock, fresh lava, newly formed sand dunes or a new pond, with pioneer species like lichens colonising first; it is very slow. Secondary succession occurs where an existing community has been destroyed but soil remains, as in abandoned farmland or a burnt forest. \"Pioneer\" describes the first species, not a separate type of succession.","o":["Primary succession","Secondary succession","Tertiary succession","Pioneer succession"],"a":[0],"qt":"క్రింది వాటిలో మునుపు జీవం లేని ప్రాంతంలో సంభవించే ఒక రకమైన పర్యావరణ అనుక్రమణ ఏది?","ot":["ప్రాథమిక అనుక్రమణ","ద్వితీయ అనుక్రమణ","తృతీయ అనుక్రమణ","మార్గదర్శక అనుక్రమణ"],"wt":"ప్రాథమిక అనుక్రమణ ఇంతకు ముందు జీవం గానీ నేల గానీ లేని చోట, అంటే బండరాయి, కొత్త లావా, కొత్తగా ఏర్పడిన ఇసుక దిబ్బలు లేదా కొత్త చెరువులో మొదలవుతుంది; లైకెన్‌ల వంటి మార్గదర్శక జాతులు మొదట స్థిరపడతాయి; ఇది చాలా నెమ్మదిగా జరుగుతుంది. ఉన్న జీవ సమాజం నాశనమైనా నేల మిగిలి ఉన్న చోట, ఉదాహరణకు వదిలేసిన పొలాలు లేదా కాలిపోయిన అడవిలో, ద్వితీయ అనుక్రమణ జరుగుతుంది. \"మార్గదర్శక\" అనేది మొదట వచ్చే జాతులను సూచిస్తుంది, అది ప్రత్యేక అనుక్రమణ రకం కాదు."},{"id":"t2023a-23","p":"t2023a","n":23,"s":"sci","t":"Chemistry","q":"Which of the following cooking methods involves a chemical reaction that results in the formation of a new substance?","w":"Baking a cake is a chemical change: heat makes baking soda or baking powder release carbon dioxide, egg proteins set, and sugars and proteins undergo caramelisation and Maillard browning, producing new substances that cannot be turned back into batter. Boiling corn and steaming vegetables are mainly physical changes. Frying chicken also browns by the Maillard reaction, so the options are loosely framed, but the key takes baking, the textbook example.","o":["Boiling corn","Frying a chicken","Steaming vegetables","Baking a cake"],"a":[3],"qt":"క్రింది వాటిలో వండినప్పుడు ఒక కొత్త పదార్ధం ఏర్పడే రసాయన చర్య ఏది?","ot":["ఉడకబెట్టిన మొక్కజొన్న","చికెన్ను వేయించడం","కూరగాయలకు ఆవిరి పట్టడం","కేక్ను బేక్ చేయడం"],"wt":"కేక్ బేక్ చేయడం రసాయన మార్పు: వేడికి బేకింగ్ సోడా లేదా బేకింగ్ పౌడర్ కార్బన్ డయాక్సైడ్‌ను విడుదల చేస్తుంది, గుడ్డు ప్రోటీన్లు గట్టిపడతాయి, చక్కెరలు, ప్రోటీన్లు కారమెలీకరణ, మైలార్డ్ బ్రౌనింగ్‌కు లోనవుతాయి; దీనివల్ల తిరిగి పిండి మిశ్రమంగా మార్చలేని కొత్త పదార్థాలు ఏర్పడతాయి. మొక్కజొన్న ఉడకబెట్టడం, కూరగాయలకు ఆవిరి పట్టడం ప్రధానంగా భౌతిక మార్పులు. చికెన్ వేయించినప్పుడు కూడా మైలార్డ్ చర్య వల్ల గోధుమ రంగు వస్తుంది కాబట్టి ఎంపికలు కచ్చితంగా రూపొందించలేదు, కానీ కీ పాఠ్యపుస్తక ఉదాహరణ అయిన బేకింగ్‌నే తీసుకుంది."},{"id":"t2023a-24","p":"t2023a","n":24,"s":"env","t":"Disaster Management","q":"Which of the following regions in India is particularly vulnerable to sea-level rise, tropical cyclones, and riverine flooding?","w":"Mumbai, a low-lying coastal megacity built partly on reclaimed land along the Arabian Sea, faces sea-level rise, storm surges from Arabian Sea cyclones such as Nisarga (2020) and Tauktae (2021), and flooding from heavy monsoon rain and the Mithi river, as in the July 2005 deluge. Patna lies on the Ganga and floods, but it is inland, as are Jhansi and Indore, so none faces sea-level rise or cyclones.","o":["Patna","Mumbai","Jhansi","Indore"],"a":[1],"qt":"క్రింది వాటిలో భారతదేశంలోని సముద్ర మట్టం పెరగడం, ఉష్ణమండల తుఫానులు మరియు నదీ ప్రవాహాలకు గురయ్యే ప్రాంతం ఏది?","ot":["పాట్నా","ముంబై","ఝాన్సీ","ఇండోర్"],"wt":"అరేబియా సముద్ర తీరంలో, పాక్షికంగా సముద్రం నుంచి పునరుద్ధరించిన భూమిపై నిర్మితమైన లోతట్టు తీర మహానగరం ముంబై సముద్ర మట్టం పెరుగుదల, నిసర్గ (2020), తౌక్టే (2021) వంటి అరేబియా సముద్ర తుఫానుల ఉప్పెనలు, జూలై 2005 జలప్రళయం లాంటి భారీ రుతుపవన వర్షాలు, మిథి నది వరదల ముప్పును ఎదుర్కొంటుంది. పాట్నా గంగా నది ఒడ్డున ఉండి వరదలకు గురైనా అది తీరానికి దూరంగా ఉంది; ఝాన్సీ, ఇండోర్ కూడా అంతే, కాబట్టి వాటికి సముద్ర మట్టం పెరుగుదల, తుఫానుల ముప్పు లేదు."},{"id":"t2023a-25","p":"t2023a","n":25,"s":"env","t":"Disaster Management","q":"Choose the correct option based on the statements below:\nStatement 1: Disaster Risk Reduction (DRR) is the process of minimizing the impact of disasters on society through precautionary measures.\nStatement 2: Early warning systems are a critical component of disaster risk reduction.","w":"Both statements are true. Disaster risk reduction aims to prevent new and reduce existing disaster risk through measures such as hazard mapping, building codes, preparedness and awareness, thereby lessening the impact of disasters. Early warning systems, which let people evacuate and protect assets before a hazard strikes, are a core element: the Sendai Framework 2015–2030 has a target on multi-hazard early warning systems, and the UN's Early Warnings for All initiative aims at universal coverage by 2027.","o":["Only statement 1 is true","Only Statement 2 is true","Both statements are true","Neither statements are true"],"a":[2],"qt":"దిగువ తెలిపిన ప్రకటనల ఆధారంగా సరైన ఎంపికను ఎంచుకోండి:\nప్రకటన 1: డిజాస్టర్ రిస్క్ రిడక్షన్ (DRR) అనేది ముందు జాగ్రత్త చర్యల ద్వారా సమాజంపై విపత్తుల ప్రభావాన్ని తగ్గించే ప్రక్రియ.\nప్రకటన 2: ముందస్తు హెచ్చరిక వ్యవస్థలు విపత్తు ప్రమాదాన్ని తగ్గించడంలో కీలకమైన అంశం.","ot":["ప్రకటన 1 మాత్రమే సరైనది","ప్రకటన 2 మాత్రమే సరైనది","రెండు ప్రకటనలు సరైనవే","రెండు ప్రకటనలలో ఏదీ సరైనది కాదు"],"wt":"రెండు ప్రకటనలూ సరైనవే. విపత్తు ప్రమాద తగ్గింపు (DRR) ప్రమాద పటాల రూపకల్పన, భవన నిర్మాణ నియమాలు, సన్నద్ధత, అవగాహన వంటి చర్యల ద్వారా కొత్త విపత్తు ప్రమాదాలను నివారించి, ఉన్నవాటిని తగ్గించి, విపత్తుల ప్రభావాన్ని తగ్గించాలని లక్ష్యంగా పెట్టుకుంటుంది. విపత్తు రాకముందే ప్రజలను తరలించడానికి, ఆస్తులను కాపాడుకోవడానికి వీలు కల్పించే ముందస్తు హెచ్చరిక వ్యవస్థలు దీనిలో కీలక అంశం: సెండాయ్ ఫ్రేమ్‌వర్క్ 2015–2030లో బహుళ విపత్తు ముందస్తు హెచ్చరిక వ్యవస్థలపై ఒక లక్ష్యం ఉంది, ఐరాస 'ఎర్లీ వార్నింగ్స్ ఫర్ ఆల్' కార్యక్రమం 2027 నాటికి అందరికీ ఈ రక్షణ కల్పించాలని లక్ష్యంగా పెట్టుకుంది."},{"id":"t2023a-26","p":"t2023a","n":26,"s":"env","t":"Disaster Management","q":"Choose the correct option based on the statements below:\nStatement 1: Remote sensing and GIS technologies can be used for damage assessment before a disaster.\nStatement 2: Remote sensing and GIS technologies can be used for post-disaster damage assessment and reconstruction planning.","w":"Remote sensing and GIS serve the whole disaster-management cycle. Before a disaster they are used for hazard, risk and vulnerability mapping, i.e. estimating the likely damage and planning mitigation; after it, satellite images compared with pre-disaster images show the extent of damage, and GIS layers help plan relief and reconstruction. The key treats both statements as true.","o":["Only statement 1 is true","Only Statement 2 is true","Both statements are true","Neither statements are true"],"a":[2],"qt":"దిగువ ప్రకటనల ఆధారంగా సరైన ఎంపికను ఎంచుకోండి:\nప్రకటన 1: విపత్తుకు ముందు నష్టాన్ని అంచనా వేయడానికి రిమోట్ సెన్సింగ్ మరియు GIS సాంకేతికతలను ఉపయోగించవచ్చు.\nప్రకటన 2: రిమోట్ సెన్సింగ్ మరియు GIS సాంకేతికతలను విపత్తు అనంతర నష్టం అంచనా మరియు పునర్నిర్మాణ ప్రణాళిక కోసం ఉపయోగించవచ్చు.","ot":["ప్రకటన 1 మాత్రమే సరైనది","ప్రకటన 2 మాత్రమే సరైనది","రెండు ప్రకటనలు సరైనవే","రెండు ప్రకటనలలో ఏదీ సరైనది కాదు"],"wt":"రిమోట్ సెన్సింగ్, GIS విపత్తు నిర్వహణ చక్రం మొత్తంలో ఉపయోగపడతాయి. విపత్తుకు ముందు ప్రమాద, దుర్బలత్వ పటాల (hazard, risk, vulnerability mapping) ద్వారా సంభవించగల నష్టాన్ని అంచనా వేయడానికి, నివారణ చర్యల ప్రణాళికకు వీటిని వాడతారు; విపత్తు తర్వాత విపత్తుకు ముందటి ఉపగ్రహ చిత్రాలతో పోల్చి నష్టం పరిధిని తెలుసుకోవచ్చు, GIS పొరల సహాయంతో సహాయ, పునర్నిర్మాణ ప్రణాళిక రూపొందించవచ్చు. కీ రెండు ప్రకటనలనూ సరైనవిగా పరిగణించింది."},{"id":"t2023a-27","p":"t2023a","n":27,"s":"env","t":"Environment & Ecology","q":"Choose the correct option based on the statements below:\nStatement 1: Air pollution is caused only by human activities.\nStatement 2: Planting more trees can significantly reduce air pollution levels.","w":"Air pollution also has natural sources, such as volcanic eruptions, forest fires, dust storms, pollen and sea salt, so Statement 1 is false. Trees absorb gases such as sulphur dioxide, nitrogen dioxide and ozone and trap particulate matter on their leaves, so large-scale planting and green belts help lower pollution levels; the key accepts Statement 2 as true, making option 2 correct.","o":["Only Statement 1 is true","Only Statement 2 is true","Both statements are true","Neither statements are true"],"a":[1],"qt":"దిగువ ప్రకటనల ఆధారంగా సరైన ఎంపికను ఎంచుకోండి:\nప్రకటన 1: వాయు కాలుష్యం కేవలం మానవ కార్యకలాపాల వల్ల మాత్రమే సంభవిస్తుంది.\nప్రకటన 2: ఎక్కువ చెట్లను నాటడం వల్ల వాయు కాలుష్య స్థాయిలు గణనీయంగా తగ్గుతాయి.","ot":["ప్రకటన 1 మాత్రమే సరైనది","ప్రకటన 2 మాత్రమే సరైనది","రెండు ప్రకటనలు సరైనవే","రెండు ప్రకటనలలో ఏదీ సరైనది కాదు"],"wt":"వాయు కాలుష్యానికి సహజ కారణాలు కూడా ఉన్నాయి — అగ్నిపర్వత విస్ఫోటనాలు, అడవి మంటలు, దుమ్ము తుఫానులు, పుప్పొడి, సముద్ర లవణం — కాబట్టి ప్రకటన 1 తప్పు. చెట్లు సల్ఫర్ డయాక్సైడ్, నైట్రోజన్ డయాక్సైడ్, ఓజోన్ వంటి వాయువులను గ్రహించి, ఆకులపై ధూళి కణాలను నిలుపుకుంటాయి; అందువల్ల పెద్ద ఎత్తున మొక్కలు నాటడం, హరిత వలయాలు కాలుష్య స్థాయిలను తగ్గిస్తాయి. కీ ప్రకటన 2ను సరైనదిగా అంగీకరించింది, కాబట్టి ఎంపిక 2 సరైనది."},{"id":"t2023a-28","p":"t2023a","n":28,"s":"env","t":"Environment & Ecology","q":"Choose the correct option based on the statements below:\nStatement 1: Marine pollution only affects marine life and ecosystems.\nStatement 2: Plastic pollution is the only form of marine pollution.","w":"Both statements say \"only\" and both are false. Marine pollution also harms people, through contaminated seafood (mercury poisoning caused Minamata disease), damaged fisheries, tourism and coastal livelihoods. Besides plastics, the sea is polluted by oil spills, sewage, agricultural run-off whose nutrients create dead zones, industrial chemicals, heavy metals and even underwater noise. Hence neither statement is true.","o":["Only statement 1 is true","Only Statement 2 is true","Both statements are true","Neither statements are true"],"a":[3],"qt":"దిగువ ప్రకటనల ఆధారంగా సరైన ఎంపికను ఎంచుకోండి:\nప్రకటన 1: సముద్ర కాలుష్యం సముద్ర జీవులు మరియు పర్యావరణ వ్యవస్థలను మాత్రమే ప్రభావితం చేస్తుంది.\nప్రకటన 2: ప్లాస్టిక్ కాలుష్యం అనేది సముద్ర కాలుష్యం యొక్క ఏకైక కారకం.","ot":["ప్రకటన 1 మాత్రమే సరైనది","ప్రకటన 2 మాత్రమే సరైనది","రెండు ప్రకటనలు సరైనవే","రెండు ప్రకటనలలో ఏదీ సరైనది కాదు"],"wt":"రెండు ప్రకటనల్లోనూ 'మాత్రమే' అనే మాట ఉంది, రెండూ తప్పు. సముద్ర కాలుష్యం మనుషులకూ హాని చేస్తుంది — కలుషితమైన సముద్ర ఆహారం (పాదరస విషప్రభావం వల్లే మినమాటా వ్యాధి వచ్చింది), దెబ్బతిన్న చేపల వేట, పర్యాటకం, తీర ప్రాంత జీవనోపాధి ద్వారా. ప్లాస్టిక్‌తో పాటు చమురు తెట్టులు, మురుగునీరు, 'డెడ్ జోన్లు' సృష్టించే పోషకాలతో కూడిన వ్యవసాయ వ్యర్థ జలాలు, పారిశ్రామిక రసాయనాలు, భార లోహాలు, నీటి అడుగున శబ్దం కూడా సముద్రాన్ని కలుషితం చేస్తాయి. కాబట్టి రెండు ప్రకటనలలో ఏదీ సరైనది కాదు."},{"id":"t2023a-29","p":"t2023a","n":29,"s":"env","t":"Environment & Ecology","q":"Choose the correct option based on the statements below:\nStatement 1: Greenhouse gases trap heat in the Earth's atmosphere, leading to the greenhouse effect.\nStatement 2: The main greenhouse gases include carbon dioxide, methane, and nitrogen oxides","w":"Greenhouse gases let sunlight through but absorb the infrared radiation given off by the Earth, warming the lower atmosphere; this is the greenhouse effect. The main greenhouse gases are water vapour, carbon dioxide, methane, nitrous oxide and fluorinated gases. Strictly, the nitrogen oxide that acts as a greenhouse gas is nitrous oxide (N₂O), but the key treats Statement 2 as true, so both statements are correct.","o":["Only statement 1 is true","Only Statement 2 is true","Both statements are true","Neither statements are true"],"a":[2],"qt":"దిగువ ప్రకటనల ఆధారంగా సరైన ఎంపికను ఎంచుకోండి:\nప్రకటన 1: గ్రీన్ హౌజ్ వాయువులు భూమి యొక్క వాతావరణంలో వేడిని బంధిస్తాయి, ఇది గ్రీన్ హౌజ్ ప్రభావానికి దారి తీస్తుంది.\nప్రకటన 2: ప్రధాన గ్రీన్ హౌజ్ వాయువులలో కార్బన్ డయాక్సైడ్, మీథేన్ మరియు నైట్రోజన్ ఆక్సైడ్లు కలవు","ot":["ప్రకటన 1 మాత్రమే సరైనది","ప్రకటన 2 మాత్రమే సరైనది","రెండు ప్రకటనలు సరైనవే","రెండు ప్రకటనలలో ఏదీ సరైనది కాదు"],"wt":"గ్రీన్ హౌజ్ వాయువులు సూర్యకాంతిని లోపలికి రానిస్తాయి కానీ భూమి విడుదల చేసే పరారుణ వికిరణాన్ని గ్రహించి దిగువ వాతావరణాన్ని వేడెక్కిస్తాయి; ఇదే గ్రీన్ హౌజ్ ప్రభావం. ప్రధాన గ్రీన్ హౌజ్ వాయువులు నీటి ఆవిరి, కార్బన్ డయాక్సైడ్, మీథేన్, నైట్రస్ ఆక్సైడ్, ఫ్లోరినేటెడ్ వాయువులు. ఖచ్చితంగా చెప్పాలంటే గ్రీన్ హౌజ్ వాయువుగా పనిచేసే నైట్రోజన్ ఆక్సైడ్ నైట్రస్ ఆక్సైడ్ (N₂O); అయినా కీ ప్రకటన 2ను సరైనదిగా పరిగణించింది, కాబట్టి రెండు ప్రకటనలూ సరైనవి."},{"id":"t2023a-30","p":"t2023a","n":30,"s":"env","t":"Environment & Ecology","q":"Choose the correct option based on the statements below:\nStatement 1: Ozone depletion is caused by human-made chemicals such as chlorofluorocarbons (CFCs).\nStatement 2: Ozone depletion only occurs in the lower atmosphere where humans live.","w":"Ozone depletion is caused by man-made chlorine and bromine compounds such as CFCs, halons, carbon tetrachloride and methyl chloroform, which release chlorine and bromine atoms that destroy ozone. It takes place in the stratosphere, about 15–35 km up, where the ozone layer lies (most dramatically as the Antarctic ozone hole), not in the lower atmosphere where humans live. Only Statement 1 is true.","o":["Only statement 1 is true","Only Statement 2 is true","Both statements are true","Neither statements are true"],"a":[0],"qt":"దిగువ ప్రకటనల ఆధారంగా సరైన ఎంపికను ఎంచుకోండి:\nప్రకటన 1: క్లోరోఫ్లోరో కార్బన్స్ (CFCలు) వంటి మానవ నిర్మిత రసాయనాల వల్ల ఓజోన్ క్షీణత ఏర్పడుతుంది.\nప్రకటన 2: ఓజోన్ క్షీణత మానవులు నివసించే దిగువ వాతావరణంలో మాత్రమే సంభవిస్తుంది.","ot":["ప్రకటన 1 మాత్రమే సరైనది","ప్రకటన 2 మాత్రమే సరైనది","రెండు ప్రకటనలు సరైనవే","రెండు ప్రకటనలలో ఏదీ సరైనది కాదు"],"wt":"CFCలు, హాలోన్లు, కార్బన్ టెట్రాక్లోరైడ్, మిథైల్ క్లోరోఫామ్ వంటి మానవ నిర్మిత క్లోరిన్, బ్రోమిన్ సమ్మేళనాలు ఓజోన్ క్షీణతకు కారణం; వీటి నుంచి విడుదలయ్యే క్లోరిన్, బ్రోమిన్ పరమాణువులు ఓజోన్‌ను నాశనం చేస్తాయి. ఈ క్షీణత ఓజోన్ పొర ఉన్న స్ట్రాటోస్ఫియర్‌లో, సుమారు 15–35 కి.మీ. ఎత్తులో జరుగుతుంది (అంటార్కిటికా ఓజోన్ రంధ్రం దీనికి ప్రముఖ ఉదాహరణ), మానవులు నివసించే దిగువ వాతావరణంలో కాదు. ప్రకటన 1 మాత్రమే సరైనది."},{"id":"t2023a-31","p":"t2023a","n":31,"s":"env","t":"Environment & Ecology","q":"Choose the correct option based on the statements below:\nStatement 1: Deforestation leads to loss of biodiversity and ecosystem services.\nStatement 2: The government of India has established community-based forest management systems to involve local communities in the conservation and management of forest resources.","w":"Clearing forests destroys habitats and species, and the ecosystem services forests give, such as soil and water conservation, carbon storage and rainfall regulation. India involves local people through Joint Forest Management (from 1990), in which village forest protection committees share forest produce, and through community forest resource rights under the Forest Rights Act, 2006. Both statements are true.","o":["Only statement 1 is true","Only Statement 2 is true","Both statements are true","Neither statements are true"],"a":[2],"qt":"దిగువ ప్రకటనల ఆధారంగా సరైన ఎంపికను ఎంచుకోండి:\nప్రకటన 1: అటవీ నిర్మూలన జీవవైవిధ్యం మరియు పర్యావరణ వ్యవస్థ సేవల నష్టానికి దారితీస్తుంది.\nప్రకటన 2: అటవీ వనరుల సంరక్షణ మరియు నిర్వహణలో స్థానిక సంఘాలను భాగస్వామ్యం చేయడానికి భారత ప్రభుత్వం కమ్యూనిటీ-ఆధారిత అటవీ నిర్వహణ వ్యవస్థలను ఏర్పాటు చేసింది.","ot":["ప్రకటన 1 మాత్రమే సరైనది","ప్రకటన 2 మాత్రమే సరైనది","రెండు ప్రకటనలు సరైనవే","రెండు ప్రకటనలలో ఏదీ సరైనది కాదు"],"wt":"అడవులను నరికివేయడం వల్ల ఆవాసాలు, జీవజాతులు నశిస్తాయి; నేల, నీటి సంరక్షణ, కార్బన్ నిల్వ, వర్షపాత నియంత్రణ వంటి అడవులు అందించే పర్యావరణ వ్యవస్థ సేవలూ దెబ్బతింటాయి. భారత ప్రభుత్వం ఉమ్మడి అటవీ నిర్వహణ (Joint Forest Management, 1990 నుంచి) ద్వారా గ్రామ అటవీ సంరక్షణ కమిటీలకు అటవీ ఉత్పత్తుల్లో వాటా ఇస్తూ, అటవీ హక్కుల చట్టం, 2006 కింద సామూహిక అటవీ వనరుల హక్కులు కల్పిస్తూ స్థానిక ప్రజలను భాగస్వాములను చేసింది. రెండు ప్రకటనలూ సరైనవి."},{"id":"t2023a-32","p":"t2023a","n":32,"s":"env","t":"Environment & Ecology","q":"Choose the correct option based on the statements below:\nStatement 1: Biodegradable plastics are a better alternative to traditional plastics.\nStatement 2: The production of some biodegradable plastics requires large amounts of energy and resources, and their disposal can still contribute to environmental pollution.","w":"Biodegradable plastics break down far faster than conventional plastics and are promoted as a better alternative. But some are made from crops that need land, water, fertiliser and energy, many break down only in industrial composting conditions, and in landfills or the sea they can persist or release methane and microplastics. Both statements are therefore true.","o":["Only statement 1 is true","Only Statement 2 is true","Both statements are true","Neither statements are true"],"a":[2],"qt":"దిగువ ప్రకటనల ఆధారంగా సరైన ఎంపికను ఎంచుకోండి:\nప్రకటన 1: జీవశైథిల్య ప్లాస్టిక్‌లు సాంప్రదాయ ప్లాస్టిక్‌లకు మంచి ప్రత్యామ్నాయం.\nప్రకటన 2: కొన్ని జీవశైథిల్య ప్లాస్టిక్‌ల ఉత్పత్తికి పెద్ద మొత్తంలో శక్తి మరియు వనరులు అవసరమవుతాయి మరియు వాటిని పారవేయడం ఇప్పటికీ పర్యావరణ కాలుష్యానికి దోహదం చేస్తుంది.","ot":["ప్రకటన 1 మాత్రమే సరైనది","ప్రకటన 2 మాత్రమే సరైనది","రెండు ప్రకటనలు సరైనవే","రెండు ప్రకటనలలో ఏదీ సరైనది కాదు"],"wt":"జీవశైథిల్య ప్లాస్టిక్‌లు సాంప్రదాయ ప్లాస్టిక్‌ల కంటే చాలా త్వరగా విచ్ఛిన్నమవుతాయి కాబట్టి వీటిని మెరుగైన ప్రత్యామ్నాయంగా ప్రోత్సహిస్తున్నారు. అయితే కొన్నింటిని భూమి, నీరు, ఎరువులు, శక్తి అవసరమయ్యే పంటల నుంచి తయారు చేస్తారు; చాలావరకు పారిశ్రామిక కంపోస్టింగ్ పరిస్థితుల్లో మాత్రమే విచ్ఛిన్నమవుతాయి; చెత్త కుప్పల్లో లేదా సముద్రంలో అవి చాలాకాలం మిగిలిపోవచ్చు లేదా మీథేన్, సూక్ష్మ ప్లాస్టిక్‌లను విడుదల చేయవచ్చు. కాబట్టి రెండు ప్రకటనలూ సరైనవి."},{"id":"t2023a-33","p":"t2023a","n":33,"s":"env","t":"Environment & Ecology","q":"Choose the correct option based on the statements below:\nStatement 1: The ozone layer is essential to protect living organisms from harmful ultraviolet (UV) radiation from the sun.\nStatement 2: The Montreal Protocol, an international agreement, was successful in phasing out the production of ozone-depleting substances.","w":"The stratospheric ozone layer absorbs most of the sun's harmful UV-B and all UV-C radiation, which would otherwise cause skin cancer and cataracts and damage plants and marine life. The Montreal Protocol (1987), the first treaty ratified by every UN member state, has phased out about 99% of ozone-depleting substances, and the ozone layer is on course to recover. Both statements are true.","o":["Only statement 1 is true","Only Statement 2 is true","Both statements are true","Neither statements are true"],"a":[2],"qt":"దిగువ ప్రకటనల ఆధారంగా సరైన ఎంపికను ఎంచుకోండి:\nప్రకటన 1: సూర్యుడి నుండి వచ్చే హానికరమైన అతినీలలోహిత (UV) వికిరణాల నుండి జీవులను రక్షించడానికి ఓజోన్ పొర అవసరం.\nప్రకటన 2: మాంట్రియల్ ప్రోటోకాల్, అనే అంతర్జాతీయ ఒప్పందం, ఓజోన్ ని-క్షీణింపజేసే పదార్థాల ఉత్పత్తిని దశలవారీగా తగ్గించడంలో విజయవంతమైంది.","ot":["ప్రకటన 1 మాత్రమే సరైనది","ప్రకటన 2 మాత్రమే సరైనది","రెండు ప్రకటనలు సరైనవే","రెండు ప్రకటనలలో ఏదీ సరైనది కాదు"],"wt":"స్ట్రాటోస్ఫియర్‌లోని ఓజోన్ పొర సూర్యుని నుంచి వచ్చే హానికరమైన UV-B వికిరణంలో ఎక్కువ భాగాన్ని, UV-C వికిరణాన్ని పూర్తిగా గ్రహిస్తుంది; లేకపోతే చర్మ క్యాన్సర్, కంటిశుక్లం వస్తాయి, మొక్కలకు, సముద్ర జీవులకు నష్టం కలుగుతుంది. ఐక్యరాజ్యసమితి సభ్య దేశాలన్నీ ఆమోదించిన మొదటి ఒప్పందమైన మాంట్రియల్ ప్రోటోకాల్ (1987) ఓజోన్‌ను క్షీణింపజేసే పదార్థాల్లో సుమారు 99% ను దశలవారీగా తొలగించింది; ఓజోన్ పొర కోలుకునే దిశలో ఉంది. రెండు ప్రకటనలూ సరైనవి."},{"id":"t2023a-34","p":"t2023a","n":34,"s":"geo","t":"Indian Geography","q":"Which of the following statements are true regarding the monsoon climate of India?\nA. It brings rainfall during the summer season\nB. It is caused by the differential heating of land and water\nC. It affects only the coastal regions of India\nD. It is responsible for 80-90% of the rainfall in India","w":"The south-west monsoon brings rain in summer (June–September); it arises from the differential heating of the Asian landmass and the surrounding seas, which sets up the pressure gradient that draws moist winds inland. It affects almost the whole country, not just the coasts, so C is false. The south-west monsoon alone gives about three-quarters of India's annual rainfall, and with the retreating (north-east) monsoon the share exceeds 80%. Hence A, B and D.","o":["Only statement D is true","Only statements A and B are true","Only statements A, B and C are true","Only statements A, B and D are true"],"a":[3],"qt":"భారతదేశంలోని రుతుపవన వాతావరణానికి సంబంధించి ఈ క్రింది ప్రకటనలలో నిజమైనది ఏది?\nA. ఇది వేసవి కాలంలో వర్షపాతాన్ని తెస్తుంది\nB. ఇది భూమి మరియు నీటి యొక్క భేదాత్మక వేడి వలన ఏర్పడుతుంది\nC. ఇది భారతదేశంలోని తీర ప్రాంతాలను మాత్రమే ప్రభావితం చేస్తుంది\nD. భారతదేశంలో 80-90% వర్షపాతానికి ఇది బాధ్యత వహిస్తుంది","ot":["ప్రకటన D మాత్రమే సరైనది","A మరియు B ప్రకటనలు మాత్రమే సరైనవి","A, B మరియు C ప్రకటనలు మాత్రమే సరైనవి","A, B మరియు D ప్రకటనలు మాత్రమే సరైనవి"],"wt":"నైరుతి రుతుపవనాలు వేసవిలో (జూన్–సెప్టెంబర్) వర్షాన్ని తెస్తాయి; ఆసియా భూభాగం, చుట్టూ ఉన్న సముద్రాలు వేర్వేరుగా వేడెక్కడం వల్ల ఏర్పడే పీడన వ్యత్యాసమే తేమతో కూడిన గాలులను భూభాగం వైపు లాగుతుంది. ఇవి తీర ప్రాంతాలనే కాకుండా దాదాపు దేశమంతటినీ ప్రభావితం చేస్తాయి, కాబట్టి C తప్పు. దేశ వార్షిక వర్షపాతంలో సుమారు మూడు వంతులు నైరుతి రుతుపవనాల నుంచే వస్తుంది; తిరోగమన (ఈశాన్య) రుతుపవనాలను కలిపితే ఈ వాటా 80% దాటుతుంది. కాబట్టి A, B, D సరైనవి."},{"id":"t2023a-35","p":"t2023a","n":35,"s":"geo","t":"Indian Geography","q":"Which of the following statements about natural resources in India is/are correct?\nI. India has abundant reserves of coal, iron ore, and bauxite.\nII. India has the world's smallest reserve of thorium.\nIII. India is in top 5 countries producing of crude oil and natural gas per year.\nIV. Major Lithium deposits have been discovered in Kashmir.","w":"I is true: India has large reserves of coal, iron ore and bauxite. II is false: its monazite sands give India one of the world's largest thorium reserves, the basis of its three-stage nuclear programme. III is false: India produces only about 30 million tonnes of crude oil a year and imports most of its needs. IV is true: in February 2023 the GSI reported 5.9 million tonnes of inferred lithium resources in Reasi district, Jammu and Kashmir.","o":["I and II","I, II, and III","I and IV","I, II, III, and IV"],"a":[2],"qt":"భారతదేశంలోని సహజ వనరుల గురించి ఈ క్రింది వాటిలో సరైనది/వి ఏది/వి?\nI. భారతదేశంలో బొగ్గు, ఇనుప ఖనిజం మరియు బాక్సైట్ నిల్వలు పుష్కలంగా ఉన్నాయి.\nII. ప్రపంచంలోనే అతి తక్కువ థోరియం నిల్వలు భారత్‌లో కలవు.\nIII. ప్రతి సంవత్సరం ముడి చమురు మరియు సహజవాయువును ఉత్పత్తి చేసే అగ్ర 5 దేశాలలో భారతదేశం కలదు.\nIV. కాశ్మీర్‌లో పెద్ద మొత్తంలో లిథియం నిక్షేపాలు కనుగొనబడ్డాయి.","ot":["I మరియు II","I, II, మరియు III","I మరియు IV","I, II, III, మరియు IV"],"wt":"I సరైనది: భారతదేశంలో బొగ్గు, ఇనుప ఖనిజం, బాక్సైట్ నిల్వలు పుష్కలంగా ఉన్నాయి. II తప్పు: మోనజైట్ ఇసుకల వల్ల భారత్‌కు ప్రపంచంలోని అతిపెద్ద థోరియం నిల్వల్లో ఒకటి ఉంది; ఇదే మన మూడు దశల అణు కార్యక్రమానికి ఆధారం. III తప్పు: భారత్ ఏటా సుమారు 3 కోట్ల టన్నుల ముడి చమురు మాత్రమే ఉత్పత్తి చేస్తుంది, అవసరాల్లో అధిక భాగాన్ని దిగుమతి చేసుకుంటుంది. IV సరైనది: ఫిబ్రవరి 2023లో GSI జమ్మూ కాశ్మీర్‌లోని రియాసి జిల్లాలో 59 లక్షల టన్నుల (5.9 మిలియన్ టన్నుల) లిథియం అంచనా (inferred) వనరులను గుర్తించింది."},{"id":"t2023a-36","p":"t2023a","n":36,"s":"geo","t":"Indian Geography","q":"Which of the following statements about the Deccan Plateau are true?\na. It is located in the southern part of India.\nb. It is a volcanic plateau.\nc. It is a fertile region with black soil.\nd. It is the smallest plateau in India.","w":"The Deccan Plateau lies in peninsular (southern) India, between the Western and Eastern Ghats and south of the Satpura–Vindhya ranges. Its north-western part is built of basaltic lava flows, the Deccan Traps, which weather into fertile black (regur) soil ideal for cotton. It is India's largest plateau, not the smallest, so d is false and a, b and c are correct.","o":["Only statements a and b are true","Only statements c and b are true","Only statements a, b and c are true","Only statements c and d are true"],"a":[2],"qt":"దక్కన్ పీఠభూమికి సంబంధించి ఈ క్రింది వాటిలో సరైనవి ఏవి?\na. ఇది భారతదేశం యొక్క దక్షిణ భాగంలో కలదు.\nb. ఇది అగ్నిపర్వత పీఠభూమి.\nc. ఇది నల్ల రేగడి నేలతో కూడిన సారవంతమైన ప్రాంతం.\nd. ఇది భారతదేశంలోనే అతి చిన్న పీఠభూమి.","ot":["a మరియు b ప్రకటనలు మాత్రమే సరైనవి","c మరియు b ప్రకటనలు మాత్రమే సరైనవి","a, b మరియు c ప్రకటనలు మాత్రమే సరైనవి","c మరియు d ప్రకటనలు మాత్రమే సరైనవి"],"wt":"దక్కన్ పీఠభూమి ద్వీపకల్ప (దక్షిణ) భారతదేశంలో, పశ్చిమ, తూర్పు కనుమల మధ్య, సాత్పురా–వింధ్య శ్రేణులకు దక్షిణాన ఉంది. దీని వాయవ్య భాగం బసాల్ట్ లావా ప్రవాహాలతో (దక్కన్ ట్రాప్స్) ఏర్పడింది; ఇవి శైథిల్యం చెంది పత్తికి అనువైన సారవంతమైన నల్లరేగడి నేలలుగా మారాయి. ఇది భారతదేశంలోనే అతిపెద్ద పీఠభూమి, అతి చిన్నది కాదు; కాబట్టి d తప్పు, a, b, c సరైనవి."},{"id":"t2023a-37","p":"t2023a","n":37,"s":"geo","t":"Indian Geography","q":"Which of the following statements are true about the Western Ghats in India?\na) The Western Ghats is a mountain range that runs parallel to the western coast of India.\nb) It is a UNESCO World Heritage Site and a biodiversity hotspot.\nc) The Western Ghats are home to several endemic species of flora and fauna, including the Lion-tailed macaque and the Nilgiri Tahr.\nd) The vegetation along the Western Ghats includes tropical evergreen forests, semi-evergreen forests, and grasslands.","w":"All four statements are true. The Western Ghats (Sahyadri) run parallel to India's west coast from Gujarat to Kanyakumari; they were inscribed as a UNESCO World Heritage Site in 2012 and form part of the Western Ghats and Sri Lanka biodiversity hotspot. Endemic animals include the lion-tailed macaque and the Nilgiri tahr, and the vegetation ranges from tropical evergreen and semi-evergreen forests to the montane shola forests and grasslands.","o":["Statements a, b, c and d are true","Only statements a, b and d are true","Only statements b, c and d are true","Only statements c and d are true"],"a":[0],"qt":"భారతదేశంలోని పశ్చిమ కనుమలకు సంబంధించి ఈ క్రింది వాటిలో ఏది సరైనది?\na) పశ్చిమ కనుమలు భారతదేశంలోని పశ్చిమ తీరానికి సమాంతరంగా ఉన్న పర్వత శ్రేణి.\nb) ఇది UNESCO ప్రపంచ వారసత్వ ప్రదేశం మరియు జీవవైవిధ్యానికి ముఖ్య ప్రదేశం .\nc) పశ్చిమ కనుమలు అనేక స్థానిక జాతుల వృక్ష మరియు జంతుజాలాలకి నిలయంగా ఉన్నాయి, వీటిలో సింహం-తోక మకాక్ మరియు నీలగిరి తహర్ కలవు.\nd) పశ్చిమ కనుమల వెంబడి గల వృక్షసంపదలో ఉష్ణమండల సతత హరిత అరణ్యాలు, పాక్షిక-సతత హరిత అరణ్యాలు మరియు గడ్డి భూములు కలవు.","ot":["a, b, c మరియు d ప్రకటనలు సరైనవి","a, b మరియు d ప్రకటనలు మాత్రమే సరైనవి","b, c మరియు d ప్రకటనలు మాత్రమే సరైనవి","c మరియు d ప్రకటనలు మాత్రమే సరైనవి"],"wt":"నాలుగు ప్రకటనలూ సరైనవి. పశ్చిమ కనుమలు (సహ్యాద్రి) గుజరాత్ నుంచి కన్యాకుమారి వరకు భారతదేశ పశ్చిమ తీరానికి సమాంతరంగా విస్తరించి ఉన్నాయి; 2012లో UNESCO ప్రపంచ వారసత్వ ప్రదేశంగా గుర్తింపు పొందాయి, 'పశ్చిమ కనుమలు–శ్రీలంక' జీవవైవిధ్య హాట్‌స్పాట్‌లో భాగం. సింహం-తోక మకాక్, నీలగిరి తహర్ ఇక్కడి స్థానిక (endemic) జాతులు; వృక్షసంపద ఉష్ణమండల సతత హరిత, పాక్షిక-సతత హరిత అరణ్యాల నుంచి పర్వత ప్రాంతాల షోలా అరణ్యాలు, గడ్డి భూముల వరకు ఉంటుంది."},{"id":"t2023a-38","p":"t2023a","n":38,"s":"geo","t":"Indian Geography","q":"Which of the following statements about the demographic profile of India is/are true?\nA) India is the third most populous country in the world as of 2022.\nB) The population of India is predominantly rural.\nC) The sex ratio in India has been improving over the years.","w":"A is false: in 2022 India was the second most populous country, after China; UN estimates show India overtaking China in April 2023 to become the most populous. B is true: Census 2011 found 68.8% of Indians living in rural areas. C is accepted as true: the sex ratio rose from 933 (2001) to 943 females per 1,000 males (2011), and NFHS-5 (2019–21) recorded 1,020.","o":["Only statement B is true","Only statement C is true","Only statements B and C are true","Only statements A and C are true"],"a":[2],"qt":"భారతదేశం యొక్క జనసంఖ్యా సంబందమైన ప్రొఫైల్కు సంబంధించి ఈ క్రింది ప్రకటనల్లో ఏది/వి సరైనది/వి?\nA) 2022 నాటికి ప్రపంచంలో అత్యధిక జనాభా కలిగిన మూడవ దేశం భారతదేశం.\nB) భారతదేశంలోని జనాభా ప్రధానంగా గ్రామీణులు.\nC) భారతదేశంలో లింగ నిష్పత్తి కొన్ని సంవత్సరాలుగా మెరుగుపడుతోంది.","ot":["B ప్రకటన మాత్రమే సరైనది","C ప్రకటన మాత్రమే సరైనది","B మరియు C ప్రకటనలు మాత్రమే సరైనవి","A మరియు C ప్రకటనలు మాత్రమే సరైనవి"],"wt":"A తప్పు: 2022లో చైనా తర్వాత భారత్ రెండవ అత్యధిక జనాభా కలిగిన దేశం; ఐరాస అంచనాల ప్రకారం ఏప్రిల్ 2023లో భారత్ చైనాను అధిగమించి అత్యధిక జనాభా కలిగిన దేశమైంది. B సరైనది: 2011 జనాభా లెక్కల ప్రకారం 68.8% మంది భారతీయులు గ్రామీణ ప్రాంతాల్లో నివసిస్తున్నారు. C సరైనదిగా అంగీకరించబడింది: లింగ నిష్పత్తి 2001లో 933 నుంచి 2011లో 943 (ప్రతి 1,000 మంది పురుషులకు స్త్రీలు)కి పెరిగింది; NFHS-5 (2019–21) 1,020గా నమోదు చేసింది."},{"id":"t2023a-39","p":"t2023a","n":39,"s":"eco","t":"Indian Economy","q":"Which of the following factors contribute to poverty in India?\na. Excess of education and skills\nb. Unequal distribution of land and other resources\nc. Low wages and poor working conditions\nd. Gender inequality","w":"Poverty in India is linked to the unequal ownership of land and other assets, low wages and poor working conditions in the large informal sector, and gender inequality, which limits women's education, work and income. An excess of education and skills is not a cause; it is the lack of education and skills that keeps people poor. So statements b, c and d are correct.","o":["Only statements a and b are true","Only statements b, c and d are true","Only statements a, b and c are true","Only statements c and d are true"],"a":[1],"qt":"భారతదేశంలో పేదరికానికి ఈ క్రింది అంశాలలో దోహదం చేసేది ఏది?\na. మితిమీరిన విద్య మరియు నైపుణ్యాలు\nb. భూమి మరియు ఇతర వనరుల అసమాన పంపిణీ\nc. తక్కువ వేతనాలు మరియు అల్పమైన పని పరిస్థితులు\nd. లింగ అసమానత","ot":["a మరియు b ప్రకటనలు మాత్రమే సరైనవి","b, c మరియు d ప్రకటనలు మాత్రమే సరైనవి","a, b మరియు c ప్రకటనలు మాత్రమే సరైనవి","c మరియు d ప్రకటనలు మాత్రమే సరైనవి"],"wt":"భారతదేశంలో పేదరికానికి భూమి, ఇతర ఆస్తుల అసమాన పంపిణీ, విస్తారమైన అసంఘటిత రంగంలో తక్కువ వేతనాలు, అల్పమైన పని పరిస్థితులు, మహిళల విద్య, ఉపాధి, ఆదాయాన్ని పరిమితం చేసే లింగ అసమానత కారణాలు. మితిమీరిన విద్య, నైపుణ్యాలు పేదరికానికి కారణం కాదు; విద్య, నైపుణ్యాల లోపమే ప్రజలను పేదరికంలో ఉంచుతుంది. కాబట్టి b, c, d ప్రకటనలు సరైనవి."},{"id":"t2023a-40","p":"t2023a","n":40,"s":"ih","t":"Art & Culture","q":"Which of the following statements about Sikhism and Buddhism in India are true?\ni. Sikhism originated in the 15th century in Punjab, while Buddhism originated in India in the 6th century BCE.\nii. Both Sikhism and Buddhism accept the caste system and emphasize inequality among all people.\niii. The Golden Temple in Amritsar is a holy site for Sikhs, while Bodh Gaya is a holy site for Buddhists.\niv. Sikhism and Buddhism have a significant following in the Indian states of Punjab and Sikkim, respectively.","w":"i is true: Guru Nanak (born 1469) founded Sikhism in 15th-century Punjab, and the Buddha taught in the 6th century BCE. ii is false: both faiths rejected caste hierarchy and stressed the equality of all people. iii is true: the Golden Temple (Harmandir Sahib) and Bodh Gaya, where the Buddha attained enlightenment, are their holiest sites. iv is true: Census 2011 shows Sikhs form about 58% of Punjab's population and Buddhists about 27% of Sikkim's.","o":["i and ii","ii and iv","ii and iii","i, iii, and iv"],"a":[3],"qt":"భారతదేశంలోని సిక్కు మతం మరియు బౌద్ధమతానికి సంబందించిన ఈ క్రింది ప్రకటనల్లో ఏది సరైనది?\ni. భారతదేశంలో సిక్కు మతం పంజాబ్‌లో 15వ శతాబ్దంలో ఉద్భవించగా, బౌద్ధమతం 6వ శతాబ్దం BCEలో ఉద్భవించింది.\nii. సిక్కు మతం మరియు బౌద్ధమతం రెండూ కుల వ్యవస్థను అంగీకరిస్తాయి మరియు ప్రజలందరి మధ్య అసమానతను నొక్కి చెబుతున్నాయి.\niii. అమృత్‌సర్‌లోని స్వర్ణ దేవాలయం సిక్కులకు పవిత్ర స్థలం అయితే, బౌద్ధులకు బుద్ధ గయ పవిత్ర స్థలం.\niv. సిక్కుమతం మరియు బౌద్ధమతం భారతదేశంలోని పంజాబ్ మరియు సిక్కింలో వరుసగా గణనీయమైన అనుచరులను కలిగి ఉన్నాయి.","ot":["i మరియు ii","ii మరియు iv","ii మరియు iii","i, iii, మరియు iv"],"wt":"i సరైనది: గురు నానక్ (జననం 1469) 15వ శతాబ్దంలో పంజాబ్‌లో సిక్కు మతాన్ని స్థాపించారు; బుద్ధుడు క్రీ.పూ. 6వ శతాబ్దంలో బోధించారు. ii తప్పు: రెండు మతాలూ కుల అంతరాలను తిరస్కరించి, అందరి సమానత్వాన్ని బోధించాయి. iii సరైనది: స్వర్ణ దేవాలయం (హర్మందిర్ సాహిబ్), బుద్ధుడు జ్ఞానోదయం పొందిన బుద్ధ గయ వాటి అతి పవిత్ర స్థలాలు. iv సరైనది: 2011 జనాభా లెక్కల ప్రకారం పంజాబ్ జనాభాలో సుమారు 58% సిక్కులు, సిక్కిం జనాభాలో సుమారు 27% బౌద్ధులు."},{"id":"t2023a-41","p":"t2023a","n":41,"s":"eco","t":"Indian Economy","q":"Match the following types of unemployment in List- I with their descriptions in List- II:\nSl No. | Types of unemployment --- List I | Sl No. | Descriptions -- List II\nA | Frictional unemployment | i | Unemployment due to changes in technology or demand for goods and services\nB | Structural unemployment | ii | Unemployment due to lack of skills or education\nC | Cyclical unemployment | iii | Unemployment due to seasonal fluctuations in industries\nD | Seasonal unemployment | iv | Unemployment due to economic downturns or recessions","w":"Cyclical unemployment comes from economic downturns or recessions (C-iv) and seasonal unemployment from seasonal fluctuations in work (D-iii), which leaves options 2 and 3. Frictional unemployment is the short spell of people moving between jobs or entering the labour force; structural unemployment is a mismatch between workers' skills and the jobs available, often caused by changes in technology or in demand. The key pairs frictional with i and structural with ii. (Preliminary key; some sources differ.) Descriptions i and ii both fit structural unemployment, so option 3 can also be argued.","o":["A - i, B - ii, C - iii, D - iv","A - i, B - ii, C - iv, D - iii","A - ii, B - i, C - iv, D - iii","A - i, B - iv, C - ii, D - iii"],"a":[1],"qt":"జాబితా-Iలోని ఈ క్రింది నిరుద్యోగిత రకాలను జాబితా- IIలోని వాటి వివరణలతో జతపరచండి:\nవ.సం. | నిరుద్యోగిత రకాలు--- జాబితా I | వ.సం. | వివరణలు – జాబితా II\nA | ఘర్షణ నిరుద్యోగం | i | సాంకేతికతలో మార్పులు లేదా వస్తువులు మరియు సేవల డిమాండ్ కారణంగా నిరుద్యోగం\nB | నిర్మాణాత్మక నిరుద్యోగం | ii | నైపుణ్యాలు లేదా విద్య లేకపోవడం వల్ల నిరుద్యోగం\nC | చక్రీయ నిరుద్యోగం | iii | పరిశ్రమలలో కాలానుగుణ హెచ్చుతగ్గుల కారణంగా నిరుద్యోగం\nD | కాలానుగుణ నిరుద్యోగం | iv | ఆర్థిక లాభాల క్షీణత లేదా మాంద్యం కారణంగా నిరుద్యోగం","ot":["A - i, B - ii, C - iii, D - iv","A - i, B - ii, C - iv, D - iii","A - ii, B - i, C - iv, D - iii","A - i, B - iv, C - ii, D - iii"],"wt":"చక్రీయ నిరుద్యోగం ఆర్థిక మాంద్యం వల్ల (C-iv), కాలానుగుణ నిరుద్యోగం పనిలో కాలానుగుణ హెచ్చుతగ్గుల వల్ల (D-iii) వస్తుంది; కాబట్టి ఎంపికలు 2, 3 మాత్రమే మిగులుతాయి. ఘర్షణ నిరుద్యోగం అంటే ప్రజలు ఒక ఉద్యోగం నుంచి మరొక ఉద్యోగానికి మారే సమయంలో లేదా కొత్తగా శ్రామిక శక్తిలో చేరేటప్పుడు ఉండే స్వల్పకాల నిరుద్యోగం; నిర్మాణాత్మక నిరుద్యోగం అంటే కార్మికుల నైపుణ్యాలకు, అందుబాటులో ఉన్న ఉద్యోగాలకు మధ్య అసమతుల్యత, ఇది తరచుగా సాంకేతికత లేదా డిమాండ్‌లో మార్పుల వల్ల వస్తుంది. కీ ఘర్షణ నిరుద్యోగాన్ని i తో, నిర్మాణాత్మక నిరుద్యోగాన్ని ii తో జతపరిచింది. (ప్రాథమిక కీ; కొన్ని మూలాలు భిన్నంగా ఉన్నాయి.) i, ii వివరణలు రెండూ నిర్మాణాత్మక నిరుద్యోగానికే సరిపోతాయి, కాబట్టి ఎంపిక 3 ని కూడా సమర్థించవచ్చు."},{"id":"t2023a-42","p":"t2023a","n":42,"s":"geo","t":"Indian Geography","q":"Match the following agricultural practices in List -I with their respective regions in India in List -II:\nSl No. | Agricultural Practices -- List -I | Sl No. | Respective Regions in India -- List -II\nA | Shifting cultivation | 1 | Punjab\nB | Terrace farming | 2 | Northeast India\nC | Intensive farming | 3 | Madhya Pradesh\nD | Dryland farming | 4 | Himalayan foothills","w":"Shifting (slash-and-burn, or jhum) cultivation is practised by tribal communities in Northeast India; terrace farming suits the steep slopes of the Himalayan foothills; intensive farming with irrigation, high-yielding seeds and fertilisers is typical of Punjab; and dryland farming is practised in low-rainfall areas (below about 75 cm) such as parts of Madhya Pradesh. Hence A-2, B-4, C-1, D-3.","o":["A-1, B-3, C-2, D-4","A-2, B-4, C-1, D-3","A-3, B-1, C-2, D-4","A-3, B-2, C-1, D-4"],"a":[1],"qt":"జాబితా -Iలోని క్రింది వ్యవసాయ పద్ధతులను జాబితా -IIలోని భారతదేశంలోని వాటి సంబంధిత ప్రాంతాలతో జతపరచండి:\nవ. సం. | వ్యవసాయ పద్ధతులు – జాబితా -I | వ. సం. | భారతదేశంలోని సంబంధిత ప్రాంతాలు – జాబితా -II\nA | బదిలీ వ్యవసాయం | 1 | పంజాబ్\nB | మిద్దె వ్యవసాయం | 2 | ఈశాన్య భారతదేశం\nC | సాంద్ర వ్యవసాయం | 3 | మధ్యప్రదేశ్\nD | ఖుష్కి భూమి వ్యవసాయం | 4 | హిమాలయ పర్వత పాద కొండలు","ot":["A-1, B-3, C-2, D-4","A-2, B-4, C-1, D-3","A-3, B-1, C-2, D-4","A-3, B-2, C-1, D-4"],"wt":"బదిలీ (నరికి-కాల్చే, 'ఝూమ్') వ్యవసాయాన్ని ఈశాన్య భారతదేశంలోని గిరిజన సమాజాలు చేస్తాయి; మిద్దె (టెర్రస్) వ్యవసాయం హిమాలయ పర్వత పాద కొండల నిటారు వాలులకు అనువైనది; నీటిపారుదల, అధిక దిగుబడి విత్తనాలు, ఎరువులతో కూడిన సాంద్ర వ్యవసాయం పంజాబ్‌కు ప్రత్యేకం; ఖుష్కి (వర్షాధార) భూమి వ్యవసాయం మధ్యప్రదేశ్‌లోని కొన్ని ప్రాంతాల వంటి తక్కువ వర్షపాతం (సుమారు 75 సెం.మీ. కంటే తక్కువ) ఉన్న చోట్ల జరుగుతుంది. కాబట్టి A-2, B-4, C-1, D-3."},{"id":"t2023a-43","p":"t2023a","n":43,"s":"geo","t":"Indian Geography","q":"Match the following sources of energy in List –I with their respective states in India in which they are found in abundance in List --II:\nSl No. | Sources of Energy --- List –I | Sl No. | Indian States of Abundance—List -II\n1 | Coal | a | Gujarat\n2 | Hydroelectric power | b | Jharkhand\n3 | Wind power | c | Tamil Nadu\n4 | Solar power | d | Himachal Pradesh","w":"Jharkhand holds India's largest coal reserves (Jharia, Bokaro); Himachal Pradesh, drained by the Satluj, Beas, Ravi and Chenab, is a leading hydropower state (Bhakra, Nathpa Jhakri); Tamil Nadu has long been a leader in wind power (Muppandal); and Gujarat is, along with Rajasthan, a leading solar-power state (Charanka Solar Park). Hence 1-b, 2-d, 3-c, 4-a.","o":["1-d, 2-c, 3-b, 4-a","1-b, 2-d, 3-c, 4-a","1-d, 2-a, 3-b, 4-c","1-b, 2-a, 3-c, 4-d"],"a":[1],"qt":"ఈ క్రింది జాబితా –Iలోని క్రింది శక్తి వనరులను జాబితా-IIలో సమృద్ధిగా ఉన్న భారతదేశంలోని వాటి సంబంధిత రాష్ట్రాలతో జతపరచండి:\nవ.సం. | శక్తి వనరులు --- జాబితా –I | వ.సం. | సమృద్ధత గల భారతదేశ రాష్ట్రాలు —జాబితా -II\n1 | బొగ్గు | a | గుజరాత్\n2 | జల విద్యుత్ శక్తి | b | ఝార్ఖండ్\n3 | పవన విద్యుత్ శక్తి | c | తమిళనాడు\n4 | సౌర విద్యుత్ శక్తి | d | హిమాచల్ ప్రదేశ్","ot":["1-d, 2-c, 3-b, 4-a","1-b, 2-d, 3-c, 4-a","1-d, 2-a, 3-b, 4-c","1-b, 2-a, 3-c, 4-d"],"wt":"ఝార్ఖండ్‌లో దేశంలోనే అత్యధిక బొగ్గు నిల్వలు ఉన్నాయి (ఝరియా, బొకారో); సట్లెజ్, బియాస్, రావి, చీనాబ్ నదులు ప్రవహించే హిమాచల్ ప్రదేశ్ ప్రముఖ జల విద్యుత్ రాష్ట్రం (భాక్రా, నాథ్పా ఝాక్రీ); తమిళనాడు చాలాకాలంగా పవన విద్యుత్‌లో అగ్రగామి (ముప్పండల్); రాజస్థాన్‌తో పాటు గుజరాత్ కూడా అగ్రగామి సౌర విద్యుత్ రాష్ట్రం (చరంకా సోలార్ పార్క్). కాబట్టి 1-b, 2-d, 3-c, 4-a."},{"id":"t2023a-44","p":"t2023a","n":44,"s":"geo","t":"Indian Geography","q":"Match the following rivers in India with the states they flow through:\nList I | List II\n(A) Brahmaputra | (i) Karnataka and Tamil Nadu\n(B) Krishna | (ii) Assam and Arunachal Pradesh\n(C) Cauvery | (iii) Andhra Pradesh and Chhattisgarh\n(D) Godavari | (iv) Maharashtra and Telangana","w":"The Brahmaputra flows through Arunachal Pradesh and Assam (A-ii) and the Cauvery through Karnataka and Tamil Nadu (C-i); option 4 is the only one with both. The Krishna rises in Maharashtra and flows through Karnataka, Telangana and Andhra Pradesh (B-iv), while the Godavari, which also crosses Maharashtra and Telangana, reaches the sea in Andhra Pradesh and its basin extends into Chhattisgarh through the Indravati and Sabari (D-iii).","o":["A-(ii), B-(iii), C-(iv), D-(i)","A-(iii), B-(i), C-(ii), D-(iv)","A-(iv), B-(ii), C-(i), D-(iii)","A-(ii), B-(iv), C-(i), D-(iii)"],"a":[3],"qt":"కింది భారతదేశంలోని నదులను అవి ప్రవహించే రాష్ట్రాలతో జతపరచండి :\nజాబితా I | జాబితా II\n(A) బ్రహ్మపుత్ర | (i) కర్ణాటక మరియు తమిళనాడు\n(B) కృష్ణా | (ii) అస్సాం మరియు అరుణాచల్ ప్రదేశ్\n(C) కావేరీ | (iii) ఆంధ్ర ప్రదేశ్ మరియు చత్తీస్ ఘడ్\n(D) గోదావరి | (iv) మహారాష్ట్ర మరియు తెలంగాణా","ot":["A-(ii), B-(iii), C-(iv), D-(i)","A-(iii), B-(i), C-(ii), D-(iv)","A-(iv), B-(ii), C-(i), D-(iii)","A-(ii), B-(iv), C-(i), D-(iii)"],"wt":"బ్రహ్మపుత్ర అరుణాచల్ ప్రదేశ్, అస్సాం గుండా (A-ii), కావేరీ కర్ణాటక, తమిళనాడు గుండా (C-i) ప్రవహిస్తాయి; ఈ రెండూ ఉన్న ఎంపిక 4 ఒక్కటే. కృష్ణా మహారాష్ట్రలో పుట్టి కర్ణాటక, తెలంగాణ, ఆంధ్రప్రదేశ్ గుండా ప్రవహిస్తుంది (B-iv); గోదావరి కూడా మహారాష్ట్ర, తెలంగాణ గుండా ప్రవహించి ఆంధ్రప్రదేశ్‌లో సముద్రంలో కలుస్తుంది, ఇంద్రావతి, శబరి ఉపనదుల ద్వారా దాని పరీవాహక ప్రాంతం ఛత్తీస్‌గఢ్‌లోకి విస్తరించి ఉంది (D-iii)."},{"id":"t2023a-45","p":"t2023a","n":45,"s":"pol","t":"Constitution & Rights","q":"Match the following Directive Principles of State Policy in List-I with their respective Articles in the Constitution of India in List -II:\nSl No. | Directive Principles of State Policy -- List-I | Sl No. | Articles in the Constitution of India -- List -II\nA | Promotion of education and economic interests of Scheduled Castes, Scheduled Tribes, and other weaker sections | i | Article 46\nB | Provision for just and humane conditions of work and maternity relief | ii | Article 42\nC | Separation of the judiciary from the executive | iii | Article 50\nD | Protection of monuments and places and objects of national importance | iv | Article 49","w":"In Part IV of the Constitution, Article 46 directs the State to promote the educational and economic interests of Scheduled Castes, Scheduled Tribes and other weaker sections; Article 42 provides for just and humane conditions of work and maternity relief; Article 49 protects monuments and places and objects of national importance; and Article 50 separates the judiciary from the executive. Hence A-i, B-ii, C-iii, D-iv.","o":["A - iv, B - ii, C - iii, D - i","A - i, B - iii, C - ii, D - iv","A - iii, B - ii, C - i, D - iv","A - i, B - ii, C - iii, D - iv"],"a":[3],"qt":"జాబితా-Iలోని రాష్ట విధానానికి సంబంధించిన క్రింది నిర్దేశక సూత్రాలను జాబితా -IIలోని భారత రాజ్యాంగంలోని వాటి సంబంధిత అధికరణాలతో జతపరచండి:\nవ.సం. | రాష్ట్ర విధాన నిర్దేశక సూత్రాలు --- జాబితా -I | వ.సం. | భారత రాజ్యాంగంలోని అధికరణాలు--- జాబితా -II\nA | షెడ్యూల్డ్ కులాలు, షెడ్యూల్డ్ తెగలు మరియు ఇతర బలహీన వర్గాల విద్య మరియు ఆర్థిక ప్రయోజనాలను ప్రోత్సహించడం | i | అధికరణం 46\nB | పని మరియు ప్రసూతి ఉపశమనం యొక్క న్యాయమైన మరియు మానవీయ పరిస్థితులు | ii | అధికరణం 42\nC | కార్యనిర్వాహక వ్యవస్థ నుండి న్యాయవ్యవస్థను వేరు చేయడం | iii | అధికరణం 50\nD | జాతీయ ప్రాముఖ్యత కలిగిన స్మారక చిహ్నాలు మరియు ప్రదేశాలు మరియు వస్తువుల రక్షణ | iv | అధికరణం 49","ot":["A - iv, B - ii, C - iii, D - i","A - i, B - iii, C - ii, D - iv","A - iii, B - ii, C - i, D - iv","A - i, B - ii, C - iii, D - iv"],"wt":"రాజ్యాంగంలోని IVవ భాగంలో అధికరణం 46 షెడ్యూల్డ్ కులాలు, షెడ్యూల్డ్ తెగలు, ఇతర బలహీన వర్గాల విద్య, ఆర్థిక ప్రయోజనాలను ప్రోత్సహించాలని రాజ్యాన్ని ఆదేశిస్తుంది; అధికరణం 42 న్యాయమైన, మానవీయ పని పరిస్థితులు, ప్రసూతి ఉపశమనం కల్పించాలంటుంది; అధికరణం 49 జాతీయ ప్రాముఖ్యత కలిగిన స్మారక చిహ్నాలు, ప్రదేశాలు, వస్తువుల రక్షణకు సంబంధించినది; అధికరణం 50 కార్యనిర్వాహక వ్యవస్థ నుండి న్యాయవ్యవస్థను వేరు చేయాలంటుంది. కాబట్టి A-i, B-ii, C-iii, D-iv."},{"id":"t2023a-46","p":"t2023a","n":46,"s":"pol","t":"Constitution & Rights","q":"Which of the following is/are the correct pair/pairs of Fundamental Duties and their article in the Indian Constitution?\nA) To uphold and protect the sovereignty, unity and integrity of India - Article 50\nB) To abide by the Constitution and respect its ideals and institutions, the National Flag and the National Anthem - Article 51A\nC) To promote harmony and the spirit of common brotherhood amongst all the people of India - Article 32\nD) To safeguard public property and to abjure violence - Article 35","w":"All the Fundamental Duties are listed in a single article, Article 51A in Part IVA, added by the 42nd Amendment, 1976 (the eleventh duty by the 86th Amendment, 2002). All four duties quoted belong to Article 51A, so only pair B is correct. Article 50 deals with separation of the judiciary, Article 32 with constitutional remedies and Article 35 with Parliament's power to make laws under Part III.","o":["Only A","Only A and B","Only B","Only C and D"],"a":[2],"qt":"ఈ క్రింది వాటిలో ప్రాథమిక విధులు మరియు భారత రాజ్యాంగంలో వాటి అధికరణాల సరియైన జత/లు ఏది/వి?\nA) భారతదేశ సార్వభౌమాధికారం, ఐక్యత మరియు సమగ్రతను సమర్థించడం మరియు రక్షించడం - అధికరణం 50\nB) రాజ్యాంగానికి కట్టుబడి ఉండి, దాని ఆదర్శాలను మరియు సంస్థలను, జాతీయ జెండాను మరియు జాతీయ గీతాన్ని గౌరవించడం - అధికరణం 51A\nC) భారతదేశంలోని ప్రజలందరి మధ్య సామరస్యాన్ని మరియు సాధారణ సోదర భావాన్ని పెంపొందించడం - అధికరణం 32\nD) ప్రజా ఆస్తులను రక్షించుట మరియు హింసను త్యజించుట - అధికరణం 35","ot":["A మాత్రమే","A మరియు B లు మాత్రమే","B మాత్రమే","C మరియు D లు మాత్రమే"],"wt":"ప్రాథమిక విధులన్నీ ఒకే అధికరణంలో — IVA భాగంలోని అధికరణం 51A లో — ఉన్నాయి; వీటిని 42వ సవరణ (1976) చేర్చింది (పదకొండవ విధిని 86వ సవరణ, 2002 చేర్చింది). ఇచ్చిన నాలుగు విధులూ అధికరణం 51A లోనివే, కాబట్టి B జత మాత్రమే సరైనది. అధికరణం 50 న్యాయవ్యవస్థను వేరు చేయడానికి, అధికరణం 32 రాజ్యాంగ పరిష్కారాలకు, అధికరణం 35 IIIవ భాగం కింద చట్టాలు చేసే పార్లమెంటు అధికారానికి సంబంధించినవి."},{"id":"t2023a-47","p":"t2023a","n":47,"s":"pol","t":"Constitution & Rights","q":"Select the correct pair of Fundamental Rights and their related articles:\nA. Right to Equality - Article 14\nB. Right to Freedom of Religion - Article 25-28\nC. Right against Exploitation - Article 32-35\nD. Right to Constitutional Remedies - Article 23-24","w":"The Right to Equality covers Articles 14–18, opening with equality before law and equal protection of laws in Article 14, and the Right to Freedom of Religion covers Articles 25–28, so A and B are correct. The Right against Exploitation is in Articles 23–24 and the Right to Constitutional Remedies in Article 32, so pairs C and D have their articles swapped.","o":["Only C","Only A and B","Only D","Only B and C"],"a":[1],"qt":"ప్రాథమిక హక్కులు మరియు వాటికి సంబంధించిన అధికరణాల సరైన జతను ఎంచుకోండి:\nA. సమానత్వపు హక్కు - అధికరణం 14\nB. మత స్వేచ్ఛపు హక్కు - అధికరణం 25-28\nC. దోపిడీని నిరోధించే హక్కు - అధికరణం 32-35\nD. రాజ్యాంగ పరిష్కారాల హక్కు - అధికరణం 23-24","ot":["C మాత్రమే","A మరియు B లు మాత్రమే","D మాత్రమే","B మరియు C లు మాత్రమే"],"wt":"సమానత్వపు హక్కు అధికరణాలు 14–18 లో ఉంది, ఇది అధికరణం 14 లోని చట్టం ముందు సమానత్వం, చట్టాల సమాన రక్షణతో మొదలవుతుంది; మత స్వేచ్ఛపు హక్కు అధికరణాలు 25–28 లో ఉంది; కాబట్టి A, B సరైనవి. దోపిడీని నిరోధించే హక్కు అధికరణాలు 23–24 లో, రాజ్యాంగ పరిష్కారాల హక్కు అధికరణం 32 లో ఉన్నాయి; కాబట్టి C, D జతల్లో అధికరణాలు తారుమారయ్యాయి."},{"id":"t2023a-48","p":"t2023a","n":48,"s":"pol","t":"Constitution & Rights","q":"Select the correct pair of terms related to Indian citizenship with their definitions:\n1. Citizenship by birth : Citizenship obtained by birth to at least one Indian parent\n2. Citizenship by naturalization : Citizenship obtained by living in India for a certain period of time\n3. Citizenship by registration : Citizenship obtained by marriage to an Indian citizen\n4. Citizenship by descent : Citizenship obtained by applying to the government and meeting certain requirements","w":"Under the Citizenship Act, 1955, citizenship by birth (Section 3) now needs birth in India with at least one parent a citizen (since 1987; stricter since 2004), and naturalisation (Section 6) needs long residence, normally 12 years. Citizenship by descent is for persons born outside India to an Indian parent, so 4 is wrong. (Preliminary key; some sources differ.) Registration (Section 5) does include persons married to Indian citizens and resident for seven years, so statement 3 is also defensible.","o":["Only options 1 and 2","Only options 1 and 3","Only options 1 and 4","Only options 2 and 4"],"a":[0],"qt":"భారత పౌరసత్వానికి సంబంధించిన నిర్వచనాలతో సరైన జత నిబంధనలను ఎంచుకోండి:\n1. పుట్టుకతో పౌరసత్వం : కనీసం ఒక భారతీయ తల్లిదండ్రులకు పుట్టుక ద్వారా పౌరసత్వం లభిస్తుంది\n2. సహజీకరణ ద్వారా పౌరసత్వం : నిర్దిష్ట కాలం పాటు భారతదేశంలో నివసించడం ద్వారా పౌరసత్వం పొందబడుతుంది\n3. రిజిస్ట్రేషన్ ద్వారా పౌరసత్వం : భారతీయ పౌరుడిని వివాహం చేసుకోవడం ద్వారా పొందిన పౌరసత్వం\n4. సంతతి వారీగా పౌరసత్వం : ప్రభుత్వానికి దరఖాస్తు చేయడం మరియు కొన్ని ఆవశ్యకతలను కలిగి ఉండడం ద్వారా పౌరసత్వం పొందవచ్చు","ot":["1 మరియు 2 ఎంపికలు మాత్రమే","1 మరియు 3 ఎంపికలు మాత్రమే","1 మరియు 4 ఎంపికలు మాత్రమే","2 మరియు 4 ఎంపికలు మాత్రమే"],"wt":"పౌరసత్వ చట్టం, 1955 ప్రకారం పుట్టుకతో పౌరసత్వానికి (సెక్షన్ 3) ఇప్పుడు భారతదేశంలో పుట్టి, తల్లిదండ్రుల్లో కనీసం ఒకరు పౌరులై ఉండాలి (1987 నుంచి; 2004 నుంచి మరింత కఠినం); సహజీకరణకు (సెక్షన్ 6) సాధారణంగా 12 సంవత్సరాల సుదీర్ఘ నివాసం అవసరం. సంతతి ద్వారా పౌరసత్వం భారతీయ తల్లి లేదా తండ్రికి విదేశాల్లో పుట్టినవారికి వర్తిస్తుంది, కాబట్టి 4 తప్పు. (ప్రాథమిక కీ; కొన్ని మూలాలు భిన్నంగా ఉన్నాయి.) రిజిస్ట్రేషన్ (సెక్షన్ 5) కింద భారత పౌరులను వివాహం చేసుకుని ఏడు సంవత్సరాలు నివసించినవారు కూడా వస్తారు, కాబట్టి ప్రకటన 3 కూడా సమర్థనీయమే."},{"id":"t2023a-49","p":"t2023a","n":49,"s":"pol","t":"Union & State Government","q":"Choose the correct pair of political positions in India and their corresponding authorities:","w":"The President of India is the head of the State and the constitutional head of the Union executive (Articles 52–53), acting on the advice of the Council of Ministers. The Chief Minister heads a state government and does not preside over the House; the Governor is the constitutional head of a state, while the Chief Minister heads its government; the Speaker presides over the Lok Sabha. Only option 4 is correct.","o":["Chief Minister of a state: Presiding Officer of the Lower House","Governor of a state: Head of Government","Speaker of Lok Sabha: Constitutional Head of a State","President of India: Head of the State"],"a":[3],"qt":"భారతదేశంలో సరైన జత రాజకీయ స్థానాలను మరియు వాటికి సంబంధించిన అధికారాలను ఎంచుకోండి:","ot":["ఒక రాష్ట్ర ముఖ్యమంత్రి: దిగువ సభ ప్రిసైడింగ్ అధికారి","రాష్ట్ర గవర్నర్: ప్రభుత్వ అధిపతి","లోక్‌సభ స్పీకర్: ఒక రాష్ట్రానికి రాజ్యాంగ అధిపతి","భారత రాష్ట్రపతి: రాష్ట్ర అధిపతి"],"wt":"భారత రాష్ట్రపతి దేశానికి అధిపతి, కేంద్ర కార్యనిర్వాహక వర్గానికి రాజ్యాంగ అధిపతి (అధికరణాలు 52–53); మంత్రిమండలి సలహా మేరకు వ్యవహరిస్తారు. ముఖ్యమంత్రి రాష్ట్ర ప్రభుత్వ అధిపతి, సభకు అధ్యక్షత వహించరు; గవర్నర్ రాష్ట్ర రాజ్యాంగ అధిపతి, ప్రభుత్వానికి అధిపతి ముఖ్యమంత్రి; స్పీకర్ లోక్‌సభకు అధ్యక్షత వహిస్తారు. ఎంపిక 4 మాత్రమే సరైనది."},{"id":"t2023a-50","p":"t2023a","n":50,"s":"pol","t":"Union & State Government","q":"Which of the following is correctly paired with its description under the Judiciary system of India?\na) Supreme Court - The highest court of appeal in India\nb) High Court - Deals with cases related to state laws\nc) District Court - Deals with cases related to national security\nd) Lok Adalat - Deals with criminal cases involving heinous crimes","w":"The Supreme Court is India's highest court of appeal, so a is correct. High Courts decide cases under both Union and state laws; district courts are the general civil and criminal courts of a district, not national-security courts; and Lok Adalats, under the Legal Services Authorities Act, 1987, settle disputes by compromise and cannot decide non-compoundable offences such as heinous crimes. Hence only a.","o":["Only option a","Only options b and d","Only options b and c","Only options c and d"],"a":[0],"qt":"ఈ క్రింది వాటిల్లో భారతదేశ న్యాయవ్యవస్థలో దాని వివరణతో సరిగ్గా జత చేయబడినది ఏది?\na) సుప్రీంకోర్టు - భారతదేశంలోని అత్యున్నత న్యాయస్థానం\nb) హైకోర్టు - రాష్ట్ర చట్టాలకు సంబంధించిన కేసులతో వ్యవహరిస్తుంది\nc) జిల్లా కోర్టు - జాతీయ భద్రతకు సంబంధించిన కేసులతో వ్యవహరిస్తుంది\nd) లోక్ అదాలత్ – అమానుష నేరాలకు సంబంధించిన క్రిమినల్ కేసులతో వ్యవహరిస్తుంది","ot":["a ఎంపిక మాత్రమే","b మరియు d ఎంపికలు మాత్రమే","b మరియు c ఎంపికలు మాత్రమే","c మరియు d ఎంపికలు మాత్రమే"],"wt":"సుప్రీంకోర్టు భారతదేశంలో అత్యున్నత అప్పీలు న్యాయస్థానం, కాబట్టి a సరైనది. హైకోర్టులు కేంద్ర, రాష్ట్ర చట్టాలు రెండింటి కింద కేసులను విచారిస్తాయి; జిల్లా కోర్టులు జిల్లా స్థాయిలో సాధారణ సివిల్, క్రిమినల్ న్యాయస్థానాలు, జాతీయ భద్రత కోర్టులు కావు; న్యాయ సేవల ప్రాధికార సంస్థల చట్టం, 1987 కింద ఏర్పడిన లోక్ అదాలత్‌లు రాజీ ద్వారా వివాదాలను పరిష్కరిస్తాయి, అమానుష నేరాల వంటి రాజీకి వీలులేని నేరాలను విచారించలేవు. కాబట్టి a మాత్రమే."},{"id":"t2023a-51","p":"t2023a","n":51,"s":"pol","t":"Union & State Government","q":"Pick the correct pair/pairs:\na. Rajya Sabha: Lower House\nb. Lok Sabha: Upper House\nc. Vidhan Sabha: State Legislative Assembly\nd. Vidhan Parishad: State Legislative Council","w":"The Rajya Sabha (Council of States) is the Upper House and the Lok Sabha (House of the People) the Lower House of Parliament, so pairs a and b are reversed. In a State, the Vidhan Sabha is the Legislative Assembly (lower house) and the Vidhan Parishad the Legislative Council (upper house); Councils are created or abolished under Article 169, and in 2023 only six States, including Telangana and Andhra Pradesh, had one. So only c and d are correct.","o":["Only option a","Only options b and d","Only options b and c","Only options c and d"],"a":[3],"qt":"సరైన జత/జతలను ఎంచుకోండి:\na. రాజ్యసభ: దిగువ సభ\nb. లోక్‌సభ: ఎగువ సభ\nc. విధానసభ: రాష్ట్ర శాసనసభ\nd. విధాన పరిషత్: రాష్ట్ర శాసన మండలి","ot":["a ఎంపిక మాత్రమే","b మరియు d ఎంపికలు మాత్రమే","b మరియు c ఎంపికలు మాత్రమే","c మరియు d ఎంపికలు మాత్రమే"],"wt":"రాజ్యసభ (రాష్ట్రాల మండలి) పార్లమెంటు ఎగువ సభ, లోక్‌సభ (ప్రజల సభ) దిగువ సభ; కాబట్టి a, b జతలు తారుమారయ్యాయి. రాష్ట్రంలో విధానసభ శాసనసభ (దిగువ సభ), విధాన పరిషత్ శాసన మండలి (ఎగువ సభ); అధికరణం 169 కింద శాసన మండలిని ఏర్పాటు చేయవచ్చు లేదా రద్దు చేయవచ్చు; 2023లో తెలంగాణ, ఆంధ్రప్రదేశ్ సహా ఆరు రాష్ట్రాలకే శాసన మండలి ఉంది. కాబట్టి c, d మాత్రమే సరైనవి."},{"id":"t2023a-52","p":"t2023a","n":52,"s":"pol","t":"Union & State Government","q":"Arrange the following State Executive positions in the order of hierarchy, starting with the highest position:\n1. Chief Secretary\n2. Governor\n3. Chief Minister\n4. Advocate General","w":"The Governor is the constitutional head of the State executive (Article 154) and appoints the Chief Minister, who heads the Council of Ministers (Articles 163 and 164). The Chief Secretary is the senior-most civil servant, heading the State secretariat under the ministers. The Advocate General (Article 165) is the State's chief legal adviser appointed by the Governor; the key places this office last. Order: Governor, Chief Minister, Chief Secretary, Advocate General.","o":["4, 3, 1, 2","2, 3, 4, 1","2, 3, 1, 4","3, 1, 2, 4"],"a":[2],"qt":"ఈ క్రింది రాష్ట్ర కార్యనిర్వాహక అధికారులను అత్యున్నత స్థానంతో ప్రారంభించి అధికార క్రమంలో అమర్చండి:\n1. ప్రధాన కార్యదర్శి\n2. గవర్నర్\n3. ముఖ్యమంత్రి\n4. అడ్వకేట్ జనరల్","ot":["4, 3, 1, 2","2, 3, 4, 1","2, 3, 1, 4","3, 1, 2, 4"],"wt":"గవర్నర్ రాష్ట్ర కార్యనిర్వాహక వ్యవస్థకు రాజ్యాంగ అధిపతి (అధికరణం 154); ఆయన ముఖ్యమంత్రిని నియమిస్తారు, ముఖ్యమంత్రి మంత్రిమండలికి నాయకత్వం వహిస్తారు (అధికరణాలు 163, 164). ప్రధాన కార్యదర్శి మంత్రుల కింద రాష్ట్ర సచివాలయానికి అధిపతిగా ఉండే అత్యంత సీనియర్ సివిల్ సర్వీసు అధికారి. అడ్వకేట్ జనరల్ (అధికరణం 165) గవర్నర్ నియమించే రాష్ట్ర ప్రధాన న్యాయ సలహాదారు; కీ ఈ పదవిని చివర ఉంచింది. క్రమం: గవర్నర్, ముఖ్యమంత్రి, ప్రధాన కార్యదర్శి, అడ్వకేట్ జనరల్."},{"id":"t2023a-53","p":"t2023a","n":53,"s":"pol","t":"Union & State Government","q":"Arrange the following in the CORRECT order of their occurrence in the Parliamentary Procedure in India:\n1. Question Hour\n2. Zero Hour\n3. Adjournment Motion\n4. Calling Attention Motion","w":"A Lok Sabha sitting opens with Question Hour (the first hour, from 11 a.m.). Calling attention notices (Rule 197) are taken up after Question Hour and the laying of papers, and an admitted adjournment motion is debated later, at a time fixed by the Speaker, for at least two and a half hours. The key puts Zero Hour last; but Zero Hour, an informal practice since the 1960s, normally begins at 12 noon right after Question Hour, which would give 1, 2, 4, 3. (Preliminary key; some sources differ.)","o":["2, 3, 4, 1","1, 2, 4, 3","1, 4, 3, 2","4, 3, 1, 2"],"a":[2],"qt":"క్రింది వాటిని భారతదేశంలో పార్లమెంటరీ కార్యనిర్వహణలలో అవి సంభవించే సరైన క్రమంలో అమర్చండి:\n1. ప్రశ్నోత్తరాల సమయం\n2. జీరో అవర్\n3. వాయిదా తీర్మానం\n4. కాలింగ్ అటెన్షన్ మోషన్","ot":["2, 3, 4, 1","1, 2, 4, 3","1, 4, 3, 2","4, 3, 1, 2"],"wt":"లోక్‌సభ సమావేశం ప్రశ్నోత్తరాల సమయంతో (మొదటి గంట, ఉదయం 11 గంటల నుంచి) ప్రారంభమవుతుంది. ప్రశ్నోత్తరాల సమయం, సభ ముందు పత్రాలు ఉంచడం పూర్తయ్యాక కాలింగ్ అటెన్షన్ నోటీసులు (నియమం 197) చేపడతారు; అనుమతించిన వాయిదా తీర్మానంపై చర్చ ఆ తర్వాత స్పీకర్ నిర్ణయించిన సమయంలో కనీసం రెండున్నర గంటలు జరుగుతుంది. కీ జీరో అవర్‌ను చివర ఉంచింది; కానీ 1960ల నుంచి వస్తున్న అనధికారిక పద్ధతి అయిన జీరో అవర్ సాధారణంగా ప్రశ్నోత్తరాల సమయం తర్వాత మధ్యాహ్నం 12 గంటలకే మొదలవుతుంది, దాని ప్రకారం క్రమం 1, 2, 4, 3 అవుతుంది. (ప్రాథమిక కీ; కొన్ని ఆధారాలు భిన్నంగా ఉన్నాయి.)"},{"id":"t2023a-54","p":"t2023a","n":54,"s":"pol","t":"Local Government","q":"Arrange the following State Institutions in CORRECT order of hierarchy, from top to bottom:\n1. District Panchayat\n2. Intermediate Panchayat\n3. Village and PESA Panchayat\n4. Wards","w":"Under Part IX (73rd Amendment) the Panchayati Raj system has three tiers: the district Panchayat (Zilla Parishad) at the top, the intermediate (mandal or block) Panchayat in the middle and the village Panchayat at the base; in Scheduled Areas the village-level bodies work under the PESA Act, 1996. Each Gram Panchayat is divided into wards, the smallest electoral units, so the order from top to bottom is 1, 2, 3, 4.","o":["2, 3, 4, 1","1, 2, 3, 4","1, 4, 3, 2","4, 3, 1, 2"],"a":[1],"qt":"ఈ క్రింది రాష్ట్ర సంస్థలను సరైన అధికార క్రమంలో అమర్చండి, పై నుండి క్రిందికి:\n1. జిల్లా పంచాయతీ\n2. మధ్యస్థ పంచాయతీ\n3. గ్రామం మరియు పెస పంచాయతీ\n4. వార్డులు","ot":["2, 3, 4, 1","1, 2, 3, 4","1, 4, 3, 2","4, 3, 1, 2"],"wt":"పార్ట్ IX (73వ సవరణ) ప్రకారం పంచాయతీ రాజ్ వ్యవస్థకు మూడు అంచెలు: పైన జిల్లా పంచాయతీ (జిల్లా పరిషత్), మధ్యలో మధ్యస్థ (మండల లేదా బ్లాక్) పంచాయతీ, అడుగున గ్రామ పంచాయతీ; షెడ్యూల్డ్ ప్రాంతాల్లో గ్రామ స్థాయి సంస్థలు పెసా చట్టం, 1996 కింద పనిచేస్తాయి. ప్రతి గ్రామ పంచాయతీని అతి చిన్న ఎన్నికల యూనిట్లైన వార్డులుగా విభజిస్తారు, కాబట్టి పై నుండి క్రిందికి క్రమం 1, 2, 3, 4."},{"id":"t2023a-55","p":"t2023a","n":55,"s":"pol","t":"Local Government","q":"Arrange the following steps in the correct order to describe the process of the formation of a Gram Panchayat in India:\n1. Elections are held for the members of the Gram Panchayat.\n2. The government announces the creation of a new Gram Panchayat.\n3. The members of the Gram Sabha elect the Sarpanch.\n4. The members of the Gram Panchayat elect the Up-Sarpanch.","w":"First the State government declares (notifies) a village or group of villages as a new Gram Panchayat; then elections are held for its ward members and Sarpanch. In Telangana, as in most States, the Sarpanch is elected directly by the voters, that is, the members of the Gram Sabha, and the members of the Gram Panchayat then elect the Up-Sarpanch from among the ward members. Hence 2-1-3-4.","o":["2-1-3-4","1-2-3-4","2-3-4-1","3-2-1-4"],"a":[0],"qt":"భారతదేశంలో గ్రామ పంచాయతీ ఏర్పాటు ప్రక్రియను వివరించడానికి ఈ క్రింది దశలను సరైన క్రమంలో అమర్చండి:\n1. గ్రామ పంచాయితీ సభ్యులకు ఎన్నికలు నిర్వహించబడతాయి.\n2. కొత్త గ్రామ పంచాయతీని ఏర్పాటు చేస్తున్నట్లు ప్రభుత్వం ప్రకటిస్తుంది.\n3. గ్రామసభ సభ్యులు సర్పంచ్‌ని ఎన్నుకుంటారు.\n4. గ్రామ పంచాయతీ సభ్యులు ఉప-సర్పంచ్‌ను ఎన్నుకుంటారు.","ot":["2-1-3-4","1-2-3-4","2-3-4-1","3-2-1-4"],"wt":"ముందుగా రాష్ట్ర ప్రభుత్వం ఒక గ్రామాన్ని లేదా గ్రామాల సమూహాన్ని కొత్త గ్రామ పంచాయతీగా ప్రకటిస్తుంది (నోటిఫై చేస్తుంది); తర్వాత దాని వార్డు సభ్యులు, సర్పంచ్ పదవులకు ఎన్నికలు జరుగుతాయి. తెలంగాణలో, చాలా రాష్ట్రాల్లో లాగే, సర్పంచ్‌ను ఓటర్లు, అంటే గ్రామసభ సభ్యులు, ప్రత్యక్షంగా ఎన్నుకుంటారు; ఆ తర్వాత గ్రామ పంచాయతీ సభ్యులు వార్డు సభ్యులలో ఒకరిని ఉప-సర్పంచ్‌గా ఎన్నుకుంటారు. కాబట్టి 2-1-3-4."},{"id":"t2023a-56","p":"t2023a","n":56,"s":"pol","t":"Local Government","q":"Arrange the following members of the Panchayati Raj system in India in the correct order of authority, from the lowest to the highest level:\ni. Gram Sabha\nii. Gram Panchayat\niii. Zila Parishad","w":"The Gram Sabha, made up of all persons on the electoral roll of the village (Article 243(b)), is the foundation of the system; the Gram Panchayat is the elected executive body at the village level; and the Zila Parishad is the top tier at the district level, coordinating and supervising the lower bodies. From lowest to highest the key therefore reads Gram Sabha, Gram Panchayat, Zila Parishad.","o":["iii, i, ii","i, iii, ii","ii, iii, i","i, ii, iii"],"a":[3],"qt":"భారతదేశంలోని పంచాయితీ రాజ్ వ్యవస్థలోని ఈ క్రింది సభ్యులను క్రింది స్థాయి నుండి అత్యున్నత స్థాయి వరకు సరైన అధికార క్రమంలో అమర్చండి:\ni. గ్రామ సభ\nii. గ్రామ పంచాయితీ\niii. జిల్లా పరిషత్","ot":["iii, i, ii","i, iii, ii","ii, iii, i","i, ii, iii"],"wt":"గ్రామ ఓటర్ల జాబితాలో పేరున్న వారందరితో కూడిన గ్రామసభ (అధికరణం 243(b)) ఈ వ్యవస్థకు పునాది; గ్రామ పంచాయతీ గ్రామ స్థాయిలో ఎన్నికైన కార్యనిర్వాహక సంస్థ; జిల్లా పరిషత్ జిల్లా స్థాయిలో దిగువ సంస్థలను సమన్వయం చేసి పర్యవేక్షించే అత్యున్నత అంచె. కాబట్టి క్రింది నుండి పై వరకు కీ ప్రకారం క్రమం: గ్రామసభ, గ్రామ పంచాయతీ, జిల్లా పరిషత్."},{"id":"t2023a-57","p":"t2023a","n":57,"s":"ih","t":"Modern India & Freedom Struggle","q":"Arrange the following Acts in chronological order of their occurrence:\na) Rowlatt Act\nb) Government of India Act\nc) Indian Independence Act\nd) Regulating Act","w":"The Regulating Act (1773) was the British Parliament's first step to control the East India Company. The Rowlatt Act was passed in March 1919. The Government of India Act here must be the Act of December 1919 or that of 1935 (the 1858 Act would come before the Rowlatt Act), and the Indian Independence Act came in July 1947. Only option 1, d, a, b, c, fits.","o":["d, a, b, c","c, d, a, b","b, a, d, c","d, c, b, a"],"a":[0],"qt":"ఈ క్రింది చట్టాలను అవి ఏర్పరచబడిన కాలక్రమానుసారంగా అమర్చండి:\na) రౌలట్ చట్టం\nb) భారత ప్రభుత్వ చట్టం\nc) భారత స్వాతంత్ర్య చట్టం\nd) రెగ్యులేటింగ్ చట్టం","ot":["d, a, b, c","c, d, a, b","b, a, d, c","d, c, b, a"],"wt":"రెగ్యులేటింగ్ చట్టం (1773) ఈస్ట్ ఇండియా కంపెనీని నియంత్రించడానికి బ్రిటిష్ పార్లమెంటు వేసిన మొదటి అడుగు. రౌలట్ చట్టం మార్చి 1919లో ఆమోదం పొందింది. ఇక్కడ భారత ప్రభుత్వ చట్టం అంటే డిసెంబర్ 1919 చట్టం లేదా 1935 చట్టం అయి ఉండాలి (1858 చట్టం అయితే రౌలట్ చట్టం కంటే ముందు వస్తుంది); భారత స్వాతంత్ర్య చట్టం జూలై 1947లో వచ్చింది. ఎంపిక 1 (d, a, b, c) మాత్రమే సరిపోతుంది."},{"id":"t2023a-58","p":"t2023a","n":58,"s":"ih","t":"Modern India & Freedom Struggle","q":"Arrange the following events in chronological order:\n1. Indigo Movement\n2. Partition of Bengal\n3. Quit India Movement\n4. Formation of Indian National Congress","w":"The Indigo (Neel) revolt of the Bengal ryots took place in 1859–60; the Indian National Congress was founded at Bombay in December 1885; Lord Curzon's Partition of Bengal came into effect on 16 October 1905; and the Quit India Movement was launched on 8 August 1942. The chronological order is therefore 1, 4, 2, 3.","o":["2, 3, 4, 1","1, 2, 3, 4","1, 4, 2, 3","4, 3, 1, 2"],"a":[2],"qt":"క్రింది సంఘటనలను కాలక్రమానుసారంగా అమర్చండి:\n1. ఇండిగో ఉద్యమం\n2. బెంగాల్ విభజన\n3. క్విట్ ఇండియా ఉద్యమం\n4. భారత జాతీయ కాంగ్రెస్ ఏర్పాటు","ot":["2, 3, 4, 1","1, 2, 3, 4","1, 4, 2, 3","4, 3, 1, 2"],"wt":"బెంగాల్ రైతుల ఇండిగో (నీలిమందు) తిరుగుబాటు 1859–60లో జరిగింది; భారత జాతీయ కాంగ్రెస్ డిసెంబర్ 1885లో బొంబాయిలో ఏర్పడింది; లార్డ్ కర్జన్ చేసిన బెంగాల్ విభజన 16 అక్టోబర్ 1905 నుంచి అమలులోకి వచ్చింది; క్విట్ ఇండియా ఉద్యమం 8 ఆగస్టు 1942న ప్రారంభమైంది. కాబట్టి కాలక్రమం 1, 4, 2, 3."},{"id":"t2023a-59","p":"t2023a","n":59,"s":"ih","t":"Modern India & Freedom Struggle","q":"Arrange the following key groups and institutions in chronological order of their formation:\nA. Indian National Congress\nB. All India Muslim League\nC. Ghadar Party\nD. Hindustan Socialist Republican Association","w":"The Indian National Congress was founded at Bombay in December 1885; the All India Muslim League at Dhaka in December 1906; the Ghadar Party in 1913, with its headquarters at San Francisco, under Lala Har Dayal and Sohan Singh Bhakna; and the Hindustan Socialist Republican Association at Feroz Shah Kotla, Delhi, in September 1928. So the order is A, B, C, D.","o":["B, A, D, C","A, D, C, B","C, D, B, A","A, B, C, D"],"a":[3],"qt":"ఈ క్రింది కీలక సమూహాలు మరియు సంస్థల ఏర్పాటు యొక్క కాలక్రమానుసారంగా అమర్చండి:\nA. భారత జాతీయ కాంగ్రెస్\nB. ఆల్ ఇండియా ముస్లిం లీగ్\nC. ఘదర్ పార్టీ\nD. హిందుస్థాన్ సోషలిస్ట్ రిపబ్లికన్ అసోసియేషన్","ot":["B, A, D, C","A, D, C, B","C, D, B, A","A, B, C, D"],"wt":"భారత జాతీయ కాంగ్రెస్ డిసెంబర్ 1885లో బొంబాయిలో; ఆల్ ఇండియా ముస్లిం లీగ్ డిసెంబర్ 1906లో ఢాకాలో; ఘదర్ పార్టీ 1913లో లాలా హర్ దయాల్, సోహన్ సింగ్ భక్నా నాయకత్వంలో శాన్ ఫ్రాన్సిస్కో ప్రధాన కేంద్రంగా; హిందుస్థాన్ సోషలిస్ట్ రిపబ్లికన్ అసోసియేషన్ సెప్టెంబర్ 1928లో ఢిల్లీలోని ఫిరోజ్ షా కోట్లాలో ఏర్పడ్డాయి. కాబట్టి క్రమం A, B, C, D."},{"id":"t2023a-60","p":"t2023a","n":60,"s":"ih","t":"Modern India & Freedom Struggle","q":"Arrange the following personalities in chronological order of their death:\n1. Rabindranath Tagore\n2. Bhagat Singh\n3. Mahatma Gandhi\n4. Sardar Vallabhbhai Patel","w":"Bhagat Singh was hanged at Lahore on 23 March 1931; Rabindranath Tagore died on 7 August 1941; Mahatma Gandhi was assassinated on 30 January 1948; and Sardar Vallabhbhai Patel died on 15 December 1950. The order of their deaths is therefore 2, 1, 3, 4.","o":["2, 1, 3, 4","4, 2, 3, 1","3, 2, 1, 4","2, 3, 4, 1"],"a":[0],"qt":"ఈ క్రింది వ్యక్తులను వారి మరణం యొక్క కాలక్రమానుసారంగా అమర్చండి:\n1. రవీంద్రనాథ్ ఠాగూర్\n2. భగత్ సింగ్\n3. మహాత్మా గాంధీ\n4. సర్దార్ వల్లభాయ్ పటేల్","ot":["2, 1, 3, 4","4, 2, 3, 1","3, 2, 1, 4","2, 3, 4, 1"],"wt":"భగత్ సింగ్‌ను 23 మార్చి 1931న లాహోర్‌లో ఉరి తీశారు; రవీంద్రనాథ్ ఠాగూర్ 7 ఆగస్టు 1941న మరణించారు; మహాత్మా గాంధీ 30 జనవరి 1948న హత్యకు గురయ్యారు; సర్దార్ వల్లభాయ్ పటేల్ 15 డిసెంబర్ 1950న మరణించారు. కాబట్టి వారి మరణాల క్రమం 2, 1, 3, 4."},{"id":"t2023a-61","p":"t2023a","n":61,"s":"ih","t":"Modern India & Freedom Struggle","q":"Arrange the following Socio and Religious Reform events in chronological order of their establishment:\n1. Beginning of the Brahmo Samaj\n2. Founding of the Theosophical Society\n3. Bengal Sati Regulation Act\n4. Sharda Act","w":"Raja Rammohan Roy began the Brahmo Sabha (later the Brahmo Samaj) in Calcutta in August 1828; Lord William Bentinck's Bengal Sati Regulation (XVII) banned sati in December 1829; Madame Blavatsky and Colonel Olcott founded the Theosophical Society in New York in 1875 (headquarters at Adyar from 1882); and the Sharda Act (Child Marriage Restraint Act) was passed in 1929. Order: 1, 3, 2, 4.","o":["2, 3, 4, 1","1, 3, 2, 4","1, 2, 3, 4","4, 2, 3, 1"],"a":[1],"qt":"ఈ క్రింది సామాజిక మరియు మత సంస్కరణ ఉద్యమాలను వాటి స్థాపన యొక్క కాలక్రమానుసారంగా అమర్చండి:\n1. బ్రహ్మ సమాజం ప్రారంభం\n2. థియోసాఫికల్ సొసైటీ స్థాపన\n3. బెంగాల్ సతీ నియంత్రణ చట్టం\n4. శారదా చట్టం","ot":["2, 3, 4, 1","1, 3, 2, 4","1, 2, 3, 4","4, 2, 3, 1"],"wt":"రాజా రామ్మోహన్ రాయ్ ఆగస్టు 1828లో కలకత్తాలో బ్రహ్మ సభను (తర్వాత బ్రహ్మ సమాజం) ప్రారంభించారు; లార్డ్ విలియం బెంటింక్ బెంగాల్ సతీ నియంత్రణ చట్టం (రెగ్యులేషన్ XVII) ద్వారా డిసెంబర్ 1829లో సతిని నిషేధించారు; మేడమ్ బ్లావట్‌స్కీ, కల్నల్ ఆల్కాట్ 1875లో న్యూయార్క్‌లో థియోసాఫికల్ సొసైటీని స్థాపించారు (1882 నుంచి ప్రధాన కార్యాలయం అడయార్‌లో); శారదా చట్టం (బాల్య వివాహ నిరోధక చట్టం) 1929లో ఆమోదం పొందింది. క్రమం: 1, 3, 2, 4."},{"id":"t2023a-62","p":"t2023a","n":62,"s":"ih","t":"Modern India & Freedom Struggle","q":"Which group of Indian nationalists was formed in 1916 with the aim of achieving Swaraj or self-rule for India?","w":"The Home Rule Leagues were set up in 1916 on the Irish model: Bal Gangadhar Tilak's at Belgaum in April and Annie Besant's at Madras in September, to win self-government within the British Empire. The Congress (1885) and the Muslim League (1906) were formed much earlier, and socialist parties came only in the 1930s (the Congress Socialist Party, 1934).","o":["The Indian National Congress","The Muslim League","The Home Rule League","The Indian Socialist Party"],"a":[2],"qt":"భారతదేశానికి స్వరాజ్యం లేదా స్వపరిపాలన సాధించే లక్ష్యంతో 1916 లో ఏర్పడిన భారతీయ జాతీయవాదుల సమూహం ఏది?","ot":["భారత జాతీయ కాంగ్రెస్","ముస్లిం లీగ్","హోమ్ రూల్ లీగ్","ఇండియన్ సోషలిస్ట్ పార్టీ"],"wt":"ఐర్లాండ్ నమూనాలో 1916లో హోమ్ రూల్ లీగ్‌లు ఏర్పడ్డాయి: బాల గంగాధర తిలక్ ఏప్రిల్‌లో బెల్గాంలో, అనిబిసెంట్ సెప్టెంబర్‌లో మద్రాసులో వీటిని స్థాపించారు; బ్రిటిష్ సామ్రాజ్యం లోపలే స్వపరిపాలన సాధించడం వీటి లక్ష్యం. కాంగ్రెస్ (1885), ముస్లిం లీగ్ (1906) చాలా ముందే ఏర్పడ్డాయి; సోషలిస్ట్ పార్టీలు 1930లలోనే వచ్చాయి (కాంగ్రెస్ సోషలిస్ట్ పార్టీ, 1934)."},{"id":"t2023a-63","p":"t2023a","n":63,"s":"ih","t":"Modern India & Freedom Struggle","q":"Which organization was formed in 1928 by Bhagat Singh, Chandrashekhar Azad, and other revolutionaries to carry out armed revolution against the British Raj?","w":"In September 1928, at a meeting at Feroz Shah Kotla in Delhi, Bhagat Singh, Chandrashekhar Azad, Sukhdev and others reorganised the Hindustan Republican Association (1924) as the Hindustan Socialist Republican Association, adding socialism to its aim of armed revolution. The Indian National Army was raised in 1942 by Mohan Singh and led by Subhas Chandra Bose from 1943; the Congress and the Muslim League were not revolutionary bodies.","o":["The Hindustan Socialist Republican Association","The Indian National Congress","The Indian National Army","The All India Muslim League"],"a":[0],"qt":"బ్రిటిష్ పరిపాలనకు వ్యతిరేకంగా సాయుధ విప్లవం చేసేందుకు భగత్ సింగ్, చంద్రశేఖర్ ఆజాద్ మరియు ఇతర విప్లవకారులు 1928 లో స్థాపించిన సంస్థ ఏది?","ot":["హిందుస్థాన్ సోషలిస్ట్ రిపబ్లికన్ అసోసియేషన్","భారత జాతీయ కాంగ్రెస్","ఇండియన్ నేషనల్ ఆర్మీ","ఆల్ ఇండియా ముస్లిం లీగ్"],"wt":"సెప్టెంబర్ 1928లో ఢిల్లీలోని ఫిరోజ్ షా కోట్లాలో జరిగిన సమావేశంలో భగత్ సింగ్, చంద్రశేఖర్ ఆజాద్, సుఖ్‌దేవ్ తదితరులు హిందుస్థాన్ రిపబ్లికన్ అసోసియేషన్‌ను (1924) సోషలిజాన్ని లక్ష్యాలలో చేర్చి హిందుస్థాన్ సోషలిస్ట్ రిపబ్లికన్ అసోసియేషన్‌గా పునర్వ్యవస్థీకరించారు; సాయుధ విప్లవం దీని మార్గం. ఇండియన్ నేషనల్ ఆర్మీని 1942లో మోహన్ సింగ్ ఏర్పాటు చేయగా 1943 నుంచి సుభాష్ చంద్రబోస్ నడిపించారు; కాంగ్రెస్, ముస్లిం లీగ్ విప్లవ సంస్థలు కావు."},{"id":"t2023a-64","p":"t2023a","n":64,"s":"eco","t":"Indian Economy","q":"_______ is a direct tax in India.","w":"A direct tax is paid by the person on whom it is levied and cannot be shifted to others, for example income tax and corporate tax (on company profits, under the Income-tax Act, 1961). GST, excise duty and customs duty are indirect taxes on goods and services that are passed on to the buyer; since July 2017 GST has replaced most central excise duties, which now remain mainly on petroleum products and tobacco.","o":["Goods and Services Tax (GST)","Excise Duty","Customs Duty","Corporate Tax"],"a":[3],"qt":"_______ అనేది భారతదేశంలో ఒక ప్రత్యక్ష పన్ను.","ot":["వస్తువులు మరియు సేవల పన్ను (GST)","ఎక్సైజ్ సుంకం","కస్టమ్స్ సుంకం","కార్పొరేట్ పన్ను"],"wt":"ప్రత్యక్ష పన్నును అది విధించబడిన వ్యక్తే చెల్లిస్తాడు, దానిని ఇతరులపైకి బదిలీ చేయలేడు; ఆదాయపు పన్ను, కార్పొరేట్ పన్ను (ఆదాయపు పన్ను చట్టం, 1961 కింద కంపెనీల లాభాలపై) దీనికి ఉదాహరణలు. జీఎస్టీ, ఎక్సైజ్ సుంకం, కస్టమ్స్ సుంకం వస్తువులు, సేవలపై విధించి కొనుగోలుదారుపైకి బదిలీ అయ్యే పరోక్ష పన్నులు; జూలై 2017 నుంచి చాలా కేంద్ర ఎక్సైజ్ సుంకాల స్థానంలో జీఎస్టీ వచ్చింది, ఎక్సైజ్ ఇప్పుడు ప్రధానంగా పెట్రోలియం ఉత్పత్తులు, పొగాకుపై మిగిలింది."},{"id":"t2023a-65","p":"t2023a","n":65,"s":"pol","t":"Governance, Schemes & Social Issues","q":"Which of the following schemes is aimed at providing financial assistance to pregnant and lactating women in India?","w":"Pradhan Mantri Matru Vandana Yojana, a centrally sponsored maternity benefit scheme under the National Food Security Act running nationwide from 1 January 2017, pays pregnant women and lactating mothers ₹5,000 by direct benefit transfer for the first live birth, as part wage compensation and to promote good nutrition. Under Mission Shakti it also gives ₹6,000 for a second child who is a girl (births from 1 April 2022). Jan Dhan is about financial inclusion; the others are sanitation and digital programmes.","o":["Pradhan Mantri Jan Dhan Yojana","Pradhan Mantri Matru Vandana Yojana","Swachh Bharat Abhiyan","Digital India Programme"],"a":[1],"qt":"క్రింది వాటిలో భారతదేశంలోని గర్భిణులు మరియు పాలిచ్చే మహిళలకు ఆర్థిక సహాయం అందించడమే లక్ష్యంగా గల పథకం ఏది?","ot":["ప్రధాన మంత్రి జన్ ధన్ యోజన","ప్రధాన మంత్రి మాతృ వందన యోజన","స్వచ్ఛ భారత్ అభియాన్","డిజిటల్ ఇండియా కార్యక్రమము"],"wt":"ప్రధాన మంత్రి మాతృ వందన యోజన జాతీయ ఆహార భద్రత చట్టం కింద 1 జనవరి 2017 నుంచి దేశవ్యాప్తంగా అమలవుతున్న కేంద్ర ప్రాయోజిత ప్రసూతి ప్రయోజన పథకం; వేతన నష్టానికి పాక్షిక పరిహారంగా, మంచి పోషణను ప్రోత్సహించేందుకు మొదటి కాన్పుకు గర్భిణులు, పాలిచ్చే తల్లులకు ₹5,000ను ప్రత్యక్ష నగదు బదిలీ ద్వారా ఇస్తుంది. మిషన్ శక్తి కింద రెండో సంతానం ఆడపిల్ల అయితే ₹6,000 కూడా ఇస్తుంది (1 ఏప్రిల్ 2022 నుంచి జన్మించినవారికి). జన్ ధన్ ఆర్థిక సమ్మిళితానికి సంబంధించినది; మిగిలినవి పారిశుద్ధ్య, డిజిటల్ కార్యక్రమాలు."},{"id":"t2023a-66","p":"t2023a","n":66,"s":"eco","t":"Indian Economy","q":"Which of the following is NOT an example of foreign direct investment (FDI) in India after liberalization?","w":"FDI means a foreign investor acquiring a lasting interest in an Indian enterprise (any equity stake in an unlisted company, or 10% or more of a listed company's equity); a foreign national buying clothes for personal use is a consumer purchase, not an investment at all, so it is the intended answer. Strictly, an FII buying government securities and a non-resident's mutual-fund investment are also not FDI but portfolio investment, and a non-resident's share purchase is FDI only when it meets that test.","o":["Investment in shares of an Indian company by a non-resident","Investment in government securities by a foreign institutional investor (FII)","Purchase of apparels by a foreign national for personal use","Investment in a mutual fund by a non-resident"],"a":[2],"qt":"సరళీకరణ తర్వాత భారతదేశంలో విదేశీ ప్రత్యక్ష పెట్టుబడులకు (FDI) ఉదాహరణగా చెప్పని వాటిలో ఏది?","ot":["ప్రవాసి ద్వారా భారతీయ కంపెనీ షేర్లలో పెట్టుబడి","విదేశీ సంస్థాగత పెట్టుబడిదారు (FII) ద్వారా ప్రభుత్వ సెక్యూరిటీలలో పెట్టుబడి","వ్యక్తిగత ఉపయోగం కోసం ఒక విదేశీ పౌరుడు దుస్తులను కొనుగోలు చేయడం","ప్రవాసి ద్వారా మ్యూచువల్ ఫండ్‌లో పెట్టుబడి"],"wt":"విదేశీ ప్రత్యక్ష పెట్టుబడి (FDI) అంటే విదేశీ పెట్టుబడిదారు భారతీయ సంస్థలో దీర్ఘకాలిక ఆసక్తి పొందడం (అన్‌లిస్టెడ్ కంపెనీలో ఏ ఈక్విటీ వాటా అయినా, లేదా లిస్టెడ్ కంపెనీ ఈక్విటీలో 10% లేదా అంతకంటే ఎక్కువ); ఒక విదేశీ పౌరుడు వ్యక్తిగత ఉపయోగం కోసం దుస్తులు కొనడం కేవలం వినియోగ కొనుగోలు, అసలు పెట్టుబడే కాదు, కాబట్టి ఇదే ఉద్దేశించిన జవాబు. కచ్చితంగా చెప్పాలంటే FII ప్రభుత్వ సెక్యూరిటీలు కొనడం, ప్రవాసి మ్యూచువల్ ఫండ్ పెట్టుబడి కూడా FDI కావు, అవి పోర్ట్‌ఫోలియో పెట్టుబడులు; ప్రవాసి షేర్ల కొనుగోలు ఈ షరతును తీర్చినప్పుడే FDI అవుతుంది."},{"id":"t2023a-67","p":"t2023a","n":67,"s":"eco","t":"Indian Economy","q":"Which of the following is an example of privatization in India under economic reforms since 1991?","w":"Privatisation transfers the ownership or control of public sector enterprises to the private sector, chiefly through disinvestment, that is, selling the government's stake: examples are Modern Food Industries (2000), BALCO (2001) and the sale of Air India to the Tata group (January 2022). Setting up a new public sector company or nationalising a private firm enlarges the public sector, and subsidies to a private firm do not change ownership.","o":["Setting up of a new public sector company","Selling a stake in an existing public sector company to private players","Nationalization of a private company","Giving subsidies to a private company"],"a":[1],"qt":"క్రింది వాటిలో 1991 నుండి ఆర్థిక సంస్కరణల క్రింద భారతదేశంలో ప్రైవేటీకరణకు ఉదాహరణ ఏది?","ot":["కొత్త ప్రభుత్వ రంగ సంస్థ ఏర్పాటు","ఇప్పటికే ఉన్న ప్రభుత్వ రంగ కంపెనీలో వాటాను ప్రైవేట్ కంపెనీలకు విక్రయించడం","ఒక ప్రైవేట్ కంపెనీ యొక్క జాతీయీకరణ","ప్రైవేట్ కంపెనీకి రాయితీలు ఇవ్వడం"],"wt":"ప్రైవేటీకరణ అంటే ప్రభుత్వ రంగ సంస్థల యాజమాన్యాన్ని లేదా నియంత్రణను ప్రైవేట్ రంగానికి బదిలీ చేయడం; ఇది ప్రధానంగా పెట్టుబడుల ఉపసంహరణ, అంటే ప్రభుత్వ వాటాను అమ్మడం ద్వారా జరుగుతుంది. ఉదాహరణలు: మోడర్న్ ఫుడ్ ఇండస్ట్రీస్ (2000), బాల్కో (2001), ఎయిర్ ఇండియాను టాటా గ్రూప్‌కు అమ్మడం (జనవరి 2022). కొత్త ప్రభుత్వ రంగ సంస్థ ఏర్పాటు లేదా ప్రైవేట్ కంపెనీ జాతీయీకరణ ప్రభుత్వ రంగాన్ని పెంచుతాయి; ప్రైవేట్ కంపెనీకి రాయితీలు యాజమాన్యాన్ని మార్చవు."},{"id":"t2023a-68","p":"t2023a","n":68,"s":"eco","t":"Indian Economy","q":"Which Five Year Plan in India was launched after the economic reforms of 1991?","w":"After the Seventh Plan (1985–90), political instability led to two Annual Plans (1990–91 and 1991–92). The first plan launched after the July 1991 reforms was the Eighth Five Year Plan (1992–97), which began on 1 April 1992 and stressed human resource development and indicative planning. The Ninth (1997–2002), Tenth (2002–07) and Eleventh (2007–12) Plans came later; NITI Aayog replaced the Planning Commission in 2015.","o":["Eighth Five Year Plan","Ninth Five Year Plan","Tenth Five Year Plan","Eleventh Five Year Plan"],"a":[0],"qt":"1991 ఆర్థిక సంస్కరణల తర్వాత భారతదేశంలో ఏ పంచవర్ష ప్రణాళిక ప్రారంభించబడింది?","ot":["ఎనిమిదవ పంచవర్ష ప్రణాళిక","తొమ్మిదవ పంచవర్ష ప్రణాళిక","పదవ పంచవర్ష ప్రణాళిక","పదకొండవ పంచవర్ష ప్రణాళిక"],"wt":"ఏడవ ప్రణాళిక (1985–90) తర్వాత రాజకీయ అస్థిరత వల్ల రెండు వార్షిక ప్రణాళికలు (1990–91, 1991–92) అమలయ్యాయి. జూలై 1991 సంస్కరణల తర్వాత ప్రారంభమైన మొదటి ప్రణాళిక ఎనిమిదవ పంచవర్ష ప్రణాళిక (1992–97); ఇది 1 ఏప్రిల్ 1992న మొదలై మానవ వనరుల అభివృద్ధికి, సూచనాత్మక ప్రణాళికకు ప్రాధాన్యం ఇచ్చింది. తొమ్మిదవ (1997–2002), పదవ (2002–07), పదకొండవ (2007–12) ప్రణాళికలు తర్వాత వచ్చాయి; 2015లో ప్రణాళికా సంఘం స్థానంలో నీతి ఆయోగ్ వచ్చింది."},{"id":"t2023a-69","p":"t2023a","n":69,"s":"eco","t":"Indian Economy","q":"Which of the following measures was taken by the Indian government to promote trade after the economic reforms of 1991?","w":"The 1991 New Economic Policy liberalised trade by cutting customs tariffs step by step (the peak rate, well above 100 per cent in 1991, was brought down sharply during the 1990s), dismantling import licensing, making the rupee fully convertible on the current account by 1994 and ending state monopolies over most exports and imports. High tariffs, trade reserved for state firms and import bans belonged to the pre-1991 regime.","o":["Imposing high tariffs on imported goods","Allowing only state-owned companies to participate in trade","Reducing tariffs on imported goods","Banning imports of all non-essential goods"],"a":[2],"qt":"క్రింది వాటిలో 1991 ఆర్థిక సంస్కరణల తర్వాత వాణిజ్యాన్ని ప్రోత్సహించడానికి భారత ప్రభుత్వం తీసుకున్న చర్య ఏది?","ot":["దిగుమతి చేసుకున్న వస్తువులపై అధిక సుంకాలు విధించడం","వాణిజ్యంలో పాల్గొనడానికి ప్రభుత్వ యాజమాన్యంలోని కంపెనీలను మాత్రమే అనుమతించడం","దిగుమతి చేసుకున్న వస్తువులపై సుంకాలను తగ్గించడం","అన్ని అత్యవసరేతర వస్తువుల దిగుమతులను నిషేధించడం"],"wt":"1991 నూతన ఆర్థిక విధానం వాణిజ్యాన్ని సరళీకరించింది: కస్టమ్స్ సుంకాలను దశలవారీగా తగ్గించింది (1991లో 100 శాతానికి పైగా ఉన్న గరిష్ఠ రేటును 1990లలో భారీగా తగ్గించారు), దిగుమతి లైసెన్సింగ్‌ను తొలగించింది, 1994 నాటికి కరెంట్ ఖాతాలో రూపాయిని పూర్తిగా మార్చుకోదగినదిగా చేసింది, చాలా ఎగుమతులు, దిగుమతులపై ప్రభుత్వ గుత్తాధిపత్యాన్ని తొలగించింది. అధిక సుంకాలు, ప్రభుత్వ సంస్థలకే వాణిజ్యం, దిగుమతుల నిషేధం 1991కి ముందటి విధానపు లక్షణాలు."},{"id":"t2023a-70","p":"t2023a","n":70,"s":"eco","t":"Indian Economy","q":"The Green Revolution in India refers to which of the following?","w":"The Green Revolution, begun in 1965–67, meant adopting high-yielding varieties (HYV) of seeds, especially the Mexican dwarf wheats bred by Norman Borlaug, together with chemical fertilisers, pesticides, assured irrigation and farm machinery, which sharply raised food-grain output. M. S. Swaminathan is called its father in India. It has nothing to do with environmental awareness, renewable energy or organic farming.","o":["The spread of environmental awareness in India","The introduction of hybrid seeds and modern farming techniques in India","The implementation of renewable energy sources in India","The promotion of organic farming in India"],"a":[1],"qt":"భారతదేశంలో హరిత విప్లవం ఈ క్రింది వాటిలో దేనిని సూచిస్తుంది?","ot":["భారతదేశంలో పర్యావరణ అవగాహన వ్యాప్తి","భారతదేశంలో హైబ్రిడ్ విత్తనాలు మరియు ఆధునిక వ్యవసాయ పద్ధతుల పరిచయం","భారతదేశంలో పునరుత్పాదక ఇంధన వనరుల అమలు","భారతదేశంలో సేంద్రీయ వ్యవసాయాన్ని ప్రోత్సహించడం"],"wt":"1965–67లో ప్రారంభమైన హరిత విప్లవం అంటే అధిక దిగుబడినిచ్చే వంగడాల (HYV) విత్తనాలను, ముఖ్యంగా నార్మన్ బోర్లాగ్ అభివృద్ధి చేసిన మెక్సికన్ పొట్టి గోధుమ రకాలను, రసాయన ఎరువులు, పురుగుమందులు, హామీ ఉన్న నీటిపారుదల, వ్యవసాయ యంత్రాలతో కలిపి వినియోగించడం; దీనితో ఆహార ధాన్యాల ఉత్పత్తి గణనీయంగా పెరిగింది. భారతదేశంలో దీని పితామహుడు ఎం.ఎస్. స్వామినాథన్. దీనికి పర్యావరణ అవగాహన, పునరుత్పాదక ఇంధనం లేదా సేంద్రీయ వ్యవసాయంతో సంబంధం లేదు."},{"id":"t2023a-71","p":"t2023a","n":71,"s":"eco","t":"Indian Economy","q":"Which of the following states in India were the first to adopt the Green Revolution?","w":"The high-yielding wheat programme was first taken up in the north-western plains of Punjab, Haryana and western Uttar Pradesh, which had canal and tube-well irrigation, fertile alluvial soil and enterprising farmers. These States gained most in the first phase, mainly in wheat; rice-growing States such as Andhra Pradesh and Tamil Nadu benefited later, as the technology spread to rice in the 1970s and 1980s.","o":["Punjab, Haryana and Uttar Pradesh","Rajasthan, Gujarat, Madhya Pradesh","Kerala, Karnataka, Uttar Pradesh","Tamil Nadu, Assam, Andhra Pradesh"],"a":[0],"qt":"భారతదేశంలోని ఈ క్రింది రాష్ట్రాలలో హరిత విప్లవాన్ని మొదటిసారిగా ప్రారంభించినది ఏది?","ot":["పంజాబ్, హర్యానా మరియు ఉత్తరప్రదేశ్","రాజస్థాన్, గుజరాత్, మధ్యప్రదేశ్","కేరళ, కర్ణాటక, ఉత్తరప్రదేశ్","తమిళనాడు, అస్సాం, ఆంధ్రప్రదేశ్"],"wt":"అధిక దిగుబడి గోధుమ కార్యక్రమాన్ని మొదట కాలువలు, గొట్టపు బావుల నీటిపారుదల, సారవంతమైన ఒండ్రు నేలలు, ఉత్సాహవంతులైన రైతులు ఉన్న వాయవ్య మైదానాలైన పంజాబ్, హర్యానా, పశ్చిమ ఉత్తరప్రదేశ్‌లలో చేపట్టారు. మొదటి దశలో, ప్రధానంగా గోధుమలో, ఈ రాష్ట్రాలే ఎక్కువగా లాభపడ్డాయి; ఆంధ్రప్రదేశ్, తమిళనాడు వంటి వరి పండించే రాష్ట్రాలు 1970, 1980 దశకాల్లో ఈ సాంకేతికత వరికి విస్తరించినప్పుడు తర్వాత లబ్ధి పొందాయి."},{"id":"t2023a-72","p":"t2023a","n":72,"s":"pol","t":"Constitution & Rights","q":"Which of the following statements is true regarding the reservation policy in India?","w":"Reservation for SCs, STs and socially and educationally backward classes (Articles 15(4) and 16(4)) rests on social backwardness, with an income-based creamy layer excluded among OBCs. The 103rd Amendment (2019) added Articles 15(6) and 16(6) for up to 10% reservation for economically weaker sections, upheld by the Supreme Court in Janhit Abhiyan (November 2022). So, as at 2023, reservation uses both social and economic criteria.","o":["Reservation is based only on economic criteria","Reservation is based on both economic and social criteria","Reservation is not based on any criteria","Reservation is based only on social criteria"],"a":[1],"qt":"భారతదేశంలో రిజర్వేషన్ విధానానికి సంబంధించి ఈ క్రింది ప్రకటనలలో నిజమైనది ఏది?","ot":["రిజర్వేషన్ ఆర్థిక ప్రమాణాలపై మాత్రమే ఆధారపడి ఉంటుంది","రిజర్వేషన్ ఆర్థిక మరియు సామాజిక వర్గంపై ఆధారపడి ఉంటుంది","రిజర్వేషన్ ఏ ప్రమాణాల ఆధారంగా ఉండవు","రిజర్వేషన్ అనేది సామాజిక ప్రమాణాలపై మాత్రమే ఆధారపడి ఉంటుంది"],"wt":"ఎస్సీ, ఎస్టీలు, సామాజికంగా, విద్యాపరంగా వెనుకబడిన తరగతులకు రిజర్వేషన్ (అధికరణాలు 15(4), 16(4)) సామాజిక వెనుకబాటుతనంపై ఆధారపడుతుంది; ఓబీసీలలో ఆదాయ ఆధారిత క్రీమీ లేయర్‌ను మినహాయిస్తారు. 103వ సవరణ (2019) ఆర్థికంగా బలహీన వర్గాలకు (EWS) 10% వరకు రిజర్వేషన్ కోసం అధికరణాలు 15(6), 16(6)లను చేర్చింది; దీనిని సుప్రీంకోర్టు జన్‌హిత్ అభియాన్ కేసులో (నవంబర్ 2022) సమర్థించింది. కాబట్టి 2023 నాటికి రిజర్వేషన్ సామాజిక, ఆర్థిక ప్రమాణాలు రెండింటినీ ఉపయోగిస్తుంది."},{"id":"t2023a-73","p":"t2023a","n":73,"s":"pol","t":"Governance, Schemes & Social Issues","q":"Which of the following schemes aims to provide healthcare services to economically weaker sections of society in India?","w":"Ayushman Bharat – Pradhan Mantri Jan Arogya Yojana, launched on 23 September 2018 at Ranchi, gives poor and vulnerable families (identified from SECC 2011 data, about 12 crore families by 2023) cashless cover of ₹5 lakh per family per year for secondary and tertiary hospitalisation. Jan Dhan deals with bank accounts, Fasal Bima with crop insurance and Atal Pension Yojana with old-age pensions. Since October 2024 it also covers all citizens aged 70 and above.","o":["Pradhan Mantri Jan Dhan Yojana","Ayushman Bharat - Pradhan Mantri Jan Arogya Yojana","Pradhan Mantri Fasal Bima Yojana","Atal Pension Yojana"],"a":[1],"qt":"ఈ క్రింది పథకాలలో భారతదేశం సమాజంలోని ఆర్థికంగా బలహీన వర్గాలకు ఆరోగ్య సంరక్షణ సేవలను అందించడానికి ఉద్దేశించబడినది ఏది?","ot":["ప్రధాన మంత్రి జన్ ధన్ యోజన","ఆయుష్మాన్ భారత్ - ప్రధాన మంత్రి జన్ ఆరోగ్య యోజన","ప్రధాన మంత్రి ఫసల్ బీమా యోజన","అటల్ పెన్షన్ యోజన"],"wt":"ఆయుష్మాన్ భారత్ – ప్రధాన మంత్రి జన్ ఆరోగ్య యోజన 23 సెప్టెంబర్ 2018న రాంచీలో ప్రారంభమైంది; పేద, బలహీన కుటుంబాలకు (SECC 2011 ఆధారంగా గుర్తించినవి, 2023 నాటికి సుమారు 12 కోట్ల కుటుంబాలు) ద్వితీయ, తృతీయ స్థాయి ఆసుపత్రి చికిత్స కోసం కుటుంబానికి ఏడాదికి ₹5 లక్షల నగదు రహిత రక్షణ ఇస్తుంది. జన్ ధన్ బ్యాంకు ఖాతాలకు, ఫసల్ బీమా పంటల బీమాకు, అటల్ పెన్షన్ యోజన వృద్ధాప్య పింఛనుకు సంబంధించినవి. అక్టోబర్ 2024 నుంచి 70 ఏళ్లు పైబడిన పౌరులందరికీ కూడా ఇది వర్తిస్తుంది."},{"id":"t2023a-74","p":"t2023a","n":74,"s":"pol","t":"Constitution & Rights","q":"In the Constitution of India, the Right to Education can be found under ______.","w":"The 86th Constitutional Amendment Act, 2002 inserted Article 21A, making free and compulsory education for all children aged 6 to 14 a Fundamental Right; it is given effect by the Right of Children to Free and Compulsory Education Act, 2009, in force from 1 April 2010. As Article 21A lies in Part III, \"Fundamental Rights\" is not wrong either, but the key picks the specific article; Article 45 (a Directive Principle) now covers early childhood care and Article 51A(k) is a parental duty.","o":["Fundamental Rights","Directive Principles","Article 21A","Fundamental Duties"],"a":[2],"qt":"భారత రాజ్యాంగంలో, విద్యా హక్కును ______ కింద చూడవచ్చు.","ot":["ప్రాథమిక హక్కులు","నిర్దేశక సూత్రాలు","అధికరణం 21A","ప్రాథమిక విధులు"],"wt":"86వ రాజ్యాంగ సవరణ చట్టం, 2002 అధికరణం 21Aను చేర్చి 6 నుంచి 14 ఏళ్ల పిల్లలందరికీ ఉచిత, నిర్బంధ విద్యను ప్రాథమిక హక్కుగా చేసింది; 1 ఏప్రిల్ 2010 నుంచి అమలులో ఉన్న ఉచిత, నిర్బంధ బాలల విద్యా హక్కు చట్టం, 2009 దీనిని అమలు చేస్తుంది. అధికరణం 21A పార్ట్ IIIలోనే ఉన్నందున 'ప్రాథమిక హక్కులు' కూడా తప్పు కాదు, కానీ కీ నిర్దిష్ట అధికరణాన్ని ఎంచుకుంది; అధికరణం 45 (నిర్దేశక సూత్రం) ఇప్పుడు బాల్య సంరక్షణను, అధికరణం 51A(k) తల్లిదండ్రుల విధిని తెలుపుతాయి."},{"id":"t2023a-75","p":"t2023a","n":75,"s":"pol","t":"Governance, Schemes & Social Issues","q":"According to the Rights of Persons with Disabilities Act, 2016, what percentage of government vacancies are reserved for persons with disabilities?","w":"Section 34 of the Rights of Persons with Disabilities Act, 2016 requires every government establishment to reserve at least 4% of the vacancies in each group of posts for persons with benchmark disabilities: 1% each for blindness and low vision, for deafness and hard of hearing, and for locomotor disability (including acid attack victims), and 1% for autism, intellectual disability, mental illness and multiple disabilities. The 1995 Act had provided 3%.","o":["1%","2%","4%","5%"],"a":[2],"qt":"వికలాంగుల హక్కుల చట్టం, 2016 ప్రకారం, వికలాంగులకు ఎంత శాతం ప్రభుత్వ ఖాళీలు రిజర్వు చేయబడ్డాయి?","ot":["1%","2%","4%","5%"],"wt":"వికలాంగుల హక్కుల చట్టం, 2016లోని సెక్షన్ 34 ప్రకారం ప్రతి ప్రభుత్వ సంస్థ ప్రతి గ్రూపు పోస్టుల ఖాళీలలో కనీసం 4% బెంచ్‌మార్క్ వైకల్యం ఉన్నవారికి రిజర్వు చేయాలి: అంధత్వం-తక్కువ దృష్టి, బధిరత్వం-వినికిడి లోపం, చలన వైకల్యం (యాసిడ్ దాడి బాధితులు సహా) ఒక్కొక్కదానికి 1%, ఆటిజం, మేధో వైకల్యం, మానసిక అనారోగ్యం, బహుళ వైకల్యాలకు కలిపి 1%. 1995 చట్టం 3% మాత్రమే ఇచ్చింది."},{"id":"t2023a-76","p":"t2023a","n":76,"s":"geo","t":"Telangana Geography","q":"Into how many agro-climatic zones Telangana State is divided?","w":"Professor Jayashankar Telangana State Agricultural University (PJTSAU) and the State Action Plan on Climate Change divide Telangana into three agro-climatic zones: Northern, Central and Southern Telangana. Some state study material counts four, adding a High Altitude and Tribal Areas zone, and the key follows that count. (Preliminary key; some sources differ: PJTSAU, the state agricultural university, lists three zones.)","o":["3","4","5","6"],"a":[1],"qt":"తెలంగాణ రాష్ట్రం ఎన్ని వ్యవసాయ-వాతావరణ మండలాలుగా విభజించబడింది?","ot":["3","4","5","6"],"wt":"ప్రొఫెసర్ జయశంకర్ తెలంగాణ రాష్ట్ర వ్యవసాయ విశ్వవిద్యాలయం (PJTSAU), రాష్ట్ర వాతావరణ మార్పుల కార్యాచరణ ప్రణాళిక తెలంగాణను ఉత్తర, మధ్య, దక్షిణ తెలంగాణ అనే మూడు వ్యవసాయ-వాతావరణ మండలాలుగా విభజిస్తున్నాయి. కొన్ని రాష్ట్ర అధ్యయన పుస్తకాలు 'ఎత్తైన ప్రాంతాలు, గిరిజన ప్రాంతాల మండలాన్ని' కూడా కలిపి నాలుగు మండలాలుగా లెక్కిస్తాయి; కీ ఆ లెక్కనే అనుసరించింది. (ప్రాథమిక కీ; కొన్ని ఆధారాలు భిన్నంగా ఉన్నాయి: రాష్ట్ర వ్యవసాయ విశ్వవిద్యాలయం PJTSAU మూడు మండలాలనే పేర్కొంటోంది.)"},{"id":"t2023a-77","p":"t2023a","n":77,"s":"geo","t":"Telangana Geography","q":"How many basins are there in Telangana state?","w":"All of Telangana's rivers belong to just two basins: the Godavari, which drains the northern part of the state through tributaries such as the Pranahita, Manjira and Manair, and the Krishna, which drains the southern part through tributaries such as the Musi, Dindi and Tungabhadra. Both rivers flow east through Andhra Pradesh into the Bay of Bengal.","o":["5","4","3","2"],"a":[3],"qt":"తెలంగాణ రాష్ట్రంలో పరీవాహక ప్రాంతాలు ఎన్ని ఉన్నాయి?","ot":["5","4","3","2"],"wt":"తెలంగాణ నదులన్నీ రెండు పరీవాహక ప్రాంతాలకే చెందుతాయి: ప్రాణహిత, మంజీరా, మానేరు వంటి ఉపనదుల ద్వారా రాష్ట్ర ఉత్తర భాగాన్ని పారుదల చేసే గోదావరి, మూసీ, దిండి, తుంగభద్ర వంటి ఉపనదుల ద్వారా దక్షిణ భాగాన్ని పారుదల చేసే కృష్ణా. ఈ రెండు నదులు తూర్పుగా ఆంధ్రప్రదేశ్ గుండా ప్రవహించి బంగాళాఖాతంలో కలుస్తాయి."},{"id":"t2023a-78","p":"t2023a","n":78,"s":"geo","t":"Telangana Geography","q":"Which of the following statement/s is / are CORRECT?\n(a) The pattern of drainage is generally Dendritic drainage pattern with wide valleys in the western pedi plain in Telangana state.\n(b) There are 4 basins and 12 sub-basins in Telangana state.","w":"Statement (a) is correct: on the western pediplain of the Telangana plateau, streams branch like a tree (dendritic pattern) across gently sloping granite-gneiss country with broad, shallow valleys. Statement (b) is wrong because Telangana has only two river basins, the Godavari and the Krishna, each divided into a number of sub-basins; there are not four basins.","o":["Only (a)","Only (b)","Both (a) and (b)","Neither (a) nor (b)"],"a":[0],"qt":"ఈ క్రింది ప్రకటన/ల్లో ఏది /ఏవి సరైనది /వి?\n(a) తెలంగాణ రాష్ట్రంలోని పశ్చిమ పర్వతసానువుల్లో విశాలమైన లోయలతో కనిపించే పారుదల నమూనా అనేది సాధారణంగా శాఖాయుత పారుదల నమూనా.\n(b) తెలంగాణ రాష్ట్రంలో 4 పరీవాహక ప్రాంతాలు మరియు 12 ఉప పరీవాహక ప్రాంతాలు ఉన్నాయి.","ot":["(a) మాత్రమే","(b) మాత్రమే","(a) మరియు (b) లు రెండూ","(a) లేదా (b) రెండూ కాదు"],"wt":"ప్రకటన (a) సరైనది: తెలంగాణ పీఠభూమి పశ్చిమ పర్వతసానువు మైదానం (పెడిప్లెయిన్)లో, మెల్లగా వాలిన గ్రానైట్-నీస్ శిలల ప్రాంతంలో విశాలమైన, లోతు తక్కువ లోయలతో వాగులు చెట్టు కొమ్మల్లా (శాఖాయుత లేదా డెండ్రిటిక్ నమూనా) చీలిపోతాయి. ప్రకటన (b) తప్పు, ఎందుకంటే తెలంగాణలో గోదావరి, కృష్ణా అనే రెండు పరీవాహక ప్రాంతాలే ఉన్నాయి; ఒక్కొక్కటి కొన్ని ఉప పరీవాహక ప్రాంతాలుగా విభజించబడింది; నాలుగు పరీవాహక ప్రాంతాలు లేవు."},{"id":"t2023a-79","p":"t2023a","n":79,"s":"geo","t":"Telangana Geography","q":"Which of the following statements are CORRECT?\n(a) Telangana is the Only State in entire Southern India with vast deposits of Coal\n(b) Bauxite Ore occurs in Adilabad District in Telangana.\n(c) Limestone Slabs occur in Vikarabad and Nalgonda Districts in Telangana.\n(d) Iron ore in Mahabubabad district in Telangana","w":"(a) The Godavari Valley coalfield, mined by the Singareni Collieries Company, gives Telangana South India's only large coal reserves (Tamil Nadu's deposits are lignite). (d) Bayyaram in Mahabubabad district has well-known iron-ore deposits. (b) Bauxite in Adilabad is accepted by the key. (c) is wrong: limestone slabs, the polished Tandur stone, are typical of Vikarabad district, while Nalgonda's limestone is cement-grade rock, not slabs.","o":["(a), (b) and (d)","(c), (b) and (d)","(a), (c) and (d)","(a), (b) and (c)"],"a":[0],"qt":"ఈ క్రింది ప్రకటనల్లో ఏది/వి సరైనది/వి?\n(a) దక్షిణ భారతదేశంలో విస్తారమైన బొగ్గు నిక్షేపాలు కలిగిన ఏకైక రాష్ట్రం తెలంగాణ\n(b) బాక్సైట్ ఖనిజం తెలంగాణలోని ఆదిలాబాద్ జిల్లాలో లభిస్తుంది.\n(c) తెలంగాణలోని వికారాబాద్ మరియు నల్గొండ జిల్లాల్లో సున్నపురాయి పలకలు లభిస్తాయి.\n(d) తెలంగాణలోని మహబూబాబాద్ జిల్లాలో ఇనుప ఖనిజం కలదు","ot":["(a), (b) మరియు (d)","(c), (b) మరియు (d)","(a), (c) మరియు (d)","(a), (b) మరియు (c)"],"wt":"(a) సింగరేణి కాలరీస్ కంపెనీ తవ్వే గోదావరి లోయ బొగ్గు క్షేత్రం వల్ల దక్షిణ భారతదేశంలో పెద్ద బొగ్గు నిల్వలు ఉన్న ఏకైక రాష్ట్రం తెలంగాణ (తమిళనాడు నిక్షేపాలు లిగ్నైట్). (d) మహబూబాబాద్ జిల్లాలోని బయ్యారంలో ప్రసిద్ధ ఇనుప ఖనిజ నిక్షేపాలు ఉన్నాయి. (b) ఆదిలాబాద్‌లో బాక్సైట్ అనే ప్రకటనను కీ సరైనదిగా అంగీకరించింది. (c) తప్పు: సున్నపురాయి పలకలు (పాలిష్ చేసే తాండూరు రాయి) వికారాబాద్ జిల్లాకు ప్రత్యేకం; నల్గొండలోని సున్నపురాయి సిమెంట్ తయారీకి ఉపయోగించే రాయి, పలకలు కాదు."},{"id":"t2023a-80","p":"t2023a","n":80,"s":"eco","t":"Telangana Economy","q":"What is Telangana’s total installed capacity from wind power as of 2022?","w":"Telangana's installed wind-power capacity has stood at about 128 MW (128.1 MW in MNRE's state-wise data) for several years. It is a very small part of the state's renewable capacity, which is dominated by solar power of over 4,000 MW, because inland Telangana has modest wind speeds compared with Tamil Nadu, Gujarat or Karnataka.","o":["108 megawatts","118 megawatts","128 megawatts","138 megawatts"],"a":[2],"qt":"2022 నాటికి తెలంగాణ యొక్క మొత్తం స్థాపిత పవన శక్తి సామర్థ్యం ఎంత?","ot":["108 మెగావాట్లు","118 మెగావాట్లు","128 మెగావాట్లు","138 మెగావాట్లు"],"wt":"తెలంగాణ స్థాపిత పవన విద్యుత్ సామర్థ్యం కొన్ని సంవత్సరాలుగా సుమారు 128 మెగావాట్ల వద్దే ఉంది (MNRE రాష్ట్రాల వారీ గణాంకాల్లో 128.1 MW). రాష్ట్ర పునరుత్పాదక సామర్థ్యంలో ఇది చాలా చిన్న భాగం; అందులో 4,000 మెగావాట్లకు పైగా ఉన్న సౌర విద్యుత్‌దే ప్రధాన వాటా. తమిళనాడు, గుజరాత్, కర్ణాటకలతో పోలిస్తే సముద్రతీరం లేని తెలంగాణలో గాలి వేగం తక్కువగా ఉండటమే దీనికి కారణం."},{"id":"t2023a-81","p":"t2023a","n":81,"s":"eco","t":"Telangana Economy","q":"According to the data from the Central Electricity Authority (CEA), Telangana is ranked ________ in India in terms of total installed capacity of renewable energy as on September 2021.","w":"According to the Central Electricity Authority data on which the key is based, Telangana ranked eighth among the states in total installed renewable-energy capacity as on September 2021, behind states such as Karnataka, Tamil Nadu, Gujarat, Rajasthan, Maharashtra and Andhra Pradesh. Most of Telangana's renewable capacity is solar; its wind capacity is only about 128 MW.","o":["sixth","eighth","fourth","tenth"],"a":[1],"qt":"సెంట్రల్ ఎలక్ట్రిసిటీ అథారిటీ (CEA) యొక్క వివరాల ప్రకారం, సెప్టెంబర్ 2021 నాటికి పునరుత్పాదక శక్తి యొక్క మొత్తం స్థాపిత సామర్థ్యంలో తెలంగాణ భారతదేశంలోనే ________ స్థానంలో ఉంది.","ot":["ఆరవ","ఎనిమిదవ","నాల్గవ","పదవ"],"wt":"కీకి ఆధారమైన సెంట్రల్ ఎలక్ట్రిసిటీ అథారిటీ (CEA) గణాంకాల ప్రకారం, సెప్టెంబర్ 2021 నాటికి మొత్తం స్థాపిత పునరుత్పాదక శక్తి సామర్థ్యంలో తెలంగాణ రాష్ట్రాల్లో ఎనిమిదవ స్థానంలో ఉంది; కర్ణాటక, తమిళనాడు, గుజరాత్, రాజస్థాన్, మహారాష్ట్ర, ఆంధ్రప్రదేశ్ వంటి రాష్ట్రాలు ముందున్నాయి. తెలంగాణ పునరుత్పాదక సామర్థ్యంలో ఎక్కువ భాగం సౌర విద్యుత్; పవన సామర్థ్యం సుమారు 128 మెగావాట్లు మాత్రమే."},{"id":"t2023a-82","p":"t2023a","n":82,"s":"geo","t":"Telangana Geography","q":"Which of the following statement/s CORRECT?\n(a) Rajiv Gandhi International Airport was opened in Telangana state in 2014.\n(b) NH 16 in Telangana state passes through the important towns of Karimnagar, Adilabad and Nizamabad.","w":"(a) is wrong: Rajiv Gandhi International Airport at Shamshabad opened in March 2008, before Telangana was formed. (b) holds under the old highway numbering, in which NH 16 ran from Nizamabad via Jagtial (then Karimnagar district) and Mancherial (then Adilabad district) to Jagdalpur; since the 2010 renumbering this road is NH 63, and today's NH 16 is the east-coast Kolkata–Chennai highway, which does not enter Telangana. (Preliminary key; some sources differ: under the current numbering neither statement is correct.)","o":["Only (a)","Only (b)","Neither (a) nor (b)","Both (a) and (b)"],"a":[1],"qt":"ఈ క్రింది ప్రకటన /ల్లో ఏది సరైనది/వి?\n(a) రాజీవ్ గాంధీ అంతర్జాతీయ విమానాశ్రయం 2014 లో తెలంగాణ రాష్ట్రంలో ప్రారంభించబడింది.\n(b) తెలంగాణ రాష్ట్రం గుండా వెళ్ళే NH 16 కరీంనగర్, ఆదిలాబాద్ మరియు నిజామాబాద్ వంటి ముఖ్యమైన పట్టణాల గుండా వెళుతుంది.","ot":["(a) మాత్రమే","(b) మాత్రమే","(a) కానీ మరియు (b) కానీ ఏదీ కాదు","(a) మరియు (b) లు రెండూ"],"wt":"(a) తప్పు: శంషాబాద్‌లోని రాజీవ్ గాంధీ అంతర్జాతీయ విమానాశ్రయం తెలంగాణ ఏర్పడక ముందే మార్చి 2008లో ప్రారంభమైంది. (b) పాత జాతీయ రహదారుల సంఖ్యల ప్రకారం సరైనది: అప్పటి NH 16 నిజామాబాద్ నుండి జగిత్యాల (అప్పటి కరీంనగర్ జిల్లా), మంచిర్యాల (అప్పటి ఆదిలాబాద్ జిల్లా) మీదుగా జగదల్‌పూర్ వరకు వెళ్ళేది; 2010 సంఖ్యల మార్పు తర్వాత ఈ రహదారి NH 63 అయింది, ప్రస్తుత NH 16 తెలంగాణలోకి ప్రవేశించని తూర్పు తీర కోల్‌కతా–చెన్నై రహదారి. (ప్రాథమిక కీ; కొన్ని ఆధారాలు భిన్నంగా ఉన్నాయి: ప్రస్తుత సంఖ్యల ప్రకారం రెండు ప్రకటనలూ సరైనవి కావు.)"},{"id":"t2023a-83","p":"t2023a","n":83,"s":"tg","t":"Telangana History & Culture","q":"Which of the following is the additional official language of Telangana state?","w":"Telugu is Telangana's official language and Urdu its second (additional) official language. The Telangana Official Language (Amendment) Act, 2017 extended the use of Urdu as the second official language to all districts of the state, reflecting the large Urdu-speaking population of Hyderabad and other towns. Tamil, Kannada and Hindi have no such status in Telangana.","o":["Urdu","Tamil","Kannada","Hindi"],"a":[0],"qt":"ఈ క్రింది వాటిల్లో తెలంగాణ రాష్ట్రం యొక్క అదనపు అధికారిక భాష ఏది?","ot":["ఉర్దూ","తమిళం","కన్నడ","హిందీ"],"wt":"తెలుగు తెలంగాణ అధికార భాష కాగా, ఉర్దూ రెండవ (అదనపు) అధికార భాష. హైదరాబాద్, ఇతర పట్టణాల్లో ఉర్దూ మాట్లాడేవారు ఎక్కువగా ఉండటంతో, తెలంగాణ అధికార భాష (సవరణ) చట్టం, 2017 ఉర్దూను రెండవ అధికార భాషగా రాష్ట్రంలోని అన్ని జిల్లాలకు విస్తరించింది. తమిళం, కన్నడ, హిందీలకు తెలంగాణలో అటువంటి హోదా లేదు."},{"id":"t2023a-84","p":"t2023a","n":84,"s":"tg","t":"Telangana History & Culture","q":"_____ is performed widely across Telangana which is similar to Yakshagana.","w":"Chindu Bhagavatham is a folk theatre of Telangana performed by the Chindu Madiga community; like Yakshagana it combines song, dance and dialogue to enact stories from the epics and Puranas, and Chindu Yellamma of Nizamabad district was its best-known artiste. Perini Sivatandavam is a warrior dance of the Kakatiya era, Golla Suddulu a ballad tradition of the Golla community, and Dhoom Dham a cultural show of the Telangana movement.","o":["Dhoom Dham","Perini Sivatandavam","Chindu Bhagavatham","Golla Suddulu"],"a":[2],"qt":"యక్షగానాన్ని పోలి ఉండే ______ అనేది తెలంగాణ అంతటా విస్తృతంగా ప్రదర్శించబడుతుంది.","ot":["ధూమ్ ధామ్","పేరిణి శివతాండవం","చిందు భాగవతం","గొల్ల సుద్దులు"],"wt":"చిందు భాగవతం చిందు మాదిగ సామాజిక వర్గం ప్రదర్శించే తెలంగాణ జానపద నాటక రూపం; యక్షగానం లాగే ఇది పాట, నృత్యం, సంభాషణలతో ఇతిహాసాలు, పురాణాల కథలను ప్రదర్శిస్తుంది; నిజామాబాద్ జిల్లాకు చెందిన చిందు ఎల్లమ్మ దీనికి ప్రసిద్ధ కళాకారిణి. పేరిణి శివతాండవం కాకతీయుల కాలం నాటి వీర నృత్యం, గొల్ల సుద్దులు గొల్ల సామాజిక వర్గం కథాగాన సంప్రదాయం, ధూమ్ ధామ్ తెలంగాణ ఉద్యమ కాలపు సాంస్కృతిక ప్రదర్శన."},{"id":"t2023a-85","p":"t2023a","n":85,"s":"tg","t":"Telangana History & Culture","q":"_____ is also known as bell metal craft and is widely seen in Jainoor Mandal, Ushegaon and Chittalbori in Adilabad district.","w":"Dhokra (Dokra) is bell-metal craft made by the lost-wax casting method. In Telangana it is practised by the Wojari (Ojari) artisans of Ushegaon and Chittalbori in Jainoor mandal of old Adilabad district, now in Kumuram Bheem Asifabad district, who cast deities, animals, lamps and bells. Banjara is the embroidery of the Lambada tribe, and Rangam and Ghattam are rituals of the Bonalu festival.","o":["Banjara","Rangam","Ghattam","Dhokra"],"a":[3],"qt":"ఆదిలాబాద్ జిల్లాలోని జైనూర్ మండలం, ఉషేగావ్ మరియు చిత్తల్‌బోరిలలో విస్తృతంగా కనిపించే _____ని బెల్ మెటల్ క్రాఫ్ట్ అని కూడా పిలుస్తారు.","ot":["బంజారా","రంగం","ఘట్టం","ధోక్రా"],"wt":"ధోక్రా (డోక్రా) మైనపు అచ్చు (లాస్ట్-వాక్స్) పోత పద్ధతిలో తయారయ్యే బెల్ మెటల్ కళ. తెలంగాణలో పాత ఆదిలాబాద్ జిల్లాలోని (ఇప్పుడు కుమురం భీం ఆసిఫాబాద్ జిల్లా) జైనూర్ మండలంలోని ఉషేగావ్, చిత్తల్‌బోరి గ్రామాల వొజారి (ఓజారి) కళాకారులు దేవతలు, జంతువులు, దీపాలు, గంటల బొమ్మలను పోత పోస్తారు. బంజారా లంబాడా తెగ ఎంబ్రాయిడరీ; రంగం, ఘట్టం బోనాల పండుగ ఆచారాలు."},{"id":"t2023a-86","p":"t2023a","n":86,"s":"tg","t":"Telangana History & Culture","q":"_____ is a Hindu Festival, celebrated during the Telugu month of Ashadam.","w":"Bonalu, the festival of the Mother Goddess (Mahakali, Yellamma, Pochamma and her other forms), is celebrated in Hyderabad, Secunderabad and across Telangana in the Telugu month of Ashadam (June–July). Women carry 'bonam', cooked rice in decorated pots, as an offering to the goddess; Telangana declared it a state festival in 2014. Dussehra falls in Aswayuja, Rama Navami in Chaitra and Holi in Phalguna.","o":["Dussehra","Bonalu","Ram Navami","Holi"],"a":[1],"qt":"_____ అనే హిందూ పండుగ తెలుగు నెలైన ఆషాడంలో జరుపబడుతుంది.","ot":["దసరా","బోనాలు","రామ నవమి","హోలీ"],"wt":"బోనాలు అమ్మవారి (మహంకాళి, ఎల్లమ్మ, పోచమ్మ తదితర రూపాలు) పండుగ; హైదరాబాద్, సికింద్రాబాద్‌తో సహా తెలంగాణ అంతటా తెలుగు నెల ఆషాఢం (జూన్–జూలై)లో జరుపుకుంటారు. మహిళలు అలంకరించిన కుండల్లో వండిన అన్నం 'బోనం'ను అమ్మవారికి నైవేద్యంగా తీసుకువెళ్తారు; 2014లో తెలంగాణ దీనిని రాష్ట్ర పండుగగా ప్రకటించింది. దసరా ఆశ్వయుజంలో, శ్రీరామ నవమి చైత్రంలో, హోలీ ఫాల్గుణంలో వస్తాయి."},{"id":"t2023a-87","p":"t2023a","n":87,"s":"tg","t":"Telangana History & Culture","q":"Which of the following statements are CORRECT?\n(a) Dhokra or Dokra is also known as bell metal craft\n(b) Bidri Craft is the unique art of silver is engraved on metal.\n(c) The renowned Nirmal oil paintings use natural dyes for depicting themes from the epics.\n(d) Telangana is famous world-wide for its amazing Copper castings","w":"(a) Dhokra is bell-metal craft made by lost-wax casting. (b) Bidri, practised in Hyderabad and Bidar, inlays silver into an alloy of zinc and copper that is then blackened. (c) Nirmal paintings, made in Nirmal town, traditionally use natural colours and show themes from the Ramayana and Mahabharata. (d) is wrong: Telangana's famed metal crafts are of brass and bell metal, such as Pembarthi brassware and Dhokra, not copper castings.","o":["(a), (b) and (d)","(a), (c) and (d)","(b), (c) and (d)","(a), (b) and (c)"],"a":[3],"qt":"ఈ క్రింది ప్రకటనల్లో ఏది/వి సరైనది/వి?\n(a) ఢోక్రా లేదా డోక్రాను బెల్ మెటల్ క్రాఫ్ట్ అని కూడా పిలుస్తారు\n(b) బిద్రి క్రాఫ్ట్ అనేది లోహంపై వెండితో చెక్కబడే ఒక ప్రత్యేకమైన కళ.\n(c) ప్రఖ్యాత నిర్మల్ ఆయిల్ పెయింటింగుల్లో ఇతిహాసాల నుండి ఇతివృత్తాలను వర్ణించడానికి సహజ రంగులు ఉపయోగించబడతాయి.\n(d) అద్భుతమైన రాగి పోతలకి తెలంగాణ ప్రపంచవ్యాప్తంగా ప్రసిద్ధి చెందింది","ot":["(a), (b) మరియు (d)","(a), (c) మరియు (d)","(b), (c) మరియు (d)","(a), (b) మరియు (c)"],"wt":"(a) ధోక్రా మైనపు అచ్చు పోత పద్ధతిలో తయారయ్యే బెల్ మెటల్ కళ. (b) హైదరాబాద్, బీదర్‌లలో ప్రాచుర్యంలో ఉన్న బిద్రి కళలో జింక్, రాగి మిశ్రమ లోహంలో వెండిని పొదిగి, ఆ లోహాన్ని నల్లగా మారుస్తారు. (c) నిర్మల్ పట్టణంలో తయారయ్యే నిర్మల్ పెయింటింగ్స్‌లో సంప్రదాయంగా సహజ రంగులు వాడి రామాయణ, మహాభారత ఇతివృత్తాలను చిత్రిస్తారు. (d) తప్పు: తెలంగాణ ప్రసిద్ధ లోహ కళలు పెంబర్తి ఇత్తడి వస్తువులు, ధోక్రా వంటి ఇత్తడి, బెల్ మెటల్ కళలు; రాగి పోతలు కాదు."},{"id":"t2023a-88","p":"t2023a","n":88,"s":"tg","t":"Telangana History & Culture","q":"Which of the following pairs is INCORRECTLY matched?","w":"'Peerla panduga' is the name given in Telangana villages to Muharram, when Hindus and Muslims together carry the 'peerlu', the standards of Imam Hussain and other martyrs, so pairing it with Sankranti is wrong. Bathukamma is the flower festival of women, Vijayadashami is another name for Dussehra, and Bonalu is celebrated in Ashadam, so the other three pairs are correct.","o":["Bathukamma Festival - celebrated by womenfolk","Vijayadashami Festival - also known as Dussehra","Bonalu Festival - celebrated during Ashadam month","Sankranthi Festival - also called as ‘peerla panduga’"],"a":[3],"qt":"ఈ క్రింది జతలలో ఏది సరిగా జతపరచబడలేదు?","ot":["బతుకమ్మ పండుగ - మహిళలు జరుపుకుంటారు","విజయదశమి పండుగ - దీనిని దసరా అని కూడా అంటారు","బోనాల పండుగ – ఆషాఢమాసంలో జరుపుకుంటారు","సంక్రాంతి పండుగ - దీనిని 'పీర్ల పండుగ' అని కూడా అంటారు."],"wt":"తెలంగాణ గ్రామాల్లో మొహర్రంను 'పీర్ల పండుగ' అంటారు; అప్పుడు హిందువులు, ముస్లింలు కలిసి ఇమామ్ హుస్సేన్, ఇతర అమరవీరుల చిహ్నాలైన 'పీర్ల'ను ఊరేగిస్తారు; కాబట్టి దానిని సంక్రాంతితో జతపరచడం తప్పు. బతుకమ్మ మహిళల పూల పండుగ, విజయదశమికి దసరా అనే మరో పేరు ఉంది, బోనాలు ఆషాఢంలో జరుపుకుంటారు; కాబట్టి మిగిలిన మూడు జతలు సరైనవి."},{"id":"t2023a-89","p":"t2023a","n":89,"s":"tg","t":"Telangana History & Culture","q":"Which of the following is CORRECTLY matched?","w":"Golconda Fort, the Qutb Shahi citadel, is in Hyderabad district. Bhongir (Bhuvanagiri) Fort, built on a huge monolithic rock and attributed to the Western Chalukya king Tribhuvanamalla Vikramaditya VI, is in Yadadri Bhuvanagiri district. Elgandal Fort, on the Manair river, is in Karimnagar district. Only option 2 matches all three forts with their districts.","o":["Golconda – Karimnagar; Bhongir – Yadadri; Elgandal – Hyderabad","Golconda – Hyderabad; Bhongir – Yadadri; Elgandal – Karimnagar","Golconda – Hyderabad; Bhongir – Karimnagar; Elgandal – Yadadri","Golconda – Yadadri; Bhongir – Hyderabad; Elgandal – Karimnagar"],"a":[1],"qt":"ఈ క్రింది వాటిల్లో ఏది సరిగ్గా జతపరచబడింది?","ot":["గోల్కొండ – కరీంనగర్; భువనగిరి – యాదాద్రి; ఎల్గండల్ – హైదరాబాద్","గోల్కొండ – హైదరాబాద్; భువనగిరి – యాదాద్రి; ఎల్గండల్ – కరీంనగర్","గోల్కొండ – హైదరాబాద్; భువనగిరి – కరీంనగర్; ఎల్గండల్ – యాదాద్రి","గోల్కొండ – యాదాద్రి; భువనగిరి – హైదరాబాద్; ఎల్గండల్ – కరీంనగర్"],"wt":"కుతుబ్ షాహీల కోట అయిన గోల్కొండ కోట హైదరాబాద్ జిల్లాలో ఉంది. పెద్ద ఏకశిలా కొండపై నిర్మించిన, పశ్చిమ చాళుక్య రాజు త్రిభువనమల్ల విక్రమాదిత్య VI కట్టించినట్లు చెప్పబడే భువనగిరి కోట యాదాద్రి భువనగిరి జిల్లాలో ఉంది. మానేరు నది ఒడ్డున ఉన్న ఎల్గండల్ కోట కరీంనగర్ జిల్లాలో ఉంది. ఈ మూడు కోటలను వాటి జిల్లాలతో సరిగా జతపరిచింది ఎంపిక 2 మాత్రమే."},{"id":"t2023a-90","p":"t2023a","n":90,"s":"tg","t":"Telangana History & Culture","q":"Arrange the following in the increasing order of year of completion / establishment\n(a) Construction of Charminar was completed.\n(b) Construction of Secunderabad Railway station was completed.\n(c) Salar Jung Museum was established in Hyderabad\n(d) The Arya Samaj was established in Hyderabad","w":"Charminar was completed in 1591 under Muhammad Quli Qutb Shah; Secunderabad railway station was built in 1874 by the Nizam's Guaranteed State Railway; the Arya Samaj was established in Hyderabad in 1892; and the Salar Jung Museum opened in 1951. The increasing order is therefore (a), (b), (d), (c).","o":["(a), (c), (d) and (b)","(a), (b), (d) and (c)","(b), (c), (d) and (a)","(c), (a), (d) and (b)"],"a":[1],"qt":"పూర్తయిన / స్థాపించబడిన సంవత్సరం యొక్క పెరిగే క్రమంలో ఈ క్రింది వాటిని అమర్చండి\n(a) చార్మినార్ నిర్మాణం పూర్తయింది.\n(b) సికింద్రాబాద్ రైల్వే స్టేషన్ నిర్మాణం పూర్తయింది.\n(c) హైదరాబాద్‌లో సాలార్ జంగ్ మ్యూజియం స్థాపించబడింది\n(d) హైదరాబాద్‌లో ఆర్యసమాజ్ స్థాపించబడింది","ot":["(a), (c), (d) మరియు (b)","(a), (b), (d) మరియు (c)","(b), (c), (d) మరియు (a)","(c), (a), (d) మరియు (b)"],"wt":"చార్మినార్ నిర్మాణం 1591లో మహమ్మద్ కులీ కుతుబ్ షా కాలంలో పూర్తయింది; సికింద్రాబాద్ రైల్వే స్టేషన్‌ను 1874లో నిజాం గ్యారంటీడ్ స్టేట్ రైల్వే నిర్మించింది; హైదరాబాద్‌లో ఆర్యసమాజ్ 1892లో స్థాపించబడింది; సాలార్ జంగ్ మ్యూజియం 1951లో ప్రారంభమైంది. కాబట్టి పెరిగే క్రమం (a), (b), (d), (c)."},{"id":"t2023a-91","p":"t2023a","n":91,"s":"tg","t":"Telangana Schemes & Policies","q":"In which year Arogya Lakshmi scheme was launched in Telangana?","w":"Arogya Lakshmi was launched by the Telangana government on 1 January 2015. Through anganwadi centres it gives pregnant and lactating women one full nutritious meal a day along with eggs and milk, and gives eggs and extra food to children under six, in order to reduce anaemia, low birth weight and malnutrition.","o":["2014","2015","2016","2017"],"a":[1],"qt":"తెలంగాణలో ఆరోగ్యలక్ష్మి పథకాన్ని ఏ సంవత్సరంలో ప్రారంభించారు?","ot":["2014","2015","2016","2017"],"wt":"ఆరోగ్యలక్ష్మి పథకాన్ని తెలంగాణ ప్రభుత్వం 1 జనవరి 2015న ప్రారంభించింది. అంగన్‌వాడీ కేంద్రాల ద్వారా గర్భిణులు, బాలింతలకు రోజుకు ఒక పూట పూర్తి పౌష్టిక భోజనంతో పాటు గుడ్లు, పాలు అందిస్తుంది; రక్తహీనత, తక్కువ బరువుతో శిశు జననాలు, పోషకాహార లోపాన్ని తగ్గించేందుకు ఆరేళ్ల లోపు పిల్లలకు గుడ్లు, అదనపు ఆహారం ఇస్తుంది."},{"id":"t2023a-92","p":"t2023a","n":92,"s":"tg","t":"Telangana History & Culture","q":"Which of the following statement/s is / are CORRECT?\n(a) In the year 1942, during the regime of Nizam, excavations were taken up in Karimnagar, Nalgonda District and discovered the historical evidences such as the signs of Buddhism, coins, utensils etc\n(b) Kotilingala in Karimnagar district was the capital city for Shatavahana dynasty. During the year 1970-74, excavations were held in Kotilingala and Doolikatta and uncovered a lot of historical evidences and archeological monuments.","w":"(b) is correct: Kotilingala on the Godavari in old Karimnagar district (now Jagtial) has yielded coins of Simuka and other early Satavahana rulers and is regarded as their early capital; excavations there and at Dhulikatta revealed fortifications, a stupa and many antiquities. The key treats (a) as wrong; the best-known Nizam-era dig of those years, at Kondapur (1940–42), was in Medak district, now Sangareddy. (Preliminary key; some sources differ: the Nizam's department also excavated the Buddhist site of Phanigiri, then in Nalgonda district, in 1941–44.)","o":["Only (a)","Only (b)","Both (a) and (b)","Neither (a) nor (b)"],"a":[1],"qt":"ఈ క్రింది ప్రకటన /ల్లో ఏది /వి సరైనది /వి?\n(a) 1942లో, నిజాం హయాంలో, నల్గొండ, కరీంనగర్ జిల్లాలో జరుపబడిన తవ్వకాలలో బౌద్ధమతానికి సంబంధించిన చిహ్నాలు, నాణేలు, పాత్రలు మొదలైన చారిత్రక ఆధారాలను కనుగొన్నారు.\n(b) కరీంనగర్ జిల్లాలోని కోటిలింగాల శాతవాహన వంశానికి రాజధాని నగరం. 1970-74 సంవత్సరంలో కోటిలింగాల, దూళికట్టలలో జరిపిన తవ్వకాల్లో ఎన్నో చారిత్రక ఆధారాలు, పురావస్తు కట్టడాలు బయటపడ్డాయి.","ot":["(a) మాత్రమే","(b) మాత్రమే","(a) మరియు (b) లు రెండూ","(a) కానీ మరియు (b) కానీ ఏదీ కాదు"],"wt":"(b) సరైనది: పాత కరీంనగర్ జిల్లా (ఇప్పుడు జగిత్యాల)లో గోదావరి ఒడ్డున ఉన్న కోటిలింగాలలో సిముకుడు, ఇతర తొలి శాతవాహన రాజుల నాణేలు లభించాయి; దీనిని వారి తొలి రాజధానిగా భావిస్తారు; అక్కడ, ధూళికట్టలో జరిగిన తవ్వకాల్లో కోట గోడలు, స్తూపం, అనేక పురావస్తు వస్తువులు బయటపడ్డాయి. కీ (a)ను తప్పుగా పరిగణించింది; ఆ సంవత్సరాల్లో నిజాం కాలం నాటి ప్రసిద్ధ తవ్వకాలు (1940–42) జరిగిన కొండాపూర్ మెదక్ జిల్లాలో (ఇప్పుడు సంగారెడ్డి) ఉంది. (ప్రాథమిక కీ; కొన్ని ఆధారాలు భిన్నంగా ఉన్నాయి: నిజాం పురావస్తు శాఖ 1941–44లో అప్పటి నల్గొండ జిల్లాలోని బౌద్ధ క్షేత్రం ఫణిగిరిలో కూడా తవ్వకాలు జరిపింది.)"},{"id":"t2023a-93","p":"t2023a","n":93,"s":"tg","t":"Telangana History & Culture","q":"Which of the following statement/s is / are CORRECT?\n(a) The Buddhist texts and the chronicles of Megasthenese, who visited India in the 5th century BCE, referred to the existence of many fortified towns in Telangana.\n(b) Telangana has an iconic saree weaving cluster at Pochampalli, Nalgonda District\n(c) During the medieval era, Telugu literature benefitted from the patronage provided by Quli Qutb Shah, the founder of the Qutb Shahi dynasty","w":"(a) is wrong: Megasthenes, Seleucus Nicator's envoy at Chandragupta Maurya's court, came to India about 300 BCE, in the 4th century BCE, not the 5th. (b) is correct: Pochampally, famous for its ikat saris, was in Nalgonda district (now Yadadri Bhuvanagiri). (c) is accepted: the Qutb Shahi dynasty founded by Sultan Quli Qutb Shah patronised Telugu, most notably under Ibrahim Qutb Shah, who supported poets such as Addanki Gangadhara.","o":["(b) and (c)","(a) and (c)","Only (c)","Only (a)"],"a":[0],"qt":"ఈ క్రింది ప్రకటన/ల్లో ఏది /వి సరైనది /వి?\n(a) బౌద్ధుల గ్రంధాలు మరియు 5వ శతాబ్దం BCEలో భారతదేశాన్ని సందర్శించిన మెగస్తనీస్ యొక్క వృత్తాంతాలు, తెలంగాణలో అనేక కోట పట్టణాల ఉనికిని సూచిస్తున్నాయి.\n(b) తెలంగాణకు చెందిన నల్గొండ జిల్లాలోని పోచంపల్లిలో విశిష్టమైన చీర నేతకి చెందిన సమూహం ఉంది\n(c) మధ్యయుగంలో, కుతుబ్ షాహీ రాజవంశ స్థాపకుడైన కులీ కుతుబ్ షా అందించిన ప్రోత్సాహంతో తెలుగు సాహిత్యం ప్రయోజనం పొందింది.","ot":["(b) మరియు (c)","(a) మరియు (c)","(c) మాత్రమే","(a) మాత్రమే"],"wt":"(a) తప్పు: చంద్రగుప్త మౌర్యుని ఆస్థానంలో సెల్యూకస్ నికేటర్ రాయబారి అయిన మెగస్తనీస్ సుమారు క్రీ.పూ. 300లో, అంటే క్రీ.పూ. 4వ శతాబ్దంలో భారతదేశానికి వచ్చాడు, 5వ శతాబ్దంలో కాదు. (b) సరైనది: ఇక్కత్ చీరలకు ప్రసిద్ధమైన పోచంపల్లి నల్గొండ జిల్లాలో ఉండేది (ఇప్పుడు యాదాద్రి భువనగిరి). (c) కీ దీన్ని అంగీకరించింది: సుల్తాన్ కులీ కుతుబ్ షా స్థాపించిన కుతుబ్ షాహీ వంశం తెలుగును పోషించింది; ముఖ్యంగా ఇబ్రహీం కుతుబ్ షా అద్దంకి గంగాధరుడు వంటి కవులను ఆదరించాడు."},{"id":"t2023a-94","p":"t2023a","n":94,"s":"tg","t":"Telangana History & Culture","q":"Arrange the following in Chronological Order based on the year of establishment.\n(a) Andhra Samvardhini Library was established\n(b) A magazine Andhra Sahitya Parishat was started\n(c) Osmania Arts College was established\n(d) Salar Jung Museum was established","w":"The Andhra Samvardhini Grandhalayam (library) in Secunderabad dates from 1905, during the library movement that began with the Sri Krishnadevaraya Andhra Bhasha Nilayam (1901). The Andhra Sahitya Parishat's journal began in the early 1910s; Osmania University's Arts College came with the university founded in 1918 (its landmark building was completed in 1939); and the Salar Jung Museum opened in 1951. The order is (a), (b), (c), (d).","o":["(b), (a), (d) and (c)","(a), (b), (d) and (c)","(a), (b), (c) and (d)","(d), (b), (a) and (c)"],"a":[2],"qt":"స్థాపించబడిన సంవత్సరం ఆధారంగా ఈ క్రింది వాటిని కాలక్రమానుసారంగా అమర్చండి.\n(a) ఆంధ్ర సంవర్ధిని అనే గ్రంథాలయం స్థాపించబడింది\n(b) ఆంధ్ర సాహిత్య పరిషత్ అనే పత్రిక ప్రారంభించబడింది\n(c) ఉస్మానియా ఆర్ట్స్ కళాశాల స్థాపించబడింది\n(d) సాలార్ జంగ్ మ్యూజియం స్థాపించబడింది","ot":["(b), (a), (d) మరియు (c)","(a), (b), (d) మరియు (c)","(a), (b), (c) మరియు (d)","(d), (b), (a) మరియు (c)"],"wt":"సికింద్రాబాద్‌లోని ఆంధ్ర సంవర్ధిని గ్రంథాలయం 1905 నాటిది; శ్రీ కృష్ణదేవరాయ ఆంధ్ర భాషా నిలయం (1901)తో మొదలైన గ్రంథాలయ ఉద్యమ కాలంలో ఇది ఏర్పడింది. ఆంధ్ర సాహిత్య పరిషత్ పత్రిక 1910ల ప్రారంభంలో మొదలైంది; ఉస్మానియా ఆర్ట్స్ కళాశాల 1918లో స్థాపించబడిన విశ్వవిద్యాలయంతో పాటు వచ్చింది (దాని ప్రసిద్ధ భవనం 1939లో పూర్తయింది); సాలార్ జంగ్ మ్యూజియం 1951లో ప్రారంభమైంది. కాబట్టి క్రమం (a), (b), (c), (d)."},{"id":"t2023a-95","p":"t2023a","n":95,"s":"tg","t":"Telangana History & Culture","q":"Which of the following is CORRECTLY matched?","w":"Puttaparthi Narayanacharyulu wrote the kavya 'Penugonda Lakshmi' on Penukonda, the later Vijayanagara capital; 'Desa Charitralu' is a famous poem in Sri Sri's (Srirangam Srinivasarao's) collection 'Mahaprasthanam'; and 'Matti Manishi' is a novel by Vasireddy Seethadevi about a farmer's attachment to his land. Only option 2 pairs all three writers with their works.","o":["Puttaparthi Narayanacharya – Desa Charitralu; Srirangam Srinivasarao – Penugonda Lakshmi; Vasireddy Seethadevi – Mattimanishi","Puttaparthi Narayanacharya – Penugonda Lakshmi; Srirangam Srinivasarao – Desa Charitralu; Vasireddy Seethadevi – Mattimanishi","Puttaparthi Narayanacharya – Mattimanishi; Srirangam Srinivasarao – Desa Charitralu; Vasireddy Seethadevi – Penugonda Lakshmi","Puttaparthi Narayanacharya – Penugonda Lakshmi; Srirangam Srinivasarao – Mattimanishi; Vasireddy Seethadevi – Desa Charitralu"],"a":[1],"qt":"ఈ క్రింది వాటిల్లో ఏది సరిగ్గా జతపరచబడింది?","ot":["పుట్టపర్తి నారాయణాచార్య – దేశ చరిత్రలు; శ్రీరంగం శ్రీనివాసరావు – పెనుగొండ లక్ష్మి; వాసిరెడ్డి సీతాదేవి – మట్టిమనిషి","పుట్టపర్తి నారాయణాచార్య – పెనుగొండ లక్ష్మి; శ్రీరంగం శ్రీనివాసరావు – దేశ చరిత్రలు; వాసిరెడ్డి సీతాదేవి – మట్టిమనిషి","పుట్టపర్తి నారాయణాచార్య – మట్టిమనిషి; శ్రీరంగం శ్రీనివాసరావు – దేశ చరిత్రలు; వాసిరెడ్డి సీతాదేవి – పెనుగొండ లక్ష్మి","పుట్టపర్తి నారాయణాచార్య – పెనుగొండ లక్ష్మి; శ్రీరంగం శ్రీనివాసరావు – మట్టిమనిషి; వాసిరెడ్డి సీతాదేవి – దేశ చరిత్రలు"],"wt":"విజయనగర రాజుల తర్వాతి రాజధాని పెనుగొండపై పుట్టపర్తి నారాయణాచార్యులు 'పెనుగొండ లక్ష్మి' కావ్యాన్ని రచించారు; 'దేశ చరిత్రలు' శ్రీశ్రీ (శ్రీరంగం శ్రీనివాసరావు) 'మహాప్రస్థానం' సంకలనంలోని ప్రసిద్ధ కవిత; 'మట్టిమనిషి' ఒక రైతుకు తన భూమిపై ఉన్న మమకారాన్ని చిత్రించిన వాసిరెడ్డి సీతాదేవి నవల. ముగ్గురు రచయితలను వారి రచనలతో సరిగా జతపరిచింది ఎంపిక 2 మాత్రమే."},{"id":"t2023a-96","p":"t2023a","n":96,"s":"tg","t":"Telangana History & Culture","q":"Which of the following pairs is CORRECTLY matched?","w":"Domakonda Fort, the seat of the old Domakonda samsthan, is in Kamareddy district. The other pairs are wrong: Koilkonda Fort is in Mahabubnagar district, the Chaya Someswara temple, known for the unexplained shadow on its sanctum, is at Panagal in Nalgonda district, and the Ramappa temple, a UNESCO World Heritage Site since 2021, is at Palampet in Mulugu district.","o":["Koilkonda Fort --- Nalgonda district","Chaya Someswara Temple ---Mahabubnagar district","Ramappa Temple --- Hyderabad district","Domakonda Fort ---- Kamareddy district"],"a":[3],"qt":"ఈ క్రింది జతలలో ఏది సరిగ్గా జతపరచబడింది?","ot":["కోయిల్కొండ కోట --- నల్గొండ జిల్లా","ఛాయా సోమేశ్వరాలయం --- మహబూబ్ నగర్ జిల్లా","రామప్ప దేవాలయం --- హైదరాబాద్ జిల్లా","దోమకొండ కోట ---- కామారెడ్డి జిల్లా"],"wt":"పాత దోమకొండ సంస్థానానికి కేంద్రమైన దోమకొండ కోట కామారెడ్డి జిల్లాలో ఉంది. మిగిలిన జతలు తప్పు: కోయిల్కొండ కోట మహబూబ్ నగర్ జిల్లాలో ఉంది; గర్భగుడిపై వివరించలేని నీడకు ప్రసిద్ధమైన ఛాయా సోమేశ్వరాలయం నల్గొండ జిల్లాలోని పానగల్‌లో ఉంది; 2021 నుండి యునెస్కో ప్రపంచ వారసత్వ ప్రదేశమైన రామప్ప దేవాలయం ములుగు జిల్లాలోని పాలంపేటలో ఉంది."},{"id":"t2023a-97","p":"t2023a","n":97,"s":"tg","t":"Telangana Schemes & Policies","q":"As per Aarogyasri the benefit on family is on floater basis i.e., the total reimbursement of ______ can be availed of individually or collectively by members of the family.","w":"Under the Aarogyasri health insurance scheme the benefit is on a family floater basis: the total of Rs 1.50 lakh a year can be used by one member or shared among members of the family, with an additional buffer of Rs 50,000 for costly treatment. This is the scheme's original norm, which the key follows; the limit has since been raised, to Rs 10 lakh per family from December 2023.","o":["Rs.1.00 lakhs","Rs.1.25 lakhs","Rs.1.50 lakhs","Rs.2.00 lakhs"],"a":[2],"qt":"ఆరోగ్యశ్రీ ప్రకారం కుటుంబానికి ఫ్లోటర్ ప్రాతిపదికన ప్రయోజనం ఉంటుంది అంటే, కుటుంబ సభ్యులు వ్యక్తిగతంగా లేదా సమిష్టిగా ______ మొత్తం రీయింబర్స్‌మెంట్‌ను పొందవచ్చు.","ot":["రూ.1.00 లక్షలు","రూ.1.25 లక్షలు","రూ. 1.50 లక్షలు","రూ. 2.00 లక్షలు"],"wt":"ఆరోగ్యశ్రీ ఆరోగ్య బీమా పథకంలో ప్రయోజనం కుటుంబ ఫ్లోటర్ ప్రాతిపదికన ఉంటుంది: ఏడాదికి మొత్తం రూ. 1.50 లక్షలను కుటుంబంలోని ఒక సభ్యుడు వాడుకోవచ్చు లేదా సభ్యులంతా పంచుకోవచ్చు; ఖరీదైన చికిత్సలకు అదనంగా రూ. 50,000 బఫర్ ఉంటుంది. ఇది పథకం అసలు నిబంధన, కీ దీనినే అనుసరించింది; ఆ తర్వాత పరిమితిని పెంచారు, డిసెంబర్ 2023 నుండి కుటుంబానికి రూ. 10 లక్షలు."},{"id":"t2023a-98","p":"t2023a","n":98,"s":"geo","t":"Telangana Geography","q":"In which district of Telangana Regional Science Centre is located?","w":"Telangana's Regional Science Centre is at Hanamkonda in the Warangal tri-city, hence Warangal; strictly, Hanamkonda has been in Hanumakonda district, the renamed Warangal Urban district, since 2021. The centre promotes popular science among students through exhibits and programmes. Hyderabad's well-known B.M. Birla Science Centre and planetarium are a different, privately run institution.","o":["Hyderabad","Warangal","Nalgonda","Nizamabad"],"a":[1],"qt":"తెలంగాణలో ప్రాంతీయ విజ్ఞాన కేంద్రం ఏ జిల్లాలో ఉంది?","ot":["హైదరాబాద్","వరంగల్","నల్గొండ","నిజామాబాద్"],"wt":"తెలంగాణ ప్రాంతీయ విజ్ఞాన కేంద్రం వరంగల్ త్రినగరిలోని హనుమకొండలో ఉంది, కాబట్టి సమాధానం వరంగల్; కచ్చితంగా చెప్పాలంటే 2021 నుండి హనుమకొండ, పేరు మారిన వరంగల్ అర్బన్ జిల్లా అయిన హనుమకొండ జిల్లాలో ఉంది. ఈ కేంద్రం ప్రదర్శనలు, కార్యక్రమాల ద్వారా విద్యార్థుల్లో విజ్ఞాన శాస్త్రంపై అవగాహన పెంచుతుంది. హైదరాబాద్‌లోని ప్రసిద్ధ బి.ఎం. బిర్లా సైన్స్ సెంటర్, ప్లానెటేరియం ప్రైవేట్ నిర్వహణలోని వేరే సంస్థ."},{"id":"t2023a-99","p":"t2023a","n":99,"s":"tg","t":"Telangana Movement & State Formation","q":"In which year the States Reorganization Commission (SRC) submitted its report and recommended formation of Telangana state?","w":"The States Reorganisation Commission headed by Fazl Ali, with K.M. Panikkar and H.N. Kunzru, submitted its report on 30 September 1955. It recommended that Telangana be kept as a separate state (Hyderabad State), which could merge with Andhra after the 1961 elections if its legislature agreed by a two-thirds majority. The merger nonetheless took place on 1 November 1956 after the Gentlemen's Agreement.","o":["1950","1953","1955","1958"],"a":[2],"qt":"ఏ సంవత్సరంలో రాష్ట్రాల పునర్వ్యవస్థీకరణ కమిషన్ (SRC) తన నివేదికను సమర్పించి తెలంగాణ రాష్ట్ర ఏర్పాటుకు సిఫారసు చేసింది?","ot":["1950","1953","1955","1958"],"wt":"ఫజల్ అలీ అధ్యక్షతన, కె.ఎం. పణిక్కర్, హెచ్.ఎన్. కుంజ్రు సభ్యులుగా ఉన్న రాష్ట్రాల పునర్వ్యవస్థీకరణ కమిషన్ 30 సెప్టెంబర్ 1955న తన నివేదికను సమర్పించింది. తెలంగాణను ప్రత్యేక రాష్ట్రంగా (హైదరాబాద్ రాష్ట్రం) ఉంచాలని, 1961 ఎన్నికల తర్వాత శాసనసభ మూడింట రెండు వంతుల మెజారిటీతో అంగీకరిస్తే ఆంధ్రతో విలీనం కావచ్చని సిఫారసు చేసింది. అయినప్పటికీ పెద్దమనుషుల ఒప్పందం తర్వాత 1 నవంబర్ 1956న విలీనం జరిగింది."},{"id":"t2023a-100","p":"t2023a","n":100,"s":"tg","t":"Telangana Movement & State Formation","q":"In which year students intensified the protests for a separate Telangana state?","w":"In 1969 the 'Jai Telangana' agitation, demanding a separate state because the safeguards of the Gentlemen's Agreement had not been honoured, was led by students, especially of Osmania University; it began in January 1969 with a fast at Khammam and spread across the region. The Telangana Praja Samithi under M. Chenna Reddy later led the movement, and many protesters died in police firing.","o":["1964","1965","1969","1972"],"a":[2],"qt":"ప్రత్యేక తెలంగాణ రాష్ట్రం కోసం విద్యార్థులు ఏ సంవత్సరంలో తమ నిరసనలు తీవ్రతరం చేశారు?","ot":["1964","1965","1969","1972"],"wt":"పెద్దమనుషుల ఒప్పందంలోని రక్షణలను అమలు చేయలేదనే కారణంతో ప్రత్యేక రాష్ట్రాన్ని కోరుతూ 1969లో జరిగిన 'జై తెలంగాణ' ఉద్యమానికి విద్యార్థులు, ముఖ్యంగా ఉస్మానియా విశ్వవిద్యాలయ విద్యార్థులు నాయకత్వం వహించారు; ఇది జనవరి 1969లో ఖమ్మంలో నిరాహార దీక్షతో మొదలై ప్రాంతమంతా వ్యాపించింది. తర్వాత ఎం. చెన్నారెడ్డి నేతృత్వంలోని తెలంగాణ ప్రజా సమితి ఉద్యమాన్ని నడిపించింది; పోలీసు కాల్పుల్లో అనేకమంది ఆందోళనకారులు మరణించారు."},{"id":"t2023a-101","p":"t2023a","n":101,"s":"tg","t":"Telangana Movement & State Formation","q":"On which date in 1969, all party accord was reached to ensure the proper implementation of Telangana safeguards?","w":"Agitation over the violation of the Telangana safeguards (the Gentlemen's Agreement and Mulki rules) began in January 1969. On 19 January 1969 an all-party meeting chaired by Chief Minister Kasu Brahmananda Reddy reached an accord to implement them, including sending non-Mulki employees in Telangana posts back to Andhra and spending Telangana's surplus revenues in the region. The accord's failure intensified the 1969 Jai Telangana movement.","o":["19th January","19th February","9th July","9th June"],"a":[0],"qt":"1969లో ఏ తేదీన, తెలంగాణా భద్రతలను సక్రమంగా అమలు చేసేందుకు అన్ని పార్టీల ఒప్పందం కుదిరింది?","ot":["జనవరి 19","ఫిబ్రవరి 19","జూలై 9","జూన్ 9"],"wt":"తెలంగాణ రక్షణల (పెద్ద మనుషుల ఒప్పందం, ముల్కీ నిబంధనలు) ఉల్లంఘనపై జనవరి 1969లో ఆందోళన మొదలైంది. 19 జనవరి 1969న ముఖ్యమంత్రి కాసు బ్రహ్మానందరెడ్డి అధ్యక్షతన జరిగిన అఖిలపక్ష సమావేశంలో వాటిని అమలు చేయడానికి ఒప్పందం కుదిరింది; తెలంగాణ పోస్టుల్లోని నాన్-ముల్కీ ఉద్యోగులను ఆంధ్రకు వెనక్కి పంపడం, తెలంగాణ మిగులు నిధులను ఆ ప్రాంతంలోనే ఖర్చు చేయడం ఇందులో ఉన్నాయి. ఈ ఒప్పందం విఫలమవడంతో 1969 జై తెలంగాణ ఉద్యమం తీవ్రమైంది."},{"id":"t2023a-102","p":"t2023a","n":102,"s":"tg","t":"Telangana History & Culture","q":"Which of the following statement/s is / are CORRECT?\n(a) Sri Lakshmi Narasimha Swamy Temple, Yadadri is termed as ‘Dakshina Kasi’ (Southern Banaras).\n(b) Charminar was built as a ceremonial gateway to celebrate the foundation of Hyderabad at the end of the 17th century.","w":"Neither statement is correct. The title 'Dakshina Kashi' belongs to the Sri Raja Rajeshwara Swamy temple at Vemulawada (Rajanna Sircilla district), not to the Yadadri Lakshmi Narasimha temple. Charminar was built by Muhammad Quli Qutb Shah in 1591, when he founded Hyderabad, i.e. at the end of the 16th century, not the 17th; it is linked with the end of a plague and the founding of the new city.","o":["Only (a)","Only (b)","Both (a) and (b)","Neither (a) nor (b)"],"a":[3],"qt":"ఈ క్రింది ప్రకటన/ ల్లో ఏది /వి సరైనది /వి?\n(a) యాదాద్రిలోని శ్రీ లక్ష్మీ నరసింహ స్వామి దేవాలయాన్ని 'దక్షిణ కాశి' (దక్షిణ బనారస్) అని పిలుస్తారు.\n(b) 17వ శతాబ్దం చివరలో హైదరాబాద్ శంకుస్థాపనను జరుపుకోవడానికి చార్మినార్ ఒక ఉత్సవ ద్వారం వలె నిర్మించబడింది.","ot":["మాత్రమే (a)","మాత్రమే (b)","(a) మరియు (b) లు రెండూ","(a) కానీ మరియు (b) కానీ ఏదీ కాదు"],"wt":"రెండు ప్రకటనలూ సరైనవి కావు. 'దక్షిణ కాశి' అనే పేరు వేములవాడ (రాజన్న సిరిసిల్ల జిల్లా) శ్రీ రాజరాజేశ్వర స్వామి దేవాలయానికి చెందుతుంది, యాదాద్రి లక్ష్మీ నరసింహ స్వామి దేవాలయానికి కాదు. చార్మినార్‌ను మహమ్మద్ కులీ కుతుబ్ షా 1591లో హైదరాబాద్‌ను స్థాపించినప్పుడు నిర్మించాడు, అంటే 16వ శతాబ్దం చివరలో, 17వ శతాబ్దంలో కాదు; ఇది ప్లేగు వ్యాధి అంతంతో, కొత్త నగర స్థాపనతో ముడిపడి ఉంది."},{"id":"t2023a-103","p":"t2023a","n":103,"s":"tg","t":"Telangana Movement & State Formation","q":"Which of the following pairs is CORRECT?","w":"KCR began his fast-unto-death on 29 November 2009, not 2008. The Centre announced on 9 December 2009 that the process of forming Telangana would be initiated, and the UPA/CWC decision came on 30 July 2013, not July 2012. TRS MLAs resigned en masse in March 2008, February 2010 and July 2011, not April 2009. K. Chandrashekar Rao formed the TRS (renamed Bharat Rashtra Samithi in December 2022) on 27 April 2001 and launched it publicly at its first mass meeting, the 'Simha Garjana' at Karimnagar, on 17 May 2001.","o":["On Nov 29th, 2008 -- Kalvakuntla Chandrashekar Raohad announced an indefinite hunger strike","In July 2012 -- UPA government started the Telangana statehood process","In April 2009 ---TRS party MLAs resigned","On May 17th 2001---launch of Telangana Rashtra Samithi."],"a":[3],"qt":"ఈ క్రింది జతలలో ఏది సరైనది?","ot":["నవంబర్ 29, 2008న -- కల్వకుంట్ల చంద్రశేఖర్ రావు ఆమరణ నిరాహార దీక్షను ప్రకటించారు.","జూలై 2012లో -- తెలంగాణ రాష్ట్ర ఏర్పాటు ప్రక్రియను UPA ప్రభుత్వం ప్రారంభించింది","ఏప్రిల్ 2009లో ---TRS పార్టీ ఎమ్మెల్యేలు రాజీనామా చేశారు","మే 17, 2001న---తెలంగాణ రాష్ట్ర సమితి ప్రారంభం."],"wt":"కేసీఆర్ ఆమరణ నిరాహార దీక్ష 29 నవంబర్ 2009న ప్రారంభమైంది, 2008లో కాదు. తెలంగాణ ఏర్పాటు ప్రక్రియను ప్రారంభిస్తామని 9 డిసెంబర్ 2009న కేంద్రం ప్రకటించింది; రాష్ట్ర ఏర్పాటుపై UPA/CWC నిర్ణయం 30 జూలై 2013న వచ్చింది, జూలై 2012లో కాదు. TRS ఎమ్మెల్యేలు మూకుమ్మడిగా మార్చి 2008, ఫిబ్రవరి 2010, జూలై 2011లలో రాజీనామా చేశారు, ఏప్రిల్ 2009లో కాదు. కె. చంద్రశేఖర్ రావు 27 ఏప్రిల్ 2001న TRS (డిసెంబర్ 2022లో భారత్ రాష్ట్ర సమితిగా పేరు మారింది)ను స్థాపించి, 17 మే 2001న కరీంనగర్‌లో జరిగిన తొలి బహిరంగ సభ 'సింహగర్జన'తో పార్టీని ప్రజల ముందు ప్రారంభించారు."},{"id":"t2023a-104","p":"t2023a","n":104,"s":"tg","t":"Telangana Movement & State Formation","q":"Which of the following statements are CORRECT?\n(a) In 1953 the Indian government appointed the States Reorganization Commission (SRC) to look into various statehood demands in the country.\n(b) The SRC Commission submitted its report on 30th December 1956, and recommended formation of Telangana state.\n(c) During the period between 1955 September and 1956 November, the people of Telangana launched a series of protests demanding statehood by implementing the SRC recommendations.\n(d) Sri M. Chenna Reddy, founded the Telangana Praja Samithi (TPS) political party in 1969 to spearhead the statehood movement.","w":"In December 1953 the Centre appointed the States Reorganisation Commission (Fazl Ali, K.M. Panikkar, H.N. Kunzru), so (a) is correct. (b) is wrong: the SRC reported on 30 September 1955, not 30 December 1956, though it did favour a separate Hyderabad (Telangana) State. Protests in Telangana between September 1955 and November 1956 sought that recommendation's implementation, (c). M. Chenna Reddy led the Telangana Praja Samithi in the 1969 agitation, (d). Only option 3 leaves out (b).","o":["(b), (c) and (d)","(a), (b) and (d)","(a), (c) and (d)","(a), (b) and (c)"],"a":[2],"qt":"ఈ క్రింది ప్రకటనల్లో ఏది/వి సరైనది/వి?\n(a) 1953లో భారత ప్రభుత్వం దేశంలోని వివిధ రాష్ట్రాల డిమాండ్లను పరిశీలించడానికి రాష్ట్రాల పునర్వ్యవస్థీకరణ కమిషన్ (SRC)ని నియమించింది.\n(b) SRC కమిషన్ 30 డిసెంబర్ 1956న తన నివేదికను సమర్పిస్తూ, తెలంగాణ రాష్ట్ర ఏర్పాటుకు సిఫారసు చేసింది.\n(c) 1955 సెప్టెంబరు మరియు 1956 నవంబర్ ల మధ్య కాలంలో, తెలంగాణ ప్రజలు SRC సిఫార్సులను అమలు చేయడం ద్వారా రాష్ట్ర హోదాను డిమాండ్ చేస్తూ నిరసనల పరంపరను ప్రారంభించారు.\n(d) శ్రీ ఎం. చెన్నా రెడ్డి 1969లో రాష్ట్ర సాధన ఉద్యమానికి నాయకత్వం వహించేందుకు తెలంగాణ ప్రజా సమితి (టిపిఎస్) అనే రాజకీయ పార్టీని స్థాపించారు.","ot":["(b), (c) మరియు (d)","(a), (b) మరియు (d)","(a), (c) మరియు (d)","(a), (b) మరియు (c)"],"wt":"డిసెంబర్ 1953లో కేంద్రం ఫజల్ అలీ, కె.ఎం. పణిక్కర్, హెచ్.ఎన్. కుంజ్రులతో రాష్ట్రాల పునర్వ్యవస్థీకరణ కమిషన్‌ను నియమించింది, కాబట్టి (a) సరైనది. (b) తప్పు: SRC తన నివేదికను 30 సెప్టెంబర్ 1955న సమర్పించింది, 30 డిసెంబర్ 1956న కాదు; అయితే అది ప్రత్యేక హైదరాబాద్ (తెలంగాణ) రాష్ట్రానికే మొగ్గు చూపింది. ఆ సిఫార్సు అమలు కోసం సెప్టెంబర్ 1955 – నవంబర్ 1956 మధ్య తెలంగాణలో నిరసనలు జరిగాయి, (c). 1969 ఉద్యమంలో ఎం. చెన్నారెడ్డి తెలంగాణ ప్రజా సమితికి నాయకత్వం వహించారు, (d). (b) లేని ఎంపిక 3 ఒక్కటే."},{"id":"t2023a-105","p":"t2023a","n":105,"s":"geo","t":"Telangana Geography","q":"_______ is NOT a tributary of Godavari River.","w":"The Musi, on whose banks Hyderabad stands, is a tributary of the Krishna, not the Godavari. Manjira (right bank) and Pranahita (left bank) are major Godavari tributaries in Telangana, and 'vagu' is simply the Telugu word for a stream; many such vagus feed the Godavari. So the option that is clearly not a Godavari tributary is the Musi.","o":["Manjira","Vagu","Pranahita","Musi"],"a":[3],"qt":"_______ అనేది గోదావరి నదికి ఉపనది కాదు.","ot":["మంజీర","వాగు","ప్రాణహిత","మూసీ"],"wt":"ఒడ్డున హైదరాబాద్ నగరం ఉన్న మూసీ నది కృష్ణా నదికి ఉపనది, గోదావరికి కాదు. మంజీర (కుడి ఒడ్డు), ప్రాణహిత (ఎడమ ఒడ్డు) తెలంగాణలో గోదావరి ప్రధాన ఉపనదులు; 'వాగు' అంటే తెలుగులో చిన్న ప్రవాహం, ఇలాంటి ఎన్నో వాగులు గోదావరిలో కలుస్తాయి. కాబట్టి స్పష్టంగా గోదావరి ఉపనది కానిది మూసీ."},{"id":"t2023a-106","p":"t2023a","n":106,"s":"tg","t":"Telangana History & Culture","q":"Which of the following statements are CORRECT?\n(a) Banjara Needle Crafts is a form of embroidery and mirror work on fabrics employing the needlecraft.\n(b) Dokra Metal Crafts Also known as bell metal craft; widely seen in Medak district.\n(c) Chindu Bhagavatham is performed widely across Telangana. It is similar to Yakshagana","w":"(a) is correct: Banjara (Lambadi) needlecraft is embroidery with mirror work on fabrics. (b) is wrong on place: Dokra, the bell-metal craft made by the lost-wax process, is practised mainly by tribal artisans of Adilabad district, not Medak. (c) is correct: Chindu Bhagavatham, the folk theatre of the Chindu Madiga community centred in Nizamabad district, is performed across Telangana and resembles Yakshagana. Hence (a) and (c).","o":["(a) and (b)","(b) and (c)","(a) and (c)","(a), (b) and (c)"],"a":[2],"qt":"ఈ క్రింది ప్రకటనల్లో ఏది/వి సరైనది/వి?\n(a) బంజారా సూది హస్త కళలు అనేది సూదిని ఉపయోగించి చేతితో బట్టలపై చేసే బుటేదారీ మరియు అద్దం పనులని చేసే ఒక కుట్టుపని రూపం.\n(b) డోక్రా మెటల్ క్రాఫ్టును బెల్ మెటల్ క్రాఫ్టు అని కూడా పిలుస్తారు; ఇది మెదక్ జిల్లాలో విస్తృతంగా కనిపిస్తుంది.\n(c) చిందు భాగవతం తెలంగాణ అంతటా విస్తృతంగా ప్రదర్శించబడుతుంది. ఇది యక్షగానాన్ని పోలి ఉంటుంది","ot":["(a) మరియు (b)","(b) మరియు (c)","(a) మరియు (c)","(a), (b) మరియు (c)"],"wt":"(a) సరైనది: బంజారా (లంబాడీ) సూది కళ బట్టలపై అద్దాల పనితో కూడిన కుట్టుపని (ఎంబ్రాయిడరీ). (b) ప్రాంతం విషయంలో తప్పు: లాస్ట్-వాక్స్ పోత పద్ధతిలో తయారయ్యే బెల్ మెటల్ కళ అయిన డోక్రాను ప్రధానంగా ఆదిలాబాద్ జిల్లా గిరిజన కళాకారులు చేస్తారు, మెదక్ కాదు. (c) సరైనది: నిజామాబాద్ జిల్లా కేంద్రంగా చిందు మాదిగలు ప్రదర్శించే జానపద నాటక రూపం చిందు భాగవతం తెలంగాణ అంతటా ప్రదర్శించబడుతుంది, ఇది యక్షగానాన్ని పోలి ఉంటుంది. కాబట్టి (a) మరియు (c)."},{"id":"t2023a-107","p":"t2023a","n":107,"s":"tg","t":"Telangana Schemes & Policies","q":"Which of the following statements are CORRECT?\n(a) KCR Nutrition Kit was launched by Health Minister T. Harish Rao at Kamareddy on 31st December 2021.\n(b) Mana ooru - Mana badi was launched on 8th March 2022\n(c) Dalit Bandhu scheme provides an one-time grant of Rs. 10,00,000/- to the beneficiaries thereby instilling a sense of financial security and hope for a better future.","w":"(a) is wrong: Health Minister T. Harish Rao launched the KCR Nutrition Kit scheme for pregnant women at Kamareddy in December 2022, not 2021. (b) Mana Ooru – Mana Badi, the programme to upgrade infrastructure in government schools, was launched by Chief Minister K. Chandrashekar Rao on 8 March 2022 at Wanaparthy. (c) Dalit Bandhu (2021) gives each eligible Dalit family a one-time grant of ₹10 lakh, with no bank-loan linkage, to set up a unit of its choice.","o":["(a) and (b)","(b) and (c)","(a) and (c)","(a), (b) and (c)"],"a":[1],"qt":"ఈ క్రింది ప్రకటనల్లో ఏది/వి సరైనది/వి?\n(a) 31 డిసెంబర్ 2021న కామారెడ్డిలో ఆరోగ్య శాఖా మంత్రి టి. హరీష్ రావు కేసీఆర్ న్యూట్రిషన్ కిట్‌ను ప్రారంభించారు.\n(b) 8 మార్చి 2022న మన ఊరు - మన బడి ప్రారంభించబడింది\n(c) దళిత బంధు పథకం లబ్ధిదారులకు రు. 10,00,000/-ల ఏక-సమయ మంజూరును అందిస్తుంది, తద్వారా వారికి ఆర్థిక భద్రత మరియు మంచి భవిష్యత్తుపై భరోసాను కలిగిస్తుంది.","ot":["(a) మరియు (b)","(b) మరియు (c)","(a) మరియు (c)","(a), (b) మరియు (c)"],"wt":"(a) తప్పు: ఆరోగ్య మంత్రి టి. హరీష్ రావు గర్భిణీ స్త్రీల కోసం కేసీఆర్ న్యూట్రిషన్ కిట్ పథకాన్ని కామారెడ్డిలో డిసెంబర్ 2022లో ప్రారంభించారు, 2021లో కాదు. (b) ప్రభుత్వ పాఠశాలల్లో మౌలిక వసతులను మెరుగుపరిచే 'మన ఊరు – మన బడి' కార్యక్రమాన్ని ముఖ్యమంత్రి కె. చంద్రశేఖర్ రావు 8 మార్చి 2022న వనపర్తిలో ప్రారంభించారు. (c) దళిత బంధు (2021) అర్హత గల ప్రతి దళిత కుటుంబానికి తమకు నచ్చిన యూనిట్ ఏర్పాటు చేసుకునేందుకు బ్యాంకు రుణ అనుసంధానం లేకుండా రూ. 10 లక్షల ఏక-సమయ గ్రాంటును ఇస్తుంది."},{"id":"t2023a-108","p":"t2023a","n":108,"s":"tg","t":"Telangana Schemes & Policies","q":"In which year the Telangana government has launched Telangana Industrial Project Approval and Self-Certification System (TS-iPASS)?","w":"TS-iPASS, Telangana's single-window industrial clearance system with time-bound approvals and self-certification, was created by the TS-iPASS Act of 2014 under the new State's industrial policy, which is why the key gives 2014. The system itself was formally launched by Chief Minister K. Chandrashekar Rao on 12 June 2015, so some sources give 2015. (Preliminary key; some sources differ.)","o":["2012","2013","2014","2015"],"a":[2],"qt":"తెలంగాణ ప్రభుత్వం తెలంగాణ ఇండస్ట్రియల్ ప్రాజెక్ట్ అప్రూవల్ మరియు సెల్ఫ్ సర్టిఫికేషన్ సిస్టమ్ (TS-iPASS)ని ఏ సంవత్సరంలో ప్రారంభించింది?","ot":["2012","2013","2014","2015"],"wt":"సమయబద్ధ అనుమతులు, స్వీయ ధ్రువీకరణతో కూడిన తెలంగాణ సింగిల్-విండో పారిశ్రామిక అనుమతుల వ్యవస్థ TS-iPASS కొత్త రాష్ట్ర పారిశ్రామిక విధానంలో భాగంగా 2014 TS-iPASS చట్టం ద్వారా ఏర్పాటైంది, అందుకే కీ 2014 అని ఇచ్చింది. ఈ వ్యవస్థను ముఖ్యమంత్రి కె. చంద్రశేఖర్ రావు 12 జూన్ 2015న అధికారికంగా ప్రారంభించారు, కాబట్టి కొన్ని మూలాలు 2015 అని చెబుతాయి. (ప్రాథమిక కీ; కొన్ని మూలాలు భిన్నంగా ఉన్నాయి.)"},{"id":"t2023a-109","p":"t2023a","n":109,"s":"eco","t":"Telangana Economy","q":"Telangana has been ranked ______ in the country in the Sustainable Development Goals (SDG) Index India for the year 2020-2021.","w":"In NITI Aayog's SDG India Index 2020-21 (released in June 2021) Telangana scored 69, a 'Front Runner'. Among the States, only Kerala (75), Himachal Pradesh and Tamil Nadu (74), Andhra Pradesh, Goa, Karnataka and Uttarakhand (72), Sikkim (71) and Maharashtra (70) scored higher, so 69 was the sixth-highest score level, which is how the key counts 'sixth'; counting each State, Telangana was joint 10th with Gujarat. (Preliminary key; some sources differ.)","o":["fifth","sixth","seventh","fourth"],"a":[1],"qt":"2020-2021 సంవత్సరానికి గాను సస్టెయినబుల్ డెవలప్‌మెంట్ గోల్స్ (SDG) ఇండెక్స్ ఇండియాలో తెలంగాణ దేశంలో ______ ర్యాంక్‌ను పొందింది.","ot":["అయిదవ","ఆరవ","ఏడవ","నాలుగవ"],"wt":"నీతి ఆయోగ్ SDG ఇండియా ఇండెక్స్ 2020-21 (జూన్ 2021లో విడుదల)లో తెలంగాణ 69 స్కోరుతో 'ఫ్రంట్ రన్నర్'గా నిలిచింది. రాష్ట్రాలలో కేరళ (75), హిమాచల్ ప్రదేశ్, తమిళనాడు (74), ఆంధ్రప్రదేశ్, గోవా, కర్ణాటక, ఉత్తరాఖండ్ (72), సిక్కిం (71), మహారాష్ట్ర (70) మాత్రమే ఎక్కువ స్కోరు సాధించాయి; కాబట్టి 69 ఆరవ అత్యధిక స్కోరు స్థాయి, కీ 'ఆరవ' అని ఇలాగే లెక్కించింది; ఒక్కో రాష్ట్రాన్ని లెక్కిస్తే తెలంగాణ గుజరాత్‌తో కలిసి సంయుక్తంగా 10వ స్థానంలో ఉంది. (ప్రాథమిక కీ; కొన్ని మూలాలు భిన్నంగా ఉన్నాయి.)"},{"id":"t2023a-110","p":"t2023a","n":110,"s":"tg","t":"Telangana Movement & State Formation","q":"The Telangana state was inaugurated formally on ______ 2014.","w":"Telangana came into existence as India's 29th State on 2 June 2014 under the Andhra Pradesh Reorganisation Act, 2014, and K. Chandrashekar Rao was sworn in as its first Chief Minister that day; 2 June is celebrated as Telangana Formation Day. (Since Jammu and Kashmir became a Union Territory in 2019, India has 28 States.)","o":["June 2nd","June 5th","June 7th","June 9th"],"a":[0],"qt":"తెలంగాణ రాష్ట్రం అధికారికంగా ______ 2014న ఆవిర్భవించింది.","ot":["జూన్ 2","జూన్ 5","జూన్ 7","జూన్ 9"],"wt":"ఆంధ్రప్రదేశ్ పునర్వ్యవస్థీకరణ చట్టం, 2014 ప్రకారం తెలంగాణ 2 జూన్ 2014న భారతదేశ 29వ రాష్ట్రంగా ఆవిర్భవించింది; అదే రోజు కె. చంద్రశేఖర్ రావు తొలి ముఖ్యమంత్రిగా ప్రమాణ స్వీకారం చేశారు. జూన్ 2ను తెలంగాణ రాష్ట్ర అవతరణ దినోత్సవంగా జరుపుకుంటారు. (2019లో జమ్మూ కాశ్మీర్ కేంద్రపాలిత ప్రాంతంగా మారినప్పటి నుంచి భారతదేశంలో 28 రాష్ట్రాలు ఉన్నాయి.)"},{"id":"t2023a-111","p":"t2023a","n":111,"s":"tg","t":"Telangana History & Culture","q":"Ramappa Temple is a historical temple situated in the _____ of Telangana.","w":"The Rudreswara (Ramappa) Temple at Palampet is in Mulugu district, formed in 2019 out of Jayashankar Bhupalpally district. Built in 1213 CE by Recherla Rudra, a general of the Kakatiya king Ganapatideva, and popularly named after its sculptor Ramappa, it was inscribed as a UNESCO World Heritage Site in July 2021.","o":["Hyderabad district","Mulugu district","Nalgonda district","Nizamabad district"],"a":[1],"qt":"రామప్ప దేవాలయం తెలంగాణలోని _____ లో ఉన్న ఒక చారిత్రాత్మక దేవాలయం.","ot":["హైదరాబాద్ జిల్లా","ములుగు జిల్లా","నల్గొండ జిల్లా","నిజామాబాద్ జిల్లా"],"wt":"పాలంపేటలోని రుద్రేశ్వర (రామప్ప) దేవాలయం 2019లో జయశంకర్ భూపాలపల్లి జిల్లా నుంచి ఏర్పడిన ములుగు జిల్లాలో ఉంది. కాకతీయ రాజు గణపతిదేవుని సేనాని రేచర్ల రుద్రుడు దీనిని 1213లో నిర్మించాడు; శిల్పి రామప్ప పేరుతో ప్రసిద్ధి చెందిన ఈ దేవాలయం జూలై 2021లో యునెస్కో ప్రపంచ వారసత్వ ప్రదేశంగా గుర్తింపు పొందింది."},{"id":"t2023a-112","p":"t2023a","n":112,"s":"rea","t":"Logical Reasoning","q":"Five cousins Mugdha, Lata, Kareena, Sushma, and Radha are seated around a circular table facing the centre. Mugdha is to the immediate right of Lata. Kareena does not sit adjacent to Radha but is a neighbour of Lata.\nWhich of the following statement(s) is/are true based on the above conditions?\nA) Kareena sits to the immediate right of Sushma.\nB) Radha sits second to the right of Lata.","w":"All face the centre. Mugdha is on Lata's right, so Kareena, Lata's other neighbour, is on Lata's left. Kareena's other neighbour cannot be Radha, so it is Sushma, and Radha takes the remaining seat beside Mugdha. Going round to the right: Lata, Mugdha, Radha, Sushma, Kareena. Kareena is immediately right of Sushma and Radha is second to the right of Lata, so both A and B are true.","o":["A only","B only","Both A and B","Neither A nor B"],"a":[2],"qt":"ముగ్ధ, లత, కరీనా, సుష్మ మరియు రాధ అను ఐదుగురు కజిన్‌లు ఒక వృత్తాకార బల్ల చుట్టూ కేంద్రాభిముఖంగా కూర్చున్నారు. లతకు తక్షణ కుడివైపున ముగ్ధ ఉన్నారు. రాధకు ప్రక్కన కరీనా కూర్చోలేదు, కానీ తను లతకు పొరుగు వ్యక్తి.\nపై షరతుల ఆధారంగా క్రింది ప్రకటన(ల)లో ఏది/ఏవి సరైనది /వి?\nA) సుష్మాకు తక్షణ కుడివైపున కరీనా కూర్చుంది.\nB) లతకి కుడివైపున రెండవ స్థానంలో రాధ కూర్చుంది.","ot":["A మాత్రమే","B మాత్రమే","A మరియు B రెండూ","A కానీ లేదా B కానీ ఏదీ కాదు"],"wt":"అందరూ కేంద్రం వైపు చూస్తున్నారు. లతకు కుడివైపు ముగ్ధ ఉంది కాబట్టి లతకు మరో పొరుగు వ్యక్తి అయిన కరీనా లతకు ఎడమవైపు ఉంటుంది. కరీనా మరో పక్కన రాధ ఉండకూడదు కాబట్టి అక్కడ సుష్మ, మిగిలిన స్థానంలో (ముగ్ధ పక్కన) రాధ ఉంటారు. కుడివైపు క్రమంలో: లత, ముగ్ధ, రాధ, సుష్మ, కరీనా. సుష్మకు తక్షణ కుడివైపు కరీనా, లతకు కుడివైపు రెండవ స్థానంలో రాధ ఉన్నారు; కాబట్టి A, B రెండూ సరైనవి."},{"id":"t2023a-113","p":"t2023a","n":113,"s":"rea","t":"Logical Reasoning","q":"Six friends Mohan, Manish, Manas, Minal, Mehak and Mohit are sitting in a straight row facing North. Mehak and Mohit are in the centre. Mohan and Manish are at the corners. Manas is sitting to the immediate left of Mohan. Who is sitting to the immediate right of Manish?","w":"Number the seats 1 to 6 from left to right (all face north). Mehak and Mohit take seats 3 and 4; Mohan and Manish take the ends. Manas is on Mohan's immediate left, so Mohan cannot be at seat 1: Mohan is at 6 and Manas at 5. Manish is at seat 1, and the only person left, Minal, sits at seat 2, immediately to Manish's right.","o":["Minal","Manas","Mehak","Mohit"],"a":[0],"qt":"మోహన్, మనీష్, మానస్, మినాల్, మెహక్ మరియు మోహిత్ అను ఆరుగురు స్నేహితులు ఒక వరుసలో ఉత్తరాభిముఖంగా కూర్చున్నారు. మెహక్ మరియు మోహిత్ మధ్యలో ఉన్నారు. మోహన్ మరియు మనీష్ మూలల్లో ఉన్నారు. మోహన్‌కి తక్షణ ఎడమ వైపున మానస్ కూర్చున్నారు. మనీష్‌కు తక్షణ కుడివైపున ఎవరు కూర్చున్నారు?","ot":["మినల్","మానస్","మెహక్","మోహిత్"],"wt":"ఎడమ నుండి కుడికి స్థానాలను 1 నుండి 6గా తీసుకోండి (అందరూ ఉత్తరం వైపు చూస్తున్నారు). మెహక్, మోహిత్ 3, 4 స్థానాల్లో; మోహన్, మనీష్ చివరల్లో ఉన్నారు. మోహన్‌కు తక్షణ ఎడమవైపు మానస్ ఉన్నాడు కాబట్టి మోహన్ 1వ స్థానంలో ఉండలేడు: మోహన్ 6, మానస్ 5. మనీష్ 1వ స్థానంలో ఉంటాడు, మిగిలిన మినాల్ 2వ స్థానంలో, అంటే మనీష్‌కు తక్షణ కుడివైపు కూర్చుంటాడు."},{"id":"t2023a-114","p":"t2023a","n":114,"s":"rea","t":"Logical Reasoning","q":"In a row of 50 students (all are facing north), Raj is to the immediate left of Kiran whose position is 21st from the left end. Find the position of Raj from the right end.","w":"When everyone faces north, a person's left is towards the left end of the row. Kiran is 21st from the left, so Raj, immediately to his left, is 20th from the left. Position from the right = total − position from the left + 1 = 50 − 20 + 1 = 31st.","o":["30th","32nd","31st","29th"],"a":[2],"qt":"50 మంది విద్యార్థులు గల ఒక వరుసలో (అందరూ ఉత్తరాభిముఖంగా ఉన్నారు), ఎడమ వైపు నుండి 21వ స్థానంలో ఉన్న కిరణ్‌కి తక్షణ ఎడమ వైపున రాజ్ ఉన్నారు. కుడి చివర నుండి రాజ్ యొక్క స్థానాన్ని కనుగొనండి.","ot":["30వ","32వ","31వ","29వ"],"wt":"అందరూ ఉత్తరం వైపు చూస్తున్నప్పుడు ఒకరి ఎడమ అంటే వరుస ఎడమ చివర వైపు. కిరణ్ ఎడమ నుండి 21వ స్థానంలో ఉన్నాడు కాబట్టి అతనికి తక్షణ ఎడమవైపు ఉన్న రాజ్ ఎడమ నుండి 20వ స్థానంలో ఉంటాడు. కుడి నుండి స్థానం = మొత్తం − ఎడమ నుండి స్థానం + 1 = 50 − 20 + 1 = 31వ స్థానం."},{"id":"t2023a-115","p":"t2023a","n":115,"s":"rea","t":"Arithmetic & Mental Ability","q":"If the day before yesterday was Sunday, when will Thursday be?","w":"If the day before yesterday was Sunday, then yesterday was Monday and today is Tuesday. Counting forward, tomorrow is Wednesday and the day after tomorrow is Thursday, so Thursday comes two days from today, i.e. the day after tomorrow.","o":["Yesterday","Today","Tomorrow","Day after tomorrow"],"a":[3],"qt":"మొన్నటి రోజు ఆదివారం అయితే, గురువారం ఎప్పుడు వస్తుంది?","ot":["నిన్న","ఈరోజు","రేపు","ఎల్లుండి"],"wt":"మొన్న ఆదివారం అయితే నిన్న సోమవారం, ఈరోజు మంగళవారం. ముందుకు లెక్కిస్తే రేపు బుధవారం, ఎల్లుండి గురువారం; కాబట్టి గురువారం ఈరోజు నుంచి రెండు రోజుల తర్వాత, అంటే ఎల్లుండి వస్తుంది."},{"id":"t2023a-116","p":"t2023a","n":116,"s":"rea","t":"Arithmetic & Mental Ability","q":"Rekha's birthday is on the 10th of April and Seema's birthday is on the 11th of May. If in a particular year, Rekha's birthday was on Sunday, what will be the day on Seema's birthday in the same year?","w":"From 10 April to 11 May there are the remaining 20 days of April (30 − 10) plus 11 days of May = 31 days. 31 = 4 weeks + 3 days, so Seema's birthday falls three weekdays after Rekha's: Sunday + 3 = Wednesday. Leap years do not matter, since February does not fall in between.","o":["Tuesday","Wednesday","Monday","Thursday"],"a":[1],"qt":"రేఖ పుట్టినరోజు ఏప్రిల్ 10 మరియు సీమ పుట్టినరోజు మే 11. ఒక నిర్దిష్ట సంవత్సరంలో రేఖ పుట్టినరోజు ఆదివారం అయితే, అదే సంవత్సరంలో సీమ పుట్టినరోజు ఏ రోజు అవుతుంది?","ot":["మంగళవారం","బుధవారం","సోమవారం","గురువారం"],"wt":"ఏప్రిల్ 10 నుండి మే 11 వరకు ఏప్రిల్‌లో మిగిలిన 20 రోజులు (30 − 10) మరియు మేలో 11 రోజులు = 31 రోజులు. 31 = 4 వారాలు + 3 రోజులు, కాబట్టి సీమ పుట్టినరోజు రేఖ పుట్టినరోజు వారం నుంచి 3 రోజులు ముందుకు జరుగుతుంది: ఆదివారం + 3 = బుధవారం. ఫిబ్రవరి మధ్యలో రాదు కాబట్టి లీపు సంవత్సరంతో సంబంధం లేదు."},{"id":"t2023a-117","p":"t2023a","n":117,"s":"rea","t":"Logical Reasoning","q":"Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusions logically follow(s) from the statements.\nStatement I: All mobiles are gadgets.\nStatement II: No gadget is a tablet.\nConclusion I: Some gadgets are mobiles.\nConclusion II: Some mobiles are tablets.","w":"All mobiles are gadgets, so the mobiles form part of the gadgets and 'some gadgets are mobiles' follows by conversion: Conclusion I follows. No gadget is a tablet and every mobile is a gadget, so no mobile can be a tablet; Conclusion II ('some mobiles are tablets') is in fact false. Only Conclusion I follows.","o":["Only conclusion I follows","Only conclusion II follows","Both conclusion I and II follow","Neither conclusion I nor II follows"],"a":[0],"qt":"ఇవ్వబడిన ప్రకటనలు మరియు తీర్మానాలను జాగ్రత్తగా చదవండి. ఇవ్వబడిన సమాచారం సాధారణంగా తెలిసిన వాస్తవాలకు భిన్నంగా కనిపించినప్పటికీ, ఇవ్వబడిన తీర్మానాలలో ఏది ప్రకటనలను తార్కికంగా అనుసరిస్తున్నాయో నిర్ణయించండి.\nప్రకటన I: అన్ని మొబైల్‌లు గాడ్జెట్‌లు.\nప్రకటన II: గాడ్జెట్ ఏదీ టాబ్లెట్ కాదు.\nతీర్మానం I: కొన్ని గాడ్జెట్‌లు మొబైల్‌లు.\nతీర్మానం II: కొన్ని మొబైల్‌లు టాబ్లెట్‌లు.","ot":["తీర్మానం I మాత్రమే అనుసరిస్తుంది","తీర్మానం II మాత్రమే అనుసరిస్తుంది","తీర్మానం I మరియు II లు రెండూ అనుసరిస్తాయి","తీర్మానం I కానీ లేదా II కానీ ఏదీ అనుసరించదు"],"wt":"అన్ని మొబైల్‌లు గాడ్జెట్‌లు కాబట్టి మొబైల్‌లు గాడ్జెట్‌లలో భాగం; దానిని తిప్పి చెబితే 'కొన్ని గాడ్జెట్‌లు మొబైల్‌లు' వస్తుంది: తీర్మానం I అనుసరిస్తుంది. గాడ్జెట్ ఏదీ టాబ్లెట్ కాదు, ప్రతి మొబైల్ గాడ్జెట్ కాబట్టి ఏ మొబైల్ కూడా టాబ్లెట్ కాదు; తీర్మానం II ('కొన్ని మొబైల్‌లు టాబ్లెట్‌లు') నిజానికి తప్పు. కాబట్టి తీర్మానం I మాత్రమే అనుసరిస్తుంది."},{"id":"t2023a-118","p":"t2023a","n":118,"s":"rea","t":"Data Interpretation","q":"The figure shows the number of people in an office who eat different kinds of vegetables namely A, B and C.\nFind the number of people who eat exactly two vegetables.","w":"In the Venn diagram the regions inside exactly two circles are C and A only = 13, C and B only = 12, and A and B only = 10; the central 4 eat all three vegetables and are not counted. Number of people who eat exactly two vegetables = 13 + 12 + 10 = 35.","img":"data:image/png;base64,","o":["4","39","35","43"],"a":[2],"qt":"ఈ చిత్రము A, B మరియు C అను వివిధ రకాల కూరగాయలను తినే ఒక కార్యాలయంలోని వ్యక్తుల సంఖ్యను చూపుతుంది.\nసరిగ్గా రెండు కూరగాయలను తినే వ్యక్తుల సంఖ్యను కనుగొనండి.","ot":["4","39","35","43"],"wt":"వెన్ చిత్రంలో సరిగ్గా రెండు వృత్తాల్లో మాత్రమే ఉన్న భాగాలు: C, A మాత్రమే = 13, C, B మాత్రమే = 12, A, B మాత్రమే = 10; మధ్యలోని 4 మంది మూడు కూరగాయలూ తింటారు కాబట్టి వారిని లెక్కించకూడదు. సరిగ్గా రెండు కూరగాయలు తినే వ్యక్తుల సంఖ్య = 13 + 12 + 10 = 35."},{"id":"t2023a-119","p":"t2023a","n":119,"s":"rea","t":"Logical Reasoning","q":"Refer to the alphanumeric series given below and answer the following questions:\n(Left) 1 % S 8 6 7 & * F 4 # U @ 1 M ! 6 B H % T ? 9 (Right)\nFind the number of letters which are immediately preceded by a symbol and immediately followed by a number when counted from left to right.","w":"Check each letter with its neighbours: S (% before, 8 after) qualifies and F (* before, 4 after) qualifies. U is followed by @, M is preceded by 1, B by 6 and H by B, and T is followed by ?. So exactly two letters, S and F, are immediately preceded by a symbol and immediately followed by a number.","o":["1","3","2","0"],"a":[2],"qt":"క్రింద ఇవ్వబడిన అక్షరాంకిక శ్రేణిని దృష్టిలో ఉంచుకొని క్రింది ప్రశ్నలకు సమాధానం ఇవ్వండి:\n(ఎడమ) 1 % S 8 6 7 & * F 4 # U @ 1 M ! 6 B H % T ? 9 (కుడి)\nఎడమ నుండి కుడికి లెక్కించినప్పుడు తక్షణ ముందు స్థానంలో ఒక గుర్తు మరియు తక్షణ తరువాతి స్తానంలో ఒక సంఖ్యను కలిగి ఉన్న అక్షరాల సంఖ్యను కనుగొనండి.","ot":["1","3","2","0"],"wt":"ప్రతి అక్షరాన్ని దాని పక్కన ఉన్న వాటితో పరిశీలించండి: S (ముందు %, తర్వాత 8), F (ముందు *, తర్వాత 4) సరిపోతాయి. U తర్వాత @, M ముందు 1, B ముందు 6, H ముందు B ఉన్నాయి, T తర్వాత ? ఉంది. కాబట్టి తక్షణ ముందు గుర్తు, తక్షణ తర్వాత సంఖ్య ఉన్న అక్షరాలు S, F అనే రెండు మాత్రమే."},{"id":"t2023a-120","p":"t2023a","n":120,"s":"rea","t":"Logical Reasoning","q":"The height of six friends is as follows. Aman is taller than Rakesh. Subham is taller than Ranjan and Prem is taller than only Mukesh. Ranjan is taller than Aman. Rakesh is taller than Prem.\nWhich of the following statement(s) is/are true based on the above conditions?\nA) Subham is the tallest\nB) Mukesh is the shortest.\nC) Rakesh is taller than Subham.","w":"Prem is taller than only Mukesh, so Mukesh is the shortest and Prem fifth. Rakesh > Prem, Aman > Rakesh, Ranjan > Aman and Subham > Ranjan give the order Subham > Ranjan > Aman > Rakesh > Prem > Mukesh. Subham is the tallest (A true), Mukesh the shortest (B true), and Rakesh is shorter than Subham (C false). Hence A and B.","o":["A only","A and B","B and C","C only"],"a":[1],"qt":"ఆరుగురు స్నేహితుల ఎత్తులు ఈ విధంగా ఉన్నాయి. రాకేష్ కంటే అమన్ పొడుగ్గా ఉన్నాడు. రంజన్ కంటే సుభమ్ పొడవుగా ఉన్నాడు మరియు ముఖేష్ కంటే మాత్రమే ప్రేమ్ పొడవుగా ఉన్నాడు. అమన్ కంటే రంజన్ పొడుగ్గా ఉన్నాడు. ప్రేమ్ కంటే రాకేష్ పొడుగ్గా ఉన్నాడు.\nపై షరతుల ఆధారంగా క్రింది ప్రకటన(ల)లో ఏది/ఏవి సరైనది /వి?\nA) అందరికన్నా పొడుగైన వ్యక్తి సుభమ్\nB) అందరికన్నా పొట్టి వ్యక్తి ముఖేష్.\nC) సుభమ్ కంటే రాకేష్ పొడవుగా ఉన్నాడు.","ot":["A మాత్రమే","A మరియు B","B మరియు C","C మాత్రమే"],"wt":"ముఖేష్ కంటే మాత్రమే ప్రేమ్ పొడవు కాబట్టి ముఖేష్ అందరికన్నా పొట్టి, ప్రేమ్ ఐదవ స్థానం. రాకేష్ > ప్రేమ్, అమన్ > రాకేష్, రంజన్ > అమన్, సుభమ్ > రంజన్ నుంచి క్రమం: సుభమ్ > రంజన్ > అమన్ > రాకేష్ > ప్రేమ్ > ముఖేష్. సుభమ్ అందరికన్నా పొడవు (A సరైనది), ముఖేష్ అందరికన్నా పొట్టి (B సరైనది), రాకేష్ సుభమ్ కంటే పొట్టి (C తప్పు). కాబట్టి A మరియు B."},{"id":"t2023a-121","p":"t2023a","n":121,"s":"rea","t":"Logical Reasoning","q":"The age of six students, Ram, Shyam, Mohan, Shivam, Resham, and Lalit are given as follows: Ram is elder than only Resham. Mohan is not the eldest student. Shyam is elder than four students. Shivam is elder than Ram but younger than Mohan. Who is the eldest student?","w":"Ram is elder than only Resham, so Resham is the youngest and Ram fifth. Shyam is elder than four students, so he is second eldest. Shivam is elder than Ram but younger than Mohan, and Mohan is not the eldest, so Mohan and Shivam are third and fourth. Only Lalit is left for the eldest place: Lalit > Shyam > Mohan > Shivam > Ram > Resham.","o":["Resham","Shyam","Lalit","Shivam"],"a":[2],"qt":"రామ్, శ్యామ్, మోహన్, శివం, రేషమ్ మరియు లలిత్ అను ఆరుగురు విద్యార్థుల వయస్సు ఈ క్రింది విధంగా ఇవ్వబడ్డాయి: కేవలం రేషం కంటే రామ్ పెద్దవాడు. మోహన్ అందరికన్నా పెద్ద విద్యార్థి కాదు. శ్యామ్ నలుగురు విద్యార్థుల కంటే పెద్దవాడు. రామ్ కంటే పెద్దవాడు కానీ మోహన్ కంటే చిన్నవాడు శివం. అందరికన్నా పెద్ద విద్యార్థి ఎవరు?","ot":["రేషమ్","శ్యామ్","లలిత్","శివం"],"wt":"కేవలం రేషం కంటే రామ్ పెద్దవాడు కాబట్టి రేషం అందరికన్నా చిన్నవాడు, రామ్ ఐదవ స్థానం. శ్యామ్ నలుగురి కంటే పెద్దవాడు కాబట్టి రెండవ పెద్దవాడు. శివం రామ్ కంటే పెద్దవాడు, మోహన్ కంటే చిన్నవాడు; మోహన్ అందరికన్నా పెద్దవాడు కాదు, కాబట్టి మోహన్, శివం మూడు, నాలుగు స్థానాల్లో ఉంటారు. అందరికన్నా పెద్ద స్థానానికి మిగిలింది లలిత్ ఒక్కడే: లలిత్ > శ్యామ్ > మోహన్ > శివం > రామ్ > రేషం."},{"id":"t2023a-122","p":"t2023a","n":122,"s":"rea","t":"Logical Reasoning","q":"In a certain code language, 'SARCASM' is written as 'MSACRAS' and 'CHEESE' is written as 'ESEEHC'.\nBased on the given coding, match the following:\nList I | List II\nA. WATER | 1. LARENEG\nB. GENERAL | 2. NIATREC\nC. CERTAIN | 3. YLEVOL\nD. LOVELY | 4. RETAW","w":"The code simply writes each word backwards: SARCASM → MSACRAS and CHEESE → ESEEHC. Hence WATER → RETAW (4), GENERAL → LARENEG (1), CERTAIN → NIATREC (2) and LOVELY → YLEVOL (3), which gives A-4, B-1, C-2, D-3.","o":["A-3, B -1; C-2; D-4","A-4, B -2; C-1; D-3","A-4, B -1; C-3; D-2","A-4, B -1; C-2; D-3"],"a":[3],"qt":"ఒక నిర్దిష్ట కోడ్ భాషలో, 'SARCASM'ని 'MSACRAS' అని మరియు 'CHEESE'ని 'ESEEHC' అని వ్రాస్తారు.\nఇవ్వబడిన కోడింగ్ ఆధారంగా, క్రింది వాటిని జతపరచండి:\nజాబితా I | జాబితా II\nA. WATER | 1. LARENEG\nB. GENERAL | 2. NIATREC\nC. CERTAIN | 3. YLEVOL\nD. LOVELY | 4. RETAW","ot":["A-3, B -1; C-2; D-4","A-4, B -2; C-1; D-3","A-4, B -1; C-3; D-2","A-4, B -1; C-2; D-3"],"wt":"ఈ కోడ్‌లో ప్రతి పదాన్ని వెనుక నుంచి రాస్తారు: SARCASM → MSACRAS, CHEESE → ESEEHC. కాబట్టి WATER → RETAW (4), GENERAL → LARENEG (1), CERTAIN → NIATREC (2), LOVELY → YLEVOL (3), అంటే A-4, B-1, C-2, D-3."},{"id":"t2023a-123","p":"t2023a","n":123,"s":"rea","t":"Logical Reasoning","q":"In a certain code language, 'num vum dum' is written as 'cats are dogs ', 'hum dum rum' is written as 'dogs don't bite', and 'cats have paws' is written as 'vum cum pum'. What is the code for the word 'are' in that language?","w":"The sentence is worded loosely (codes 'written as' words), but the pairing is clear. 'dogs' is common to 'cats are dogs' and 'dogs don't bite', and 'dum' to their codes, so dogs = dum. 'cats' is common to 'cats are dogs' and 'cats have paws', and 'vum' to 'num vum dum' and 'vum cum pum', so cats = vum. The remaining word, 'are', is therefore num.","o":["hum","vum","num","dum"],"a":[2],"qt":"ఒక నిర్దిష్ట కోడ్ భాషలో, 'num vum dum' ని 'cats are dogs’ అని వ్రాస్తారు, 'hum dum rum' ని 'dogs don't bite' అని వ్రాస్తారు మరియు 'cats have paws' ని 'vum cum pum' అని వ్రాస్తారు. ఆ భాషలో 'are' అనే పదానికి కోడ్ ఏమిటి?","ot":["hum","vum","num","dum"],"wt":"ప్రశ్న వాక్యం కొంత తారుమారుగా ఉన్నా (కోడ్‌లను పదాలుగా 'వ్రాస్తారు' అని), జతలు స్పష్టంగా ఉన్నాయి. 'cats are dogs', 'dogs don't bite' రెండింటిలో 'dogs', వాటి కోడ్‌లలో 'dum' ఉమ్మడి కాబట్టి dogs = dum. 'cats are dogs', 'cats have paws' లలో 'cats', 'num vum dum', 'vum cum pum' లలో 'vum' ఉమ్మడి కాబట్టి cats = vum. మిగిలిన పదం 'are' కోడ్ num."},{"id":"t2023a-124","p":"t2023a","n":124,"s":"rea","t":"Logical Reasoning","q":"Subham walks 5 km towards the north, then turns left and walk 12 km, turns left again and walks 10 km, and finally turns left and walks for another 12 km. Find the distance from the starting point to the end point.","w":"Take the start as (0, 0). Walking 5 km north brings him to (0, 5). Turning left he faces west and walks 12 km to (−12, 5); turning left again he faces south and walks 10 km to (−12, −5); a final left turn faces him east, and 12 km brings him to (0, −5). He ends 5 km due south of the start.","o":["10 km","5 km","15 km","20 km"],"a":[1],"qt":"సుభం ఉత్తర దిశగా 5 km నడిచి, ఎడమవైపుకు తిరిగి 12 km నడిచి, మళ్ళీ ఎడమకు తిరిగి 10 km నడిచి, చివరకు ఎడమవైపు తిరిగి మరో 12 km నడిచాడు. ప్రారంభ బిందువు నుండి ముగింపు బిందువుకు మధ్య గల దూరాన్ని కనుగొనండి.","ot":["10 km","5 km","15 km","20 km"],"wt":"ప్రారంభ బిందువును (0, 0)గా తీసుకోండి. ఉత్తరానికి 5 km నడిస్తే (0, 5). ఎడమకు తిరిగితే పడమర వైపు 12 km నడిచి (−12, 5); మళ్ళీ ఎడమకు తిరిగి దక్షిణం వైపు 10 km నడిచి (−12, −5); చివరగా ఎడమకు తిరిగి తూర్పు వైపు 12 km నడిచి (0, −5) చేరాడు. అతను ప్రారంభ బిందువుకు సరిగ్గా దక్షిణాన 5 km దూరంలో ఉన్నాడు."},{"id":"t2023a-125","p":"t2023a","n":125,"s":"rea","t":"Logical Reasoning","q":"Select the option that is related to the fifth number-letter-cluster in the same way as the second number-letter-cluster is related to the first number-letter-cluster and the fourth number-letter-cluster is related to the third number-letter-cluster.\nS8 : H19 :: M14 : N13 :: V5 : ?","w":"In S8 : H19, 8 is S's position in the reversed alphabet (27 − 19), and H, the 8th letter, carries 19, S's own position. Likewise M (13) has 27 − 13 = 14, and N, the 14th letter, carries 13. For V (22), 27 − 22 = 5, so the answer is E, the 5th letter, carrying 22: E22.","o":["F22","E23","E22","D23"],"a":[2],"qt":"రెండవ సంఖ్యా అక్షర సమూహం మొదటి సంఖ్యా అక్షర సమూహముకు మరియు నాల్గవ సంఖ్యా అక్షర సమూహం మూడవ సంఖ్యా అక్షర సమూహముకు సంబంధించిన విధంగానే ఐదవ సంఖ్యా అక్షర సమూహసహముకు సంబంధించిన ఎంపికను ఎంచుకోండి.\nS8 : H19 :: M14 : N13 :: V5 : ?","ot":["F22","E23","E22","D23"],"wt":"S8 : H19లో 8 అనేది వ్యతిరేక అక్షర క్రమంలో S స్థానం (27 − 19); 8వ అక్షరం H, దానితో S యొక్క స్వంత స్థానం 19 వస్తుంది. అదే విధంగా M (13) కు 27 − 13 = 14, 14వ అక్షరం N, దానితో 13. V (22) కు 27 − 22 = 5, కాబట్టి 5వ అక్షరం E, దానితో 22: E22."},{"id":"t2023a-126","p":"t2023a","n":126,"s":"rea","t":"Logical Reasoning","q":"Consider the following pairs and choose the pair which matches the given relation.\nDisease : Body part\nA. Conjunctivitis : Ears\nB. Asthma : Lungs\nC. Polio : Skin\nD. Arthritis : Bones","w":"Asthma is a chronic disease of the airways of the lungs, and arthritis is inflammation of the joints, where bones meet, so pairs B and D are correct. Conjunctivitis ('pink eye') is inflammation of the conjunctiva of the eye, not the ears, and polio is a viral disease that attacks the nervous system (spinal cord) and can cause paralysis; it is not a skin disease.","o":["B and C","A and D","B and D","D only"],"a":[2],"qt":"క్రింది జతలను పరిగణించండి మరియు సరైన సంబంధాలను కలిగి ఉన్న జతలను ఎంచుకోండి.\nవ్యాధి : శరీర భాగం\nA. కండ్లకలక : చెవులు\nB. ఆస్తమా : ఊపిరితిత్తులు\nC. పోలియో : చర్మం\nD. ఆర్థరైటిస్ : ఎముకలు","ot":["B మరియు C","A మరియు D","B మరియు D","D మాత్రమే"],"wt":"ఆస్తమా ఊపిరితిత్తులలోని శ్వాస నాళాలకు వచ్చే దీర్ఘకాలిక వ్యాధి; ఆర్థరైటిస్ ఎముకలు కలిసే కీళ్ల వాపు; కాబట్టి B, D జతలు సరైనవి. కండ్లకలక (కంజంక్టివైటిస్, 'పింక్ ఐ') కంటిలోని కంజంక్టైవా పొర వాపు, ఇది చెవులకు సంబంధించినది కాదు; పోలియో నాడీ వ్యవస్థను (వెన్నుపామును) దెబ్బతీసి పక్షవాతం కలిగించగల వైరస్ వ్యాధి, ఇది చర్మ వ్యాధి కాదు."},{"id":"t2023a-127","p":"t2023a","n":127,"s":"rea","t":"Logical Reasoning","q":"A question is followed by two statements numbered I and II. You have to decide whether the data provided in the statements are sufficient to answer the question. Read both statements and answer.\nQuestion: What is Shyam's age?\nStatement I: Shyam, Ram and Sundar are of the same age.\nStatement II: Ram is 5 more than twice the age of Mohan, whose age is 32 years.","w":"Statement II gives Ram's age: twice Mohan's age plus 5 = 2 × 32 + 5 = 69 years, but it says nothing about Shyam. Statement I says Shyam is the same age as Ram but gives no number. Together, Shyam is 69 years old, so both statements together are sufficient, while neither is sufficient alone.","o":["I alone is sufficient while II alone is not sufficient","II alone is sufficient while I alone is not sufficient","Both I and II together are sufficient","Neither I nor II is sufficient"],"a":[2],"qt":"I మరియు II అను రెండు ప్రకటనల తరువాత ఒక ప్రశ్న ఇవ్వబడింది. ప్రశ్నకు సమాధానం ఇవ్వడానికి ఆ ప్రకటనలలో ఇవ్వబడిన సమాచారం సరిపోతుందో లేదో మీరు నిర్ణయించాలి. రెండు ప్రకటనలనూ చదివి సమాధానం ఇవ్వండి.\nప్రశ్న: శ్యామ్ యొక్క వయస్సు ఎంత?\nప్రకటన I: శ్యామ్, రామ్ మరియు సుందర్ ఒకే వయస్సు గలవారు.\nప్రకటన II: రామ్ యొక్క వయసు 32 సంవత్సరాల వయస్సు గల మోహన్ వయస్సుకు రెండింతల కంటే 5 ఎక్కువ.","ot":["I మాత్రమే సరిపోతుంది, అయితే II మాత్రమే సరిపోదు","II మాత్రమే సరిపోతుంది, అయితే I మాత్రమే సరిపోదు","I మరియు II రెండూ కలిసి సరిపోతాయి","I కానీ లేదా II కానీ ఏదీ సరిపోదు"],"wt":"ప్రకటన II నుండి రామ్ వయస్సు = మోహన్ వయస్సుకు రెండింతలు + 5 = 2 × 32 + 5 = 69 సంవత్సరాలు, కానీ ఇందులో శ్యామ్ గురించి ఏమీ లేదు. ప్రకటన I శ్యామ్ వయస్సు రామ్ వయస్సుకు సమానమని చెబుతుంది, కానీ సంఖ్య ఇవ్వదు. రెండింటినీ కలిపితే శ్యామ్ వయస్సు 69 సంవత్సరాలు; కాబట్టి I మరియు II రెండూ కలిసి సరిపోతాయి, విడివిడిగా ఏదీ సరిపోదు."},{"id":"t2023a-128","p":"t2023a","n":128,"s":"rea","t":"Logical Reasoning","q":"A question is followed by three statements numbered I, II and III. You have to decide whether the data provided in the statements are sufficient to answer the question. Read all the statements and answer.\nQuestion: Find the mean age of the family.\nStatement I: A family consists of a father, a mother and their two children.\nStatement II: The mother is 5 years younger than the father whose age is 50 years.\nStatement III: The elder child is half the age of the father and the younger child is one-third the age of the mother.","w":"Statement II gives the father's age (50) and the mother's (50 − 5 = 45); Statement III then gives the elder child's age (50 ÷ 2 = 25) and the younger child's (45 ÷ 3 = 15); Statement I is needed to know that the family has exactly these four members. Mean age = (50 + 45 + 25 + 15) ÷ 4 = 135 ÷ 4 = 33.75 years, so all three statements together are sufficient.","o":["Only I and III together are sufficient","Only III is sufficient","Only I and II together are sufficient","All three together are sufficient"],"a":[3],"qt":"I, II మరియు III అను మూడు ప్రకటనల తరువాత ఒక ప్రశ్న ఇవ్వబడింది. ప్రశ్నకు సమాధానం ఇవ్వడానికి ఆ ప్రకటనలలో ఇవ్వబడిన సమాచారం సరిపోతుందో లేదో మీరు నిర్ణయించాలి. అన్ని ప్రకటనలనూ చదివి సమాధానం ఇవ్వండి.\nప్రశ్న: కుటుంబం యొక్క సగటు వయస్సును కనుగొనండి.\nప్రకటన I: ఒక కుటుంబంలో తండ్రి, తల్లి మరియు వారి ఇద్దరు పిల్లలు ఉన్నారు.\nప్రకటన II: 50 సంవత్సరాల వయస్సు గల తండ్రి కంటే తల్లి 5 సంవత్సరాలు చిన్నది.\nప్రకటన III: పెద్ద బిడ్డ యొక్క వయస్సు తండ్రి వయస్సులో సగం మరియు చిన్న బిడ్డ యొక్క వయస్సు తల్లి వయస్సులో మూడింట ఒక వంతు.","ot":["I మరియు III మాత్రమే సరిపోతాయి","III మాత్రమే సరిపోతుంది","I మరియు II మాత్రమే సరిపోతాయి","మూడూ కలిసి సరిపోతాయి"],"wt":"ప్రకటన II తండ్రి వయస్సు (50), తల్లి వయస్సు (50 − 5 = 45) ఇస్తుంది; ప్రకటన III పెద్ద బిడ్డ వయస్సు (50 ÷ 2 = 25), చిన్న బిడ్డ వయస్సు (45 ÷ 3 = 15) ఇస్తుంది; కుటుంబంలో సరిగ్గా ఈ నలుగురే ఉన్నారని తెలుసుకోవడానికి ప్రకటన I అవసరం. సగటు వయస్సు = (50 + 45 + 25 + 15) ÷ 4 = 135 ÷ 4 = 33.75 సంవత్సరాలు. కాబట్టి మూడు ప్రకటనలూ కలిసి సరిపోతాయి."},{"id":"t2023a-129","p":"t2023a","n":129,"s":"rea","t":"Logical Reasoning","q":"Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusions logically follow(s) from the statements.\nStatement I: Most Medical students are brilliant.\nStatement II: Subham is brilliant.\nConclusion I: Subham is a Medical student.\nConclusion II: Some medical students are not brilliant.","w":"Being brilliant does not make a person a medical student, because brilliant people can belong to any group, so Conclusion I does not follow. The key takes 'most' in its everyday sense of 'a majority but not all', so 'Most medical students are brilliant' implies that some medical students are not brilliant, and only Conclusion II follows. Strict syllogism rules read 'most' as 'some', which does not exclude 'all', so on that reading neither conclusion follows (option 4). (Preliminary key; some sources differ.)","o":["Only conclusion I follows","Only conclusion II follows","Both conclusion I and II follow","Neither conclusion I nor II follows"],"a":[1],"qt":"ఇవ్వబడిన ప్రకటనలు మరియు ముగింపులను జాగ్రత్తగా చదవండి. ప్రకటనలలో ఇవ్వబడిన సమాచారం నిజమని భావిస్తూ సాధారణంగా తెలిసిన వాస్తవాలకు భిన్నంగా కనిపించినప్పటికీ, ఇవ్వబడిన తీర్మానాలలో ఏది ప్రకటనలను తార్కికంగా అనుసరిస్తాయో నిర్ణయించండి.\nప్రకటన I: చాలా మంది వైద్య విద్యార్థులు తెలివైనవారు.\nప్రకటన II: శుభం తెలివైనవాడు.\nతీర్మానం I: శుభం ఒక వైద్య విద్యార్థి.\nతీర్మానం II: కొంతమంది వైద్య విద్యార్థులు తెలివైనవారు కాదు.","ot":["తీర్మానం I మాత్రమే అనుసరిస్తుంది","తీర్మానం II మాత్రమే అనుసరిస్తుంది","తీర్మానం I మరియు II లు రెండూ అనుసరిస్తాయి","తీర్మానం I కానీ లేదా II కానీ ఏదీ అనుసరించదు"],"wt":"తెలివైనవారు ఏ వర్గానికైనా చెందినవారు కావచ్చు, కాబట్టి శుభం తెలివైనవాడు అయినంత మాత్రాన వైద్య విద్యార్థి అని చెప్పలేము; తీర్మానం I అనుసరించదు. కీ 'చాలా మంది' (most) అనే పదాన్ని సాధారణ అర్థంలో, అంటే 'అధికులు, కానీ అందరూ కాదు' అని తీసుకుంది; ఆ ప్రకారం 'చాలా మంది వైద్య విద్యార్థులు తెలివైనవారు' అంటే కొంతమంది వైద్య విద్యార్థులు తెలివైనవారు కాదు అని అర్థం, కాబట్టి తీర్మానం II మాత్రమే అనుసరిస్తుంది. కఠినమైన సిలాజిజం నియమాల ప్రకారం 'most' ను 'some' (కొంతమంది) గా చదువుతారు, అది 'అందరూ' అనే అవకాశాన్ని తోసిపుచ్చదు; ఆ దృష్టితో ఏ తీర్మానమూ అనుసరించదు (ఎంపిక 4). (ప్రాథమిక కీ; కొన్ని మూలాలు భిన్నంగా ఉన్నాయి.)"},{"id":"t2023a-130","p":"t2023a","n":130,"s":"rea","t":"Data Interpretation","q":"The bar graph shows the production of TV's and laptops in four consecutive years. Calculate the ratio of TV in 2019 to laptops in 2022.","w":"From the bar graph, TV production in 2019 was 230 lakh and laptop production in 2022 was 180 lakh. The ratio is 230 : 180; dividing both terms by 10 gives 23 : 18, which cannot be simplified further. Option (4), 18 : 23, is the reverse ratio (laptops in 2022 to TVs in 2019).","img":"data:image/png;base64,","o":["21 : 23","23 : 18","21 : 18","18 : 23"],"a":[1],"qt":"ఈ కమ్మీ రేఖా చిత్రము వరుసగా నాలుగు సంవత్సరాలలో టీవీలు మరియు ల్యాప్‌టాప్‌ల ఉత్పత్తిని సూచిస్తుంది. 2019లో టీవీ మరియు 2022లో ల్యాప్‌టాప్‌ల నిష్పత్తిని లెక్కించండి.\nNumbers in lakhs – లక్షల్లో సంఖ్యలు, TV (in lakhs) – టీవీ (లక్షల్లో), Laptop (in lakhs) – ల్యాప్‌టాప్ (లక్షల్లో)\nYear – సంవత్సరం","ot":["21 : 23","23 : 18","21 : 18","18 : 23"],"wt":"కమ్మీ రేఖా చిత్రం ప్రకారం 2019లో టీవీల ఉత్పత్తి 230 లక్షలు, 2022లో ల్యాప్‌టాప్‌ల ఉత్పత్తి 180 లక్షలు. నిష్పత్తి 230 : 180; రెండు పదాలనూ 10తో భాగిస్తే 23 : 18 వస్తుంది, దీనిని ఇంకా సూక్ష్మీకరించలేము. ఎంపిక (4) 18 : 23 విలోమ నిష్పత్తి (2022 ల్యాప్‌టాప్‌లు : 2019 టీవీలు)."},{"id":"t2023a-131","p":"t2023a","n":131,"s":"rea","t":"Data Interpretation","q":"The following pie chart shows the spending of a country on various sectors. If the total amount spent on agriculture was Rs. 850 crore, then find the amount spent on Health sector.","w":"Agriculture's share is 17% and equals Rs. 850 crore, so 1% of total spending = 850 ÷ 17 = Rs. 50 crore (total spending Rs. 5,000 crore). Health's share is 18%, so spending on health = 18 × 50 = Rs. 900 crore. The five sectors add up to 24 + 18 + 17 + 20 + 21 = 100%.","img":"data:image/png;base64,","o":["Rs. 90 crore","Rs. 900 crore","Rs. 1000 crore","Rs. 750 crore"],"a":[1],"qt":"క్రింది పై రేఖా చిత్రము వివిధ రంగాలలో దేశం యొక్క ఖర్చులను సూచిస్తుంది. వ్యవసాయానికి ఖర్చు చేసిన మొత్తం రూ. 850 కోట్లు అయితే ఆరోగ్య రంగానికి చేసిన ఖర్చు మొత్తాన్ని కనుగొనండి.\nExpenditure (in percentage) – ఖర్చు (శాతంలో), Industrial – పారిశ్రామిక, Health – ఆరోగ్యం\nAgriculture – వ్యవసాయం, Infrastructure – మౌలిక సదుపాయాలు","ot":["Rs. 90 కోట్లు","Rs. 900 కోట్లు","Rs. 1000 కోట్లు","Rs. 750 కోట్లు"],"wt":"వ్యవసాయం వాటా 17%, అది రూ. 850 కోట్లకు సమానం; కాబట్టి మొత్తం ఖర్చులో 1% = 850 ÷ 17 = రూ. 50 కోట్లు (మొత్తం ఖర్చు రూ. 5,000 కోట్లు). ఆరోగ్యం వాటా 18%, కాబట్టి ఆరోగ్య రంగంపై ఖర్చు = 18 × 50 = రూ. 900 కోట్లు. ఐదు రంగాల వాటాలు కలిపితే 24 + 18 + 17 + 20 + 21 = 100%."},{"id":"t2023a-132","p":"t2023a","n":132,"s":"eng","t":"Grammar","q":"Select the most appropriate option to fill in the blank.\nHe did not do ______ things that the other schoolmates did.","w":"The definite article is needed because 'things' is made specific by the defining clause 'that the other schoolmates did': 'He did not do the things that the other schoolmates did.' 'An' cannot be used with a plural noun, 'their' does not fit with a clause that already identifies the things, and leaving the blank empty would make 'things' general, which clashes with that specifying clause.","o":["the","an","their","No word required"],"a":[0]},{"id":"t2023a-133","p":"t2023a","n":133,"s":"eng","t":"Grammar","q":"Select the most appropriate option to fill in the blank.\nHe was wearing round glasses, and on his forehead was _____ deep frown.","w":"'Frown' is a singular countable noun mentioned for the first time, so it takes the indefinite article, and 'a' is used because the next word, 'deep', begins with a consonant sound: 'on his forehead was a deep frown.' 'An' is used only before a vowel sound, 'the' would point to a frown already known to the reader, and a singular countable noun cannot stand without an article.","o":["an","the","No word required","a"],"a":[3]},{"id":"t2023a-134","p":"t2023a","n":134,"s":"eng","t":"Vocabulary","q":"Select the most appropriate option to fill in the blank.\nThe script was the only hint of Mrinalini's very _______ past.","w":"The blank comes between the intensifier 'very' and the noun 'past', so an adjective is needed. 'Mysterious' (difficult to know or explain) fits the idea that the script was the only clue to her past: 'Mrinalini's very mysterious past.' 'Definitely' and 'cleanly' are adverbs and cannot qualify a noun, and 'frowning' describes a facial expression, which does not suit a past.","o":["definitely","frowning","mysterious","cleanly"],"a":[2]},{"id":"t2023a-135","p":"t2023a","n":135,"s":"eng","t":"Grammar","q":"Select the most appropriate option to fill in the blank.\nWhat a contrast ______ him and his friend.","w":"'Between' is used when two persons or things are compared or contrasted, and the noun 'contrast' is normally followed by 'between': 'What a contrast between him and his friend.' 'Amidst' means in the middle of a group or surroundings, 'across' means from one side to the other, and 'through' means passing from one end to the other; none of them fits a comparison of two people.","o":["through","between","amidst","across"],"a":[1]},{"id":"t2023a-136","p":"t2023a","n":136,"s":"eng","t":"Grammar","q":"Which of the given statements has a grammatical error?\nStatement A: As he stared out into the dark, a black shadow moved under the trees.\nStatement B: You had better let me invest it, because if you take it, you’ll spend it.","w":"Both sentences are correct. In A, two past actions happening at the same time are joined by 'as' (while), each in the simple past. In B, 'had better' is correctly followed by the bare infinitive ('let me invest it'), and the first conditional 'if you take it, you'll spend it' correctly uses the present tense in the if-clause and 'will' in the main clause. Hence neither statement has an error.","o":["Only A","Only B","Both A and B","Neither A nor B"],"a":[3]},{"id":"t2023a-137","p":"t2023a","n":137,"s":"eng","t":"Grammar","q":"Which of the given statements has/have a grammatical error?\nStatement A: I knew the risk of snow, though it seldom falls heavy so far south, save high up in the mountains.\nStatement B: He said it would tell my whole fortune if I wanted it to.","w":"Statement A has an error: the verb 'falls' must be modified by an adverb, so it should read 'though it seldom falls heavily so far south'. Statement B is correct: in reported speech 'will' becomes 'would', and 'if I wanted it to' is an acceptable short form of 'if I wanted it to tell my fortune'. So only A has a grammatical error.","o":["Only A","Only B","Both A and B","Neither A nor B"],"a":[0]},{"id":"t2023a-138","p":"t2023a","n":138,"s":"eng","t":"Grammar","q":"Parts of a paragraph are given below in jumbled order. Arrange the parts in the correct order to form a meaningful paragraph.\nA. her conversations with students and posing\nB: After a few minutes she got to her feet and began to pace\nC. questions here and there. Harry\nD. the room in Trelawney's wake, listening to\nE. bent his head hurriedly over his book.","w":"B opens the paragraph with a subject and verb ('she got to her feet and began to pace'). 'Pace' needs an object, which D supplies ('the room in Trelawney's wake, listening to'); 'listening to' needs A ('her conversations with students and posing'); 'posing' needs C ('questions here and there. Harry'); and the subject 'Harry' is completed by E ('bent his head hurriedly over his book'). The order is BDACE.","o":["ABDEC","CADEB","BDCEA","BDACE"],"a":[3]},{"id":"t2023a-139","p":"t2023a","n":139,"s":"eng","t":"Grammar","q":"Which of the given statements has/have a grammatical error?\nStatement A: We hadn’t rob nobody, hadn’t killed any people, but only just pretended.\nStatement B: They were not welcomed home very cordial by their mother.","w":"Both statements are wrong. In A, the past perfect needs the past participle and standard English does not allow a double negative, so 'hadn't rob nobody' should be 'hadn't robbed anybody'. In B, the participle 'welcomed' must be modified by an adverb, so 'very cordial' should be 'very cordially'. Hence both A and B have grammatical errors.","o":["Only A","Only B","Both A and B","Neither A nor B"],"a":[2]},{"id":"t2023a-140","p":"t2023a","n":140,"s":"eng","t":"Grammar","q":"Which of the given statements has/have a grammatical error?\nStatement A: We must not look at them, shouldn't we?\nStatement B: I am the lost princess, aren't I?","w":"A question tag repeats the auxiliary of the statement and reverses its polarity. 'We must not look at them' is negative with 'must', so the tag should be 'must we?', not 'shouldn't we?'; A has an error. For 'I am', the accepted tag is 'aren't I?', so 'I am the lost princess, aren't I?' is correct. Hence only A has an error.","o":["Only A","Only B","Both A and B","Neither A nor B"],"a":[0]},{"id":"t2023a-141","p":"t2023a","n":141,"s":"eng","t":"Grammar","q":"Select the most appropriate question tag to fill in the blank.\nHis real name is Tom, ________?","w":"The statement is positive and uses 'is' with the singular subject 'His real name' (replaced by 'it' in the tag), so the tag must be the negative 'isn't it?': 'His real name is Tom, isn't it?' 'Aren't' does not agree with 'it', and 'was it' and 'wasn't it' change the tense from present to past.","o":["aren’t it","isn’t it","was it","wasn't it"],"a":[1]},{"id":"t2023a-142","p":"t2023a","n":142,"s":"eng","t":"Grammar","q":"Select the option that expresses the given sentence in active voice.\nWorried looks were exchanged between Harry, Ron and Hermione as they were unconvinced.","w":"In the passive sentence the doers are Harry, Ron and Hermione, the verb 'were exchanged' is simple past and the object is 'worried looks'; 'as they were unconvinced' gives their state. In active voice: 'Unconvinced, Harry, Ron and Hermione exchanged worried looks.' Option 2 changes the tense to past continuous, option 1 makes the people 'worried' instead of the looks, and option 3 drops 'worried'.","o":["Worried Harry, Ron and Hermione exchanged looks as they were unconvinced.","Unconvinced, Harry, Ron and Hermione were exchanging worried looks.","Harry, Ron and Hermione exchanged unconvinced looks.","Unconvinced, Harry, Ron and Hermione exchanged worried looks."],"a":[3]},{"id":"t2023a-143","p":"t2023a","n":143,"s":"eng","t":"Vocabulary","q":"Which of the following idioms is correctly matched with its meaning?","w":"'Eat your heart out' traditionally means to suffer or brood over grief, longing or envy, so it matches 'to make yourself sick with grief' (today 'Eat your heart out!' is also said playfully to make someone envious). The others are wrongly matched: 'fit as a fiddle' means in very good health, 'get real' means be realistic, and 'jump the gun' means to act too soon, before the proper time.","o":["Fit as a fiddle: To go to bed","Get real: Slow down","Eat your heart out: To make yourself sick with grief","Jump the gun: To say something crazy"],"a":[2]},{"id":"t2023a-144","p":"t2023a","n":144,"s":"eng","t":"Vocabulary","q":"Select the most appropriate meaning of the given proverb.If you snooze, you lose.","w":"'If you snooze, you lose' means that if you are slow or not alert, you will miss an opportunity that someone else will take, so one must act fast to get what one wants. 'You cannot change what has happened' is the sense of 'what's done is done' or 'no use crying over spilt milk', and the other two options do not describe the proverb at all.","o":["You cannot change what has happened.","Act fast to get what you want.","To be exceptional","Something very easy to do"],"a":[1]},{"id":"t2023a-145","p":"t2023a","n":145,"s":"eng","t":"Vocabulary","q":"Match the following words with their respective ANTONYMS.\nWords | Their Antonyms\nA. Floppy | 1. Lenient\nB. Poignant | 2. Cheerful\nC. Adamant | 3. Cognisant\nD. Ignorant | 4. Stiff","w":"Floppy (soft and hanging loosely) is the opposite of stiff (A-4); poignant (causing deep sadness) is the opposite of cheerful (B-2); adamant (refusing to change one's mind) is the opposite of lenient (C-1); and ignorant (lacking knowledge or awareness) is the opposite of cognisant (aware, having knowledge) (D-3). So the answer is A-4, B-2, C-1, D-3.","o":["A-2, B-1, C-4, D-3","A-4, B-2, C-1, D-3","A-3, B-1, C-2, D-4","A-2, B-4, C-3, D-1"],"a":[1]},{"id":"t2023a-146","p":"t2023a","n":146,"s":"eng","t":"Vocabulary","q":"Consider the following pairs:\nA. Honour: Respect\nB. Stigma: Approval\nC. Exaltation: Scorn\nD. Misery: Calm\nIdentify the correct pair of synonyms.","w":"Honour and respect both mean high regard or esteem, so A is a pair of synonyms. The other pairs are opposites or unrelated: stigma (a mark of disgrace) is the opposite of approval, exaltation (high praise or glorification) is the opposite of scorn, and misery (great distress) is nearly the opposite of calm (peace). Hence only A is correct.","o":["A only","A and B only","C and D only","A, C and D only"],"a":[0]},{"id":"t2023a-147","p":"t2023a","n":147,"s":"eng","t":"Vocabulary","q":"Select the correctly spelt word.","w":"'Aggression' (hostile or violent behaviour) is correctly spelt, with a double 'g' and a double 's'. The correct spellings of the others are 'foreign' (-eign), 'deceive' (e before i after c) and 'calendar' (ending in -ar); a 'calender' is a different word, a machine with rollers for pressing cloth or paper.","o":["Foriegn","Aggression","Decieve","Calender"],"a":[1]},{"id":"t2023a-148","p":"t2023a","n":148,"s":"eng","t":"Vocabulary","q":"Select the INCORRECTLY spelt word.","w":"'Heirarchy' is incorrect; the correct spelling is 'hierarchy' (h-i-e-r), a system in which people or things are ranked one above another. The word comes from the Greek 'hieros' (sacred) and has nothing to do with 'heir', which is why the 'ie' order is kept. 'Guidance', 'category' and 'conscious' are spelt correctly.","o":["Guidance","Category","Conscious","Heirarchy"],"a":[3]},{"id":"t2023a-149","p":"t2023a","n":149,"s":"eng","t":"Vocabulary","q":"Select the most appropriate homophone to fill in the blank.\nHad the late Mr. Darcy liked me less, his son might have ______ with me better.","w":"'Bear with' means to be patient with or tolerate someone, and after 'might have' the past participle is needed; the past participle of 'bear' in this sense is 'borne': 'his son might have borne with me better.' 'Born' is used only for birth (to be born), 'bore' is the simple past tense, and 'boar' is a male pig.","o":["born","bore","boar","borne"],"a":[3]},{"id":"t2023a-150","p":"t2023a","n":150,"s":"eng","t":"Vocabulary","q":"Select the most appropriate homophone to fill in the blank.\nI cannot ________ to hear you mentioning this thing again and again.","w":"The verb 'bear' means to tolerate or endure, and 'cannot bear to' is a fixed expression: 'I cannot bear to hear you mentioning this thing again and again.' The other words do not fit: a 'bier' is a stand on which a coffin or corpse is placed, 'bare' means uncovered or naked, and 'beer' is an alcoholic drink.","o":["bier","bear","bare","beer"],"a":[1]},{"id":"t2023b-1","p":"t2023b","n":1,"s":"thm","t":"Thermodynamics","q":"Which of the following laws provides the basis for the temperature measurement?","w":"The zeroth law states that if two bodies are each in thermal equilibrium with a third body, they are in thermal equilibrium with each other. This lets a thermometer (the third body) compare temperatures, so it is the basis of temperature measurement. The first law deals with conservation of energy, the second with the direction of heat flow and entropy, and Boyle's law with the P–V relation of a gas at constant temperature.","o":["Zeroth law of thermodynamics","First law of thermodynamics","Second law of thermodynamics","Boyle’s law"],"a":[0]},{"id":"t2023b-2","p":"t2023b","n":2,"s":"thm","t":"Thermodynamics","q":"For an isothermal process, which of the following is correct based on first law of thermodynamics?","w":"By the first law, Q = ΔU + W. For an ideal gas the internal energy depends only on temperature, so in an isothermal process ΔU = 0 and Q = W: the heat added equals the work done by the system, and the work done on it is rejected as heat. Option 2 describes an adiabatic process (Q = 0), option 3 a constant-volume process (W = 0), and option 4 wrongly assumes ΔU ≠ 0.","o":["Heat added or rejected by the system equals to the work done by the system or work done on the system","Work done by the system or work done on the system equals to the change in internal energy","Heat added or rejected equals to the change in internal energy","Heat added or rejected is equals to the sum of change in internal energy (not equal to zero) and work done by a system or work done on a system"],"a":[0]},{"id":"t2023b-3","p":"t2023b","n":3,"s":"ice","t":"Engine Fundamentals & Cycles","q":"In context of I.C. engines, what is the ratio of shaft energy to the energy available at the piston is called?","w":"Mechanical efficiency ηm = brake power / indicated power, i.e. the useful output at the shaft divided by the power developed by the gases on the piston; the difference is lost in friction and pumping. Brake thermal efficiency compares brake power with the fuel energy supplied, indicated thermal efficiency compares indicated power with the fuel energy, and volumetric efficiency compares the charge actually inducted with the swept volume.","o":["Brake thermal efficiency","Indicated thermal efficiency","Mechanical efficiency","Volumetric efficiency"],"a":[2]},{"id":"t2023b-4","p":"t2023b","n":4,"s":"ice","t":"Engine Fundamentals & Cycles","q":"For the I.C. engine, the ratio of total volume of the cylinder to clearance volume is called ______.","w":"Compression ratio r = total cylinder volume / clearance volume = (Vs + Vc)/Vc, where Vs is the swept (stroke) volume and Vc the clearance volume left above the piston at TDC. Typical values are about 6–10 for petrol (SI) engines and 14–22 for diesel (CI) engines. The clearance ratio is Vc/Vs, and a higher compression ratio raises the air-standard efficiency.","o":["clearance ratio","efficiency","expansion ratio","compression ratio"],"a":[3]},{"id":"t2023b-5","p":"t2023b","n":5,"s":"ice","t":"Engine Fundamentals & Cycles","q":"Which of the following is an advantage of reciprocating internal combustion engines over external combustion engines?","w":"Because the fuel burns inside the cylinder, an IC engine needs no boiler, condenser or separate furnace, so it is compact, with a low weight-to-power ratio and higher overall efficiency, which suits vehicles. External combustion engines such as steam engines give high starting torque and can burn cheaper fuels like coal or wood, but they need more space; these are not advantages of IC engines.","o":["Starting torque is high","Weight to power ratio is generally low","Require more space","Cheaper fuel can be used"],"a":[1]},{"id":"t2023b-6","p":"t2023b","n":6,"s":"ice","t":"Engine Fundamentals & Cycles","q":"Which of the following is a function of Gudgeon pin in internal combustion engines?","w":"The gudgeon (piston or wrist) pin joins the piston to the small end of the connecting rod and acts as a pivot, supporting the rod and allowing it to swivel as the crank turns. The piston crown receives the gas pressure, the piston rings give the seal between piston and cylinder, and the flywheel takes care of speed fluctuations during a cycle.","o":["It acts as a face to receive gas pressure and transmits the thrust to connecting rod","Provide a good sealing fit between the piston and cylinder","It supports and allows the swivel of the connecting rod","It reduces friction and takes care of the fluctuations of speed during a cycle"],"a":[2]},{"id":"t2023b-7","p":"t2023b","n":7,"s":"ice","t":"Engine Fundamentals & Cycles","q":"During which of the following stroke, the flywheel stores energy so that it can supply the energy during the idle strokes?","w":"In a four-stroke engine only the expansion (power) stroke produces work. During this stroke the flywheel absorbs the surplus energy as kinetic energy, its speed rising slightly, and gives it back during the idle suction, compression and exhaust strokes, keeping the crankshaft speed nearly uniform. A multi-cylinder engine overlaps power strokes and so needs a lighter flywheel.","o":["Suction stroke","Expansion stroke","Compression stroke","Exhaust stroke"],"a":[1]},{"id":"t2023b-8","p":"t2023b","n":8,"s":"ice","t":"Engine Fundamentals & Cycles","q":"To allow the fresh charge to enter the cylinder, the inlet valve is opened in advance of the T.D.C position. The inlet valve is opened in advance by ______.","w":"In the actual valve timing of a four-stroke engine the inlet valve opens about 10°–30° of crank rotation before TDC, so that it is fully open when the suction stroke begins and the fresh charge can enter without restriction. It closes some degrees after BDC, using the inertia of the incoming charge to improve volumetric efficiency. The period when both valves are open near TDC is the valve overlap.","o":["10° to 30°","50° to 60°","30° to 70°","0° to 10°"],"a":[0]},{"id":"t2023b-9","p":"t2023b","n":9,"s":"ice","t":"Fuel Supply & Combustion","q":"Which one of the following factors affect the ignition timing of an internal combustion engine?","w":"The spark must occur early enough for the flame to burn the charge near TDC, and the time needed depends on the fuel: its octane rating (knock resistance) and burning rate decide how much spark advance can be used. Engine speed, load and mixture strength also affect the timing, which is why distributors have centrifugal and vacuum advance. The flywheel and the piston or cylinder materials do not decide ignition timing.","o":["Type of fuel","Flywheel","Piston material","Cylinder material"],"a":[0]},{"id":"t2023b-10","p":"t2023b","n":10,"s":"ice","t":"Engine Fundamentals & Cycles","q":"In a two-stroke engine, the process of clearing the cylinder after the expansion stroke is called ______.","w":"Scavenging is the sweeping out of the burnt gases from the cylinder of a two-stroke engine by the fresh charge or air entering through the transfer ports at the end of the expansion stroke. Common methods are cross-flow, loop (reverse-flow) and uniflow scavenging. Knocking is abnormal combustion, while expansion and compression are the normal working processes.","o":["expansion","scavenging","compressing","knocking"],"a":[1]},{"id":"t2023b-11","p":"t2023b","n":11,"s":"ice","t":"Engine Fundamentals & Cycles","q":"What is the difference between indicated power and brake power of internal combustion engine?","w":"Indicated power is the power developed by the gases on the piston, and brake power is the useful power available at the crankshaft. Their difference, friction power = IP − BP, is the power lost in friction of pistons, rings and bearings, in pumping the charge and in driving accessories. The ratio BP/IP is the mechanical efficiency; friction power can be measured by the Morse or motoring test.","o":["Total power","Total available energy","Total engine friction loss","Total clearance"],"a":[2]},{"id":"t2023b-12","p":"t2023b","n":12,"s":"ice","t":"Fuels, Lubricants & Emissions","q":"The lowest temperature at which lubricating oil changes from a liquid state to plastic or solid state is called ______.","w":"As an oil is cooled it reaches its cloud point when wax and other dissolved solids begin to separate and make it hazy, the start of its change from a liquid towards a plastic or solid state; the key takes this as the answer. On further cooling it reaches the pour point, the lowest temperature at which it will still flow, and the word \"lowest\" in the question fits the pour point better. The flash point concerns ignition of the oil's vapour. (Preliminary key; some sources differ.)","o":["cloud point","emulsification point","flash point","pour point"],"a":[0]},{"id":"t2023b-13","p":"t2023b","n":13,"s":"ice","t":"Cooling & Lubrication","q":"Which of the following is correct about cooling system of engines?\nI. The cooling system is provided on an engine because high temperatures reduce strength of piston and cylinder liner.\nII. The cooling system is provided on an engine because the overheated cylinder may lead to ignition lag in spark ignition engines.","w":"Statement I is correct: at high temperatures the piston, cylinder liner and valves lose strength and the oil film breaks down, so the cooling system removes roughly a third of the fuel's heat. Statement II is wrong: an overheated cylinder causes pre-ignition and detonation (knocking) in spark ignition engines, not ignition lag, which is the short delay between the spark and a noticeable pressure rise.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":[0]},{"id":"t2023b-14","p":"t2023b","n":14,"s":"ice","t":"Fuel Supply & Combustion","q":"Which of the following is correct regarding the diesel engines?\nI. Diesel engines uses an injector.\nII. There is no pre-ignition in diesel engines.","w":"Both statements are correct. A diesel (CI) engine uses a fuel injection pump and an injector that sprays fuel into the hot compressed air, instead of a carburettor and spark plug. Since only air is compressed and fuel is admitted only at the end of the compression stroke, there is no charge in the cylinder that could ignite early, so pre-ignition does not occur.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":[2]},{"id":"t2023b-15","p":"t2023b","n":15,"s":"ice","t":"Fuels, Lubricants & Emissions","q":"Which of the following is correct about grease?\nI. Grease is only used where there is a low bearing and shock loads.\nII. Lubricating grease is a solid to semi solid dispersion of a thickening agent in liquid lubricant.","w":"Statement II is the standard definition: a lubricating grease is a solid to semi-solid dispersion of a thickening agent, usually a metallic soap, in a liquid lubricant. Statement I is wrong: grease is used where bearing pressures are high, where shock loads occur, at low speeds and where oil cannot be retained or would leak away, as in wheel bearings and chassis joints.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":[1]},{"id":"t2023b-16","p":"t2023b","n":16,"s":"ice","t":"Fuels, Lubricants & Emissions","q":"Which of the following is correct about lubricating oils?\nI. Fatty oils exhibit less oiliness than mineral oils of the same viscosity.\nII. Multigrade oil are not required to change as per ambient temperature.\nIII. Multigrade oil has short warming up period.","w":"Statement I is wrong: fatty (animal and vegetable) oils show greater oiliness, that is, stronger adherence to metal surfaces, than mineral oils of the same viscosity. Statements II and III are correct: a multigrade oil such as SAE 20W-40 meets both a low-temperature and a high-temperature grade, so it need not be changed with the season, and it flows freely when cold, giving a short warming-up period.","o":["Only I and II","Only II","Only II and III","Only I and III"],"a":[2]},{"id":"t2023b-17","p":"t2023b","n":17,"s":"ice","t":"Fuel Supply & Combustion","q":"Which of the following is correct about the fuel injection system?\nI. It controls the rate of fuel injection.\nII. It filters the fuel.\nIII. It controls the quantity of fuel to be injected.","w":"A diesel fuel injection system must filter the fuel, meter the correct quantity of fuel for each cycle according to the load, time the injection, control the rate of injection, atomise the fuel finely and distribute it properly in the combustion chamber. The fuel filters form part of the system, so all three statements describe its functions.","o":["Only I and II","Only II and III","All I, II and III","Only I and III"],"a":[2]},{"id":"t2023b-18","p":"t2023b","n":18,"s":"ice","t":"Fuel Supply & Combustion","q":"Which of the following statement is correct regarding the effects of the air fuel mixtures in SI engine?\nI. If the air fuel mixture is slightly richer, mean effective pressure reaches its maximum value.\nII. The rate of fuel consumption is lowest for rich air fuel mixtures.\nIII. By decreasing the richness of air fuel mixture, the proportion of CO₂ will decrease while those of CO with certain traces of unburnt H₂ will increase.","w":"Only I is correct: maximum power, and so maximum mean effective pressure, is obtained with a slightly rich mixture of about 12.5:1. II is wrong because the lowest specific fuel consumption is obtained with a slightly lean mixture. III is reversed: as the mixture is made less rich, more oxygen is available, so the proportion of CO₂ increases while CO and unburnt H₂ decrease.","o":["Only I","Only II and III","Only I and III","Only II"],"a":[0]},{"id":"t2023b-19","p":"t2023b","n":19,"s":"ice","t":"Fuel Supply & Combustion","q":"Match the following statements in context of Spark Ignition engine.\nEffect | Cause\nI. Results in lowering of efficiency | 1. Running on the weakest air fuel mixture\nII. Results in high efficiency | 2. Running on the richest air fuel mixture\nIII. Results in complete burning of the fuel | 3. During the cruising the air fuel mixture is approximately 16.5: 1 so that","w":"With the richest mixture part of the fuel cannot find oxygen and leaves as CO and unburnt hydrocarbons, so efficiency falls: I-2. The weakest mixture that still burns gives the best economy and the highest efficiency: II-1. In the cruising range the carburettor supplies a slightly lean mixture of about 16.5:1 so that the excess air ensures complete burning of the fuel: III-3. Hence I-2, II-1, III-3.","o":["I-1, II-2, III-3","I-2, II-1, III-3","I-3, II-2, III-1","I-2, II-3, III-1"],"a":[1]},{"id":"t2023b-20","p":"t2023b","n":20,"s":"ice","t":"Fuels, Lubricants & Emissions","q":"Match the following fuel standard to its specialty.\nStandard | Specialty\nI. Iso-octane | 1. Very prone to knock\nII. Normal heptane | 2. Measure of ignition quality of diesel\nIII. Cetane number | 3. Very high resistance to knock\n| 4. Anti knock performance under severe operating conditions","w":"Octane numbers are fixed with two reference fuels: iso-octane (2,2,4-trimethylpentane), which has very high resistance to knock and is rated 100, and normal heptane, which is very prone to knock and is rated 0. The cetane number measures the ignition quality of diesel fuel, using cetane (100) and alpha-methylnaphthalene (0) as references. Hence I-3, II-1, III-2.","o":["I-4, II-2, III-3","I-3, II-1, III-2","I-1, II-3, III-4","I-2, II-4, III-1"],"a":[1]},{"id":"t2023b-21","p":"t2023b","n":21,"s":"thm","t":"Thermodynamics","q":"Which of the following is correctly matched pair regarding Clausius Inequality?","w":"The Clausius inequality states that for any cycle ∮δQ/T ≤ 0 (the cyclic integral sign is not printed in the options). The equality holds for a reversible cycle, ∮δQ/T < 0 for an irreversible cycle, and ∮δQ/T > 0 is impossible. For an isolated system the entropy change is ΔS ≥ 0 (principle of increase of entropy), so ΔS < 0 cannot occur. Only \"δQ/T < 0 : Irreversible cycle\" is correctly matched.","o":["δQ/T > 0 : Reversible cycle","δQ/T = 0 : Irreversible cycle","δQ/T < 0 : Irreversible cycle","ΔS < 0 : Isolated system"],"a":[2]},{"id":"t2023b-22","p":"t2023b","n":22,"s":"ice","t":"Engine Fundamentals & Cycles","q":"For same compression ratio and same heat input, which of the following order of efficiency is correct?","w":"For the same compression ratio and heat input, the Otto cycle adds all its heat at constant volume at TDC, so it rejects the least heat and is the most efficient; the Diesel cycle adds heat at constant pressure during part of the expansion and is the least efficient; the dual cycle, with part of each, lies in between. So η_Otto > η_Dual > η_Diesel (\"duel\" is printed for dual). For the same maximum pressure and temperature the order is reversed.","o":["η_duel > η_otto > η_diesel","η_diesel > η_duel > η_otto","η_duel > η_diesel > η_otto","η_otto > η_duel > η_diesel"],"a":[3]},{"id":"t2023b-23","p":"t2023b","n":23,"s":"thm","t":"Thermodynamics","q":"Arrange the following in an increasing order of value of n in PVⁿ = C.\nI. Constant pressure process\nII. Reversible adiabatic process\nIII. Constant volume process\nIV. Isothermal process","w":"In the polytropic relation PVⁿ = C, n = 0 for a constant pressure process (P = C), n = 1 for an isothermal process of an ideal gas (PV = C), n = γ (about 1.4 for air) for a reversible adiabatic process, and n = ∞ for a constant volume process. The increasing order is therefore constant pressure, isothermal, reversible adiabatic, constant volume: I, IV, II, III.","o":["I, II, III, IV","II, I, III, IV","II, III, I, IV","I, IV, II, III"],"a":[3]},{"id":"t2023b-24","p":"t2023b","n":24,"s":"ice","t":"Engine Fundamentals & Cycles","q":"For the four stroke otto engines, arrange the following in the correct order (first to last).\nI. The piston moves T.D.C. to B.D.C. and work is obtained after fuel is ignited.\nII. The piston moves B.D.C. to T.D.C. and compresses the air fuel mixture.\nIII. The piston moves T.D.C. to B.D.C. and the inlet valve opens and air fuel mixture is sucked in.\nIV. The piston moves B.D.C. to T.D.C. and gases are made to escape through exhaust value.","w":"A four-stroke Otto (petrol) engine completes its cycle in two crankshaft revolutions: suction, with the piston moving from TDC to BDC and the charge drawn in (III); compression from BDC to TDC (II); power or expansion after the spark ignites the charge, TDC to BDC (I); and exhaust, BDC to TDC, pushing the burnt gases out through the exhaust valve (IV; \"value\" is printed for valve). Order: III, II, I, IV.","o":["I, III, IV, II","III, II, I, IV","IV, II, I, III","III, I, IV, II"],"a":[1]},{"id":"t2023b-25","p":"t2023b","n":25,"s":"ice","t":"Fuel Supply & Combustion","q":"For a simple or elementary carburettor, arrange the following in a correct order (first to last).\nI. The velocity of air increases as it passes through the constriction at the venturi.\nII. Pressure decreases due to conversion of a portion of pressure head into kinetic energy.\nIII. The piston moves down and the suction is produced in the cylinder and the induction manifold.\nIV. Due to pressure difference the jet issues fuel oil into air stream which vapourise forming air fuel mixture.\nV. The air flows through the carburettor.","w":"In a simple carburettor the piston's suction stroke creates a depression in the cylinder and induction manifold (III), so air flows through the carburettor (V). Its velocity rises at the venturi throat (I), where the pressure falls as part of the pressure head becomes kinetic energy (II). The pressure difference between the float chamber and the throat makes the jet discharge fuel, which vaporises in the air stream to form the mixture (IV). Order: III, V, I, II, IV.","o":["III, V, I, II, IV","II, V, III, I, IV","III, II, I, IV, V","II, IV, III, V, I"],"a":[0]},{"id":"t2023b-26","p":"t2023b","n":26,"s":"chs","t":"Chassis & Body","q":"Which one of the following is an advantage of chassis with engine at front and drive is given to the wheels from rear of a vehicle?","w":"In the conventional layout, with the engine at the front driving the rear wheels, the radiator faces the oncoming air, so cooling is more efficient; weight is also well distributed and the front wheels only steer. Elimination of the propeller shaft and a combined clutch, gearbox and differential unit are advantages of front-wheel-drive or rear-engine layouts, and inadequate luggage space is a drawback, not an advantage.","o":["Increased efficiency of cooling system","Inadequate space behind the rear seat for the luggage","Elimination of propeller shaft","The clutch, gear box and differential are usually made as one unit results in cost reduction"],"a":[0]},{"id":"t2023b-27","p":"t2023b","n":27,"s":"chs","t":"Chassis & Body","q":"Which one of the following is a defect that may be found in chassis body of an automobile?","w":"The chassis frame and body are inspected for cracks, bent or twisted members, loose rivets and broken welds, which develop from fatigue, overloading, accidents and road shocks. A built-up edge forms on a cutting tool during machining, the heat-affected zone is the metallurgically altered region beside any weld, and toe-out is a wheel-alignment setting of the front wheels, not a chassis defect.","o":["Build up edges","Broken welds","Heat affected zone","Toe out"],"a":[1]},{"id":"t2023b-28","p":"t2023b","n":28,"s":"chs","t":"Chassis & Body","q":"For an automotive body, the magnitude of the drag force depends on ______.","w":"The aerodynamic drag on a vehicle is F = ½ ρ C_d A V², where ρ is the air density, C_d the drag coefficient set by the body shape, A the frontal area and V the speed relative to the air. Drag therefore grows with the square of the velocity, and the power needed to overcome it with the cube. It does not depend on the strength of the body or on gravity.","o":["shear strength of automotive body","magnitude of gravity","velocity of automotive body","strength of automotive body"],"a":[2]},{"id":"t2023b-29","p":"t2023b","n":29,"s":"chs","t":"Chassis & Body","q":"Which one of the following load acts on a chassis when a vehicle crosses a broken patch of road?","w":"Automobile engineering textbooks classify the loads on a chassis frame as static loads (weight of body, passengers and cargo), short-duration loads (while crossing a broken patch of road), momentary loads (while taking a curve), impact loads (from collisions), inertia loads (on sudden acceleration or braking) and overloads (beyond the design capacity). Crossing a broken patch is thus a short-duration load.","o":["Inertia load","Short duration load","Overload","Impact load"],"a":[1]},{"id":"t2023b-30","p":"t2023b","n":30,"s":"chs","t":"Steering & Suspension","q":"In which of the following the carriage unit of a car rolls about a transverse axis?","w":"The sprung body (carriage unit) of a car can rotate about three axes. Rolling is rotation about the longitudinal axis, as on cornering; pitching is rotation about the transverse axis, the nose diving under braking or rising under acceleration and over bumps; and yawing is rotation about the vertical axis. So rotation about a transverse axis is pitching; bending is a frame deformation, not a body motion.","o":["Rolling","Yawing","Pitching","Bending"],"a":[2]},{"id":"t2023b-31","p":"t2023b","n":31,"s":"chs","t":"Steering & Suspension","q":"Which one of the following is a function of the shackle in the context of a leaf spring?","w":"A semi-elliptic leaf spring straightens and becomes longer as it deflects under load. Its front eye is pinned to a fixed bracket on the frame, while the rear eye is connected through a swinging shackle that allows this change in length. The spring is held on the axle by U-bolts and a centre bolt, progressive stiffness comes from graduated or helper leaves, and the leaves are lubricated with grease or graphite.","o":["It helps in accommodating the change in the length of the spring.","It is used to keep leaf spring in position on the axle.","It is used to provide progressive stiffness against increasing load.","It provides lubrication between the leaf spring."],"a":[0]},{"id":"t2023b-32","p":"t2023b","n":32,"s":"chs","t":"Clutch & Gearbox","q":"Which one of the following is a formula of the effective mean radius of a clutch for uniform pressure condition? (Where r₁ is inner radius and r₂ is outer radius).","w":"With uniform pressure p on the annular friction face, the axial load is W = πp(r₂² − r₁²) and the friction torque is T = (2/3)πμp(r₂³ − r₁³), so T = μWR with mean radius R = (2/3)(r₂³ − r₁³)/(r₂² − r₁²). With the uniform-wear assumption, used for worn clutches, the mean radius is (r₁ + r₂)/2 (option 3), giving a slightly smaller and safer torque estimate. Option 4 gives a negative value.","o":["(1/3)[(r₂³ − r₁³)/(r₂² − r₁²)]","(2/3)[(r₂³ − r₁³)/(r₂² − r₁²)]","(r₂ + r₁)/2","(2/3)[(r₁³ − r₂³)/(r₂² − r₁²)]"],"a":[1]},{"id":"t2023b-33","p":"t2023b","n":33,"s":"chs","t":"Clutch & Gearbox","q":"In gear box, the device that is used to lock collar into the gear is called ______.","w":"In constant-mesh and synchromesh gearboxes the gears turn freely on the main shaft, and a toothed sliding collar splined to the shaft, moved by the selector fork, engages dog teeth on the side of the chosen gear to lock it to the shaft. This arrangement is the dog clutch. Diaphragm and electromagnetic clutches are main clutches between engine and gearbox, and reverse gear is only a gear ratio.","o":["reverse gear","dog clutch","electromagnetic clutch","diaphragm clutch"],"a":[1]},{"id":"t2023b-34","p":"t2023b","n":34,"s":"chs","t":"Drive Line, Axles & Differential","q":"The terms used for a combination of transmission and rear axles as a unit of a vehicle is ______.","w":"A transaxle combines the gearbox (transmission) with the final drive and differential of the driving axle in a single housing. It is used in rear-engine rear-wheel-drive and front-engine front-wheel-drive vehicles and does away with a long propeller shaft. A live axle is one that transmits drive to the wheels, and a tandem axle is a pair of closely spaced axles used on heavy vehicles.","o":["live axle","tandem axle","split axle","trans axle"],"a":[3]},{"id":"t2023b-35","p":"t2023b","n":35,"s":"chs","t":"Wheels & Tyres","q":"If vehicle is taking a turn, what is the ratio of side force sustained to slip angle called?","w":"When a vehicle turns, the tyre deforms and runs at a slip angle to the plane of the wheel, developing a side or cornering force. The ratio of this side force to the slip angle, in newtons per degree, is the cornering power (cornering stiffness) of the tyre; it depends on inflation pressure, load, tyre construction and rim width. Camber force arises from the tilt of the wheel.","o":["Camber force","Cornering power","Frictional power","Camber angle"],"a":[1]},{"id":"t2023b-36","p":"t2023b","n":36,"s":"chs","t":"Drive Line, Axles & Differential","q":"Which of the following statement is correct about front axles of a vehicle?\nI. The front wheels are mounted on stub axles which are connected to the front axle by king pin.\nII. When brakes are provided at the front wheels the front axle withstand bending stresses only.","w":"Statement I is correct: the front wheels run on stub axles pivoted to the ends of the axle beam by king pins, so that they can be steered. Statement II is wrong: with brakes on the front wheels, the axle beam must resist bending due to the vehicle's weight and also torsion due to the braking torque. For this reason the beam has an I-section in the middle and a round or elliptical section near the ends.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":[0]},{"id":"t2023b-37","p":"t2023b","n":37,"s":"chs","t":"Steering & Suspension","q":"Which of the following is correct regarding steering mechanism of a vehicle?\nI. In order to avoid skidding, the two front wheels instantaneous centre should not coincide with the two rear wheels instantaneous centre.\nII. The fundamental equation for correct steering is cot φ − cot θ = c/b.\nWhere, c = distance between the pivots of front axle.\nb = wheel base\nθ = inner wheel turning angle\nφ = outer wheel turning angle","w":"For true rolling without skidding, the axes of all four wheels must meet at one instantaneous centre lying on the line of the rear axle, so the front wheels' centre must coincide with that of the rear wheels; statement I is wrong. Statement II is the condition for correct steering, cot φ − cot θ = c/b, with φ the outer and θ the inner wheel angle; the Ackermann linkage satisfies it closely, and the Davis gear exactly.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":[1]},{"id":"t2023b-38","p":"t2023b","n":38,"s":"chs","t":"Drive Line, Axles & Differential","q":"Which of the following statement is correct regarding transmission system of automobiles?\nI. The main advantage of an overdrive is prolonged engine life since the engine turns slower.\nII. A slip joint is attached to the driven yoke in order to increase or decrease the propeller shaft.","w":"Both statements are correct. An overdrive makes the propeller shaft turn faster than the engine, so at cruising speed the engine runs slower, reducing wear and fuel consumption and prolonging engine life. A slip (sliding) joint, with splines between the shaft and a universal-joint yoke, lets the effective length of the propeller shaft increase or decrease as the rear axle moves up and down (statement II omits the word \"length\").","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":[2]},{"id":"t2023b-39","p":"t2023b","n":39,"s":"chs","t":"Drive Line, Axles & Differential","q":"Which of the following statement is correct regarding rear axles of a vehicle?\nI. The Banjo axle arrangement is a central housing that contains the final drive and it is fitted with a tube on each side to carry the half axles and bearings.\nII. The main advantage of three-quarter floating rear axle over the half floating axle is that the major part of the load is taken by the axle and not by the axle casing.\nIII. A full floating rear axle is not supported by bearing at either end, is very strong and used for heavy duty vehicles.","w":"Only III is correct. Statement I describes the Salisbury (carrier) type; a banjo casing is a one-piece housing with a large central opening, shaped like a banjo, into which a separate final-drive carrier is bolted. Statement II is reversed: in a three-quarter floating axle the hub bearing sits on the axle casing, so most of the load is taken by the casing, not the shaft. In a full-floating axle the hub runs on two bearings on the casing, so the shaft itself needs no bearing and only transmits torque; it suits heavy vehicles.","o":["Only II","I and II","Only III","II and III"],"a":[2]},{"id":"t2023b-40","p":"t2023b","n":40,"s":"chs","t":"Drive Line, Axles & Differential","q":"Which of the following is correct regarding causes of axle failure of a vehicle?\nI. Lubricant is not maintained at the required level.\nII. The vehicle is over loaded.\nIII. Using of lubricant of correct grade.","w":"Axle failures commonly result from a low lubricant level, which leads to wear, overheating and seizure of bearings and gears, and from overloading the vehicle, which overstresses the shafts and casing. Wrong lubricant grade, poor adjustment and shock loads from snatching the clutch are other causes. Using a lubricant of the correct grade prevents failure, so III is not a cause.","o":["Only I","II and III","I and II","Only III"],"a":[2]},{"id":"t2023b-41","p":"t2023b","n":41,"s":"chs","t":"Clutch & Gearbox","q":"Match the following symptoms with their causes for troubleshooting of gear box.\nSymptoms | Causes\nI. Oil leaks | 1. Excessive wear on gear shift control\nII. Gear jumps out | 2. Defective synchronizer\nIII. Gears clash while they are shifted | 3. Broken gaskets\n| 4. Heavy heat contact on the ring gear","w":"Oil leaks from a gearbox are mainly due to broken gaskets or worn oil seals (I-3). A gear that jumps out of mesh usually points to excessive wear in the gear-shift control, such as worn selector forks, weak detent springs or worn bearings (II-1). Gears that clash while shifting indicate a defective synchronizer or a dragging clutch (III-2). Hence I-3, II-1, III-2; contact marking on the ring gear concerns the final drive.","o":["I-1, II-2, III-3","I-3, II-1, III-2","I-2, II-1, III-4","I-4, II-3, III-1"],"a":[1]},{"id":"t2023b-42","p":"t2023b","n":42,"s":"chs","t":"Drive Line, Axles & Differential","q":"Which of the following is a correctly matched pair universal joint of a vehicle with their classification?","w":"Universal joints are classed as variable-velocity joints, whose output speed fluctuates when they work at an angle, such as the cross or spider (Hooke's) type, the ring type and the ball-and-trunnion type; and constant-velocity joints such as the Tracta, Rzeppa and Bendix-Weiss types, which transmit uniform speed and are used in front-wheel drives. So ball and trunnion with variable velocity is correctly matched (\"Trunion\" is printed for trunnion).","o":["Tracta type : Variable velocity joints","Rzeppa type : Variable velocity joint","Ball and Trunion type : Variable velocity joints","Ring type : Constant velocity joint"],"a":[2]},{"id":"t2023b-43","p":"t2023b","n":43,"s":"chs","t":"Wheels & Tyres","q":"Which of the following is correctly matched pair regarding the tyres?","w":"The bead is the stiff edge of the tyre, reinforced with steel wires, that is shaped to fit the rim and hold the tyre on it. A ply is a layer of rubber-coated parallel cords, the carcass is the body of the tyre built from these plies, and ribs and grooves make up the tread pattern. An annular toroidal inflatable envelope of elastic material describes the tyre itself (\"aunclar torridal\" is printed for annular toroidal).","o":["Ply : The cross grooved tyre tread","Carcass : An aunclar torridal shaped inflatable envelope made of an elastic material","Ribs : The layer of rubber coated parallel cords","Bead : Part which is shaped to fit the rim and hold the tyre on it"],"a":[3]},{"id":"t2023b-44","p":"t2023b","n":44,"s":"chs","t":"Clutch & Gearbox","q":"Arrange the following position in decreasing order of power transmission based on the position of gear shift lever of a vehicle.\nI. Low position\nII. Reverse position\nIII. Neutral position","w":"In the low (first) position the gearbox gives a large reduction, so the greatest torque reaches the wheels for starting and climbing. The reverse position also gives a large reduction, but the drive passes through an extra idler gear, adding one more gear mesh and its friction loss, and is used only for slow manoeuvring. In neutral no gear on the main shaft is engaged, so no power is transmitted. The key's decreasing order is therefore low, reverse, neutral.","o":["I, II, III","II, I, III","III, I, II","III, II, I"],"a":[0]},{"id":"t2023b-45","p":"t2023b","n":45,"s":"chs","t":"Brakes","q":"Arrange the following in a correct order (first to last) for air brakes of a vehicle.\nI. The air pressure act on a diaphragm of brake chamber.\nII. Brake shoes expands outwards and hold the moving brake drums.\nIII. The foot pedal is pressed down.\nIV. The diaphragm is pushed outward in the brake chamber causing movement of brake shoe operating cam.","w":"In an air brake system, pressing the foot pedal (III) opens the brake valve, admitting compressed air from the reservoir to the brake chambers, where it acts on the diaphragm (I). The diaphragm is pushed outward and, through the push rod and slack adjuster, turns the brake-shoe operating cam (IV), which expands the shoes against the rotating drums (II). Order: III, I, IV, II.","o":["III, IV, I, II","III, I, IV, II","III, IV, II, I","III, II, IV, I"],"a":[1]},{"id":"t2023b-46","p":"t2023b","n":46,"s":"chs","t":"Clutch & Gearbox","q":"Arrange the following statements in correct order (first to last) regarding fluid coupling.\nI. The prime mover starts rotating.\nII. The oil is thrown outwards by centrifugal action by pump impeller.\nIII. The oil then enters the impeller pump again.\nIV. The pump impeller starts rotating.\nV. The oil enters the turbine runner and exerts force on runner blades.\nVI. The torque increases results in rotation of turbine runner after overcoming inertia effects.","w":"In a fluid coupling the prime mover (engine) starts rotating (I) and turns the pump impeller fixed to the driving shaft (IV). The impeller throws the oil outwards by centrifugal action (II) into the turbine runner, where it strikes the runner blades (V). As the torque builds up it overcomes inertia and the runner rotates (VI), and the oil returns to the impeller to circulate again (III). Order: I, IV, II, V, VI, III.","o":["I, V, II, IV, III, VI","I, II, III, V, IV, VI","I, IV, II, V, VI, III","II, III, I, VI, IV, V"],"a":[2]},{"id":"t2023b-47","p":"t2023b","n":47,"s":"mva","t":"Vehicle Maintenance & Testing","q":"Which of the following is correct for improving fuel economy of vehicle?","w":"Driving at a steady, moderate speed, as traffic permits, avoids repeated acceleration and braking, which waste fuel. Under-inflated tyres raise rolling resistance and consume more fuel, a low engine oil level increases friction and wear, and replacing brake fluid is a safety task that does not affect fuel consumption. Correct tyre pressures, timely servicing and avoiding needless idling also improve economy.","o":["Under inflated tyre consume less fuel","Check and maintain low engine oil level","Replace the brake fluid to avoid extra fuel consumption","Keep a constant speed as road traffic situation permit"],"a":[3]},{"id":"t2023b-48","p":"t2023b","n":48,"s":"ice","t":"Engine Fundamentals & Cycles","q":"Which of the following is a standard operating condition for an automotive engine as per Indian Standard Institute?","w":"The \"Indian Standard Institute\" is the Indian Standards Institution, now the Bureau of Indian Standards. As keyed, its reference conditions for testing automotive engines include a mean barometric pressure of 736 mm Hg, corresponding to about 300 m above mean sea level; this agrees with the standard atmosphere, which gives about 733 mm Hg at 300 m. Option 2 is impossible, since the saturation vapour pressure of water at 25°C is only about 24 mm Hg, and the key accepts neither 25°C nor 45°C as the reference intake temperature.","o":["Intake air temperature is 25°C","Water vapour pressure of 150 mm of Hg of mercury, corresponding to a relative humidity of 40 percent at 25°C","Mean barometric pressure of 736 mm Hg corresponding to an altitude of 300 metres above mean sea level","Intake temperature is 45°C"],"a":[2]},{"id":"t2023b-49","p":"t2023b","n":49,"s":"mva","t":"Vehicle Maintenance & Testing","q":"Which of the following information is conveyed by the lubrication chart of the vehicle?","w":"A lubrication chart, supplied by the vehicle manufacturer, shows each point on the vehicle that needs lubrication, the type or grade of lubricant for that point (engine oil, gear oil or grease) and the interval in kilometres or months. Battery electrolyte level and spark-plug deposits are checked in routine maintenance, and \"type of engine oil\" covers only one of the many points on the chart.","o":["The type of lubricant needed for a particular point","The battery acid level","Carbon deposition on sparkplug","Type of engine oil needed"],"a":[0]},{"id":"t2023b-50","p":"t2023b","n":50,"s":"ael","t":"Batteries & Charging","q":"Which of the following is a part of charging system of the automotive electrical system?","w":"The charging system consists of the battery, the alternator (the dynamo in older vehicles) with its rectifier and voltage regulator, and the charge warning lamp. The belt-driven alternator recharges the battery and supplies the electrical load while the engine runs. Horns, lighting and the ignition system are consumers of electrical energy, not parts of the charging system.","o":["Horns","Alternator","Electronic ignition systems","Lighting"],"a":[1]},{"id":"t2023b-51","p":"t2023b","n":51,"s":"ael","t":"Batteries & Charging","q":"Which of the following test is conducted to ascertain the conditions of a battery of an automobile?","w":"The state of charge of a lead-acid battery is checked by measuring the specific gravity of its electrolyte with a hydrometer: about 1.26–1.28 when fully charged, falling to about 1.12 when discharged. The Morse test finds the indicated power of each cylinder of a multi-cylinder engine, the motoring test finds friction power, and a static brake test checks brakes, so none of them tells the battery's condition.","o":["Hydrometer testing","Morse testing","Motoring test","Static brake testing"],"a":[0]},{"id":"t2023b-52","p":"t2023b","n":52,"s":"ael","t":"Starting & Ignition","q":"Which of the following is a merit of transistorized coil ignition systems over conventional ignition system of a vehicle?","w":"In a transistorised coil ignition system a power transistor switches the coil primary current, triggered by breaker points carrying only a tiny control current or by a breakerless pulse generator. The higher, steadier secondary voltage at all speeds reduces misfiring and plug fouling, so spark plugs last longer; the system costs more, not less. Because the version that keeps breaker points also lengthens their life, option 4 is also argued. (Preliminary key; some sources differ.)","o":["Better working of contact breaker at high speeds","Less costly","Increased service life of spark plug","Improves life of contact breaker"],"a":[2]},{"id":"t2023b-53","p":"t2023b","n":53,"s":"ael","t":"Lighting, Instruments & Wiring","q":"According to Lucas, what is the colour of wiring cables for dynamo circuit of a car?","w":"The Lucas (British) cable colour code identifies each circuit by the colour of its insulation, and yellow is used for the dynamo (charging) circuit. In the same code brown is the main battery feed, red is for side and tail lamps, green for fused accessories switched through the ignition, and black for earth connections.","o":["Red","Black","Green","Yellow"],"a":[3]},{"id":"t2023b-54","p":"t2023b","n":54,"s":"ael","t":"Lighting, Instruments & Wiring","q":"The lights which indicate the direction the vehicle is about to turn are ______.","w":"Trafficators, or direction indicators, show the direction in which the vehicle is about to turn; early ones were illuminated semaphore arms, and modern vehicles use flashing amber lamps worked by a flasher unit. Side lights mark the width of a parked or moving vehicle, tail lights are red lamps at the rear, and the reverse light is a white lamp lit when reverse gear is engaged.","o":["side lights","trafficators","tail light","reverse light"],"a":[1]},{"id":"t2023b-55","p":"t2023b","n":55,"s":"thm","t":"Refrigeration & Air Conditioning","q":"Which of the following is correct regarding hot water liquid heater in an automobile?","w":"A hot-water heater passes hot engine coolant through a small radiator (heater core) behind the dashboard, and a blower fan drives air through it into the passenger compartment, so the coolant's heat becomes hot air. Options 1 and 4 describe a combustion heater, which burns fuel in its own chamber, and option 2 describes an exhaust-manifold (exhaust) heater.","o":["It consists of a combustion chamber and re-ignitor.","Outside air made to flow through the passage between the covering and exhaust manifold and air then circulated inside the car.","The heat from the coolant circulating inside the engine is converted into hot air.","A mixture of air and fuel is drawn from carburetor and burns inside the combustion chamber."],"a":[2]},{"id":"t2023b-56","p":"t2023b","n":56,"s":"mva","t":"Vehicle Maintenance & Testing","q":"Which of the following is correct regarding the preventive maintenance of a car?","w":"Preventive maintenance is scheduled inspection, adjustment, lubrication and replacement of wearing parts such as filters, plugs and belts before they fail. A well-tuned engine with clean filters and correct tyre pressures gives better fuel mileage, the keyed option, though \"dramatically\" overstates the gain. It cannot raise power above the rated level, it does involve planned replacement of parts, and it prevents rather than causes a drop in performance.","o":["The horsepower improves more than the rated level","Fuel mileage is increased dramatically","There is no replacement of parts","It leads to sharp drop in performance of vehicle"],"a":[1]},{"id":"t2023b-57","p":"t2023b","n":57,"s":"mva","t":"Vehicle Maintenance & Testing","q":"Which of the following is a correct about preventive maintenance of piston and piston rings of a car?\nI. Piston rings are to be checked for tension and scratches.\nII The carbon is removed and piston is cleaned using caustic cleaning solution and wire brush.","w":"During servicing, piston rings are checked for tension, wear, scratches and end gap, so statement I is correct. Pistons are usually of aluminium alloy, which is attacked by caustic (alkaline) cleaning solutions and scored by a wire brush; carbon is therefore removed with a suitable solvent and a soft scraper, and ring grooves with a groove cleaner. Statement II is wrong, so only I is correct.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":[0]},{"id":"t2023b-58","p":"t2023b","n":58,"s":"ael","t":"Starting & Ignition","q":"Which of the following is correct about vacuum spark advance mechanism of an engine?\nI. It contains a spring loaded diaphragm which is connected with the distributor by means of a link and damp.\nII. When distributor body is rotated opposite to the rotation of the rotor ignition is advanced.","w":"The vacuum advance unit has a spring-loaded diaphragm whose chamber is piped to the inlet manifold near the throttle; a link connects the diaphragm to the contact-breaker plate of the distributor. At part throttle the high vacuum pulls the diaphragm and turns the plate against the direction of cam (rotor) rotation, so the points open earlier and ignition is advanced, which is also why turning the distributor body against rotor rotation advances timing. Both statements are correct.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":[2]},{"id":"t2023b-59","p":"t2023b","n":59,"s":"ael","t":"Starting & Ignition","q":"Which of the following statements is correct regarding starting motor of an automobile?\nI. Bendix drive is known as overrunning clutch drive.\nII. The pole shoes hold the field coils and become magnetized when current flows through the coil.\nIII. The purpose of the solenoid switch is to shift the drive pinion magnetically into mesh with the flywheel to complete the circuit.\nIV. If the starter works but does not crank the engine then the solenoid switch may be defective.","w":"The Bendix drive is an inertia drive in which the pinion runs along a screwed sleeve into mesh; the overrunning (roller) clutch drive is a different type, so I is wrong. Pole shoes carry the field coils and become electromagnets (II), and the solenoid shifts the pinion into mesh with the flywheel ring gear and closes the main circuit (III). A motor that spins without cranking points to a slipping drive or overrunning clutch, not the solenoid, so IV is wrong.","o":["I, II","I, II and III","II, IV","II, III"],"a":[3]},{"id":"t2023b-60","p":"t2023b","n":60,"s":"ael","t":"Batteries & Charging","q":"Match the following.\nFunction | Components\nI. Convert mechanical energy from engine into electrical energy | 1. Regulator\nII. Control the amount of electrical energy produced | 2. Relay\nIII. Converts electrical energy into mechanical energy | 3. Dynamo\n| 4. Starting motor","w":"The dynamo (generator), driven by the engine, converts mechanical energy into electrical energy (I-3). The regulator controls the dynamo's output voltage and current, and so the amount of electrical energy produced (II-1). The starting motor converts electrical energy from the battery into mechanical energy to crank the engine (III-4). A relay is only an electrically operated switch, so it is the extra item.","o":["I-3, II-1, III-4","I-1, II-4, III-3","I-2, II-1, III-4","I-1, II-2, III-3"],"a":[0]},{"id":"t2023b-61","p":"t2023b","n":61,"s":"ael","t":"Starting & Ignition","q":"Which of the following is a correctly matched pair regarding troubles in spark plug and ignition system with their cause?\nI. Engine misfires on one cylinder : Detached high tension cable\nII. External insulator broken : Defective ignition coil\nIII. Engine gets unduly hot : Loose contact screws","w":"A detached or broken high-tension lead stops the spark reaching one plug, so that cylinder misfires: pair I is correct. A broken external insulator is mechanical damage from careless handling or a wrong or slipping spanner during fitting, not a coil defect. Undue engine heating is traced to causes such as wrong ignition timing, a plug of the wrong heat range or a cooling fault, not loose contact screws. Only pair I is correctly matched.","o":["Only III","Only I and II","Only I","Only I and III"],"a":[2]},{"id":"t2023b-62","p":"t2023b","n":62,"s":"ael","t":"Lighting, Instruments & Wiring","q":"Arrange the following in decreasing order of total value of resistance.\nI. V = 200 V, I = 10 Amp\nII. R₁ = 5.5 Ω, R₂ = 10 Ω and R₃ = 6.5 Ω arranged in series circuit\nIII. R₁ = 5 Ω, R₂ = 12 Ω and R₃ = 6 Ω arranged in parallel circuit","w":"By Ohm's law, I gives R = V/I = 200/10 = 20 Ω. In series, resistances add: II gives 5.5 + 10 + 6.5 = 22 Ω. In parallel, reciprocals add: for III, 1/R = 1/5 + 1/12 + 1/6 = 0.45, so R ≈ 2.22 Ω, smaller than the smallest single resistor. The decreasing order is II (22 Ω), I (20 Ω), III (2.22 Ω).","o":["I, II, III","I, III, II","II, III, I","II, I, III"],"a":[3]},{"id":"t2023b-63","p":"t2023b","n":63,"s":"mva","t":"Vehicle Maintenance & Testing","q":"Arrange the following in a correct order (first to last) for washing the car.\nI. Wash all body panels.\nII. Lift the car on a car lift.\nIII. Dry the car using a clean chamois.\nIV. Complete the washing with a sponge using running water.\nV. Wash the bottom of the car wheels included.\nVI. Rub a polishing compound of good commercial grade with a cloth.","w":"The car is first raised on a lift so that the underbody and wheels, the dirtiest parts, can be washed before the panels; mud splashed from below would otherwise spoil cleaned panels. The body panels are then washed, the washing is finished with a sponge under running water, the car is dried with a clean chamois, and the polishing compound is applied last on the dry, clean surface: II, V, I, IV, III, VI.","o":["II, V, VI, III, I, IV","I, IV, III, VI, V, II","III, II, V, IV, I, VI","II, V, I, IV, III, VI"],"a":[3]},{"id":"t2023b-64","p":"t2023b","n":64,"s":"mec","t":"Engineering Mechanics","q":"What is the value of TAB and TAC in the given diagram? (where sin165° = 0.26)","w":"Three concurrent forces in equilibrium obey Lami's theorem. The angles between the forces are 150° (TAB and TAC), 45° (TAC and the 3500 N weight) and 165° (weight and TAB). So TAB = 3500 × sin 45°/sin 150° = 3500 × 0.7071/0.5 ≈ 4950 N and TAC = 3500 × sin 165°/sin 150° ≈ 1812 N, about 1810 N (1820 N with the rounded 0.26). Option 3 prints TAB twice, a misprint.","img":"data:image/png;base64,","o":["TAB = 4950 N, TAC = 3005 N","TAC = 1810 N, TAB = 4950 N","TAB = 1810 N, TAB = 3500 N","TAB = 3500 N, TAC = 1810 N"],"a":[1]},{"id":"t2023b-65","p":"t2023b","n":65,"s":"mfg","t":"Metrology & Measurement","q":"The prefix used to show multiplying factor of 10⁻¹² is ______.","w":"The SI prefix pico (symbol p) stands for 10⁻¹², as in picofarad (pF). Tera (T) is 10¹² and nano (n) is 10⁻⁹. The fermi is not a prefix at all but an old name for the femtometre, a unit of length equal to 10⁻¹⁵ m; the prefix for 10⁻¹⁵ is femto (f).","o":["tera","nano","pico","fermi"],"a":[2]},{"id":"t2023b-66","p":"t2023b","n":66,"s":"mec","t":"Engineering Mechanics","q":"What is the total load acting on the beam AB?","w":"The beam carries a uniformly varying (triangular) load rising from zero at A to 120 N/m at B over 12 m. The total load equals the area of the load diagram: ½ × 12 m × 120 N/m = 720 N, acting through the centroid of the triangle, 8 m from A. 1440 N is the value for a uniform 120 N/m load over the full span.","img":"data:image/png;base64,","o":["14400 N","7200 N","720 N","1440 N"],"a":[2]},{"id":"t2023b-67","p":"t2023b","n":67,"s":"mec","t":"Engineering Mechanics","q":"The ratio of the limiting force of friction (F) to the normal reaction (R) between two bodies is called ______.","w":"The coefficient of friction is μ = F/R, the ratio of the limiting friction force to the normal reaction between the surfaces. The angle of repose is the angle of an inclined plane at which a body resting on it just begins to slide; it equals the angle of friction, with tan φ = μ. \"Coefficient of repose\" is not a standard term.","o":["Coefficient of repose","Angle of repose","Frictional power","Coefficient of friction"],"a":[3]},{"id":"t2023b-68","p":"t2023b","n":68,"s":"mec","t":"Strength of Materials","q":"The change in length (elongation) of bar due to self-weight is given by ______. (P = Load, ρ = density, E = Young’s Modulus, d₁ and d₂ are diameters)","w":"For a bar of length l hanging under its own weight, the weight below a section at distance x from the free end is ρgAx, so the stress there is ρgx. Integrating the strain ρgx/E over the length gives δ = ρgl²/(2E), which equals WL/(2AE) with W the total weight. The expression 4PL/(πd₁d₂E) is the elongation of a tapering circular bar under an axial load P.","o":["ρgl/(3E)","ρgl²/(2E)","4PL/(πd₁d₂E)","ρgL/(2πd₁d₂G)"],"a":[1]},{"id":"t2023b-69","p":"t2023b","n":69,"s":"mec","t":"Strength of Materials","q":"Which of the following is a correct relation between the material properties? (where (1/m) is poission ratio, K is bulk modulus, E is Young’s modulus)","w":"Young's modulus and bulk modulus are related by E = 3K(1 − 2μ), where μ is Poisson's ratio. Putting μ = 1/m gives E = 3K(m − 2)/m, so K = mE/(3(m − 2)). Option 2, E/(2(1/m + 1)) = mE/(2(m + 1)), is the modulus of rigidity C, not the bulk modulus.","o":["K = mE/(3(m − 2))","K = E/(2(1/m + 1))","K = 2mE/(m + 2)","K = mE/(2m + 1)"],"a":[0]},{"id":"t2023b-70","p":"t2023b","n":70,"s":"mec","t":"Strength of Materials","q":"Which of the following is a possible shear force diagram for an inclined beam under uniformly distributed load and a point load as shown in a diagram?","w":"A uniformly distributed load makes the shear force change linearly along the loaded length, and a point load makes it jump suddenly at the point where it acts. The beam is loaded by the UDL throughout and by P near its lower end, so the shear force diagram is a sloping straight line with a vertical step at P, as in Figure 3. Figure 2 has only steps (point loads alone), Figure 1 has a constant part, and Figure 4 is curved.","img":"data:image/png;base64,","o":["Figure 1","Figure 2","Figure 3","Figure 4"],"a":[2]},{"id":"t2023b-71","p":"t2023b","n":71,"s":"mec","t":"Strength of Materials","q":"The maximum deflection for a simply supported beam with a uniformly distributed load is given by ______. (Where w is weight per unit length)","w":"For a simply supported beam of span l carrying a uniformly distributed load w per unit length, the maximum deflection occurs at mid-span and is 5wl⁴/(384EI), where EI is the flexural rigidity (printed \"El\" in the options). The similar form Wl³/(48EI) is the central deflection under a single central point load W, so the other options mix up the two cases.","o":["wl³/(584El)","5wl⁴/(384El)","wl³/(16El)","wl⁴/(48El)"],"a":[1]},{"id":"t2023b-72","p":"t2023b","n":72,"s":"mec","t":"Strength of Materials","q":"Which of the following is a bending moment diagram for a cantilever beam with a uniformly distributed load?","w":"For a cantilever carrying a uniformly distributed load w, the bending moment at distance x from the free end is wx²/2. The diagram is therefore a parabola (second-degree curve), zero at the free end and rising to wL²/2 at the fixed end, as in Figure 4. A triangle (Figure 1) is the diagram for a point load at the free end, and a rectangle (Figure 2) for a pure couple.","img":"data:image/png;base64,","o":["Figure 1","Figure 2","Figure 3","Figure 4"],"a":[3]},{"id":"t2023b-73","p":"t2023b","n":73,"s":"mec","t":"Strength of Materials","q":"The ratio of lateral strain to linear strain of a body is called ______.","w":"Within the elastic limit, the ratio of lateral strain to linear (longitudinal) strain is constant for a material and is called Poisson's ratio, about 0.25–0.33 for most metals. Young's modulus is the ratio of stress to linear strain, resilience is the strain energy stored in a body, and deflection is the displacement of a beam under load.","o":["Resilience","Deflection","Poisson's ratio","Young’s modulus"],"a":[2]},{"id":"t2023b-74","p":"t2023b","n":74,"s":"mec","t":"Strength of Materials","q":"Which of the following is correct about strain in a body?\nI. Shear strain is defined as the ratio between change in volume and original volume of the body.\nII. The ratio between the compressing stress and compressive strain is called modulus of elasticity.","w":"The ratio of change in volume to original volume is volumetric strain, not shear strain; shear strain is the angular distortion (in radians) produced by shear stress. Within the elastic limit, the ratio of compressive stress to compressive strain is the modulus of elasticity (Young's modulus), just as for tension. So only statement II is correct.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":[1]},{"id":"t2023b-75","p":"t2023b","n":75,"s":"mec","t":"Strength of Materials","q":"Which of the following is correct regarding load?\nI. For a bar with different section subjected to axial load P, the resultant deformation will be summation of change of length of every section.\nII. For the above diagram the value of P₁ is 52 N.","w":"For a bar made of sections of different areas, the total change in length is the sum of the changes of the individual sections, δ = Σ PᵢLᵢ/(AᵢEᵢ), so I is correct. In the diagram, 40 N acts to the left at A, while 12 N and P₁ act to the right. For equilibrium P₁ + 12 = 40, giving P₁ = 28 N, not 52 N, so II is wrong.","img":"data:image/png;base64,","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":[0]},{"id":"t2023b-76","p":"t2023b","n":76,"s":"mec","t":"Strength of Materials","q":"A 1 m long rod is fixed at both ends. What is the temperature through which rod can be heated to NOT exceed the thermal stress of 90 MPa? The value of α is 2 × 10⁻⁵ K⁻¹ and E is 90 GPa.","w":"When a rod fixed at both ends is heated, its free expansion is fully prevented and the thermal stress is σ = EαΔT, independent of the length. So ΔT = σ/(Eα) = 90 × 10⁶/(90 × 10⁹ × 2 × 10⁻⁵) = 50 K. Heating it by more than 50 K would raise the stress above 90 MPa.","o":["90 K","180 K","50 K","100 K"],"a":[2]},{"id":"t2023b-77","p":"t2023b","n":77,"s":"mec","t":"Strength of Materials","q":"Which of the following is correct regarding thermal stress?\nI. If the supports yield by an amount Δ, the change in length will be summation of l α T and Δ.\nII. The stress of the supports yield by an amount Δ is (αt − Δ/l) E.\n(where l = length of the original body, α = coefficient of thermal expansion)","w":"Free thermal expansion is lαT. If the supports yield by Δ, part of this expansion is allowed, so the expansion prevented is the difference lαT − Δ, not the sum; statement I is wrong. The thermal stress is then (lαT − Δ)E/l = (αT − Δ/l)E, which is statement II (printed with a small t for the temperature rise T).","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":[1]},{"id":"t2023b-78","p":"t2023b","n":78,"s":"mec","t":"Strength of Materials","q":"Which of the following is correct regarding elasticity of a body?\nI. In elasticity, the body regains its shape after force is removed.\nII. The resistance force remains even after load is removed.\nIII. The body can regain its original shape after load removed upto elastic limit.","w":"Elasticity is the property by which a body returns to its original shape and size when the deforming force is removed, and this holds only up to the elastic limit; beyond it some permanent set remains. So I and III are correct. The internal resisting force exists only while the load acts and vanishes when the load is removed, so II is wrong.","o":["Only I","II and III only","I and III only","I and II only"],"a":[2]},{"id":"t2023b-79","p":"t2023b","n":79,"s":"mec","t":"Strength of Materials","q":"Which of the following is correct regarding shearing force, bending moment and loading condition on the beam?\nI. A point load at a section on the beam will cause sudden change in shear force.\nII. A point load at a section on the beam will results in sudden change in bending moment.\nIII. When there is no load between two point, then shear force does not change.","w":"Since dF/dx = −w, a point load makes the shear force jump suddenly by the value of the load (I correct), and over a length with no load the shear force stays constant (III correct). Because dM/dx = F, a point load only changes the slope of the bending moment diagram; a sudden change in bending moment is caused by a concentrated couple, so II is wrong.","o":["Only I","II and III only","I and III only","II only"],"a":[2]},{"id":"t2023b-80","p":"t2023b","n":80,"s":"mec","t":"Strength of Materials","q":"Match the following bending moment diagram with the conditions.","w":"For a cantilever, a point load at the free end gives a bending moment varying linearly from zero to WL, a triangle (I-1). A moment alone gives a constant bending moment, a rectangle (II-4). A uniformly distributed load over the whole length gives a parabola (III-2). A load over only part of the length gives a curve over the loaded part joined to a straight line over the unloaded part (IV-3).","img":"data:image/png;base64,","o":["I-1, II-2, III-3, IV-4","I-2, II-1, III-3, IV-4","I-2, II-3, III-4, IV-1","I-1, II-4, III-2, IV-3"],"a":[3]},{"id":"t2023b-81","p":"t2023b","n":81,"s":"mec","t":"Strength of Materials","q":"Which of the following is a correctly matched pair regarding section modulus of different section?","w":"The section modulus is Z = I/y(max). For a solid circle, I = πd⁴/64 and y(max) = d/2, so Z = πd³/32. For a hollow circle, I = π(D⁴ − d⁴)/64 and y(max) = D/2, so Z = π(D⁴ − d⁴)/(32D); option 1 uses π/32 instead of π/64 and doubles this. For a semicircle, Z is only about 0.024d³, far below 3πd³/64.","o":["Hollow circular section : Z = (π/32)(D⁴ − d⁴)/(D/2)","Solid circular section : Z = (π/32)d³","Solid semi-circular section : Z = (3π/64)d³","Hollow circular section : Z = (π/14)(D⁴ − d⁴)"],"a":[1]},{"id":"t2023b-82","p":"t2023b","n":82,"s":"mec","t":"Strength of Materials","q":"Arrange the following in the increasing order of maximum bending moment for the given loading condition.","w":"I: the 10 kN load acts on a bracket at 2 m from A, so R(A) = 10 × 3/5 = 6 kN; just left of the bracket joint at 3 m, M = 6 × 3 = 18 kN·m. II: a cantilever with 10 kN at the free end has M(max) = 10 × 3 = 30 kN·m at the support. III: the 24 kN·m couple at mid-span gives reactions of 24/4 = 6 kN and M(max) = 6 × 2 = 12 kN·m. So III < I < II.","img":"data:image/png;base64,","o":["I, II, III","II, III, I","III, II, I","III, I, II"],"a":[3]},{"id":"t2023b-83","p":"t2023b","n":83,"s":"mec","t":"Engineering Mechanics","q":"Arrange the following in a decreasing order of the moment of inertia of the given geometric shapes.\nI. Circle\nII. Quarter circle\nIII. Semi-circle","w":"For the same radius r, a full circle has I = πr⁴/4 about a diameter. A semicircle is half of it, πr⁴/8 about its diameter, and a quarter circle is a quarter, πr⁴/16 about either straight edge, because each is a part of the full circle about the same axis. About their own centroidal axes the order is the same (about 0.785r⁴, 0.110r⁴ and 0.055r⁴). So the decreasing order is circle, semicircle, quarter circle: I, III, II.","o":["I, II, III","II, III, I","I, III, II","II, I, III"],"a":[2]},{"id":"t2023b-84","p":"t2023b","n":84,"s":"mec","t":"Engineering Mechanics","q":"Arrange the following steps of analysis of machines in a correct order (first to last).\nI. Dismember the machine and draw a free body diagram of each member.\nII. Draw a free body diagram of the whole machine.\nIII. Equilibrium equations can be written and solved.\nIV. Consider multiforce member and show all the forces acting on the member.\nV. Finally check your solution.","w":"A machine (or frame) is analysed by first drawing the free-body diagram of the whole machine to relate the external forces and reactions. It is then dismembered and a free-body diagram of each member is drawn; the multiforce members are considered with all the forces acting on them, equal and opposite forces being shown at the connections. The equilibrium equations are then written and solved, and the solution is finally checked: II, I, IV, III, V.","o":["I, III, IV, II, V","II, I, III, IV, V","II, I, IV, III, V","IV, I, II, III, V"],"a":[2]},{"id":"t2023b-85","p":"t2023b","n":85,"s":"mfg","t":"Metrology & Measurement","q":"For the limit system, what is the difference between the basic dimensions of the mating parts is called?","w":"In the system of limits and fits, allowance is the intentional difference between the basic dimensions of the mating parts, that is, the minimum clearance or the maximum interference between a hole and a shaft. Tolerance is the difference between the upper and lower limits of one dimension, and the fundamental deviation is the deviation closest to the zero line that fixes the position of the tolerance zone.","o":["Allowance","Fundamental deviation","Tolerance","Mean deviation"],"a":[0]},{"id":"t2023b-86","p":"t2023b","n":86,"s":"mec","t":"Machine Design","q":"The ratio of maximum stress to the working stress of a material is called ______.","w":"The factor of safety is the ratio of the maximum stress a material can bear (ultimate stress for brittle materials, yield stress for ductile ones) to the working or permissible stress used in design. It allows for uncertain loads, material defects and errors of analysis. Strain is deformation per unit length, and Poisson's ratio and Young's modulus are elastic constants.","o":["Strain","Poisson’s ratio","Factor of safety","Young modulus"],"a":[2]},{"id":"t2023b-87","p":"t2023b","n":87,"s":"mec","t":"Machine Design","q":"The stresses which vary from one value of tensile to same value of compressive or vice versa of the beam are known as ______.","w":"A completely reversed (alternating) stress swings between equal tensile and compressive values, so its mean stress is zero; a rotating shaft under bending is the usual example. A repeated stress varies from zero to a maximum of the same kind, and a fluctuating stress varies between two unequal values. Bending stress names the cause of the stress, not how it varies with time.","o":["repeated stress","bending stress","fluctuating stress","completely reversed stress"],"a":[3]},{"id":"t2023b-88","p":"t2023b","n":88,"s":"mfg","t":"Manufacturing & Workshop","q":"What does the weld symbol ‘—’ represents according to IS : 813 – 1961?","w":"IS 813 (Scheme of symbols for welding; the 1961 edition has since been replaced by its first revision, IS 813:1986) uses supplementary contour symbols placed with the weld symbol. A straight line means a flush (flat) contour, the weld face finished level with the plate surface; a convex arc means convex contour and a concave arc concave contour. Field (site) welds and finishing methods such as chipping are shown by other marks or letters, and flash welding is a resistance welding process.","o":["Field weld","Chipping finish","Flush contour","Flash welding"],"a":[2]},{"id":"t2023b-89","p":"t2023b","n":89,"s":"mec","t":"Machine Design","q":"The surface joining the crest and root of the screw threads is called ______.","w":"The flank of a screw thread is the surface joining the crest (the top of the thread) to the root (the bottom of the groove). Pitch is the axial distance between corresponding points on adjacent threads, and lead is the axial distance the nut advances in one turn, equal to the pitch multiplied by the number of starts.","o":["pitch","slope","lead","flank"],"a":[3]},{"id":"t2023b-90","p":"t2023b","n":90,"s":"mec","t":"Engineering Mechanics","q":"The ratio of load lifted to the effort applied for a lever is called ______.","w":"Mechanical advantage is the ratio of the load lifted (W) to the effort applied (P); for an ideal lever it equals the effort arm divided by the load arm. Mechanical efficiency is the ratio of mechanical advantage to velocity ratio, a moment is a force multiplied by its perpendicular distance from a point, and notch sensitivity is a term from fatigue design.","o":["Notch sensitivity","Moment","Mechanical advantage","Mechanical efficiency"],"a":[2]},{"id":"t2023b-91","p":"t2023b","n":91,"s":"mec","t":"Machine Design","q":"The perpendicular distance between the centre lines of the successive rows in riveted joints is called ______.","w":"In a riveted joint, the back pitch (row pitch) is the perpendicular distance between the centre lines of successive rows of rivets. The pitch is the distance between centres of adjacent rivets in the same row, the diagonal pitch is between centres of rivets in adjacent rows of a zig-zag joint, and the margin or marginal pitch is the distance from a rivet hole centre to the plate edge.","o":["pitch","marginal pitch","back pitch","diagonal pitch"],"a":[2]},{"id":"t2023b-92","p":"t2023b","n":92,"s":"mec","t":"Machine Design","q":"Which one of the following is related to the crushing of the rivets? (where, α = coefficient of thermal expansion, ΔT = change in temperature, σc = crushing stress, p = pitch of rivets, d = diameter of rivet hole, t = thickness of the plate and n = number rivets, Pc = crushing resistance)","w":"The crushing (bearing) resistance of the rivets is the projected bearing area of each rivet, d × t, times the permissible crushing stress, times the number of rivets per pitch length: Pc = n·d·t·σc. The form n(π/4)d² goes with shear stress in the shearing resistance of rivets, (p − d)t goes with tensile stress in the tearing resistance of the plate, and αΔT is a thermal strain.","o":["Pc = n.d.t.σc","Pc = n(π/4).d². σc","Pc = (p − d)t. σc","Pc = α ΔT"],"a":[0]},{"id":"t2023b-93","p":"t2023b","n":93,"s":"mec","t":"Theory of Machines","q":"Which of the following gives the coefficient of fluctuation of speed of a flywheel? (where N₁ = Maximum speed during cycle and N₂ is minimum speed during the cycle)","w":"The coefficient of fluctuation of speed is the maximum fluctuation of speed divided by the mean speed: Cₛ = (N₁ − N₂)/N, where the mean speed N = (N₁ + N₂)/2. Substituting gives Cₛ = 2(N₁ − N₂)/(N₁ + N₂). A heavier flywheel lowers this value; its reciprocal is called the coefficient of steadiness.","o":["Cₛ = (N₁ + N₂)/(N₁ − N₂)","Cₛ = (N₁ − N₂)/(2(N₁ + N₂))","Cₛ = 2(N₁ − N₂)/(N₁ + N₂)","Cₛ = 2(N₁ + N₂)/(N₁ − N₂)"],"a":[2]},{"id":"t2023b-94","p":"t2023b","n":94,"s":"mec","t":"Machine Design","q":"Which of the following is correct regarding leaf spring?","w":"A leaf (laminated or carriage) spring is built up from a number of flat steel plates (leaves) of graded lengths held together by a centre bolt and clips; it is widely used in vehicle suspensions. Options 3 and 4 describe helical (coil) springs, and option 2 describes a fluid or gas spring, as in air or hydropneumatic suspension.","o":["It consists of a number of flat plates of varying lengths.","In this spring, fluid behave as a compressive spring.","This type of springs are helical in shape and used under compressive load only.","It is made of a wire coiled in the form of a helix."],"a":[0]},{"id":"t2023b-95","p":"t2023b","n":95,"s":"chs","t":"Clutch & Gearbox","q":"Which of the following is correct regarding clutches?\nI. The material used as a friction surface of clutch should have low heat conductivity.\nII. The material used as a friction surface for clutches should have high and uniform coefficient of friction.","w":"A clutch friction material should have a high and uniform coefficient of friction so that it transmits torque smoothly (II correct). It should also have high heat conductivity, to carry away the heat produced during slipping, and should withstand high temperature, resist wear and not be affected by moisture or oil. Low heat conductivity would let the lining overheat and fade, so I is wrong.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":[1]},{"id":"t2023b-96","p":"t2023b","n":96,"s":"mec","t":"Machine Design","q":"Which of the following is the advantage of rolling contact bearings over sliding contact bearings?\nI. They have high resistance to shock loading.\nII. They have low starting and running friction except at very high speeds.","w":"Rolling contact (ball and roller) bearings have low starting and running friction except at very high speeds, which is their main advantage over sliding (journal) bearings (II correct). Because the load is carried at very small contact areas, they have low resistance to shock loading, which textbooks list as a disadvantage, and they are noisier at high speeds and costlier. Sliding bearings with an oil film take shocks better, so I is wrong.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":[1]},{"id":"t2023b-97","p":"t2023b","n":97,"s":"mec","t":"Theory of Machines","q":"Which of the following is the advantage of the involute gears?\nI. The centre distance for a pair of involute gear can be varied within limits without changing the velocity ratio.\nII. The interference does not occur at all in this type of gears.","w":"The great advantage of involute gears is that the centre distance can vary within limits without changing the velocity ratio, since the base circles and the common normal stay the same; they are also easy to cut. Interference, however, can occur in involute gears when the number of teeth on the pinion is small; it is cycloidal gears that are free from interference. So only I is correct.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":[0]},{"id":"t2023b-98","p":"t2023b","n":98,"s":"mec","t":"Machine Design","q":"Which of the following is correct regarding springs?\nI. For the springs connected in series, the total deflection of the springs is summation of the deflection of each spring.\nII. For the springs connected in series, the combined stiffness of the spring is sum of the stiffness of each spring.\nIII. For the springs connected in parallel, the total load acting on it is the sum of the loads acting on individual springs.","w":"Springs in series carry the same load, so the total deflection is the sum of the individual deflections (I correct) and the combined stiffness follows 1/k = 1/k₁ + 1/k₂, which is less than either stiffness, so II is wrong. Springs in parallel deflect by the same amount, the total load is the sum of the loads on the individual springs (III correct), and their stiffnesses add.","o":["I and II","II and III","I and III","Only III"],"a":[2]},{"id":"t2023b-99","p":"t2023b","n":99,"s":"mec","t":"Machine Design","q":"Which of the following is correct regarding the sunk keys?\nI. A rectangular sunk key with a head at one end is called splines.\nII. A key attached as one member of a pair and which permits relative axial movement is known as woodruff key.\nIII. Woodruff key’s advantage is it accommodates itself to any taper in the hub or boss of the mating piece.","w":"A rectangular sunk key with a head at one end is a gib-head key; splines are keys made integral with the shaft. A key fixed to one member that allows relative axial movement is a feather key. A Woodruff key is a semicircular disc fitted in a curved seat, and it can tilt to accommodate itself to any taper in the hub or boss of the mating piece. So only III is correct.","o":["Only I","II and III","Only III","I and III only"],"a":[2]},{"id":"t2023b-100","p":"t2023b","n":100,"s":"mec","t":"Machine Design","q":"Match the following method with the equation for combination of stresses. (where σv = variable stress, σm = mean stress, σu = ultimate stress, σe = endurance limit for reversed loading, Kf = fatigue stress concentration factor, F.S. = factor of safety, σy = yielding stress)\nEquation for combination of stress | Method\nI. 1/F.S. = (σm/σu)² F.S. + σv.Kf/σe | 1. Soderberg method\nII. 1/F.S. = σm/σu + σv.Kf/σe | 2. Gerber method\nIII. 1/F.S. = σm/σy + σv.Kf/σe | 3. Goodman method","w":"For combined mean and variable stresses, the Gerber method uses a parabola, so the mean-stress term is squared: 1/F.S. = (σm/σu)² F.S. + σv·Kf/σe (I-2). The Goodman method uses a straight line through the ultimate stress: 1/F.S. = σm/σu + σv·Kf/σe (II-3). The Soderberg method uses a straight line through the yield stress, the most conservative: 1/F.S. = σm/σy + σv·Kf/σe (III-1).","o":["I-1, II-3, III-2","I-2, II-1, III-3","I-3, II-2, III-1","I-2, II-3, III-1"],"a":[3]},{"id":"t2023b-101","p":"t2023b","n":101,"s":"mec","t":"Theory of Machines","q":"Which of the following is a correctly matched pair regarding the classification of gears based on the position of axes of shafts?","w":"Mitre gears are bevel gears of equal size whose shaft axes intersect, usually at right angles, so they connect intersecting and non-parallel shafts. Spur gears and ordinary helical gears connect parallel shafts, while spiral (crossed helical) gears connect shafts that are non-parallel and non-intersecting, so the other three pairs are wrongly matched.","o":["Mitres : Intersecting and non-parallel","Spur gear : Non-parallel and non-intersecting","Helical gear : Intersecting and non-parallel","Spiral gear : Parallel and non-intersecting"],"a":[0]},{"id":"t2023b-102","p":"t2023b","n":102,"s":"mec","t":"Strength of Materials","q":"Which one of the following is a correctly matched pair?\nSection | Distance from the neutral axis to the extreme fibre\nI. Triangle | h/2\nII. Hollow rectangle | h/2\nIII. I-section | h/3\nIV. Hollow circle | (d − d₁)/2, (where d = outer diameter and d₁ = inner diameter)","w":"The neutral axis passes through the centroid. In a hollow rectangle of overall depth h it lies at mid-depth, so the extreme fibre is h/2 away and pair II is correct. In a triangle the centroid is h/3 from the base, so the extreme fibre (apex) is 2h/3 away; a symmetrical I-section gives h/2, not h/3; and a hollow circle gives d/2 (half the outer diameter), not (d − d₁)/2. Hence only II.","o":["Only I","Only II","II and III","Only IV"],"a":[1]},{"id":"t2023b-103","p":"t2023b","n":103,"s":"mec","t":"Machine Design","q":"For a same tensile load, arrange the following in an increasing order of maximum stress, given the theoretical stress concentration factor is (1 + 2a/b). (where r = radius of the circle)","w":"For an elliptical hole Kt = 1 + 2a/b, where a is the semi-axis at right angles to the load and b the semi-axis along it. In II the long axis lies along the load (a < b), so Kt < 3; in III the hole is a circle (a = b = r), so Kt = 3; in I the long axis lies across the load (a > b), so Kt > 3. For the same load the maximum stress rises with Kt: II, III, I.","img":"data:image/png;base64,","o":["I, II, III","II, I, III","II, III, I","I, III, II"],"a":[2]},{"id":"t2023b-104","p":"t2023b","n":104,"s":"mec","t":"Machine Design","q":"Arrange the following steps of procedure to solve design problem in a correct order (first to last).\nI. Synthesis\nII. Material selection\nIII. Recognition of need\nIV. Detailed drawing\nV. Modification\nVI. Production\nVII. Analysis of forces\nVIII. Design of elements (size and stresses)","w":"The standard machine-design flow chart begins with recognition of the need, followed by synthesis of a suitable mechanism, analysis of the forces acting on it, selection of material, and design of the elements for size and stresses. The design is then modified where needed, detailed drawings are prepared, and finally the part goes into production. This gives the order III, I, VII, II, VIII, V, IV, VI.","o":["III, I, VII, II, VIII, V, IV, VI","II, III, V, VI, I, VIII, VII, IV","VI, I, II, III, V, IV, VIII, VII","IV, II, III, I, VII, VIII, V, VI"],"a":[0]},{"id":"t2023b-105","p":"t2023b","n":105,"s":"mec","t":"Machine Design","q":"Arrange the following steps in a correct order (first to last) of design procedure for journal bearing.\nI. Determine the bearing length by choosing ratio of l/d.\nII. Check the bearing pressure for a probable satisfactory value.\nIII. Determine the heat generated.\nIV. Determine the operating value of ZN/p for the assumed bearing temperature and check this value.\nV. Determine the thermal equilibrium to see that the heat dissipated at least equal to heat generated.\nVI. Determine the coefficient of friction.\nVII. In case the heat generated is more than the heat dissipated than bearing is artificially cooled by water.","w":"In the standard procedure for a journal bearing, the length is first fixed from a chosen l/d ratio and the bearing pressure is checked. The operating ZN/p for the assumed temperature is then found and checked, the coefficient of friction is determined and from it the heat generated. Heat dissipated is compared with heat generated for thermal equilibrium, and if generation exceeds dissipation the bearing is cooled artificially. Order: I, II, IV, VI, III, V, VII.","o":["I, II, IV, VI, III, V, VII","II, I, III, V, VI, IV, VII","I, II, VII, IV, VI, V, III","III, V, VI, II, I, IV, VII"],"a":[0]},{"id":"t2023b-106","p":"t2023b","n":106,"s":"mfg","t":"Manufacturing & Workshop","q":"Which of the following is a finishing process of manufacturing?","w":"Burnishing is a finishing process in which a hard, smooth tool or rollers are pressed against a machined surface so that the peaks of the surface roughness are plastically flattened, giving a smooth, work-hardened surface without removing metal. Soldering is a joining process, extrusion is a forming process and milling is a primary metal-removal (machining) process.","o":["Soldering","Extrusion","Burnishing","Milling"],"a":[2]},{"id":"t2023b-107","p":"t2023b","n":107,"s":"mfg","t":"Manufacturing & Workshop","q":"Which of the following is a permanent mould casting process?","w":"In die casting, molten metal is forced under pressure into a reusable metal (steel) die, so the mould is permanent and serves for thousands of castings. Investment casting, sand casting and lost foam casting all use expendable moulds or patterns that are destroyed or broken up to remove each casting.","o":["Investment casting process","Die casting","Sand casting","Lost foam casting"],"a":[1]},{"id":"t2023b-108","p":"t2023b","n":108,"s":"mfg","t":"Engineering Materials","q":"Nylon is a ______.","w":"Nylon (a polyamide) is a thermoplastic: it softens on heating and hardens on cooling, and can be remelted and reshaped repeatedly, which is why it is injection-moulded into gears, bushes and fasteners. Thermosets such as Bakelite cure irreversibly into a cross-linked network, and elastomers such as rubber are highly elastic polymers.","o":["thermoplastic","resin","thermoset","elastomer"],"a":[0]},{"id":"t2023b-109","p":"t2023b","n":109,"s":"mfg","t":"Engineering Materials","q":"The property which allows material to undergo plastic deformation under tensile load before fracture is ______.","w":"Ductility is the ability of a material to undergo large plastic deformation under tensile load before fracture, so that it can be drawn into wire; it is measured by percentage elongation or reduction in area. Brittleness is the opposite (fracture with little deformation), fatigue is failure under repeated loading and resilience is the strain energy stored within the elastic limit.","o":["brittleness","ductility","fatigue","resilience"],"a":[1]},{"id":"t2023b-110","p":"t2023b","n":110,"s":"mfg","t":"Engineering Materials","q":"Which of the following is a test used to measure hardness of the material?","w":"The Vickers hardness test presses a square-based diamond pyramid (136° between opposite faces) into the surface and calculates hardness from the load and the diagonal of the indentation. Izod and Charpy tests are impact tests that measure toughness, the energy absorbed in breaking a notched specimen, and a disk test is not a standard hardness test.","o":["Disk test","Izod test","Charpy test","Vickers test"],"a":[3]},{"id":"t2023b-111","p":"t2023b","n":111,"s":"mfg","t":"Engineering Materials","q":"The permanent elongation of a component under a static load maintained for a long period of time is called ______.","w":"Creep is the slow, time-dependent permanent deformation of a material under a constant (static) load maintained for a long time; it becomes significant at high temperatures, as in turbine blades and boiler tubes. Plasticity is permanent deformation without time dependence, fatigue fracture results from fluctuating loads, and residual stresses are locked-in stresses present without external load.","o":["Plasticity","Creep","Fatigue fracture","Residual stress"],"a":[1]},{"id":"t2023b-112","p":"t2023b","n":112,"s":"mfg","t":"Engineering Materials","q":"When white cast iron is annealed in an atmosphere of carbon monoxide and carbon dioxide, at temperature between 800°C and 900°C for several hours depending on size, we obtain ______.","w":"Malleable iron is produced by long annealing (malleabilising) of white cast iron at about 800–900 °C in a controlled atmosphere; the cementite breaks down into irregular nodules (rosettes) of temper carbon, making the iron tough and ductile. Nodular iron is made by adding magnesium or cerium to the molten iron, and grey and compacted graphite irons form their graphite directly on solidification.","o":["compacted graphite iron","nodular iron","gray cast iron","malleable iron"],"a":[3]},{"id":"t2023b-113","p":"t2023b","n":113,"s":"mfg","t":"Engineering Materials","q":"The heating process by which hardness is reduced and toughness is improved is called ______.","w":"Tempering is reheating a hardened (quenched) steel to a temperature below the lower critical temperature, holding it and then cooling it; it relieves internal stresses, reduces hardness and brittleness and improves toughness. Quenching increases hardness, while cyaniding and carburizing are case-hardening processes that increase surface hardness.","o":["quenching","cyaniding","tempering","carburizing"],"a":[2]},{"id":"t2023b-114","p":"t2023b","n":114,"s":"mfg","t":"Manufacturing & Workshop","q":"The machining process of making a hole by removing a disk shaped piece from a flat plate is called ______.","w":"Trepanning cuts a narrow annular groove through a plate with a tool rotating about the hole centre, so the central disc (core) comes out in one piece; it is economical for large holes in plates because little metal is turned into chips. Gun drilling makes deep holes, boring enlarges an existing hole and tapping cuts internal threads.","o":["trepanning","gun drilling","boring","tapping"],"a":[0]},{"id":"t2023b-115","p":"t2023b","n":115,"s":"mfg","t":"Manufacturing & Workshop","q":"Which of the following is a correct relation of material removal rate for milling? (l = length of cut, w = width of the cut, d = depth of cut, t = cutting time, f = feed per tooth, v = feed rate)","w":"Material removal rate is the volume of metal removed per unit time. A milling cut of length l, width w and depth d removes a volume l × w × d in the cutting time t, so MRR = l × w × d/t; since the feed rate v = l/t, this also equals w × d × v. The other expressions do not even have the units of volume per unit time.","o":["MRR = (l × w)/(d × t)","MRR = (f × d × t)/l","MRR = (w × d)/v","MRR = (l × w × d)/t"],"a":[3]},{"id":"t2023b-116","p":"t2023b","n":116,"s":"mfg","t":"Manufacturing & Workshop","q":"The phenomenon of wandering of arc that occurs in DC welding is called ______.","w":"Arc blow is the wandering or deflection of the welding arc from its intended path caused by unbalanced magnetic fields around the arc and the work; it is serious in DC welding, especially near the ends of joints and in corners. It is reduced by using AC, shifting the earth connection or using a short arc. Spatter, underfill and lamellar tearing are other weld defects.","o":["Arc blow","Spattering","Underfilling","Lamellar tears"],"a":[0]},{"id":"t2023b-117","p":"t2023b","n":117,"s":"mfg","t":"Manufacturing & Workshop","q":"Which of the following is correct regarding the process of reaming?\nI. Reaming is an operation used to achieve a high grade of surface finish on a hole.\nII. The tool used in reaming operation has multiple cutting edges.","w":"Reaming is a finishing (sizing) operation done on an already drilled hole to bring it to accurate size and give it a good surface finish, removing only a small amount of metal. The reamer is a multi-tooth tool with several straight or helical cutting edges. Both statements are therefore correct.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":[2]},{"id":"t2023b-118","p":"t2023b","n":118,"s":"mfg","t":"Manufacturing & Workshop","q":"Which of the following is correct regarding the lathe operations?\nI. Process of reducing the diameter of a workpiece over a very narrow surface is called knurling.\nII. Knurling is done at the slowest speed available in a lathe.","w":"Reducing the diameter of a workpiece over a very narrow width is grooving (necking), not knurling, so statement I is wrong. Knurling embosses a straight or diamond pattern on a surface by pressing hardened knurling wheels against the rotating work; being a forming operation that needs high pressure, it is done at the slowest spindle speed with plenty of lubricant, so statement II is correct.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":[1]},{"id":"t2023b-119","p":"t2023b","n":119,"s":"mfg","t":"Manufacturing & Workshop","q":"Which of the following is correct about broaching?\nI. It is a process of machining a surface with a special multipoint tool.\nII. Gears cannot be manufactured using a broaching process.","w":"Broaching machines a surface by pulling or pushing a long multipoint tool (broach) whose successive teeth are slightly higher, so statement I is correct. Broaching is widely used to cut internal gears, splines and keyways, and even external gear teeth, so statement II, that gears cannot be made by broaching, is wrong. Hence only I.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":[0]},{"id":"t2023b-120","p":"t2023b","n":120,"s":"mfg","t":"Manufacturing & Workshop","q":"Which of the following is correct regarding forging?\nI. Upsetting is a process of increasing cross sectional dimensions when forging.\nII. Process of cutting large holes of various shapes by using a chisel over a hole in the sewage block is called setting down.\nIII. One of the advantages of open die forging is, it can be employed for long run production.","w":"Upsetting increases the cross-section of a bar while reducing its length, so I is correct. Setting down is the local thinning or shouldering of a bar with a set hammer; cutting holes in the work with a chisel over the hole of a swage block (printed \"sewage block\") is a hole-making operation, not setting down, so II is wrong. Open die forging suits small quantities, while long production runs use closed (impression) dies, so III is wrong.","o":["Only I","I and II only","II and III only","Only III"],"a":[0]},{"id":"t2023b-121","p":"t2023b","n":121,"s":"mfg","t":"Manufacturing & Workshop","q":"Which of the following is correct regarding electron beam machining?\nI. It can be used on all materials.\nII. Material removal rate is low and vacuum is needed for operation.\nIII. The voltage required for electron beam machining is 1150 kV.","w":"Electron beam machining uses a focused beam of high-velocity electrons that melts and vaporises the work, so it can machine practically any material, whatever its hardness or conductivity (I correct). Its material removal rate is very low and it must be done in a vacuum so that the electrons are not scattered (II correct). Accelerating voltages are typically about 50–200 kV, not 1150 kV (III wrong).","o":["I and III only","I and II only","II and III only","Only III"],"a":[1]},{"id":"t2023b-122","p":"t2023b","n":122,"s":"mfg","t":"Manufacturing & Workshop","q":"Which of the following is correct regarding advantages of cold working?\nI. Ductility of metal is improved.\nII. Minimum contamination during cold working compare to hot working.\nIII. Good surface finish and better dimensional accuracy than hot working.","w":"Cold working, done below the recrystallisation temperature, strain-hardens the metal: strength and hardness rise but ductility falls, so I is wrong. Since the metal is not heated there is no scaling or oxidation and little contamination (II correct), and cold-worked parts have a better surface finish and closer dimensional accuracy than hot-worked ones (III correct). Hence II and III only.","o":["Only I","Only II","II and III only","I and II only"],"a":[2]},{"id":"t2023b-123","p":"t2023b","n":123,"s":"mfg","t":"Engineering Materials","q":"Match the following elements with its effect on the steel.\nElements | Effect on the steel\nI. Calcium | 1. Improves hardenability\nII. Boron | 2. Improves resistance to atmospheric corrosion\nIII. Lead | 3. Improves toughness and formability\nIV. Copper | 4. Improves machinability","w":"Calcium treatment changes the shape of sulphide inclusions, improving toughness and formability (I-3). Very small additions of boron, a few thousandths of a per cent, greatly raise hardenability (II-1). Lead in free-cutting steels breaks up the chips and lubricates the tool, improving machinability (III-4). Copper, about 0.2–0.5 %, improves resistance to atmospheric corrosion, as in weathering steels (IV-2).","o":["I-3, II-4, III-1, IV-2","I-2, II-1, III-4, IV-3","I-3, II-1, III-4, IV-2","I-2, II-4, III-1, IV-3"],"a":[2]},{"id":"t2023b-124","p":"t2023b","n":124,"s":"mfg","t":"Engineering Materials","q":"Which one of the following is a correctly matched pair?","w":"In grey cast iron most of the carbon is present as graphite flakes, which give the grey fracture, so pair 1 is correct. White cast iron has its carbon combined as cementite with no free graphite; ductile (nodular) iron has graphite in spherical form; and compacted graphite iron has short, thick, interconnected (vermicular) flakes, so pairs 2, 3 and 4 are wrong.","o":["Grey cast iron : Graphite exists largely in form of flakes","White cast iron : Graphite in a spherical form","Ductile iron : Graphite in form of short, thick interconnected flakes","Compacted graphite iron : Do not have any carbon flakes"],"a":[0]},{"id":"t2023b-125","p":"t2023b","n":125,"s":"mfg","t":"Manufacturing & Workshop","q":"Arrange the following brazing alloys in order of their increasing melting point.\nI. Copper = 50 percent, Zinc = 50 percent\nII. Copper = 70 percent, Zinc = 30 percent\nIII. Copper = 60 percent, Zinc = 40 percent","w":"Brazing brasses melt at lower temperatures as their zinc content rises, because zinc (melting point about 420 °C) lowers the melting point of copper (about 1083 °C). So the 50 % copper–50 % zinc alloy melts lowest, the 60–40 alloy next and the 70–30 alloy highest, giving the increasing order I, III, II.","o":["I, II, III","II, III, I","III, II, I","I, III, II"],"a":[3]},{"id":"t2023b-126","p":"t2023b","n":126,"s":"mfg","t":"Manufacturing & Workshop","q":"Arrange the following three region in decreasing order of percentage of heat generated during metal cutting.\nI. The shear zone\nII. The chip tool interface region\nIII. The tool-work interface region","w":"In metal cutting most of the heat is generated in the primary shear zone, where the metal is plastically deformed to form the chip. The next largest share comes from friction and deformation at the chip–tool interface (secondary zone), and the least from rubbing of the tool flank on the machined surface (tool–work interface). Hence the decreasing order is I, II, III.","o":["III, II, I","I, II, III","II, III, I","II, I, III"],"a":[1]},{"id":"t2023b-127","p":"t2023b","n":127,"s":"mfg","t":"Manufacturing & Workshop","q":"Arrange the following steps in a correct order (first to last) regarding thermit welding.\nI. After cutting, pouring and heating gates and risers a flame is directed into heating oven to drain out wax.\nII. Molten iron run into the mould which fuses with part to be welded.\nIII. Wax pattern of desired size and shape is prepared around joint.\nIV. The thermit mixture packed in the crucible of conical shape formed from sheet iron casting lined with heat resisting cement is ignited.","w":"In thermit welding a wax pattern of the required shape is first built around the joint (III). The mould is rammed round it and, after the pouring and heating gates and risers are cut, a flame is directed in to melt out the wax and preheat the joint (I). The thermit mixture in a conical, refractory-lined crucible is then ignited (IV), and the molten iron runs into the mould and fuses with the parts (II).","o":["I, II, IV, III","III, I, IV, II","II, IV, III, I","IV, III, II, I"],"a":[1]},{"id":"t2023b-128","p":"t2023b","n":128,"s":"mfg","t":"Manufacturing & Workshop","q":"Arrange the following steps in a correct order (first to last) of greens and mouldings.\nI. Making the mould\nII. Closing and weighing\nIII. Core setting\nIV. Preparation of the pattern","w":"In green sand moulding (printed \"greens and mouldings\") the pattern is prepared first, the mould is then made by ramming sand round it and withdrawing the pattern, the cores are set in place, and finally the mould halves are closed and weighted down to resist the pressure of the metal before pouring. The order is therefore IV, I, III, II.","o":["II, I, III, IV","IV, I, III, II","III, II, IV, I","II, IV, I, III"],"a":[1]},{"id":"t2023b-129","p":"t2023b","n":129,"s":"chs","t":"Chassis & Body","q":"The actual average rate of coverage by the farm machine, based upon total field time is called ______.","w":"Effective field capacity is the actual average rate at which a farm machine covers a field (for example in hectares per hour), based on the total field time including turning and other lost time. Theoretical field capacity is the rate at full width and speed with no lost time, field efficiency is the ratio of effective to theoretical field capacity, and effective operating time is only the time actually spent working.","o":["effective operating time","theoretical field capacity","field efficiency","effective field capacity"],"a":[3]},{"id":"t2023b-130","p":"t2023b","n":130,"s":"chs","t":"Chassis & Body","q":"An assemblage of one or more winding drums mounted on a frame of a crane is called ______.","w":"A winch consists of one or more winding drums mounted on a frame, on which the hoisting rope is wound to lift or pull loads; cranes use winches for hoisting and for raising the boom. The boom is the long arm that carries the load rope, the main clutch transmits engine power to the drums, and a flange is a projecting rim, not an assembly of drums.","o":["Main clutch","Winch","Boom","Flange"],"a":[1]},{"id":"t2023b-131","p":"t2023b","n":131,"s":"flu","t":"Fluid Mechanics","q":"A fluid in which shear stress is more than the yield value and shear stress is proportional to the rate of shear strain is called ______.","w":"An ideal plastic (Bingham plastic) fluid does not flow until the shear stress exceeds a yield value; beyond it the shear stress increases linearly with the rate of shear strain, τ = τy + μ(du/dy). A Newtonian fluid has no yield stress (τ = μ du/dy), an ideal fluid has no viscosity, and a real fluid is any fluid that has viscosity.","o":["Newtonian fluid","Ideal fluid","Ideal plastic fluid","Real fluid"],"a":[2]},{"id":"t2023b-132","p":"t2023b","n":132,"s":"flu","t":"Fluid Mechanics","q":"What is the ratio of dynamic viscosity to the density of the fluid?","w":"Kinematic viscosity ν is the ratio of dynamic viscosity μ to density ρ, ν = μ/ρ. Its SI unit is m²/s and its CGS unit is the stoke (1 stoke = 1 cm²/s = 10⁻⁴ m²/s). Specific gravity is a ratio of densities, specific volume is the reciprocal of density, and mass is not a ratio of fluid properties at all.","o":["Mass","Kinematic viscosity","Specific gravity","Specific volume"],"a":[1]},{"id":"t2023b-133","p":"t2023b","n":133,"s":"flu","t":"Hydraulic Machines & Pneumatics","q":"The ratio of weight lifted to the force applied on the plunger of a hydraulic press is called ______.","w":"In a hydraulic press a small effort F on the plunger of area a creates a pressure that acts on the large ram of area A, lifting a weight W = F × A/a. The ratio W/F, the load lifted per unit effort, is the mechanical advantage. Volumetric and Rankine efficiencies relate to pumps and steam cycles, and effort is the applied force itself.","o":["Volumetric efficiency","Mechanical advantage","Rankine efficiency","Effort"],"a":[1]},{"id":"t2023b-134","p":"t2023b","n":134,"s":"flu","t":"Hydraulic Machines & Pneumatics","q":"The ratio of power given by water to the runner of a turbine to the power supplied by the water at the inlet of the turbine is called ______.","w":"Hydraulic efficiency of a turbine is the ratio of the power given by the water to the runner (runner power) to the power supplied by the water at the inlet (water power, ρgQH). Mechanical efficiency is shaft power divided by runner power, overall efficiency is shaft power divided by water power (the product of the two), and volumetric efficiency compares the water acting on the runner with that supplied.","o":["Overall efficiency","Mechanical efficiency","Hydraulic efficiency","Volumetric efficiency"],"a":[2]},{"id":"t2023b-135","p":"t2023b","n":135,"s":"flu","t":"Hydraulic Machines & Pneumatics","q":"The axial flow reaction turbine which vanes on the hub are adjustable is called ______.","w":"A Kaplan turbine is an axial flow reaction turbine whose runner vanes on the hub are adjustable, so their angle can be changed with the load to keep the efficiency high at part load. A propeller turbine is also axial flow but its vanes are fixed to the hub; the Francis turbine is a radial (mixed) flow reaction turbine and the Pelton wheel is an impulse turbine.","o":["Propeller turbine","Francis turbine","Pelton turbine","Kaplan turbine"],"a":[3]},{"id":"t2023b-136","p":"t2023b","n":136,"s":"flu","t":"Fluid Mechanics","q":"The flow in which the velocity at any given time changes with respect to space are called ______.","w":"Non-uniform flow is flow in which the velocity at a given instant changes from point to point along the flow (∂V/∂s ≠ 0), as in a tapering pipe. In uniform flow the velocity is the same at every point at a given time, while steady and unsteady flows are defined by whether the conditions at a point change with time.","o":["Non-uniform flow","Steady flow","Uniform flow","Unsteady flow"],"a":[0]},{"id":"t2023b-137","p":"t2023b","n":137,"s":"chs","t":"Chassis & Body","q":"Which of the following vehicle have rotating beam attached to a vertical mast and supporting a hoist?","w":"A jib crane has a horizontal beam (jib) attached to a vertical mast or pillar; the jib can rotate (slew) about the mast and carries a trolley and hoist that lift and move loads within the circle it sweeps. Bulldozers push earth with a front blade, fork lift trucks raise loads on forks along a vertical mast, and loaders scoop and load material with a bucket.","o":["Bulldozer","Fork lift truck","Loaders","Jib Crane"],"a":[3]},{"id":"t2023b-138","p":"t2023b","n":138,"s":"chs","t":"Chassis & Body","q":"Which of the following vehicle designed for transporting large quantities of bulk material like gravel over short distance?","w":"A dumper is a vehicle designed to carry large quantities of bulk material such as sand, gravel or earth over short distances on construction and mining sites, and to unload it by tipping its skip or body. Fork lift trucks handle palletised loads, loaders scoop material and load it into other vehicles, and bulldozers push earth with a blade.","o":["Fork lift truck","Loaders","Dumpers","Bulldozer"],"a":[2]},{"id":"t2023b-139","p":"t2023b","n":139,"s":"flu","t":"Hydraulic Machines & Pneumatics","q":"Which of the following is correct regarding the Francis turbine?\nI. It is an inward flow reaction turbine having radial discharge at outlet.\nII. The work done by water on the runner per second is ρQ(Vw₁u₁). (where Q is discharge, Vw₁ = Whirl velocity at inlet, u₁ is blade velocity of wheel at inlet, ρ = density of fluid)","w":"Textbooks define the Francis turbine as an inward flow reaction turbine having radial discharge at outlet (modern Francis runners are in fact mixed flow, discharging axially). With radial discharge the whirl velocity at outlet Vw₂ is zero, so the Euler expression ρQ(Vw₁u₁ − Vw₂u₂) for the work done per second reduces to ρQVw₁u₁. Hence both statements are correct as given.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":[2]},{"id":"t2023b-140","p":"t2023b","n":140,"s":"flu","t":"Fluid Mechanics","q":"Which of the following is correct regarding the surface tension?\nI. The pressure intensity of soap bubble is twice of a liquid droplet for same diameter and surface tension.\nII. Surface tension is a shear force acting on the surface of a liquid.","w":"The excess pressure inside a liquid droplet is p = 4σ/d, while a soap bubble has two surfaces, so p = 8σ/d: twice that of a droplet of the same diameter and surface tension (I correct). Surface tension is a tensile force per unit length acting in the surface of a liquid, not a shear force (II wrong). Hence only I.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":[0]},{"id":"t2023b-141","p":"t2023b","n":141,"s":"flu","t":"Hydraulic Machines & Pneumatics","q":"Match the following turbines with their classification based on the direction of flow through runner.\nTurbine | Direction of flow\nI. Pelton | 1. Axial flow reaction turbine\nII. Francis | 2. Tangential flow turbine\nIII. Kaplan | 3. Inward flow reaction turbine","w":"In a Pelton wheel the jet strikes the buckets tangentially at the rim of the wheel, so it is a tangential flow (impulse) turbine (I-2). The Francis turbine is an inward (radial) flow reaction turbine (II-3), and the Kaplan turbine is an axial flow reaction turbine in which the water flows parallel to the shaft (III-1). The match is I-2, II-3, III-1.","o":["I-1, II-2, III-3","I-3, II-1, III-2","I-3, II-2, III-1","I-2, II-3, III-1"],"a":[3]},{"id":"t2023b-142","p":"t2023b","n":142,"s":"flu","t":"Fluid Mechanics","q":"Arrange the following in an increasing order of shear stress.\nI. Shear stress of oil with oil viscosity 12 poise, velocity of 2.5 m/s and clearance of 1.25 cm.\nII. Shear stress of oil having dynamic viscosity 0.1 Ns/m², clearance of 2 mm and velocity 2500 mm/s⁻¹.\nIII. Shear stress of oil on an inclined plane having viscosity 2 poise, velocity 1.5 m/s and clearance of 3 cm.","w":"Use Newton's law of viscosity, τ = μu/y, with 1 poise = 0.1 N·s/m². I: τ = 1.2 × 2.5/0.0125 = 240 N/m². II: τ = 0.1 × 2.5/0.002 = 125 N/m² (2500 mm/s = 2.5 m/s; the unit is misprinted as mm/s⁻¹). III: τ = 0.2 × 1.5/0.03 = 10 N/m². The increasing order is III (10), II (125), I (240).","o":["II, III, I","I, II, III","III, I, II","III, II, I"],"a":[3]},{"id":"t2023b-143","p":"t2023b","n":143,"s":"flu","t":"Fluid Mechanics","q":"Which of the following is correct about flow of fluids through pipes?\nI. Hydraulic gradient line gives the sum of pressure head and kinetic head.\nII. Total energy line gives the sum of pressure head, kinetic head and datum head.\nIII. The Chezy’s formula for loss of head due to friction in pipes is h_f = 4.f.L.V²/(d2g)\n(where f = co-efficient of friction, L = length of pipe, V = mean velocity of flow, d = diameter of pipe)","w":"The hydraulic gradient line shows the piezometric head, the sum of pressure head and datum head (p/ρg + z), not kinetic head, so I is wrong. The total energy line adds the velocity head, p/ρg + V²/2g + z, so II is correct. h_f = 4fLV²/(2gd) is the Darcy–Weisbach formula; Chezy's formula is V = C√(mi), so III is wrong. Hence only II.","o":["I and II","Only II","II and III","I and III"],"a":[1]},{"id":"t2023b-144","p":"t2023b","n":144,"s":"flu","t":"Hydraulic Machines & Pneumatics","q":"Which of the following is correctly matched?\nTypes of turbine | Specific speed in MKS units\nI. Francis turbine | 300 to 600\nII. Pelton wheel with single jet | 10 to 35\nIII. Pelton wheel with two or more jets | 100 to 800\nIV. Kalpan Propeller turbine | 300 to 1000","w":"In MKS units the usual ranges of specific speed are: Pelton wheel with a single jet 10–35, Pelton wheel with two or more jets 35–60, Francis turbine 60–300 and Kaplan or propeller turbine 300–1000. So pairs II and IV are correct, while the ranges given for the Francis turbine (300–600) and the multi-jet Pelton wheel (100–800) are wrong. \"Kalpan\" is a misprint for Kaplan.","o":["Only I and II","Only I, II and III","Only II and IV","Only III and IV"],"a":[2]},{"id":"t2023b-145","p":"t2023b","n":145,"s":"mva","t":"Motor Vehicles Act & Rules","q":"A registration code of a vehicle is given as:\nUP 26 B 9126.\nWhat does the value 26 represents?","w":"Indian registration marks follow the pattern state code, district (RTO) code, series and number. In UP 26 B 9126, \"UP\" is the state code for Uttar Pradesh, \"26\" identifies the district registering authority (RTO) where the vehicle is registered, \"B\" is the series and 9126 is the vehicle's own number. Since 2021 vehicles may also take the separate BH (Bharat) series mark, which has no state or district code.","o":["Series","State code","District or town code","Village code"],"a":[2]},{"id":"t2023b-146","p":"t2023b","n":146,"s":"mva","t":"Motor Vehicles Act & Rules","q":"Section 3 of The Motor Vehicles Act, 1988 deals with ______.","w":"Section 3 of the Motor Vehicles Act, 1988 is headed \"Necessity for driving licence\": no person shall drive a motor vehicle in any public place unless he holds an effective driving licence authorising him to drive that vehicle. Grant of learner's licence and grant of driving licence are covered by Sections 8 and 9. Section 3 continues in force after the Motor Vehicles (Amendment) Act, 2019.","o":["Grant of learner’s licence","Grant of driving licence","Endorsement","Necessity for driving licence"],"a":[3]},{"id":"t2023b-147","p":"t2023b","n":147,"s":"mva","t":"Transport Management","q":"Which of the following is correct regarding continuous flow production model?\nI. In this model, facility should be flexible to handle a wide variety of products.\nII. In this model a standard set of processes and sequence of processes can be adopted.","w":"Continuous (flow or mass) production makes large volumes of standardised products, so a standard set of processes in a fixed sequence, with special-purpose machines and a product layout, can be adopted (II correct). Flexibility to handle a wide variety of products is a feature of job-shop or intermittent production, not of continuous flow production, so I is wrong. Hence only II.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":[1]},{"id":"t2023b-148","p":"t2023b","n":148,"s":"mva","t":"Transport Management","q":"Which of the following is correct regarding principle for personnel management?\nI. People are to be dealt with as a complete individual.\nII. There should be fairness in dealing with the employees to win their confidence.\nIII. All the employees doing the same type of work are not needed to pay the same.","w":"Accepted principles of personnel management include dealing with each employee as a whole individual with personal needs (I) and treating employees fairly so as to win their confidence and co-operation (II). Another principle is equal pay for equal work, so the statement that employees doing the same type of work need not be paid the same (III) is wrong. Hence I and II only.","o":["Only I","I and II only","II and III only","III and I only"],"a":[1]},{"id":"t2023b-149","p":"t2023b","n":149,"s":"mva","t":"Transport Management","q":"Which of the following is a correct pair regarding the types of communication in an organization?\nI. Downward communication : The transmission of feedback, orientation, complaints, suggestions for improvements etc. from lowest grade employee to top executive\nII. Horizontal communication : Transmission of information between persons having the same level of authority in the organization\nIII. Upward communication : The transmission of instructions and information from top executive downwards to the lowest grade employee.","w":"Horizontal (lateral) communication is the flow of information between persons at the same level of authority, so II is correct. The descriptions in I and III are interchanged: downward communication carries instructions and information from top executives to lower employees, while upward communication carries feedback, complaints and suggestions from the lowest grades to the top. Hence only II.","o":["Only I","Only II","II and III only","I and III only"],"a":[1]},{"id":"t2023b-150","p":"t2023b","n":150,"s":"mva","t":"Road Safety","q":"Match the following.\nSigns | Symbols\nI. Railway crossing (Guarded) | 1. Symbol 1\nII. Narrow bridge | 2. Symbol 2\nIII. Cross roads | 3. Symbol 3\nIV. Steep hills | 4. Symbol 4","w":"The guarded railway crossing sign shows a gate or fence in a red-bordered triangle (I-2). The narrow bridge sign shows two lines closing in towards each other like bridge parapets (II-3). The crossroads sign shows two roads crossing, the X of symbol 1 (III-1), which leaves the sloping wedge of symbol 4 for steep hills (IV-4). The match is I-2, II-3, III-1, IV-4.","img":"data:image/png;base64,","o":["I-1, II-2, III-4, IV-3","I-2, II-3, III-1, IV-4","I-2, II-4, III-1, IV-3","I-3, II-1, III-2, IV-4"],"a":[1]}],"instagram":"learn_with_anil06","site":"https://learnwithanil.in","notes":[],"wa":"919494792739","key":"tg-amvi","exam":"TGPSC AMVI (Assistant Motor Vehicles Inspector)","bahubali":"","examShort":"TGPSC AMVI","papersNote":"Answers come from TSPSC's preliminary key on the master question papers of the computer-based test held on 28 June 2023 (Notification 31/2022). TSPSC released its final key on 7 February 2024 only on candidates' individual response sheets, so a few answers may differ from the final key; doubtful ones are marked in the explanations. Paper I is in English and Telugu as printed; Paper II (Automobile Engineering) is in English only.","hub":false,"board":"TGPSC","l2":{"code":"te","label":"తెలుగు","name":"Telugu","font":"Noto Sans Telugu"},"base":"tgpsc-amvi/","qotd":[],"pay":{"on":true,"api":"https://script.google.com/macros/s/AKfycbxgNi2CfnbaEsVpA1Ghgy0AdYdUG7eYBkol5zqcbMgA2Q4D0Pvy0rndLxeyE7MlPy_3Rg/exec","exam":"tgpsc-amvi","pyq":{"price":45,"valid":"valid for 12 months from the day you pay, on every exam","exams":"APPSC Group 2, APPSC Group 1, UPSC CAPF AC, UPSC EPFO, SSC CGL, TS Police SI, TS Police Constable, TGPSC HMWSSB Manager, APPSC AMVI, TGPSC AMVI","trial":0},"mock":null,"combo":null,"pages":{"pyq":"/tgpsc-amvi/pyqs.html","mock":"/tgpsc-amvi/mock-test.html","sec":"/tgpsc-amvi/sectional-tests.html"},"sample":10},"exams":[],"cats":[],"timers":[],"pb":"/tgpsc-amvi/","qpages":true,"examSeo":"TGPSC AMVI","homeTitle":"TGPSC (TSPSC) AMVI Previous Question Papers with Answers – Assistant Motor Vehicles Inspector 2023, GS & Automobile Engineering | Learn with Anil","hubTitle":"Learn with Anil (LearnWithAnil.in) – PYQs with Answers: APPSC Group 1 & 2, TS Police SI & Constable, UPSC CAPF & EPFO"};
